__reload_all = true
local System = require("System.System")
local readonly = System.readonly
local Text_Voice = readonly({
  Voice_100335_AwakerVoiceContent = {
    Text = "Koruyucu, Mythag mezarlığına ne zaman geri dönebilirim? Oraya gömülü büyük ruhlar bana büyük ilhamlar vermeli! Merak etme, bu sefer o cesetleri daha yakından bakmak için kazmayacağıma söz veriyorum..."
  },
  Voice_100335_AwakerVoiceTitle = {
    Text = "Sohbet: Modeller Hakkında"
  },
  Voice_100336_AwakerVoiceContent = {
    Text = "Bekle! Yeni bir teknik düşündüm. Bütün sanat dünyasını sarsıntı içinde bırakacak!"
  },
  Voice_100336_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_100337_AwakerVoiceContent = {
    Text = "Ben ışığın gölgeye sızmasıyım. Ben pigment ve verniğin fısıltısıyım. Ben... resmeden açlığım!"
  },
  Voice_100337_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_100338_AwakerVoiceContent = {
    Text = "Hımm? ...Psikende bir Ana Renk var, daha önce hiç görmediğim bir ton... nedir o..."
  },
  Voice_100338_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_100338_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_100339_AwakerVoiceContent = {
    Text = "Ah, enfes bir siyah boya! Eskiden resimlerimde çok Çözünme sıvısı kullanırdım, ama o eserlerin hepsi yok oldu. Eski evrenden gelen renkler, resmimi yutup dünyaca sonsuza dek unutuldu... Bu daha da iyi değil mi?!"
  },
  Voice_100339_AwakerVoiceTitle = {
    Text = "Sohbet: Kriz Hakkında"
  },
  Voice_100340_AwakerVoiceContent = {
    Text = "Yaklaşmama izin ver... daha fazlasını görmeme izin ver! Bu ışıklar, bu gölgeler, bu şekiller... Daha önce yaptığım her şey bunun yanında çöp..."
  },
  Voice_100340_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_100340_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_100341_AwakerVoiceContent = {
    Text = "Doresain hep yemeklerinin sanat olduğunu söyler. Hadi ama. Yemeğin sanatla ne ilgisi var ki! Ceset hazırlarken iyi resim yapma zamanını harcıyor, üstüne hem göze hem damağa hitap eden bir tabak yaptıktan sonra onu çiğneyip yutmak zorunda kalıyorum! Bu sanatın işlenmiş suçudur!"
  },
  Voice_100341_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_100342_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_100342_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_100343_AwakerVoiceContent = {
    Text = "Ne zalim bir model..."
  },
  Voice_100343_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_100344_AwakerVoiceContent = {
    Text = "Hayır, hayır, yine berbat bir tablo... Kavrayış’ı nerede bulabilirim? Bir mezarlıkta mı? Yoksa bir infaz meydanında mı..."
  },
  Voice_100344_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_100345_AwakerVoiceContent = {
    Text = "Genelde heykeli donuk ve sıkıcı bulurum, ama o heykeltıraş Sanga, onun keskisi tekniğin ötesinde bir güce sahip... gerçek bir dahi!"
  },
  Voice_100345_AwakerVoiceTitle = {
    Text = "Sohbet: Sanga Hakkında"
  },
  Voice_100345_UnlockDesc = {
    Text = "\"Uyanış\" Sanga elde edildikten sonra açılır"
  },
  Voice_100346_AwakerVoiceContent = {
    Text = "Bunu gördün mü, Koruyucu? Bu senin portren. Ceset yerken ne kadar güzelsin, bak! Herkesin işlerimi anlamadığını biliyorum, ama sen içindeki o güzel Delilik’i hissediyorsun, değil mi?! Benim için bu yeter. Fazlasıyla yeter..."
  },
  Voice_100346_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_100346_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_100347_AwakerVoiceContent = {
    Text = "Bu tabloyu satın almak istiyorsun... gerçekten mi?! Te-teşekkür ederim, Koruyucu! İ-İnsanlar bunu neredeyse hiç anlamaz..."
  },
  Voice_100347_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_100347_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_100348_AwakerVoiceContent = {
    Text = "Koruyucu, tekrar modellik yapmaya vaktin var mı? Geçen sefer sende gördüklerimle kıyaslayınca, diğer modeller tam bir zaman kaybı..."
  },
  Voice_100348_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_100349_AwakerVoiceContent = {
    Text = "Bu tabloda, yeni bir doğuşa tanık ol!"
  },
  Voice_100349_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_100350_AwakerVoiceContent = {
    Text = "Şu canlı çizgilere bak!"
  },
  Voice_100350_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_100351_AwakerVoiceContent = {
    Text = "Bu fırça darbesi... bir impasto şaheseri olacak! Herkes hayretler içinde kalacak!"
  },
  Voice_100351_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_100352_AwakerVoiceContent = {
    Text = "Ah! Yeni bir pigment! Kompozisyonu en iyi tamamlayacağı yere sürmeliyim!"
  },
  Voice_100352_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_100353_AwakerVoiceContent = {
    Text = "Bu yer bana fikirler veriyor! Yeni işlerim var, Koruyucu. Atölyemi ziyaret etmeye vaktin var mı? Hadi, hadi!"
  },
  Voice_100353_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_100353_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_100354_AwakerVoiceContent = {
    Text = "Evet, işte böyle, mükemmel! Kana boyanmış bir zafer! Ne parlak bir kompozisyon!"
  },
  Voice_100354_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_100355_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_100355_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_100356_AwakerVoiceContent = {
    Text = "Ah! Lütfen otur, Koruyucu. Benim için modellik yapmak Zor bir iş, biliyorum. Bana güven, seni bir şahesere dönüştüreceğim."
  },
  Voice_100356_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_100356_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_100357_AwakerVoiceContent = {
    Text = "Bir sanatçı yalnızca eseri görmeli, başkalarının ne düşündüğünü umursamamalı... ama ben yapamıyorum. İlk kez fırça tuttuğum andan beri, Herkes’e gerçek güzelliği göstermek istedim."
  },
  Voice_100357_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_100357_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_100358_AwakerVoiceContent = {
    Text = "Burası bana sanat okulunu hatırlatıyor. Çoğu öğretmen ve öğrenci sanattan zerre anlamazdı, ama her zaman tablolarımdaki güzelliği görebilen bir iki kişi olurdu."
  },
  Voice_100358_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_100359_AwakerVoiceContent = {
    Text = "Bu barbarca performans ne tür çılgın bir sanat eseri doğuracak?!"
  },
  Voice_100359_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_100360_AwakerVoiceContent = {Text = "Paletim!"},
  Voice_100360_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_100361_AwakerVoiceContent = {
    Text = "Acı da sanattır..."
  },
  Voice_100361_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_100362_AwakerVoiceContent = {
    Text = "Ah! Görüyorum... Uçurum’un altında, göz bebeği olmayan Göz Bebeği’ni, evrenin son bakışını... Sadece bir an daha, Koruyucu, neredeyse bitti!"
  },
  Voice_100362_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_100362_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_100363_AwakerVoiceContent = {
    Text = "Fırçam, kaval kemiğimden yapılma. Paletim, yirmi farklı şehrin mezarlıklarından topladığım bu Ana Renk’ler... ve kıymetli deri tuvalim! Koruyucu, bunları al ve beni resmet! Hayır, hayır, Beceri’ye ihtiyacın yok... Ruhlarımız tuvalde buluştuğunda, bunun düşlerimin ötesinde bir şaheser olacağına inanıyorum...!"
  },
  Voice_100363_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_100363_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_100364_AwakerVoiceContent = {
    Text = "Ben ışığın gölgeye sızmasıyım. Ben pigment ve verniğin fısıltısıyım. Ben... resmeden açlığım!"
  },
  Voice_100364_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_100365_AwakerVoiceContent = {
    Text = "Bu Ana Rengi nasıl buldun?"
  },
  Voice_100365_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_100366_AwakerVoiceContent = {
    Text = "Sanatın gerçek özü Delilikte yatar...!"
  },
  Voice_100366_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_100367_AwakerVoiceContent = {
    Text = "Ne? Bir sonraki eserimde bedenin bu kısmına yakın plan mı öneriyorsun? Hımm... Bunu hiç düşünmemiştim! İyi fikir!"
  },
  Voice_100367_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_100368_AwakerVoiceContent = {Text = "Dikkat et!"},
  Voice_100368_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_100369_AwakerVoiceContent = {
    Text = "Sanatın gerçek özü Delilikte yatar...!"
  },
  Voice_100369_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_100370_AwakerVoiceContent = {Text = "Paletim!"},
  Voice_100370_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_100371_AwakerVoiceContent = {
    Text = "Ah! Şu keskin çene hattına bak! O parlak gözlere! Ve ideal oranlara sahip o bedene... üstelik ruhunun içinden taşan engin, yıldızlı gökyüzü... Ben Ressam Pickman’ım! Seni modelim olarak resmetme yüce onuruna erişebilir miyim?"
  },
  Voice_100371_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_100372_AwakerVoiceContent = {
    Text = "Sanatım delilik ve huzursuzlukla ilgilidir, ama şu Hameln’in müziği mezarlıktaki mezar taşları gibi sıkı ve düzenli. Yine de nedense, o düzenli notalarda hep evrenin en beter kaosunu görüyorum..."
  },
  Voice_100372_AwakerVoiceTitle = {
    Text = "Sohbet: Hameln Hakkında"
  },
  Voice_100372_UnlockDesc = {
    Text = "“Uyanış” Sanga elde edildikten sonra açılır"
  },
  Voice_100373_AwakerVoiceContent = {
    Text = "Bak, Koruyucu! Tuvaldeki o ebedi, çılgın sahne! Ne kadar güzel, ne kadar yıkıcı! Bu delilikten ve Pain’den filizlenen şey sanattır..."
  },
  Voice_100373_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_100373_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_100374_AwakerVoiceContent = {
    Text = "Ah! Öz-özür dilerim, Koruyucu... Sende... Uçurum’dan bile daha korkunç ve daha güzel bir şey görüyorum..."
  },
  Voice_100374_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_100374_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_100375_AwakerVoiceContent = {
    Text = "Anlamıyorum. Biri neden bir gule dönüşme fırsatını reddetsin ki?! Bu kanlı, çılgın güzellik, koca evde yaşayan sıkıcı bir insan olmaktan çok daha eğlenceli, değil mi?!"
  },
  Voice_100375_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_100376_AwakerVoiceContent = {Text = "Ha!"},
  Voice_100376_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_116964_AwakerVoiceContent = {
    Text = "Cezalandırma！"
  },
  Voice_116964_AwakerVoiceTitle = {
    Text = "Özel Beceri: I"
  },
  Voice_116965_AwakerVoiceContent = {
    Text = "Cezalandırma！"
  },
  Voice_116965_AwakerVoiceTitle = {
    Text = "Özel Beceri: II"
  },
  Voice_117791_AwakerVoiceContent = {
    Text = "Kabul ediyorum, onun çalma konusunda kaba saba bir becerisi var; ama benim gibi ince ruhlu bir hanımefendinin böyle aşağılık numaralara ihtiyacı yok. Bir şeyi arz edersem, onu bana \"gönüllü\" olarak teslim etmelerini sağlarım."
  },
  Voice_117791_AwakerVoiceTitle = {
    Text = "Sohbet: Jenkin Hakkında"
  },
  Voice_117791_UnlockDesc = {
    Text = "\"Jenkin\" Uyandıranı edinince açılır"
  },
  Voice_117792_AwakerVoiceContent = {
    Text = "Hahaha! Benim, hepsi benim! Tüm Mythag’ın şekerleri bana ait! Ne bekliyorsun? Büyük Şeker Cadısı’nı takip et! Şimdi hemen Londinium’daki her şekerciyi fethetmeye gidiyoruz!"
  },
  Voice_117792_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_117792_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_117793_AwakerVoiceContent = {
    Text = "Şeker yok mu? O hâlde bu Cadı ciddileşmek zorunda kalacak!"
  },
  Voice_117793_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_117794_AwakerVoiceContent = {
    Text = "İçinin dolgusu nasıl konuyor? Ne dikiş izi var ne iğne deliği! Keşke şu şeker mucitleri Mythag’ın kadrosuna katılsa da her gün benim için yeni bir tatlı icat etse!"
  },
  Voice_117794_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_117795_AwakerVoiceContent = {
    Text = "Cadıyla sakın oyun oynama!"
  },
  Voice_117795_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_117796_AwakerVoiceContent = {
    Text = "Eskiden şekeri, pastaya kıyasla fazla sade ve yeterince zarif bulmazdım; ama şimdi bu renkli plastik ambalajlara sarılı küçük şeyleri hafife aldığımı fark ettim. Raf ömürleri ne kadar uzun! İstediğim kadar stoklayabilirim, tüm odayı onlarla doldurabilirim!"
  },
  Voice_117796_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_117797_AwakerVoiceContent = {
    Text = "Yeni bir şeker mi buldun? Bakayım... Tsk, şu yüzük şeker ne kadar gülünç görünüyor! Yumurta büyüklüğünde bir “elmas” yüzük mü? Bekle! Bana yüzük takdim etmekten ne kastın var? Derhal kendini açıkla!"
  },
  Voice_117797_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_117797_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_117798_AwakerVoiceContent = {
    Text = "Cadıların gizemli bir kara kedisi olduğunu duydum. Ama o iğrenç kampüs serserisi kedi, benim gibi zarif bir hanımefendi için utanç verici. Öyleyse karar verildi. Şu {Male=erkek kedi,Female=kedi kız} saç bandını tak. Seni benim küçük kara kedim yapacağım."
  },
  Voice_117798_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_117798_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_117799_AwakerVoiceContent = {
    Text = "Direnç anlamsız."
  },
  Voice_117799_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_117800_AwakerVoiceContent = {
    Text = "BLIIİĞHHH!"
  },
  Voice_117800_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_117801_AwakerVoiceContent = {
    Text = "Gerçekten Cadılar var mı? Issız ormanlarda yaşıyorlarsa, yemeklerini, temizliklerini ve tatlı hazırlıklarını kim yapıyor? İkindi çayı bile veremeyeceksen, o hayatın ne anlamı var? Düşüncesine bile katlanamıyorum."
  },
  Voice_117801_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_117801_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_117802_AwakerVoiceContent = {
    Text = "Cadı geliyor!"
  },
  Voice_117802_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_117803_AwakerVoiceContent = {
    Text = "Hâlâ çikolatan mı var? Mükemmel, hepsini bana ver. Ne? Senin olan benim, benim olan da benim; bundan daha doğal ne olabilir?"
  },
  Voice_117803_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_117803_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_117804_AwakerVoiceContent = {
    Text = "En çok hangi şekeri seviyorum? Bir düşüneyim... Fındıklı krokanın kokusu nefis, karamelli çikolata çok lezzetli, o çilek ve üzüm aromalı yumuşak şekerlerin dokusu da oldukça eğlenceli, bir de çok uzun çekilebilen, rengi bal gibi güzel bir malt şekeri var... Hayır, seçim yapmayı reddediyorum. Her şekerin kendine özgü bir cazibesi var! Zaten elimde bir sürü balkabağı sepeti var, hepsini alırım gitsin!"
  },
  Voice_117804_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_117804_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_117805_AwakerVoiceContent = {
    Text = "Şu anki yaşam hedefim, dünyadaki her bir şekeri yemek. Dışarıda beni bekleyen sayısız şeker türünü düşünmek bile... yataktan kalkma sebebim bu. Pasta mı diyorsun? Pasta da diğer yaşam hedefim."
  },
  Voice_117805_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_117805_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_117806_AwakerVoiceContent = {
    Text = "Görünüşüne aldanma! Tulu çocuk gibi görünüyor ama neredeyse mezarın sakini sayılır. Yaşayan birinin zevk aldığı hiçbir şeye ihtiyacı yok, hele şeker hiç değil. Öyleyse ona ayrılan şekerleri... hepsini bana vermelisin. Onları gerçekten takdir edecek tek kişi benim."
  },
  Voice_117806_AwakerVoiceTitle = {
    Text = "Sohbet: Tulu Hakkında"
  },
  Voice_117806_UnlockDesc = {
    Text = "\"Tulu\" Uyandıranı edinince açılır"
  },
  Voice_117807_AwakerVoiceContent = {
    Text = "Ben bir cadı olsaydım, sarayım elbette ihtişamın zirvesi olurdu. Her gün benim için yeni pastalar ve şekerler yapmaları için on usta aşçı tutardım... Bunun beni cadıdan çok prenses yapacağını mı söylüyorsun? Ne olmuş yani? Ben de Prenses Cadı olurum!"
  },
  Voice_117807_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_117807_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_117808_AwakerVoiceContent = {
    Text = "Hey! Çabuk bana birkaç çeşit diş macunu getir! Hayır, o kadar çok şeker yemedim! Ve dişimde çürük yok! Sadece... uyurken biraz acıyor..."
  },
  Voice_117808_AwakerVoiceTitle = {
    Text = "Sohbet: Şeker Hakkında"
  },
  Voice_117809_AwakerVoiceContent = {
    Text = "Mythag’ın restoranındaki kurallar çoğu zaman sinir bozucu, ama pastacılık becerileri... hmm, zar zor geçer not alırlar, diyelim."
  },
  Voice_117809_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_117810_AwakerVoiceContent = {
    Text = "Dünya karanlık, iğrenç şeylerle dolu. Sonunu dert edeceğine, o vakti kullanıp olup bitmeden biraz daha şeker yemeye baksan daha iyi."
  },
  Voice_117810_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_117811_AwakerVoiceContent = {Text = "Ah!"},
  Voice_117811_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_117812_AwakerVoiceContent = {
    Text = "Artık pelüş kuzu postu halılar, siyah inci kolyeler ya da uzak doğudan ipek pijamalar yok... ama her gün, sepetlerin taştığı, şekerle dolu bir odada uyanmak... belki de gerçek mutluluk böyle bir şeydir...\nHey, o aptal sırıtışı yüzünden sil! Eğer bana sonsuza dek hizmet etmek istiyorsan, hâlâ yapman gereken çok iş var!"
  },
  Voice_117812_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_117812_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_117813_AwakerVoiceContent = {
    Text = "Şu alçak Mythag tayfası, şekerlerime erişimimi kesmeye cüret ediyor! Gördün mü? Sonunda yine de hepsini aldım!"
  },
  Voice_117813_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_117814_AwakerVoiceContent = {
    Text = "Şekerlerimden mi istiyorsun? Hmph. Cömert hissediyorum, belki sana bir parça bahşedebilirim... tabii güzelce yalvarırsan."
  },
  Voice_117814_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_117815_AwakerVoiceContent = {
    Text = "Buna nasıl “soygun” dersin? Ben sadece bir hanımefendinin Asil ayrıcalığını kullanıyorum!"
  },
  Voice_117815_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_117816_AwakerVoiceContent = {
    Text = "Adaletin Şeker Cadısı geldi! Kaybolmuş tüm tatlılar, yüce ve haklı sahiplerine Dönüş yapacak!"
  },
  Voice_117816_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_117817_AwakerVoiceContent = {
    Text = "Lanet olsun sana, pinti şey! Yüzünü aklımda tutacağım..."
  },
  Voice_117817_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_117818_AwakerVoiceContent = {
    Text = "O küçük fare nasıl oluyor da göz göre göre şeker çalabiliyor da ben yapamıyorum? Bu apaçık bir hanımefendiye karşı ayrımcılık! Böylesi saygısızlık olur mu!"
  },
  Voice_117818_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_117819_AwakerVoiceContent = {
    Text = "Şeker yok mu? O hâlde bu Cadı ciddileşmek zorunda kalacak!"
  },
  Voice_117819_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_117820_AwakerVoiceContent = {
    Text = "Al biraz şeker!"
  },
  Voice_117820_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_117821_AwakerVoiceContent = {
    Text = "O berbat garsonlardan çok daha düşüncelisin—hatta benim için özel şeker bile ayırmışsın. Böyle devam et, bana özel hizmetkârım."
  },
  Voice_117821_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_117821_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_117822_AwakerVoiceContent = {
    Text = "BLIIİĞHHH!"
  },
  Voice_117822_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_117823_AwakerVoiceContent = {
    Text = "Bu da biraz fazla!"
  },
  Voice_117823_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_117824_AwakerVoiceContent = {
    Text = "Neden beni durduruyorsun? Sadık hizmetkârım olarak, tüm şekerleri soymama... yani, ele geçirmeme aktif biçimde yardım etmen gerekmiyor mu?"
  },
  Voice_117824_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_117825_AwakerVoiceContent = {
    Text = "Dur! Bu bir soygun! Akıllı olmanı ve bütün şekerlerini usulca teslim etmeni tavsiye ederim, yoksa... Hıh."
  },
  Voice_117825_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_117826_AwakerVoiceContent = {
    Text = "Yumuşak, Zor, kıtır, gevrek, sütlü, meyveli, fındıklı, çikolatalı... Ah, tadına bakmadığım nasıl bu kadar çok çeşit olabilir? Karar verdim: Mythag Cadılar Bayramı’nı haftalık bir bayram yapmak zorunda!"
  },
  Voice_117826_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_117827_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_117827_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_117828_AwakerVoiceContent = {
    Text = "Büyük Cadı zafer kazanacak! Yüce şeker tanrısı beni korur, ben de tüm şekerleri korurum! AHAHAHA!"
  },
  Voice_117828_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_117829_AwakerVoiceContent = {
    Text = "Direnç anlamsız."
  },
  Voice_117829_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_117830_AwakerVoiceContent = {
    Text = "Tüm şekerler eninde sonunda bana ait olacak!"
  },
  Voice_117830_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_117831_AwakerVoiceContent = {
    Text = "O çocuk ürkütücü derecede itaatkâr. Tüm şekerlerini hemen veriyor... bu da aslında bende hafif bir suçluluk hissi uyandırıyor. Öhöm! Yani, madem bu kadar akıllı uslu, merhametli Cadı elbette ona da biraz şeker bırakacaktır... küçük bir ödül olarak!"
  },
  Voice_117831_AwakerVoiceTitle = {
    Text = "Sohbet: Lily Hakkında"
  },
  Voice_117831_UnlockDesc = {
    Text = "\"Lily\" Uyandıranı edinince açılır"
  },
  Voice_117832_AwakerVoiceContent = {
    Text = "Cadıyla sakın oyun oynama!"
  },
  Voice_117832_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_117833_AwakerVoiceContent = {
    Text = "Artık resmen öfkeliyim!"
  },
  Voice_117833_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_117834_AwakerVoiceContent = {
    Text = "Tüm şekerler eninde sonunda bana ait olacak!"
  },
  Voice_117834_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_117835_AwakerVoiceContent = {
    Text = "Ne? Bu tür bir marshmallow’u közleyebiliyor musun? Ama sıcacık ve yapış yapış olacak... Gerçekten tadı güzel mi? Tadına bakayım... Pekâlâ, küçücük bir ısırık alacağım. Eğer beni kandırmaya cüret edersen... Ha?! Bu yumuşak ve çıtır doku gerçekten harika!"
  },
  Voice_117835_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_117835_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_122115_AwakerVoiceContent = {
    Text = "Düş, Tersyüz... Bunlar Kader’in aletleridir!"
  },
  Voice_122115_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_122117_AwakerVoiceContent = {
    Text = "Düş, Tersyüz... Bunlar Kader’in aletleridir!"
  },
  Voice_122117_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_123312_AwakerVoiceContent = {
    Text = "Gerçek benliğim seni korkutmuyor, çünkü “gerçek dehşeti görmüşsün”, öyle mi? Hımpf... kurnaz bir cevap. Ama bu da bende... seni daha da parçalarına ayırma isteği uyandırıyor."
  },
  Voice_123312_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_123312_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_123313_AwakerVoiceContent = {
    Text = "Dünya senin gözlerinde nasıl görünüyor? Gerçek dehşetin sınırları nerede? Bana sadece anlatma; seninle birlikte gidip bizzat hissetmek istiyorum, tüm o deliliği, ölümü ve dehşeti! Evet, kararımı verdim! Merakım yatışana kadar yanından ayrılmayacağım!"
  },
  Voice_123313_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_123313_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_123314_AwakerVoiceContent = {
    Text = "Kontrol edilemeyen bir manyak mı? Tam isabet! Burası benim dünyam değil; sıkıcı yasalar, kurallar beni tutamaz... Burada canım ne isterse onu yaparım. O yüzden dikkatli ol, Koruyucu, bir manyağın ne zaman ısıracağını asla bilemezsin."
  },
  Voice_123314_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_123314_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_123315_AwakerVoiceContent = {
    Text = "Ruh sağlığım için derin bir sohbet mi istiyorsun? Hadi ama, beni bundan kurtar. Madem sıkılacağız, bari çabuk bitirelim."
  },
  Voice_123315_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_123315_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_123316_AwakerVoiceContent = {
    Text = "Sorularına cevap verirken normalmiş gibi yaptığımı mı söylüyorsun? Heh, yakaladın beni. Peki, gerçekten ne olduğumu görmeye hazır mısın?"
  },
  Voice_123316_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_123316_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_123770_AwakerVoiceContent = {
    Text = "Kafanı uçuracağım."
  },
  Voice_123770_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_123771_AwakerVoiceContent = {
    Text = "İşte herkesin favorisi—Parlayan☆Kasırga!"
  },
  Voice_123771_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_123772_AwakerVoiceContent = {
    Text = "Bu ben olmamalıydı..."
  },
  Voice_123772_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_123773_AwakerVoiceContent = {
    Text = "Parlayan☆Parçalama!"
  },
  Voice_123773_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_123774_AwakerVoiceContent = {
    Text = "Bu çarpık, dehşet verici dünyayı kurtarmak mı istiyorsun? Delicesine eğlenceli bir ölüm yolu olacak. Bakalım ne kadar ileri gidebileceksin."
  },
  Voice_123774_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_123775_AwakerVoiceContent = {
    Text = "Baltamın tadına bakmak ister misiniz, cicilerim? Korkmayın, geliyor..."
  },
  Voice_123775_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_123776_AwakerVoiceContent = {
    Text = "Koruyucu, sanırım bir ışık gördüm... Bu sefer işe yaradı mı...? Acaba meslektaşlarım ne hâlde? Ben yokken masanın üstüne iş yığını bırakmasınlar, mesaiye kalmam."
  },
  Voice_123776_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_123776_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_123777_AwakerVoiceContent = {
    Text = "Bu ayin beni yurda geri mi yollayacak? Emin misin? Kaç kere denedik ki...? Neyse, denemekten zarar gelmez sanırım."
  },
  Voice_123777_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_123777_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_123778_AwakerVoiceContent = {
    Text = "Haha, işte hayat dediğin böyle olur! O sıkıcı günlük koşuşturmanın eline su dökemez!"
  },
  Voice_123778_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_123779_AwakerVoiceContent = {Text = "Ha!"},
  Voice_123779_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_123780_AwakerVoiceContent = {
    Text = "Bu ben olmamalıydı..."
  },
  Voice_123780_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_123781_AwakerVoiceContent = {
    Text = "Parlayan☆Süpernova—PATLAMA!"
  },
  Voice_123781_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_123782_AwakerVoiceContent = {
    Text = "İşte herkesin favorisi—Parlayan☆Kasırga!"
  },
  Voice_123782_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_123783_AwakerVoiceContent = {
    Text = "Sanki yeniden Sise adım atıyormuşum gibi hissediyorum. Madem konu açıldı, Sisteki o küçük yaratıkları şimdiden özledim. Artık kötü modumu onlardan çıkaramayacak olmam ne yazık."
  },
  Voice_123783_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_123783_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_123784_AwakerVoiceContent = {
    Text = "Nefret mi? Öyle demem. Sadece o yorucu toplantıların, sosyal yükümlülüklerin ve evrensel değerlerin bir gün Hepsi Yok Olsun! diye yok olmasını diliyorum."
  },
  Voice_123784_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_123785_AwakerVoiceContent = {
    Text = "İşte bu... \"gerçek benliğime\" yaklaşıyorum. Hissedebiliyorum..."
  },
  Voice_123785_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_123786_AwakerVoiceContent = {
    Text = "Ah... Demek yine olmadı. Bekliyordum zaten. Can iniş çıkışlarla dolu—gerçi daha çok iniş... Bir gün alışıyorsun. Yine de, denediğin için sağ ol."
  },
  Voice_123786_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_123786_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_123787_AwakerVoiceContent = {
    Text = "Çözünme hakkında bildiğim, memleketteki Sis Felaketi hakkında bildiğim kadar—yani hiçbir şey. Ama işte tam da bu onları böylesine büyüleyici kılıyor, değil mi?"
  },
  Voice_123787_AwakerVoiceTitle = {
    Text = "Sohbet: Kriz Hakkında"
  },
  Voice_123788_AwakerVoiceContent = {
    Text = "Adım Mouchette, müfettiş... Aa evet, artık A.U.G.E.'nin ön saflarında değilim. Kendimi yeniden tanıtayım—Ben Mouchette, sadece tatlı, sevimli bir kız çocuğuyum."
  },
  Voice_123788_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_123789_AwakerVoiceContent = {Text = "Uzak dur!"},
  Voice_123789_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_123790_AwakerVoiceContent = {
    Text = "Burada insan Yerleşimlerine fazlasıyla yakınız; sıkıcı yetişkinler her yerde... Okulu ıssız, derin Sıradağlara taşımayı hiç düşündün mü?"
  },
  Voice_123790_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_123791_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_123791_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_123792_AwakerVoiceContent = {
    Text = "Başka bir dünyada mahsur kalma hissine âşık olmaya başlıyorum! Güçlü Uyanışçılar, dehşet verici Çözünme ve esrarengiz tanrılar! Ah, sıradanlıktan bu kadar uzak olmanın salt coşkusu!"
  },
  Voice_123792_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_123793_AwakerVoiceContent = {
    Text = "Hepsi bu mu? Daha yeni eğlenmeye başlamıştım! Hadi, sıradaki kelle kim?"
  },
  Voice_123793_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_123794_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_123794_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_123795_AwakerVoiceContent = {
    Text = "Derler ki tek bir başarısızlık seni tanımlamaz... Katılmıyorum! Tanımı benim baltam yapacak, o yüzden boyunlarınızı tetikte tutun!"
  },
  Voice_123795_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_123796_AwakerVoiceContent = {
    Text = "Yeni görev mi? Bir dahaki sefere nezaket gösterilerini atla; artık çoktan şu \"sosyalleşme ayinlerini\" icra etmemize gerek kalmadı."
  },
  Voice_123796_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_123797_AwakerVoiceContent = {
    Text = "Başkaları için kendini feda etmek mi? Ne aptalca bir fikir. Öfke verici. Bunu kimseden istemeye kimsenin hakkı yok, bir tanrının bile."
  },
  Voice_123797_AwakerVoiceTitle = {
    Text = "Sohbet: Salvador Hakkında"
  },
  Voice_123797_UnlockDesc = {
    Text = "Uyanışçı \"Salvador\" elde edildikten sonra açılır"
  },
  Voice_123798_AwakerVoiceContent = {
    Text = "Hah, fena değil..."
  },
  Voice_123798_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_123799_AwakerVoiceContent = {
    Text = "Hepsi bu kadar mı? Artık rol yapmaya gerek yok... Şimdi, biraz <Italic:gerçek> eğlenelim."
  },
  Voice_123799_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_123800_AwakerVoiceContent = {
    Text = "Ayin hâlâ bitmedi mi? Gerçekten geri dönmek istiyorum. Son zamanlarda Ravenlog Balık Yahnisi ve dumanı tüten Fındıklı Kava Çayı çekiyorum canım. Yine de, buradaki Seylan Siyah Çayı ve Endülüs Churrosu da fena sayılmaz."
  },
  Voice_123800_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_123800_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_123801_AwakerVoiceContent = {
    Text = "Demek hâlâ beni inşa ediyorsun. Bir gün kontrolden çıkmamdan korkmuyor musun? Şaka yaptım... Haha!"
  },
  Voice_123801_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_123802_AwakerVoiceContent = {
    Text = "Bilirsin, bir süre daha burada kalmak o kadar da kötü görünmüyor. Burada olan her şeyi hatırlayacağım, yazacağım ve yurttakilerle paylaşacağım. Başlık olarak <Italic:Mouchette’in Öte Dünya Macerası> nasıl? Kulağa hoş geliyor, değil mi?"
  },
  Voice_123802_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_123802_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_123803_AwakerVoiceContent = {
    Text = "Kabul ediyorum, oldukça sevimli... Evet, kampüsteki başıboşların peşine düşüp onlarla dövüşürken gerçekten çok tatlı."
  },
  Voice_123803_AwakerVoiceTitle = {
    Text = "Sohbet: Murphy Hakkında"
  },
  Voice_123803_UnlockDesc = {
    Text = "Uyanışçı \"Murphy\" edinildiğinde açılır"
  },
  Voice_123804_AwakerVoiceContent = {
    Text = "Hâlâ burada sıkışıp kaldım ama, güçlenmek her zaman güzeldir."
  },
  Voice_123804_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_123805_AwakerVoiceContent = {
    Text = "Bir hizmetçi mi? Ben de öyleydim. Savaşta ona elektrikli süpürge hareketlerimi göstermeye vakit bulmalıyım!"
  },
  Voice_123805_AwakerVoiceTitle = {
    Text = "Sohbet: Karen Hakkında"
  },
  Voice_123805_UnlockDesc = {
    Text = "Uyanışçı \"Karen\" edinildiğinde açılır"
  },
  Voice_123806_AwakerVoiceContent = {
    Text = "Haha, işte hayat dediğin böyle olur! O sıkıcı günlük koşuşturmanın eline su dökemez!"
  },
  Voice_123806_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_124737_AwakerVoiceContent = {
    Text = "Bir darbe, bir öldür."
  },
  Voice_124737_AwakerVoiceTitle = {
    Text = "Özel Beceri: II"
  },
  Voice_124738_AwakerVoiceContent = {
    Text = "Baltam için güzelce sıraya girin!"
  },
  Voice_124738_AwakerVoiceTitle = {
    Text = "Özel Beceri: I"
  },
  Voice_124769_AwakerVoiceContent = {Text = "Kaybol!"},
  Voice_124769_AwakerVoiceTitle = {
    Text = "Özel Beceri: I"
  },
  Voice_126946_AwakerVoiceContent = {
    Text = "Düşünme, Tasalanma; Körce Dinle, Dilsizce İtaat Et, çünkü Fani Döngü yalnızca Yüktür!"
  },
  Voice_126946_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_126947_AwakerVoiceContent = {
    Text = "Düşünme, Tasalanma; Körce Dinle, Dilsizce İtaat Et, çünkü Fani Döngü yalnızca Yüktür!"
  },
  Voice_126947_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_126948_AwakerVoiceContent = {
    Text = "Neden Kafatasları bu denli boş, diye soruyorsun? Hm, belki de bu yalnızca onların doğasıdır."
  },
  Voice_126948_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_126949_AwakerVoiceContent = {
    Text = "Ne Gazap çek, ne de Kin besle; zira Her Şey Hiçliktir."
  },
  Voice_126949_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_126950_AwakerVoiceContent = {
    Text = "Böylesine dikkatli oluşun, seni daha da fazla kızdırmak istememe yol açıyor."
  },
  Voice_126950_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_126951_AwakerVoiceContent = {Text = "Eyvah!"},
  Voice_126951_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_126952_AwakerVoiceContent = {
    Text = "Benden daha büyük bir güzellik mi bekliyorsun, yoksa daha büyük bir dehşet mi?"
  },
  Voice_126952_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_126953_AwakerVoiceContent = {
    Text = "Bir zamanlar Hazdan doğmuş bir Prenses vardı. Giysileri altınla işlenmişti, teni fildişi gibiydi, çevresinde öd ağacının kokusu gezinirdi ve bakışının tek bir süpürmesi bir ruhu çalmaya yeterdi."
  },
  Voice_126953_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_126953_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_126954_AwakerVoiceContent = {
    Text = "Bu eğlenceden de çabucak sıkıldı. Müritleri aynı tiyatroyu durmadan tekrar ediyordu; Şehvetten doğan Aşk ya da Aşktan doğan Şehvet tarafından tüketilmişlerdi. Aptallıkları—ihanet ve kayıp yüzünden parçalanan yürekleri—onu sıkıyordu. Gözyaşları da öyle."
  },
  Voice_126954_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_126954_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_126955_AwakerVoiceContent = {
    Text = "Böylesine küçük, sıradan zihinlerin bakışı benim için tam bir eziyet."
  },
  Voice_126955_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_126956_AwakerVoiceContent = {
    Text = "O Kırmızılı Madam bir zamanlar salonlarına birkaç davetiye göndermişti.\nYabancı tatlılar fena sayılmazdı, ama...\nEvinde \"tatlılar\" ile \"hizmetkârlar\"ın aynı şey olmadığını bana daha önce söylemeliydi."
  },
  Voice_126956_AwakerVoiceTitle = {
    Text = "Sohbet: Sorel Hakkında"
  },
  Voice_126956_UnlockDesc = {
    Text = "\"Sorel\" Uyandıranı edinince açılır"
  },
  Voice_126958_AwakerVoiceContent = {
    Text = "Beni sevmiyor musun? O halde kuşatıldığında neden siniyorsun? Benden nefret etmiyor musun? O halde dönüş yokken neden ağlıyorsun?\nAh, şimdi gölgemden mi korkuyorsun? Beyaz manolyaların kokusu senin için boğucu, anlaşılmaz bir miske mi dönüştü?"
  },
  Voice_126958_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_126958_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_126959_AwakerVoiceContent = {Text = "Elbette."},
  Voice_126959_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_126960_AwakerVoiceContent = {
    Text = "Oh? Neden kollarının altında o izleri taşıdıklarını mı soruyorsun? Bunu son derece eğlendirici bulmuyor musun?"
  },
  Voice_126960_AwakerVoiceTitle = {
    Text = "Sohbet: Kabaran Lütuf Tarikatı"
  },
  Voice_126961_AwakerVoiceContent = {Text = "Eyvah!"},
  Voice_126961_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_126963_AwakerVoiceContent = {
    Text = "Bu ufak eğlenceler, müritlerimin sunduğu sunulardan çok daha fazla hoşuma gidiyor."
  },
  Voice_126963_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_126964_AwakerVoiceContent = {
    Text = "Önce Duruşlarını, sonra Şekillerini, ta ki onlar da bir çift... ya da daha doğrusu, geriye hatırlanmaya değer tek şey, benimkiler gibi güzel, Ruh Çalan Gözler—bir çift göz kalana dek."
  },
  Voice_126964_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_126964_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_126965_AwakerVoiceContent = {
    Text = "Bugün son derece sıkıldım. Gerçekleştirmemi istediğin bir dileğin yok mu?\n\nYokmuş, ne yazık. Çok daha önemsiz amaçlar için tırpanı sallamaya ve bana tatlı ikram etmeye istekli olan o kadar çok kişi var.\nAma eğer isteyen sensen..."
  },
  Voice_126965_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_126965_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_126966_AwakerVoiceContent = {
    Text = "Kabaran Lütuf Tarikatı neden beni takip ediyor ve nasıl doğdu? Eğlenceli bir soru. Sen de ulaşılamaz birini tanıdın mı, ya da başarısız bir mücadelenin pişmanlığını yaşadın mı?\nHmm, öyle görünmüyor. Ne israf. O çaresiz mücadele ifadesi—senin yüzünde görmek çok eğlenceli olurdu."
  },
  Voice_126966_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_126966_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_126967_AwakerVoiceContent = {
    Text = "...Eğer böyle izinsiz girmeyi sürdürürsen, senin uğruna kuşandığım suret, pek de hoşuna gidecek halde kalmayabilir."
  },
  Voice_126967_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_126968_AwakerVoiceContent = {
    Text = "Onun hikâyesini neredeyse tümüyle unuttum, ama o bir Vecd, bir Zalimlik hikâyesiydi; Terk Ediliş ve Hesaplaşma ile başlayan, Kurban ve Kör İtaat ile son bulan bir hikâye."
  },
  Voice_126968_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_126968_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_126969_AwakerVoiceContent = {
    Text = "Eğlendirin beni. Acı ve dehşet içinde birbirinizi katledin!"
  },
  Voice_126969_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_126970_AwakerVoiceContent = {
    Text = "...Hiç değilse bu, bende hafif bir ilgi kıvılcımı uyandırıyor."
  },
  Voice_126970_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_126971_AwakerVoiceContent = {
    Text = "Yelpazemin altında her ruh, en değer verdiği kişinin yüzünü görür. Bu gücü zayıflara ödünç veririm, kendi eğlencem için bir bıçak gibi kullansınlar diye.\n\nAma belki—sadece belki diyorum. Eğer sen buna kapılsaydın, gerçek, saf bir Vecdi tanırdım."
  },
  Voice_126971_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_126971_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_126972_AwakerVoiceContent = {
    Text = "Kendini üzme; sen o sıradan kalabalıktan değilsin. \nSus. Arkama bakma. Görünmeyen okşamaya aldırma. Gözlerime bak, sadece gözlerime."
  },
  Voice_126972_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_126972_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_126973_AwakerVoiceContent = {
    Text = "Hehe... İçinizden hiçbiri gerçek suretime bakmaya cüret ediyor mu?"
  },
  Voice_126973_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_126975_AwakerVoiceContent = {
    Text = "Gürültücüsün."
  },
  Voice_126975_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_126976_AwakerVoiceContent = {
    Text = "Ah, yine yelpazeme büyülenmiş bakıyorsun? Hehe. Kimin yüzünü istersen, sana göstereyim. Gel, daha yaklaş—\nOh? Reddediyor musun? Ne soğuk sözler, ama ne sevimli bir ifade..."
  },
  Voice_126976_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_126976_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_126977_AwakerVoiceContent = {
    Text = "Benim Rüyasız Diyar’ımda ne arıyorsun?"
  },
  Voice_126977_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_126978_AwakerVoiceContent = {
    Text = "Ne Gazap çek, ne de Kin besle; zira Her Şey Hiçliktir."
  },
  Voice_126978_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_126979_AwakerVoiceContent = {
    Text = "Küstahlığını dizginle."
  },
  Voice_126979_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_126980_AwakerVoiceContent = {Text = "Elbette."},
  Voice_126980_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_126981_AwakerVoiceContent = {
    Text = "Benim de bir zamanlar böyle güzel, uysal bir kızım vardı. Baştan çıkarıcı bir çiçek tomurcuğu, elbette birkaç dikene ihtiyacı vardı—öylece bir vazonun içine konulamazdı."
  },
  Voice_126981_AwakerVoiceTitle = {
    Text = "Sohbet: Lily Hakkında"
  },
  Voice_126981_UnlockDesc = {
    Text = "\"Lily\" Uyandıranı edinince açılır"
  },
  Voice_126982_AwakerVoiceContent = {
    Text = "Üniversite, psikolojik terapi ofisi için yaptığım başvuruyu ne kadar da kesin bir dille reddetti. Ne tuhaf; acaba ne gibi bir itirazları olabilir?"
  },
  Voice_126982_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_126983_AwakerVoiceContent = {
    Text = "Her şey Boşluk'ta son bulur. O zamana kadar neden benimle biraz daha zevk aramıyorsun?\n\nİçin rahat olsun, Çözünme'ye daha fazla direnemeyeceğin gün geldiğinde, Onun seni önce almasına izin vermeyeceğim."
  },
  Voice_126983_AwakerVoiceTitle = {
    Text = "Sohbet: Kriz Hakkında"
  },
  Voice_126984_AwakerVoiceContent = {Text = "Sıkıcı."},
  Voice_126984_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_126985_AwakerVoiceContent = {
    Text = "Sen gerçekten bir harikasın, yıkıma mahkûm bir dünyada bedensel önemsizliklerle bu kadar meşgul olmak.\n\nBeni de ilgilenmeye mecbur ediyor."
  },
  Voice_126985_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_126985_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_126986_AwakerVoiceContent = {Text = "İlerleme!"},
  Voice_126986_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_126988_AwakerVoiceContent = {
    Text = "Ben, Rüyasız Diyar’ın Hanımı Xu. Eğer kalbinde, görmeyi arzuladığın ama asla erişemediğin biri varsa, yelpazemi indirecek ve sana ondan bir kesit sunacağım."
  },
  Voice_126988_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_127088_AwakerVoiceContent = {
    Text = "Tüm yeni doğmuş varlıklar baş belasıdır. Küçük, yumuşak, gürültücü; bilinçsizce etraflarındaki her şeye hükmederler.\n\nGösteriden hoşlanırım, ama kesinlikle bu türden değil. Lütfen, onları uzak, çok uzak tutun."
  },
  Voice_127088_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_127089_AwakerVoiceContent = {
    Text = "Sen mi? Sen benim küçük Yasemin'imsin, itaatkâr sevgilim, büyük bir zevkle katıldığım o hoş ev oyunu...\nAh, sadece mutlu sayıklamalar. Lütfen aldırış etmeyin."
  },
  Voice_127089_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_127090_AwakerVoiceContent = {
    Text = "Panlong İmparatorluğu'nun efsanelerinde tavus kuşu yakışıklı, gösterişli ve kötü niyetli bir yaratıktır. Güzel ve acımasız—kalbi hızlandırır. Çirkin ve iyi kalpli olmak ise oldukça sıkıcıdır."
  },
  Voice_127090_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_129651_AwakerVoiceContent = {
    Text = "Silip süpür! Nefis nefis!"
  },
  Voice_129651_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_129652_AwakerVoiceContent = {Text = "Gurg gurg~"},
  Voice_129652_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_129653_AwakerVoiceContent = {
    Text = "Coalsie, ben, yer, birlikte? Birlikte!"
  },
  Voice_129653_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_129653_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_129654_AwakerVoiceContent = {
    Text = "Girdap! Çok güçlü!"
  },
  Voice_129654_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_129655_AwakerVoiceContent = {
    Text = "Uçurum! Sarmal! Yok oldu, her şey—hepsi bir Girdap oldu!"
  },
  Voice_129655_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_129656_AwakerVoiceContent = {Text = "Ah!"},
  Voice_129656_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_129657_AwakerVoiceContent = {
    Text = "Dokunma! Kırılma!"
  },
  Voice_129657_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_129657_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_129658_AwakerVoiceContent = {
    Text = "Kabuk, pırıl pırıl! Güzel! Sana, ver!"
  },
  Voice_129658_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_129658_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_129659_AwakerVoiceContent = {
    Text = "Soğuk, korkunç. Vortice, saklanma!"
  },
  Voice_129659_AwakerVoiceTitle = {
    Text = "Sohbet: Doll Hakkında"
  },
  Voice_129659_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Doll\" elde edildikten sonra açılır"
  },
  Voice_129660_AwakerVoiceContent = {Text = "Yaşasın!"},
  Voice_129660_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_129661_AwakerVoiceContent = {
    Text = "Av! Kötü! Kırılma! Vortice, vur onlara, kırılma!"
  },
  Voice_129661_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_129662_AwakerVoiceContent = {
    Text = "Çok eğlenceli! Bir dahakine! Daha çok!"
  },
  Voice_129662_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_129662_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_129663_AwakerVoiceContent = {
    Text = "Pıt pıt, iyi! Vortice, seni, pıt pıt!"
  },
  Voice_129663_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_129664_AwakerVoiceContent = {
    Text = "Hayır, hayır! Coalsie, Vortice korur!"
  },
  Voice_129664_AwakerVoiceTitle = {
    Text = "Sohbet: Kriz Hakkında"
  },
  Voice_129665_AwakerVoiceContent = {
    Text = "Yine mi? Yine!"
  },
  Voice_129665_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_129666_AwakerVoiceContent = {
    Text = "Hehe, Girdap, oyna oyna!"
  },
  Voice_129666_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_129667_AwakerVoiceContent = {
    Text = "Kocaman bir dalga geliyor!"
  },
  Voice_129667_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_129668_AwakerVoiceContent = {Text = "Bang!"},
  Voice_129668_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_129669_AwakerVoiceContent = {Text = "Ah!"},
  Voice_129669_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_129670_AwakerVoiceContent = {Text = "İiiih!"},
  Voice_129670_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_129671_AwakerVoiceContent = {
    Text = "Ayin mi?! Beni götür!"
  },
  Voice_129671_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_129671_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_129672_AwakerVoiceContent = {
    Text = "Girdap! Güçlü! İyi!"
  },
  Voice_129672_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_129672_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_129673_AwakerVoiceContent = {Text = "Bang!"},
  Voice_129673_AwakerVoiceTitle = {
    Text = "Özel Beceri: I"
  },
  Voice_129674_AwakerVoiceContent = {Text = "Yaşasın!"},
  Voice_129674_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_129675_AwakerVoiceContent = {
    Text = "Fışş fışş~"
  },
  Voice_129675_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_129676_AwakerVoiceContent = {Text = "Dövüş!"},
  Voice_129676_AwakerVoiceTitle = {
    Text = "Sohbet: Golyat Hakkında"
  },
  Voice_129676_UnlockDesc = {
    Text = "\"Golyat\" Uyandıranı edinince açılır"
  },
  Voice_129677_AwakerVoiceContent = {
    Text = "Çok, pırıl pırıl bul!"
  },
  Voice_129677_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_129677_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_129678_AwakerVoiceContent = {
    Text = "Uçurum! Sarmal! Yok oldu, her şey—hepsi bir Girdap oldu!"
  },
  Voice_129678_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_129679_AwakerVoiceContent = {Text = "Yahoo!"},
  Voice_129679_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_129680_AwakerVoiceContent = {Text = "İiiih!"},
  Voice_129680_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_129681_AwakerVoiceContent = {
    Text = "Girdap! Çok güçlü!"
  },
  Voice_129681_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_129682_AwakerVoiceContent = {
    Text = "Silip süpür! Nefis nefis!"
  },
  Voice_129682_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_129683_AwakerVoiceContent = {
    Text = "Nautilus, Nautila, Coalsie! Pırıllar!"
  },
  Voice_129683_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_129684_AwakerVoiceContent = {
    Text = "Vortice, doldur!"
  },
  Voice_129684_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_129685_AwakerVoiceContent = {
    Text = "Girdap, hepsini yıka götür!"
  },
  Voice_129685_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_129686_AwakerVoiceContent = {
    Text = "Sarılma! Vortice! Seviyor!"
  },
  Voice_129686_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_129686_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_129687_AwakerVoiceContent = {
    Text = "Coalsie, arkadaş! Vortice, sonsuza dek!"
  },
  Voice_129687_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_129688_AwakerVoiceContent = {
    Text = "Çabuk, çabuk!"
  },
  Voice_129688_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_129688_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_129689_AwakerVoiceContent = {
    Text = "Vortice! Coalsie! Birlikte, hep? Sonsuza dek!"
  },
  Voice_129689_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_129689_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_129690_AwakerVoiceContent = {
    Text = "Fışş fışş~ Kocaman dalga yüksel!"
  },
  Voice_129690_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_129690_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_129691_AwakerVoiceContent = {
    Text = "Arkadaşlar! Çok! Seviyor!"
  },
  Voice_129691_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_129692_AwakerVoiceContent = {
    Text = "Girdap! Harika!"
  },
  Voice_129692_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_129693_AwakerVoiceContent = {
    Text = "Nautila, özledim seni... Ha? Nautila, Vortice, burada, Vortice, BURADA!"
  },
  Voice_129693_AwakerVoiceTitle = {
    Text = "Sohbet: Nautila Hakkında"
  },
  Voice_129693_UnlockDesc = {
    Text = "\"Nautila\" Uyandıranı edinince açılır"
  },
  Voice_129694_AwakerVoiceContent = {
    Text = "Girdap! Güçlü!"
  },
  Voice_129694_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_129695_AwakerVoiceContent = {
    Text = "Ben! Girdap! Yahoo!"
  },
  Voice_129695_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_130511_AwakerVoiceContent = {Text = "Püf—"},
  Voice_130511_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_133720_AwakerVoiceContent = {
    Text = "Hata düzeltilmeli."
  },
  Voice_133720_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_133721_AwakerVoiceContent = {
    Text = "Önündeki trajedi, sayısız olasılık arasında yalnızca bir bakıştan ibaret.\n\nKaderin perdesinin ardında karanlığa yutulmuş bir sahne var—\nışıklar sönmüş, oyuncular gitmiş, her şey derinlere geri dönmüş.\n\nAma son burası değil.\nIşıkların geri döneceği güne dek bu nankör emeğe katlanma kararlılığını taşıyorum."
  },
  Voice_133721_AwakerVoiceTitle = {
    Text = "Sohbet: Kriz Hakkında"
  },
  Voice_133722_AwakerVoiceContent = {
    Text = "Her ruhun kaderi ipliklerle taşınır... ama seninki çözemediğim bir senaryo. Bu dünyaya ne gibi bir doğaçlama getireceğini merakla bekliyorum."
  },
  Voice_133722_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_133723_AwakerVoiceContent = {
    Text = "Sahne her zaman senindi. Öne çık, sevgili kukla."
  },
  Voice_133723_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_133724_AwakerVoiceContent = {Text = "Hm?"},
  Voice_133724_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_133725_AwakerVoiceContent = {
    Text = "Her şey geçmiş bir son söz. Her şey yeni bir önsöz. Aramızdaki yeni bölüm senin yazmanı bekliyor, Koruyucu."
  },
  Voice_133725_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_133725_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_133726_AwakerVoiceContent = {
    Text = "Komedi hoşuna gidiyorsa, <Italic:Bir Yaz Gecesi Rüyası> tam sana göre olur. Ben özellikle Puck'ın yaramaz gevezeliklerine bayılırım—bir perenin kahkahasının ardına gizlenmiş kader, her zaman bir şeyleri ağzından kaçırır."
  },
  Voice_133726_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_133726_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_133727_AwakerVoiceContent = {
    Text = "Buna boyun eğ."
  },
  Voice_133727_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_133728_AwakerVoiceContent = {
    Text = "Kaderin iği şimdi dönüyor."
  },
  Voice_133728_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_133729_AwakerVoiceContent = {
    Text = "Kaderin tutsağı, her zamanki gibi acınası... yazılmış olan reddedilemez."
  },
  Voice_133729_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_133730_AwakerVoiceContent = {
    Text = "Her şeyi izleyen biri bile kendi senaryosunda beceriksiz bir oyuncu olarak kalır. Kaderin ağını tutmak, ama ipliklerine bağlı olmak—bu kadersel durumda farklı yollardan yürüyoruz, ama ikimiz de nankör uğraşlarımızı gerçekten hiç terk etmedik. Belki aptallık. Belki yanılsama. Benim için de böyle, onun için de böyle."
  },
  Voice_133730_AwakerVoiceTitle = {
    Text = "Sohbet: Tawil Hakkında"
  },
  Voice_133730_UnlockDesc = {
    Text = "Uyanışçı \"Tawil\" edinildiğinde açılır"
  },
  Voice_133731_AwakerVoiceContent = {
    Text = "Beklenmedik bir dönüş mü?"
  },
  Voice_133731_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_133732_AwakerVoiceContent = {
    Text = "Bunca açılıp kapanan perdede bana eşlik ettiğin için teşekkür ederim. Seni hayal kırıklığına uğratmayacağım—daha nice akşamlar var ki seni beklenmedik şekillerde duygulandıracak."
  },
  Voice_133732_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_133732_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_133733_AwakerVoiceContent = {
    Text = "Ne yetenekli bir şarkıcı. Lütufla verilmiş bir ses; berrak ve yakıcı, sanki kaderin kendisinden yükseliyor. Tiyatromda sahneye çıksa, en titiz seyirciyi bile hazırlıksız yakalayacağını düşünüyorum."
  },
  Voice_133733_AwakerVoiceTitle = {
    Text = "Sohbet: Tinktur Hakkında"
  },
  Voice_133733_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Tinct\" elde edildikten sonra açılır"
  },
  Voice_133734_AwakerVoiceContent = {
    Text = "Sana ve bana ait görünmez ipler çoktan birbirine sıkıca dolanmış; aynı anda hem bir kafes hem de bir yol örmüş.\nKafesin nerede bittiğini de, yolun nereye çıktığını da göremiyorum.\nBu hikâyeyi bu denli büyüleyici kılan da tam olarak bu."
  },
  Voice_133734_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_133734_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_133735_AwakerVoiceContent = {
    Text = "Kaderin iplikleri hareketsiz asılı duruyor."
  },
  Voice_133735_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_133736_AwakerVoiceContent = {
    Text = "Tiyatroma sık sık gelir... ama oyunlar için gelmediğini biliyorum. Bu sahneyi kendi imajına belirli bir incelik katmak için kullanıyor gibi görünüyor. Gerçekten olağanüstü bir yetenek, ama onu yalnızca seyirci olarak harcamak israf olur. O hanımefendi, seyircinin karanlığında çiçek açacak türden biri değil. O, ışığın altına ait."
  },
  Voice_133736_AwakerVoiceTitle = {
    Text = "Sohbet: Sorel Hakkında"
  },
  Voice_133736_UnlockDesc = {
    Text = "\"Sorel\" Uyandıranı edinince açılır"
  },
  Voice_133737_AwakerVoiceContent = {
    Text = "Bir keresinde onu çalarken dinledim. O müzik ruhu titretti... Belki de bir sonraki yapımım için bir kader senfonisi bestelemesi için onu davet etmeliyim."
  },
  Voice_133737_AwakerVoiceTitle = {
    Text = "Sohbet: Hameln Hakkında"
  },
  Voice_133737_UnlockDesc = {
    Text = "“Uyanış” Sanga elde edildikten sonra açılır"
  },
  Voice_133738_AwakerVoiceContent = {
    Text = "Bir hikâye daha, güzelce tamamlanmış, sonuna yaklaşıyor."
  },
  Voice_133738_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_133739_AwakerVoiceContent = {
    Text = "Sonunda bütünüyle gördüm. Kaderin sonsuz ağını."
  },
  Voice_133739_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_133740_AwakerVoiceContent = {
    Text = "Eğer izin verirsen... yalnızca sana ve bana ait bir oyun örmek istiyorum. \nSeyirci yok, prova yok. Sadece, sen ışığa adım attığında, benim bile okuyamadığım o ipliğin nasıl kıpırdamaya başlayacağını görmek istiyorum."
  },
  Voice_133740_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_133740_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_133741_AwakerVoiceContent = {
    Text = "Ne talihsiz bir dansçı. Adımlarını izledim. Onunki yıkıma doğru ilerleyen bir güzellik—her dönüşte yeşil alevler tutuşturuyor, sanki kaderin ipliklerini yakıp kül etmeye çalışıyor, ama sonunda o ipler ondan yalnızca yürek burkan bir canlılık yontacak. Fırsat olursa, yalnızca ona bir bale yazmak isterdim."
  },
  Voice_133741_AwakerVoiceTitle = {
    Text = "Sohbet: Liz Hakkında"
  },
  Voice_133741_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Liz\" elde edildikten sonra açılır"
  },
  Voice_133742_AwakerVoiceContent = {
    Text = "Burada örülür. Burada tartılır. Burada kesilir."
  },
  Voice_133742_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_133743_AwakerVoiceContent = {
    Text = "Sakin ol..."
  },
  Voice_133743_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_133744_AwakerVoiceContent = {
    Text = "Bir iplik daha belirginleşiyor."
  },
  Voice_133744_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_133745_AwakerVoiceContent = {
    Text = "Perde senin için açık ve kaderin senaryosu başlamayı bekliyor. Söyle bana: hangi mukadder yolda yürümeyi tercih edersin? Hüzünlü bir son mu, yoksa neşeli bir başlangıç mı?"
  },
  Voice_133745_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_133745_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_133746_AwakerVoiceContent = {
    Text = "Bu örmeye gün be gün oldukça alıştım... Her birinin sessiz, tekrarlanan çekişinde, tüm hikâyelerin başlangıçlarını ve sonlarını görüyorum. Her perdenin kapanışını izlerken, zaman zaman kaderin kendisinin de üstüne yükselmiş gibi hissediyorum. Yine de kaderin ağından kaçılamaz ve yalnızca izlemek, sonunda içi boş bir his bırakır.\nO anlarda tiyatroya gidiyorum. Kendi ellerimle eğirdiğim ama bir kez bile yaşamadığım acıları ve sevinçleri sahnelemek için."
  },
  Voice_133746_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_133747_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_133747_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_133748_AwakerVoiceContent = {Text = "Heh..."},
  Voice_133748_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_133749_AwakerVoiceContent = {
    Text = "Burada örülür. Burada tartılır. Burada kesilir."
  },
  Voice_133749_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_133750_AwakerVoiceContent = {
    Text = "Kader kıpırdanıyor. Fısıltısı yaklaşıyor."
  },
  Voice_133750_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_133751_AwakerVoiceContent = {
    Text = "Tiyatro yeni bir romantik komedi sahneye koydu ve kaderin seyircileri arasında sana bir yer ayırdım. Yazgıların birbirine dolandığı her uzun gecede, yıldızlarımızın buluşacağı anı sessizce bekleyeceğim."
  },
  Voice_133751_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_133751_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_133752_AwakerVoiceContent = {
    Text = "Kaderin iplerini bu kadar ısrarla çekmek...\n\nKendi hikâyeni okumaya oldukça hevesli görünüyorsun, değil mi?"
  },
  Voice_133752_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_133753_AwakerVoiceContent = {
    Text = "Yazılmış olan yaklaşıyor."
  },
  Voice_133753_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_133754_AwakerVoiceContent = {
    Text = "Trajedinin salonuna girmek istersen, izin ver sana <Italic:Antigone>'yi sunayım. İlahi yasa ile ölümlü ferman arasında sıkışmış, attığı her adım kaderin çoktan eğirdiği ipliklerin üzerine düşer, ta ki sonunda taş mezarın derin gölgesine adım atana dek. O zincirlerin kırılamaması tam da bu yüzdendir ki, küçük bedeninin içinde yanan irade, uzun geceye karşı böylesine canlı parıldar."
  },
  Voice_133754_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_133754_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_133755_AwakerVoiceContent = {
    Text = "Hiçbir son gerçekten kesin değildir, ama hiçbiri de sebep ve sonuç ağından kaçamaz..."
  },
  Voice_133755_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_133756_AwakerVoiceContent = {
    Text = "İplerin üzerinde, gökkuşağının her tonundan geçen renklerin değişimini görüyorum.\nSonsuz bir ağ boyunca uzanıyorlar; sınırsız dünyalar ve nihayetsiz olasılıklar eğiriyorlar, ta ki daha önce görülmüş herhangi bir desenden daha güzel bir örüntü oluşturana dek.\n\nSonunda—tanrı ya da ölümlü, kahraman ya da kötü—her biri o ince iplikler tarafından yönlendirilir ve kaderin kırpmayan bakışı altında kaderlerine doğru başı dönmüş bir hızla koşar."
  },
  Voice_133756_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_133757_AwakerVoiceContent = {
    Text = "Bu dünyada artık hiçbir şeyin beni şaşırtamayacağını sanıyordum... Tiyatro zevkin üzerimde iz bıraktı."
  },
  Voice_133757_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_133757_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_133758_AwakerVoiceContent = {
    Text = "Kaderin iplikleri her zaman gölgelerde birbirine bağlanır... Sen o ipliklerden birine dokundun ve böylece beni irkilttin."
  },
  Voice_133758_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_133758_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_133759_AwakerVoiceContent = {
    Text = "Kendini tekrar eden gösterilere hiçbir zaman ilgi duymadım. İnsanın tiyatroya adım atmasının tek nedeni, canlı bir sahneye—yeniden yaratılamayacak bir sahneye—tanık olmaktır.\nEğer bir saat gibi dönüp durmaktan başka bir şey yapmıyorsa, sahne süslü bir kafese dönüşür ve izlemek, zaten bildiğin bir sona doğru sıkıcı bir hac yolculuğundan öteye geçmez.\nYapım ne kadar görkemli olursa olsun, ruhsuz bir maskeli balo. Sen ne düşünüyorsun?"
  },
  Voice_133759_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_133760_AwakerVoiceContent = {
    Text = "O iplikler bir zamanlar ellerimden kusursuz bir düzenle akıyordu... ta ki sen ortaya çıkana ve akışlarında hiç öngörmediğim dalgalanmalar yaratana dek."
  },
  Voice_133760_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_133760_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_133761_AwakerVoiceContent = {
    Text = "Kaderin tutsağı, her zamanki gibi acınası... yazılmış olan reddedilemez."
  },
  Voice_133761_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_133762_AwakerVoiceContent = {
    Text = "Sonsuz ipliklerden, tek bir yol eğiririm."
  },
  Voice_133762_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_133763_AwakerVoiceContent = {
    Text = "Kaderin büyük sahnesinde, tüm ruhlar sebep ve sonuç ağında işaretlerini bekler; çarklar dönerken sevinçleri ve kederleri sessizce şekillenir...\nPerde kalktı, Koruyucu. Senin ve benim hikâyemiz burada başlıyor."
  },
  Voice_133763_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_133764_AwakerVoiceContent = {
    Text = "Çatışma burada. Ağı kıran kahraman mı olacaksın, yoksa yalnızca iplerin izin verdiği kadar hareket eden bir oyuncu mu?"
  },
  Voice_133764_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_133765_AwakerVoiceContent = {
    Text = "Boşuna direniş."
  },
  Voice_133765_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_139865_AwakerVoiceContent = {
    Text = "Bu hediye için teşekkür ederim. Onu güvenle saklayacağım."
  },
  Voice_139865_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_139866_AwakerVoiceContent = {
    Text = "Uyandırıcı yapısını epey inceledim, bu yüzden artık kendimi uzman sayarım. Ama Gümüş Çekirdeklerin içindeki \"ruhaniyet\"... o kısmı hâlâ tam olarak anlayamıyorum."
  },
  Voice_139866_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_139866_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_139867_AwakerVoiceContent = {
    Text = "Burası... yeni bir dünyanın başladığı yer."
  },
  Voice_139867_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_139868_AwakerVoiceContent = {
    Text = "Ben böyle şeyler yapabiliyorum, biliyorsun. Diğer canlıların bedenlerini yeniden düzenlemek ya da değiştirmek gibi..."
  },
  Voice_139868_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_139868_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_139869_AwakerVoiceContent = {
    Text = "Her canlı farklıdır, bu yüzden bir şeyleri değiştirmeye başlamadan önce onları gerçekten dikkatli bir şekilde incelemen gerekir."
  },
  Voice_139869_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_139869_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_139870_AwakerVoiceContent = {
    Text = "Benden korkmadın mı? Aaa... bu hiç eğlenceli değil..."
  },
  Voice_139870_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_139871_AwakerVoiceContent = {
    Text = "Kimsenin yolumuza çıkmasına izin vermeyeceğim."
  },
  Voice_139871_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_139872_AwakerVoiceContent = {
    Text = "Hazırım, her zaman."
  },
  Voice_139872_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_139873_AwakerVoiceContent = {
    Text = "Canlılar gerçekten çeşitlilikle dolu. Çok daha fazlasını öğrenmek istiyorum!"
  },
  Voice_139873_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_139875_AwakerVoiceContent = {
    Text = "Saya ile oynamak ister misin?"
  },
  Voice_139875_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_139876_AwakerVoiceContent = {Text = "CIKCIIK!"},
  Voice_139876_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_139877_AwakerVoiceContent = {
    Text = "Burası... yeni bir dünyanın başladığı yer."
  },
  Voice_139877_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_139878_AwakerVoiceContent = {
    Text = "Tıka basa doydum. İkram için teşekkürler!"
  },
  Voice_139878_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_139880_AwakerVoiceContent = {
    Text = "Hey, Koruyucu... hiç birini sevdin mi? Hiç tüm kalbinle birini özledin mi?"
  },
  Voice_139880_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_139880_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_139881_AwakerVoiceContent = {Text = "Ngh!"},
  Voice_139881_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_139882_AwakerVoiceContent = {
    Text = "Burası mı?"
  },
  Voice_139882_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_139883_AwakerVoiceContent = {
    Text = "Güzel iş! İyi bir şey buldun mu?"
  },
  Voice_139883_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_139884_AwakerVoiceContent = {
    Text = "Tüm testlerimden sonra artık çok daha fazla şey anlıyorum. Her Uyandırıcının taşıdığı \"ruhaniyet\"—hepsi tamamen farklı. Ve görünüşe göre benim Gümüş Çekirdeğimin ruhaniyeti... \"sevgi.\""
  },
  Voice_139884_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_139884_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_139885_AwakerVoiceContent = {
    Text = "Nasıl? Yakaladım, değil mi?"
  },
  Voice_139885_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_139886_AwakerVoiceContent = {
    Text = "Bu benim son hediyem... sana."
  },
  Voice_139886_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_139887_AwakerVoiceContent = {
    Text = "\"<Italic:Bu yıldızlardan birinde çiçeğim açıyor...>\"\nDaha önce buna benzer bir şey söylediğini hissediyorum."
  },
  Voice_139887_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_139887_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_139888_AwakerVoiceContent = {
    Text = "Görünüşe göre \"Gümüş Çekirdekler\"in her biri çok uzaklardan gelen bir iradeye bağlı. Ne gizemli…"
  },
  Voice_139888_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_139888_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_139889_AwakerVoiceContent = {
    Text = "Bu benim son hediyem... sana."
  },
  Voice_139889_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_139891_AwakerVoiceContent = {Text = "Argh!"},
  Voice_139891_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_139892_AwakerVoiceContent = {
    Text = "Küçük Prens, gülünün özel hale geldiğini söylüyor çünkü ona bakım yapmış... Sence de öyle mi?"
  },
  Voice_139892_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_139892_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_139893_AwakerVoiceContent = {
    Text = "Dün Lily'nin kitaplığında <Italic:Küçük Prens> adında bir kitap buldum. Gerçekten çok güzeldi! Okumak ister misin?"
  },
  Voice_139893_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_139893_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_139895_AwakerVoiceContent = {
    Text = "Evet, Gümüş Çekirdeklerin yapısını inceledim ve Uyandırıcıların nasıl çalıştığını anlamaya başlıyorum."
  },
  Voice_139895_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_139895_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_139896_AwakerVoiceContent = {Text = "Argh!"},
  Voice_139896_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_139897_AwakerVoiceContent = {Text = "Selam!"},
  Voice_139897_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_139899_AwakerVoiceContent = {
    Text = "Çok şey öğreteceğinizi umuyorum!"
  },
  Voice_139899_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_139900_AwakerVoiceContent = {
    Text = "Merhaba! ...Böyle mi söyleniyor?\nBen Saya ve... tanıştığımıza memnun oldum!"
  },
  Voice_139900_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_139901_AwakerVoiceContent = {
    Text = "Karahindibayı bilirsin, değil mi? Tohumlarını rüzgârla uçuranları. Küçücük bir tohum, vatanından çok ama çok uzaklara taşınır... ve belki de hiçbir şeyin yetişmediği bir çöle düşer—tek bir çimen yaprağı bile olmayan bir yere. Acaba... o küçücük tohum ne hissediyordur...?"
  },
  Voice_139901_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_139901_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_139902_AwakerVoiceContent = {
    Text = "Ne kadar yaparsam yapayım, hep eğlenceli!"
  },
  Voice_139902_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_139903_AwakerVoiceContent = {Text = "Heya!"},
  Voice_139903_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_139906_AwakerVoiceContent = {Text = "Dikkat et!"},
  Voice_139906_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_140533_AwakerVoiceContent = {
    Text = "Güzel yemekleri seviyorum! Ve bana iyi davranan insanları seviyorum! Biri bana nazik davrandığında... bu beni gerçekten mutlu ediyor."
  },
  Voice_140533_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_140534_AwakerVoiceContent = {
    Text = "Beni uyandıran o mu? Gerçekten... göz kamaştırıcı görünüyor. Peki, kız kardeşini bulmasına yardım ettin mi?"
  },
  Voice_140534_AwakerVoiceTitle = {
    Text = "Sohbet: Tinktur Hakkında"
  },
  Voice_140534_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Tinct\" elde edildikten sonra açılır"
  },
  Voice_140535_AwakerVoiceContent = {
    Text = "Ne zaman senin yanında olsam, garip insanlar ortaya çıkıp etrafımızda toplanıyor. Aslında Alanda sadece ikimiz olduğu zamanları tercih ediyorum."
  },
  Voice_140535_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_140536_AwakerVoiceContent = {
    Text = "Anladım. Hemen hallederim!"
  },
  Voice_140536_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_140537_AwakerVoiceContent = {
    Text = "Koruyucu, Bağ, Uyandırıcı. Bağlantımız böyle. Bana anlattın. Ruhlarımızın birbirine bağlı olduğunu hissedebiliyorum... gümüş bir iplik gibi mi? Hmm, kulağa biraz fazla karmaşık geliyor..."
  },
  Voice_140537_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_140538_AwakerVoiceContent = {
    Text = "Et ve kan yoluyla tohum yaymak mı? Hmm... ilginç. Aslında onun koyunlarını merak ediyorum."
  },
  Voice_140538_AwakerVoiceTitle = {
    Text = "Sohbet: Thais Hakkında"
  },
  Voice_140538_UnlockDesc = {
    Text = "\"Thais\" Uyandıranı edinince açılır"
  },
  Voice_140539_AwakerVoiceContent = {
    Text = "Dışarıda bu dünyayı yok edecek kadar büyük bir karanlık getirebilecek tehditler var, değil mi? Biliyorum. Profesör Doll bana her şeyi anlattı."
  },
  Voice_140539_AwakerVoiceTitle = {
    Text = "Sohbet: Kriz Hakkında"
  },
  Voice_140540_AwakerVoiceContent = {
    Text = "Kaba insanları sevmiyorum. Bana kötü bir his veriyorlar..."
  },
  Voice_140540_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_140541_AwakerVoiceContent = {
    Text = "Oh? Yani onun türü yeni gezegenlerde diğer türleri avlayarak çoğalıyor. Huh, anlıyorum..."
  },
  Voice_140541_AwakerVoiceTitle = {
    Text = "Sohbet: Winkle Hakkında"
  },
  Voice_140541_UnlockDesc = {
    Text = "\"Winkle\" Uyandıranı edinince açılır"
  },
  Voice_141963_AwakerVoiceContent = {
    Text = "Aferin çocuğum."
  },
  Voice_141963_AwakerVoiceTitle = {
    Text = "Özel Beceri: II"
  },
  Voice_141964_AwakerVoiceContent = {Text = "Hey!"},
  Voice_141964_AwakerVoiceTitle = {
    Text = "Özel Beceri: III"
  },
  Voice_141965_AwakerVoiceContent = {Text = "Elbette."},
  Voice_141965_AwakerVoiceTitle = {
    Text = "Vuruş·Beş"
  },
  Voice_143501_AwakerVoiceContent = {
    Text = "Ne yazık, fikrini değiştirdiğinde nerede bulacağını biliyorsun beni."
  },
  Voice_143501_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_143501_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_143502_AwakerVoiceContent = {
    Text = "Kahretsin..."
  },
  Voice_143502_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_143503_AwakerVoiceContent = {
    Text = "Deri, kas, sinir, kemik; hepsi yeniden inşa edilecek, yeniden sağlıklı ve tam olacak, yeniden canlılık kazanacak."
  },
  Voice_143503_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_143503_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_143504_AwakerVoiceContent = {
    Text = "Derin Deniz karşısında yenilmez düşman yoktur!"
  },
  Voice_143504_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_143505_AwakerVoiceContent = {
    Text = "Ziyafet, Av, sığınak mı?\nBana dua et, en kadim deniz suları sana adımı söyler.\nBen derinliklerin efendisiyim, Pontos."
  },
  Voice_143505_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_143506_AwakerVoiceContent = {
    Text = "Heh heh, Ebwynnos'taki zamanı mı özlüyorsun…\nO bu bedende yaşıyor, seni her an geri dönmeye davet ediyor."
  },
  Voice_143506_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_143507_AwakerVoiceContent = {
    Text = "Ben öyle yapmadım ama, bir gün kulaklarında deniz suyu ve kanat çırpıntısı sesi duyarsan endişelenme, bu normal bir şeydir."
  },
  Voice_143507_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_143508_AwakerVoiceContent = {
    Text = "Duyularını sun, sonsuza dek derinliklerde pişman ol!"
  },
  Voice_143508_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_143509_AwakerVoiceContent = {
    Text = "Enerjik gençleri severim; ne yazık ki Mythag'ın şenliğe getirdiği kısıtlamalar fazlasıyla sıkı, düzgün bir av alanı bile yok.\nÜstelik İçinde, alenen ortalıkta dolaşmaya, hatta profesör unvanı taşımaya cüret eden o pis şey de var."
  },
  Voice_143509_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_143510_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_143510_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_143511_AwakerVoiceContent = {
    Text = "Bu kadar şey yaptım, sen bana bir kez daha dayı bile demek istemiyorsun; gerçekten baş ağrısı."
  },
  Voice_143511_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_143513_AwakerVoiceContent = {
    Text = "Acele etmeyin, Derin Deniz'in en dibindeki Karanlık sizi mutlaka Yutacak."
  },
  Voice_143513_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_143514_AwakerVoiceContent = {
    Text = "Diz çök, Ebwynnos'un besin kaynağı ol."
  },
  Voice_143514_AwakerVoiceTitle = {
    Text = "Özel Beceri: III"
  },
  Voice_143515_AwakerVoiceContent = {
    Text = "Beni seçen o varlığa gelince… hem dostane hem de kötü niyetli demekten başka bir şey söyleyemem.\nNereye düşeceği tamamen keyfine bağlı; seni tehlikeden mutlaka kurtarır, ama orası başka bir tehlike mi, bu \"yolculuk\"un düşünmesi gereken bir şey değil.\nNe kadar ilginç, ne kadar öngörülemez; bu geleneği sürdürmeyi düşünüyorum."
  },
  Voice_143515_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_143515_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_143516_AwakerVoiceContent = {
    Text = "Ebwynnos ile özel bir bağım var; daha doğrusu, ben Ebwynnos'um, Ebwynnos bana bağlı ve benim bedenim aracılığıyla var oluyor."
  },
  Voice_143516_AwakerVoiceTitle = {
    Text = "Sohbet: Ebwynnos Hakkında"
  },
  Voice_143517_AwakerVoiceContent = {
    Text = "Başını kaldır, boğazını ortaya çıkar."
  },
  Voice_143517_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_143518_AwakerVoiceContent = {
    Text = "Anıları silmek, varlığı yok etmek. Tanıdık geliyor… ne demek istediğimi anlıyorsun; kaynakları farklı olsa da görünüşe göre onlar her zaman ışıksız yerlerden filizleniyor."
  },
  Voice_143518_AwakerVoiceTitle = {
    Text = "Sohbet: Kriz Hakkında"
  },
  Voice_143519_AwakerVoiceContent = {
    Text = "Heybetime meydan okuyacak kadar aptal olmamalıydınız."
  },
  Voice_143519_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_143520_AwakerVoiceContent = {
    Text = "Çok zayıf."
  },
  Voice_143520_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_143521_AwakerVoiceContent = {
    Text = "Ebwynnos'ta şenlik asla durmaz, Ebwynnos'un düşmanları da sonsuza dek huzur bulamaz."
  },
  Voice_143521_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_143521_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_143522_AwakerVoiceContent = {
    Text = "Ah, titremeni anlıyorum, ama buna hiç gerek yok, genç dostum.\nSıradanlığa ve aşınmaya duyduğun korkuyu kucakla; bana bak, her zaman başka bir seçeneğin olduğunu anlarsın."
  },
  Voice_143522_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_143522_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_143523_AwakerVoiceContent = {
    Text = "Evet, o felaketi doğrudan emretmediğini, eğlenirken yaşanan bir tesadüf olduğunu biliyorum; ama bu açıkçası onu öldürmek istemememi daha da artırıyor.\nO kara sis tek başına kalmasın, benim eline geçmesin de iyi olur."
  },
  Voice_143523_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_143524_AwakerVoiceContent = {
    Text = "O yapışkan Derin Varlıklar benim dostlarım değil, düşmanlarımdır. Şaşırdın mı? Derin Deniz zaten onlara ait değildi ki."
  },
  Voice_143524_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_143524_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_143525_AwakerVoiceContent = {
    Text = "Sonsuza dek, burada kal!"
  },
  Voice_143525_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_143526_AwakerVoiceContent = {
    Text = "Hazır mısınız, avlar!"
  },
  Voice_143526_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_143527_AwakerVoiceContent = {
    Text = "Ruhaniyet yeni bedenler doğurur, bedenler önemsiz bilgiyle doldurulur, ardından o güzel ve canlı bireyler sonsuza dek tek bir yerde bir araya gelir.\nHâlâ söylediklerimi hatırlıyor musun, Derin Deniz'in en dibi her şeyi barındırır… her şeyi alıkoyar."
  },
  Voice_143527_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_143527_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_143528_AwakerVoiceContent = {
    Text = "Kabus, Onları durdur."
  },
  Voice_143528_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_143529_AwakerVoiceContent = {
    Text = "Umarım bu küçük şeyler seni iflas ettirmez, bilirsin, büyük bir aileyi geçindirmek gerçekten kolay değildir."
  },
  Voice_143529_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_143530_AwakerVoiceContent = {
    Text = "Çok çok uzun zaman önce, kara henüz Derin Deniz'in üzerine çıkmadan önce, bu gezegen bazı özel tinsel varlıkları uyandırdı. Güçlü, heybetli, Dikizci'ye kapalı.\nOnları düşmanca ya da dostane olarak tanımlamak mümkün değildi; insanlar, geçmişte sayısız canlı gibi, onlar için önemsizdi — toz gibi silinebilir ya da topraklarıyla birlikte korunabilirdi."
  },
  Voice_143530_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_143530_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_143531_AwakerVoiceContent = {
    Text = "Yalnız yüzleşmen gereken tek macera, en iyi dostun ve en inatçı düşmanın yalnızca yaşlanmaktır; Ebwynnos'un ışıkları onu tamamen sürer gider… Bunlar yalnızca önemsiz anılardır, onlara çıpalanmana gerek yok."
  },
  Voice_143531_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_143531_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_143532_AwakerVoiceContent = {
    Text = "Kaçış hayalinden vazgeç."
  },
  Voice_143532_AwakerVoiceTitle = {
    Text = "Özel Beceri: I"
  },
  Voice_143533_AwakerVoiceContent = {
    Text = "Gri beyaz bir toza dönüşeceksin."
  },
  Voice_143533_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_143534_AwakerVoiceContent = {Text = "Hıh!"},
  Voice_143534_AwakerVoiceTitle = {Text = "Darbe"},
  Voice_143535_AwakerVoiceContent = {
    Text = "Akıllıca bir hareket, küçük arkadaşım. Dışarıdan gelen canavarların inananları her zaman cesetleri denize atmak kadar aptal olur, bu bir Hediye sayılmaz, değil mi?"
  },
  Voice_143535_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_143536_AwakerVoiceContent = {
    Text = "Zaten hedef alındın."
  },
  Voice_143536_AwakerVoiceTitle = {
    Text = "Özel Beceri: II"
  },
  Voice_143537_AwakerVoiceContent = {
    Text = "Kabul etmek istemesem de, son derece nadir anlarda, yaşlanmanın zamanın getirdiği tek şey olmadığını, yalnızca bir simge olduğunu hissediyorum.\nBu yüzden üzerimde var olmasına izin veriyorum. Elbette — yalnızca görünüşte."
  },
  Voice_143537_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_143539_AwakerVoiceContent = {
    Text = "Dua işe yarar; bir düşün, önünde böcekler Leou harfleri oluştursa bile, böceklerin talebine yanıt vermeyi bir düşünürsün."
  },
  Voice_143539_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_143539_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_143540_AwakerVoiceContent = {
    Text = "Hahaha, tamam, o İfade'yi takınma, küçük dostum.\nBunlar yalnızca sözde \"eski tanrıların\" uyması gereken gelenekler; sen için ise hiçbir bedel ya da koşul gerekmez, ben sonsuza dek senin yanında olacağım."
  },
  Voice_143540_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_143540_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_143554_AwakerVoiceContent = {
    Text = "Hüh, dışarıdan gelen Canavar'larla iş birliği yapan küçük Canavar.\nBeni onunla aynı sunağa koymaya cüret eden aptallar var; bu tam bir hakaret!"
  },
  Voice_143554_AwakerVoiceTitle = {
    Text = "Sohbet: Tulu Hakkında"
  },
  Voice_143554_UnlockDesc = {
    Text = "\"Tulu\" Uyandıranı edinince açılır"
  },
  Voice_143555_AwakerVoiceContent = {
    Text = "Düşmanımın düşmanı dostumdur; fırsat olursa, can düşmanımın en sevdiği oyuncağı elinden almak gibi güzel bir anlaşmaya itiraz etmem."
  },
  Voice_143555_AwakerVoiceTitle = {
    Text = "Sohbet: Ryker Hakkında"
  },
  Voice_143555_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Ryker\" elde edildikten sonra açılır"
  },
  Voice_146158_AwakerVoiceContent = {
    Text = "Oh? Benimle burada mı dövüşmek istiyorsun? Benim için sorun değil."
  },
  Voice_146158_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_146159_AwakerVoiceContent = {
    Text = "Daha fazla—bana daha fazla güç ver!"
  },
  Voice_146159_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_146160_AwakerVoiceContent = {
    Text = "Bölünmüş bir kalbe sahip olanlardan hoşlanmıyorum, zira bu tür bir bölünme genellikle zayıflık anlamına gelir. Ama sen bir istisnaısın. Bir zamanlar çok fazla şey taşıyanların asla uzağa gidemeyeceğine inanırdım. Ama seçtiğin yol beni şaşırtıyor… Belki farklı bir yolda yürüyen bir rakip, bilemeye ve meydan okumaya daha layıktır. Katılmıyor musun, \"rakip\"?"
  },
  Voice_146160_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_146161_AwakerVoiceContent = {
    Text = "Astral Deniz'in Cetus'u—hepsini yut!"
  },
  Voice_146161_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_146162_AwakerVoiceContent = {
    Text = "Benimle karşı karşıya gelmekten onur duy!"
  },
  Voice_146162_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_146163_AwakerVoiceContent = {
    Text = "Yıldızlar yok oluşa tanıklık etsin!"
  },
  Voice_146163_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_146164_AwakerVoiceContent = {
    Text = "Yetmez. Çok uzak…"
  },
  Voice_146164_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_146165_AwakerVoiceContent = {Text = "Heh."},
  Voice_146165_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_146166_AwakerVoiceContent = {Text = "Hıh."},
  Voice_146166_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_146167_AwakerVoiceContent = {
    Text = "Bu dünyanın solup gitmesini pek umursamıyorum—ama güç arayışımın önünde engel olmasına da izin vermeyeceğim."
  },
  Voice_146167_AwakerVoiceTitle = {
    Text = "Sohbet: Kriz Hakkında"
  },
  Voice_146168_AwakerVoiceContent = {
    Text = "Yalnızca unutuluş beklediği için varoluşun değerini sorgulamak... Bu tür çocuksu tartışmalarla ilgilenmiyorum. Yıkımın hiçbir önemi yok, anının da. Gücün kendisi anlam taşır."
  },
  Voice_146168_AwakerVoiceTitle = {
    Text = "Sohbet: Doll: Cehennem Hakkında"
  },
  Voice_146168_UnlockDesc = {
    Text = "Uyanışçı \"Erime·Doll\" edinildikten sonra açılır"
  },
  Voice_146169_AwakerVoiceContent = {
    Text = "Gözlerinde yabancı bir irade görüyorum. Saf değil, ama yeterince inatçı. Haydi, hangi gücün ya da özlemin seni benim önüme getirdiğini göster."
  },
  Voice_146169_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_146170_AwakerVoiceContent = {Text = "Ha!"},
  Voice_146170_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_146171_AwakerVoiceContent = {
    Text = "Benimle karşı karşıya gelmekten onur duy!"
  },
  Voice_146171_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_146172_AwakerVoiceContent = {
    Text = "Kaosun kokusu—ne kadar nostaljik… Bu boşluktan doğduğum andan itibaren, arayışım hiç değişmedi."
  },
  Voice_146172_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_146172_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_146173_AwakerVoiceContent = {
    Text = "Bana meydan mı okumak istiyorsun? Cesaretine hayranım ve yenilme şerefini sana bahşedeceğim. Bunu \"Mythag'ın Koruyucusu\"na duyduğum saygının bir göstergesi olarak kabul et."
  },
  Voice_146173_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_146173_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_146174_AwakerVoiceContent = {
    Text = "Zayıflarla, korkaklar ve kendini kandıran ahmakların doldurduğu sahte bir ütopya. Ama neyse. Bu yer bana en heyecan verici rakipleri getiriyor—bu yeterli."
  },
  Voice_146174_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_146175_AwakerVoiceContent = {
    Text = "Muazzam bir gücü boşa harcamak, korku, suçluluk ve yorgunluk yüzünden yeteneğini uzun bir rüyada hapsetmek. Ne yazık."
  },
  Voice_146175_AwakerVoiceTitle = {
    Text = "Sohbet: Tulu Hakkında"
  },
  Voice_146175_UnlockDesc = {
    Text = "\"Tulu\" Uyandıranı edinince açılır"
  },
  Voice_146176_AwakerVoiceContent = {
    Text = "Zamanıma değmez."
  },
  Voice_146176_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_146177_AwakerVoiceContent = {
    Text = "Mühür biraz gevşiyor… Evrenin derinliklerinden gelen güç kabarıyor. Bunu uzun zamandır hissetmemiştim…"
  },
  Voice_146177_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_146177_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_146178_AwakerVoiceContent = {
    Text = "Astral Deniz'in Cetus'u—hepsini yut!"
  },
  Voice_146178_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_146179_AwakerVoiceContent = {
    Text = "…Coşturucu."
  },
  Voice_146179_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_146180_AwakerVoiceContent = {
    Text = "Uçsuz bucaksız evrende çağlar boyunca dolaştım; tüm o \"güçlü\" olanları uçuruma fırlattım. Sen eşsizsin, ama yanımda yer almak istiyorsan önce başını dik tutmayı öğren. Korkakların bana faydası yok."
  },
  Voice_146180_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_146180_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_146181_AwakerVoiceContent = {
    Text = "Cesur ya da korkak, güçlü ya da zayıf… Heh—hayır, rakibimin nasıl biri olduğunu umursamıyorum. Gerçek anlamda değerli her rakip bana hakiki bir heyecan yaşatır."
  },
  Voice_146181_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_146182_AwakerVoiceContent = {
    Text = "Zayıflık. Dünyadaki tüm iğrenç şeyler arasında, zayıflık en sefil günahtır. Herkes elinde bir kılıçla doğar; kimsenin son gelmeden teslim olma hakkı yoktur, ne de kaderin belirlediği savaş alanına zaten yenilgiyi kabullenerek adım atma hakkı. Bu hem rakibine hem de kendine hakaret etmektir."
  },
  Voice_146182_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_146183_AwakerVoiceContent = {
    Text = "Bozulmuş Astral Ceset—uyan!"
  },
  Voice_146183_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_146184_AwakerVoiceContent = {
    Text = "Heh… İşte bu heyecan vericiydi. Bir dahaki sefere geri adım atmayacağım."
  },
  Voice_146184_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_146185_AwakerVoiceContent = {
    Text = "Kemiklerim sevinçle titriyor… Çabanıza tanıklık ettim. Ve bu, yanımda durmaya layık olduğunuzu kanıtlıyor, Koruyucu."
  },
  Voice_146185_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_146185_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_146186_AwakerVoiceContent = {
    Text = "Heh… Açıkça görüyorsun, Koruyucu. Gücün prangaları kırılmak için vardır!"
  },
  Voice_146186_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_146186_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_146187_AwakerVoiceContent = {Text = "Hm?"},
  Voice_146187_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_146188_AwakerVoiceContent = {Text = "Hm?"},
  Voice_146188_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_146189_AwakerVoiceContent = {
    Text = "Tam önümde… tüm hayatım boyunca peşinde koştuğum gücün zirvesi… Bu yolda benimle yürüdün ve beni bu eşiğe kadar rehberlik ettin. O nihai günü seninle birlikte tanıklık etmek için sabırsızlanıyorum!"
  },
  Voice_146189_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_146189_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_146190_AwakerVoiceContent = {
    Text = "Belki seni çok aceleyle yargıladım... Büyümen ve gizli gücün beni şaşırttı. Sayısız hayatın zamanla solup gittiğini izledim, ama sen... gerçekten farklısın. Gücünün gerçek kaynağı konusunda oldukça meraklıyım."
  },
  Voice_146190_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_146190_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_146192_AwakerVoiceContent = {
    Text = "Cehennemin ağzı, benim için sonuna kadar aç!"
  },
  Voice_146192_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_146193_AwakerVoiceContent = {
    Text = "Ah, anlıyorum… gücün hiçbir zaman bir sonu yoktu. Gerçek meydan okuma ancak şimdi başlıyor! Beni buraya getiren ve gerçeği gösteren sendin. Yakında, önünde çok daha mükemmel bir savaşçı sunacağım. Sen de çok daha güçlü döndüğünden emin ol, \"rakibim.\""
  },
  Voice_146193_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_146193_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_146194_AwakerVoiceContent = {
    Text = "Küçük numaralar."
  },
  Voice_146194_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_146195_AwakerVoiceContent = {
    Text = "İliğimde güç kaynıyor!"
  },
  Voice_146195_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_146196_AwakerVoiceContent = {
    Text = "Yut—hepsini!"
  },
  Voice_146196_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_146197_AwakerVoiceContent = {
    Text = "Merhamet, zayıflık, kafa karışıklığı… gözlerin safsatalarla bulanmış. Kararsızlık içinde olan biri, gücün ne olduğunu asla anlayamaz."
  },
  Voice_146197_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_146197_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_146198_AwakerVoiceContent = {
    Text = "Gerçek Güç, hiçbir zaman intikam ya da koruyuculukla ilgili olmamıştır. Güç, Tam Güç'tür; diğer ben bu gerçeği hiçbir zaman \"gerçekten\" anlayamadı. İşte onun yeterince güçlü olmamasının Kökeni de budur."
  },
  Voice_146198_AwakerVoiceTitle = {
    Text = "Sohbet: Lotan Hakkında"
  },
  Voice_146198_UnlockDesc = {
    Text = "\"Lotan\" Uyandıranı edinince açılır"
  },
  Voice_146199_AwakerVoiceContent = {
    Text = "İyi dinle, bunu yalnızca bir kez söyleyeceğim:\nBen, Lotan, seni sabrıma değer bir rakip olarak görüyorum.\nZirvene ulaşana dek, en güvenilir kılıcın ben olacağım. Bu söz, duygu ya da sadakatle ilgili değil. Sen benim en heyecan verici rakibimsin ve yolun ortasında düşmene asla izin vermeyeceğim."
  },
  Voice_146199_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_146199_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_146200_AwakerVoiceContent = {
    Text = "Gel—ya beni öldür, ya da öldürül."
  },
  Voice_146200_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_146201_AwakerVoiceContent = {
    Text = "Cehennemin ağzı, benim için sonuna kadar aç!"
  },
  Voice_146201_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_146521_AwakerVoiceContent = {
    Text = "Kemik bıçağı nereye yönelirse, her şey çöker!"
  },
  Voice_146521_AwakerVoiceTitle = {
    Text = "Özel Beceri: I"
  },
  Voice_147047_AwakerVoiceContent = {
    Text = "Gücün… sonu yok!"
  },
  Voice_147047_AwakerVoiceTitle = {
    Text = "Özel Beceri: II"
  },
  Voice_147493_AwakerVoiceContent = {Text = "—"},
  Voice_147493_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_147493_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_147494_AwakerVoiceContent = {
    Text = "(Boğuk ve dinlendirici bir şarkı)"
  },
  Voice_147494_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_147495_AwakerVoiceContent = {
    Text = "Seyirci, daha fazla seyirciye ihtiyacımız var..."
  },
  Voice_147495_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_147496_AwakerVoiceContent = {
    Text = "Kum... Beyaz bir çöl... Burası tehlikeli. Birlikte ayrılalım."
  },
  Voice_147496_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_147496_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_147497_AwakerVoiceContent = {
    Text = "Yeni yurdun haritasını hâlâ hatırlıyorum. Rengarenk ve güzeldi. Gitmemiz gereken yer orası. Şarkı söyleyebiliriz ve mutluluğu bulabiliriz."
  },
  Voice_147497_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_147498_AwakerVoiceContent = {Text = "Ah!"},
  Voice_147498_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_147499_AwakerVoiceContent = {Text = "—"},
  Voice_147499_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_147499_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_147500_AwakerVoiceContent = {Text = "Hımm...?"},
  Voice_147500_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_147501_AwakerVoiceContent = {
    Text = "Bu... yıldızların sesi"
  },
  Voice_147501_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_147502_AwakerVoiceContent = {
    Text = "Yine geldin. Eskisi gibi yanıma otur ve benimle birlikte bekle. Neyi bekliyoruz mu...? Sadece bekle."
  },
  Voice_147502_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_147503_AwakerVoiceContent = {
    Text = "Mükemmel prova. Sanırım sahneye çıkmaya hazırım."
  },
  Voice_147503_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_147503_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_147504_AwakerVoiceContent = {Text = "Düş."},
  Voice_147504_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_147505_AwakerVoiceContent = {
    Text = "Issızlığa ve ölüme adanmış."
  },
  Voice_147505_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_147506_AwakerVoiceContent = {
    Text = "Ne deliyim ne de hiç üzüntü hissettim. Lütfen saçma söylentilere inanmayın."
  },
  Voice_147506_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_147507_AwakerVoiceContent = {
    Text = "Garip, şarkımdan korkuyor gibiler..."
  },
  Voice_147507_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_147508_AwakerVoiceContent = {Text = "Şşşt..."},
  Voice_147508_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_147509_AwakerVoiceContent = {
    Text = "Ne güzel bir sahne kostümü, çok parlak, çok göz kamaştırıcı..."
  },
  Voice_147509_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_147509_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_147510_AwakerVoiceContent = {Text = "—"},
  Voice_147510_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_147511_AwakerVoiceContent = {
    Text = "Ah, yıldızların oyalanan renkleri."
  },
  Voice_147511_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_147512_AwakerVoiceContent = {
    Text = "Şarkı söyle."
  },
  Voice_147512_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_147513_AwakerVoiceContent = {
    Text = "Düzgün vokal eğitimi mi...? Ama şu anki sesimden oldukça memnunum."
  },
  Voice_147513_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_147513_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_147514_AwakerVoiceContent = {Text = "—"},
  Voice_147514_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_147515_AwakerVoiceContent = {
    Text = "Bir şeyler değişmiş gibi görünüyor..."
  },
  Voice_147515_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_147515_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_147516_AwakerVoiceContent = {
    Text = "Şarkım nasıldı?"
  },
  Voice_147516_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_147517_AwakerVoiceContent = {
    Text = "İyi uykular..."
  },
  Voice_147517_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_147518_AwakerVoiceContent = {Text = "—"},
  Voice_147518_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_147519_AwakerVoiceContent = {Text = "Tamam."},
  Voice_147519_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_147520_AwakerVoiceContent = {Text = "Ah!"},
  Voice_147520_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_147521_AwakerVoiceContent = {
    Text = "Teşekkür ederim... Teşekkür etmeli miyim?"
  },
  Voice_147521_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_147522_AwakerVoiceContent = {
    Text = "*İç çeker*..."
  },
  Voice_147522_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_147523_AwakerVoiceContent = {
    Text = "Işıkla çiçek aç."
  },
  Voice_147523_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_147524_AwakerVoiceContent = {
    Text = "Uzun zaman oldu... Sonunda sahneye geri döndüm. Teşekkür ederim, Koruyucu."
  },
  Voice_147524_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_147524_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_147525_AwakerVoiceContent = {
    Text = "Rahatsız ettiğim için özür dilerim... Bu ağaçtan inmeme yardım eder misiniz? Neden tırmandığımı hatırlamıyorum. Belki de yukarıdaki bulutlar bana nostalji hissettirdi..."
  },
  Voice_147525_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_147526_AwakerVoiceContent = {
    Text = "Soydaşlarım beni hiç terk etmedi; sadece çok, çok uzaklara gittiler."
  },
  Voice_147526_AwakerVoiceTitle = {
    Text = "Sohbet: Kabiledaşları Hakkında"
  },
  Voice_147527_AwakerVoiceContent = {Text = "Duydun mu?"},
  Voice_147527_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_147528_AwakerVoiceContent = {Text = "Ah."},
  Voice_147528_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_147529_AwakerVoiceContent = {
    Text = "Sürekli etrafımda dolanıyormuşsun gibi görünüyor... Anlıyorum, hayranım olmalısın."
  },
  Voice_147529_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_147529_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_147530_AwakerVoiceContent = {
    Text = "Lalala... Hımm? Dünyayı sona erdirecek bir felaket mi oluyor? Anlıyorum... ama önce saçımı yapmam ve gidip Tinktur’u bulmam gerek..."
  },
  Voice_147530_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_147531_AwakerVoiceContent = {
    Text = "Şşş... Konuşma. Kötü adamlar geliyor. Ablamı ve beni alıp götürmek istiyorlar, gemiye binmemize izin vermiyorlar..."
  },
  Voice_147531_AwakerVoiceTitle = {
    Text = "Sohbet: Güvenlik Hakkında"
  },
  Voice_147532_AwakerVoiceContent = {Text = "—"},
  Voice_147532_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_147532_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_147533_AwakerVoiceContent = {
    Text = "Uyandığımda gezegen yok oluyordu. Gece göğünün şeritler halinde soyulduğunu gördüm ve dünya şiddetli rüzgârlarla dolu bir tuvale dönüştü—önce büküldü, sonra parçalanıp paramparça oldu."
  },
  Voice_147533_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_147533_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_147534_AwakerVoiceContent = {
    Text = "Bu, Bay Pickman tarafından çizilmiş, imzalı posterim. Onu alabilirsin, %player%."
  },
  Voice_147534_AwakerVoiceTitle = {
    Text = "Sohbet: Faint Hakkında"
  },
  Voice_147534_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Faint\" elde edildikten sonra açılır"
  },
  Voice_149667_AwakerVoiceContent = {
    Text = "Hm? Merak mı ediyorsun? Bir Vaftiz Annenin hazine kasası yabancıların gözü için değildir, bilirsin. İçinde ne kadar dolu olduğunu öğrenmek için can atıyorsan... neden hemen Kutsal Düzen'e katılmıyorsun... Hehe."
  },
  Voice_149667_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_149668_AwakerVoiceContent = {
    Text = "Bana inanmıyor musun? Hüngür hüngür... Sanırım herkesi kandırmak gerçekten mümkün değil... Gerçek şu ki, ben @1'ın VI. Bohemond'unun piç kızıyım, ölümlüler arasında gizlenerek yaşıyorum ve düşmanın avından kaçmak için kendimi peri olarak tanıttım... Sana en değerli sırrımı söyledim. Bana inanmaz... mısın?"
  },
  Voice_149668_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_149668_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_149669_AwakerVoiceContent = {Text = "Ayy~"},
  Voice_149669_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_149670_AwakerVoiceContent = {
    Text = "Çok fazla şeker mi? Hayır hayır hayır, bu Vaftiz Annenin gülümsemesini korumasının sırrı, bilirsin. Sanki küçük bir diş çürüğü yüzünden bırakırmışım?"
  },
  Voice_149670_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_149671_AwakerVoiceContent = {
    Text = "Gel, Perinin yanında dur. Ne? Herkes sunuları paylaşıp birlikte mi yiyor? ...Peki. Eğer bu Mythag'ın geleneğiyse... o zaman ben... kesinlikle hiçbir itirazım yok. Haydi, herkes, bir şölen yapalım!"
  },
  Voice_149671_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_149671_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_149672_AwakerVoiceContent = {
    Text = "Eh, ne kadar dindar bir küçük kuzusun."
  },
  Voice_149672_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_149673_AwakerVoiceContent = {
    Text = "Biraz daha, ve Peri seni kutsayacak, hmm?"
  },
  Voice_149673_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_149674_AwakerVoiceContent = {
    Text = "Hepiniz hâlâ biraz toy~"
  },
  Voice_149674_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_149676_AwakerVoiceContent = {
    Text = "Bu ibadet töreni daha önce yapılanların hepsinden görkemli olacak—ve sunuların da daha fazla olması gerekecek... Aman Tanrım, elbette uzuvlarını kesmiyoruz! Ben iyi kalpli bir periyim; kimseye zarar verecek bir şey yapmam~"
  },
  Voice_149676_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_149676_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_149677_AwakerVoiceContent = {
    Text = "Koruyucu, Caraboo'nun yüreğinin derinliklerinden gelen en gerçek itirafına hazır mısın?\nNereden geldiğim hiç önemli değil. Asıl önemli olan şu: Sen bana gökten gelen bir armağansın ve ben değerli hayırseverimin yanında sonsuza dek kalmaya karar verdim.\nBu, daha fazla araştırmanı durdurmak için söylenmiş bir yalan mı, diye soruyorsun? Hehe, sence ne?\nNeyse... Gerçek duygularımı seninle paylaştığım için küçük bir ödülü hak ettiğimi düşünüyorum. Elma aromalı bir jelibon olsa yeter, lütfen?"
  },
  Voice_149677_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_149677_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_149678_AwakerVoiceContent = {Text = "Hehe~"},
  Voice_149678_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_149680_AwakerVoiceContent = {
    Text = "Sorun değil! Bir dahaki sefere sadece Peri'ni korumaya odaklan, o zaman başarısız olmazsın~"
  },
  Voice_149680_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_149682_AwakerVoiceContent = {
    Text = "Beni kandırmaya kalkma!"
  },
  Voice_149682_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_149683_AwakerVoiceContent = {
    Text = "Vay be, bu kadar adak...! Öhöm. Hehe, aferin, ödülü hak ettin! Gel buraya, sana bir perinin öpücüğünü vereyim! ...Ne düşünüyorsun? Alnından tabii ki!"
  },
  Voice_149683_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_149683_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_149684_AwakerVoiceContent = {
    Text = "Sunularınız için teşekkürler, sadık kullarım! Her şeyi anlayışla karşılayan Vaftiz Anneniz, tapınağa sizin altın yaldızlı bir heykelinizi de diktirtecek. Aman canım—o soğuk, zarif siluetinizi yakalamak için biraz daha fazla toplamam gerekecek~"
  },
  Voice_149684_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_149684_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_149685_AwakerVoiceContent = {
    Text = "Sen mi? ...Sen henüz aydınlanmamış sürümüzden birisin. Caraboo, dünyanın gerçek doğasını gördüğün günü sabırla bekleyecek. Ve o gün geldiğinde—bedenini, sadakatini ve dünyevi mallarını herkesin Vaftiz Annesine sunmayı unutma. Hehe."
  },
  Voice_149685_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_149686_AwakerVoiceContent = {
    Text = "Listedeki her şey... zaten toplandı mı? Mythag'ın serveti benim kavrayabileceğimden çok daha derin... Bilseydim, yapardım... Hmm? Ne mırıldandığımı mı soruyorsun? Sadece Lord Dexter'ın cömertliği için şükrediyorum, hehe~"
  },
  Voice_149686_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_149686_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_149687_AwakerVoiceContent = {
    Text = "En çok neyden nefret ederim? Sözleşmeye saygı göstermeyen büyücülerden, tabii ki. İşte aramızda kalacak küçük bir sır: Her büyücü kocaman bir sahtekârdır. Tüm o sözde kehanetler ve lanetler? Seni meteliksiz bırakmak için kullanılan hilelerden ibaret! Peki kendinizi nasıl korursunuz...? Basit! Tüm paranızın Perinin kutsalını almasına izin verin!"
  },
  Voice_149687_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_149688_AwakerVoiceContent = {
    Text = "Tanıştığımıza çok sevindim! Ben uzak diyarlardan gelen bir Solgun Peri'yim. Daha fazlasını duymak ister misin? Bir perinin nimeti, üyelik seviyene göre farklı güçlerde gelir, hehe~"
  },
  Voice_149688_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_149689_AwakerVoiceContent = {
    Text = "Geçmiş ibadet törenlerinde, yedili ritüel ve üçlü yeminin yanı sıra, inananlar bana yepyeni bir tapınak inşa eder ve görkemli adaklar sunarlardı. İşte liste!"
  },
  Voice_149689_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_149689_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_149690_AwakerVoiceContent = {
    Text = "Haydi... geride bırakmak istediğin her şeyi karların derinliklerine göm..."
  },
  Voice_149690_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_149691_AwakerVoiceContent = {
    Text = "Nereden geldiğimi sorduğunu duydum. Hehe, bu Vaftiz Annenin küçük sırrı. Ama mutlaka araştırmak istiyorsan, Kutsal Düzen benim kaleme aldığım bir biyografi saklıyor. Yalnızca yüz bin Gümüş karşılığında okuyabilirsin. Denemek ister misin?"
  },
  Voice_149691_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_149691_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_149692_AwakerVoiceContent = {
    Text = "Oh, burası çok güzel—pek çok sevimli çocuk ve müstehcen derecede cömert sosyal yardımlar. Tüm bunlarla, Doğu'ya gidecek yol param yakında birikmiş olacak..."
  },
  Voice_149692_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_149693_AwakerVoiceContent = {
    Text = "Vaftiz annenize tapmayı unutmayın, hehe."
  },
  Voice_149693_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_149694_AwakerVoiceContent = {
    Text = "Çok özür dilerim, ama Perinin diyarı kutsal bir alan—burada yabancı kurt adamları kabul etmiyoruz... Havanın yalan kokuyor olduğunu mu söylüyor? Burnu bozulmuş olmalı."
  },
  Voice_149694_AwakerVoiceTitle = {
    Text = "Sohbet: Ryker Hakkında"
  },
  Voice_149694_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Ryker\" elde edildikten sonra açılır"
  },
  Voice_149695_AwakerVoiceContent = {
    Text = "Ha? Biri sahte peri olduğumu mu söylüyor... Yakalandım demek. Hehe. Ama senin umursamayacağını biliyorum... değil mi?"
  },
  Voice_149695_AwakerVoiceTitle = {
    Text = "Sohbet: Dedikodular Hakkında"
  },
  Voice_149696_AwakerVoiceContent = {
    Text = "Mmm, nefis~♪"
  },
  Voice_149696_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_149697_AwakerVoiceContent = {
    Text = "Orada, orada~"
  },
  Voice_149697_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_149698_AwakerVoiceContent = {
    Text = "Yolunu şaşırmış küçük kuzular, Peri'niz günahlarınızı yıkamaya geldi, hehe~"
  },
  Voice_149698_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_149699_AwakerVoiceContent = {
    Text = "Hâlâ vazgeçmedin mi? Peki, peki—Caraboo sana kendisi anlatacak. Bak, Caraboo, Doğu'daki bulutları delen bir kar zirvesinin tanrıçası Umapati'nin kızıdır... Hm? O tanrıçanın iki oğlu vardı, kızı yoktu? Şey, ilahi kayıtlar her zaman biraz... eksik olur, anlarsın."
  },
  Voice_149699_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_149699_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_149700_AwakerVoiceContent = {
    Text = "Karşınızda~ Peri'nin ışığı artık üzerinde parlıyor. Hadi, göster kendini!"
  },
  Voice_149700_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_149701_AwakerVoiceContent = {
    Text = "Tamam tamam, araştırmayı bırakır mısın? Uslu bir {Male=boy,Female=girl} ol da bu kaba soruşturmayı bırak, sana en değerli şekerimin yarısını gizlice paylaşayım. Biliyor musun, Haçlı Seferi savaş alanlarında tatlı şeker gerçekten nadir bir hazineydi."
  },
  Voice_149701_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_149701_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_149702_AwakerVoiceContent = {
    Text = "Caraboo'nun kutsalı dünyadaki her hastalığı iyileştirebilir—elbette bu kara veba da dahil... Elbette gerçek! Yeter ki yeterince dindar olasın, Caraboo'ya yeterince güvenesin, hehe."
  },
  Voice_149702_AwakerVoiceTitle = {
    Text = "Sohbet: Kriz Hakkında"
  },
  Voice_149703_AwakerVoiceContent = {Text = "Ay~"},
  Voice_149703_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_149704_AwakerVoiceContent = {
    Text = "Peri'nin ışığına bak!"
  },
  Voice_149704_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_149705_AwakerVoiceContent = {
    Text = "Yedili ritüel, üçlü yemin—onları sun ve Peri'nin affını satın al!"
  },
  Voice_149705_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_150079_AwakerVoiceContent = {
    Text = "Hisset bunu!"
  },
  Voice_150079_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_150104_AwakerVoiceContent = {
    Text = "Huh, Ogier seni nasıl içeri aldı? Herkesi dışarıda tutacağına söz vermişti. Senin efendin misin...? Ugh, güvenilmez küçük çocuklar baş ağrısı. Bu toplantıyı hazırlamak için çok emek verdim, bilirsin. Şey... sunulardan elli-elli pay alalım ve sen de görmezden gel, olur mu?"
  },
  Voice_150104_AwakerVoiceTitle = {
    Text = "Sohbet: Ogier Hakkında"
  },
  Voice_150104_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Ogier\" elde edildikten sonra açılır"
  },
  Voice_22276_AwakerVoiceContent = {
    Text = "Çabuk, toparlan! Sokaklarda oyalanma."
  },
  Voice_22276_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_36679_AwakerVoiceContent = {
    Text = "Ben uyurken tarikata katılmış, yani onunla hiçbir bağım yok.\nKendi isteğiyle geldiğini duydum, tam bir Denizci olmak için insan formunu terk etmek istiyormuş... Hmph, güç tarafından kör edilmiş bir aptal daha."
  },
  Voice_36679_AwakerVoiceTitle = {
    Text = "Sohbet: Caecus Hakkında"
  },
  Voice_36679_UnlockDesc = {
    Text = "Ana Hikâye 6. Bölüm tamamlandıktan sonra kilidi açılır"
  },
  Voice_36680_AwakerVoiceContent = {
    Text = "Golyat asla sadık bir evcil hayvan olmadı. Miryam’ın ona bu kadar değer vermesini anlayamıyorum... Zincire vurulmamış olsaydı çoktan kaçıp ona ihanet ederdi."
  },
  Voice_36680_AwakerVoiceTitle = {
    Text = "Sohbet: Golyat Hakkında"
  },
  Voice_36680_UnlockDesc = {
    Text = "Ana Hikâye 6. Bölüm tamamlandıktan sonra kilidi açılır"
  },
  Voice_36681_AwakerVoiceContent = {
    Text = "Denizciler bu şekilde doğmazlar. Uyum sağlamak için hayatlarının ilk yarısını tıpkı insanlar gibi yaşarlar...\nDikkatli olsan iyi olur—en sevdiğin pastane sahibi onlardan biri olabilir!"
  },
  Voice_36681_AwakerVoiceTitle = {
    Text = "Sohbet: Denizciler Hakkında"
  },
  Voice_36681_UnlockDesc = {
    Text = "Ana Hikâye 6. Bölüm tamamlandıktan sonra kilidi açılır"
  },
  Voice_36682_AwakerVoiceContent = {
    Text = "Celeste’in detone Deniz Türküsü, Kaptan’ın meşhur tütsülenmiş balık güveci, deniz melteminden sertleşmiş ve balık kokan battaniyeler... Gergin ve tehlikeli olsa da, o sürgün aylarını denizde Asla Unutma."
  },
  Voice_36682_AwakerVoiceTitle = {
    Text = "Sohbet: \"Hayalet Gemi\" Hakkında"
  },
  Voice_36682_UnlockDesc = {
    Text = "Ana Hikâye 6. Bölüm tamamlandıktan sonra kilidi açılır"
  },
  Voice_36683_AwakerVoiceContent = {
    Text = "Bu okuldaki herkes çok meşgul görünüyor, ama...\nBurada daha önce hiç bilmediğim sessiz bir huzur var.\nAynı hedef için birlikte çalışmak... Hmph, sanırım tamamen berbat değil."
  },
  Voice_36683_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında II"
  },
  Voice_36683_UnlockDesc = {
    Text = "Ana Hikâye 6. Bölüm tamamlandıktan sonra kilidi açılır"
  },
  Voice_36684_AwakerVoiceContent = {
    Text = "Yatak çok sert, hava çok soğuk, çay kirli durulama suyu gibi... Bu yerden nefret etmek için bin tane nedenim var.\nAma sen burada olduğun için, sanırım katlanabilirim. İstemeyerek de olsa."
  },
  Voice_36684_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında III"
  },
  Voice_36684_UnlockDesc = {
    Text = "Ana Hikâye 6. Bölüm tamamlandıktan sonra kilidi açılır"
  },
  Voice_36685_AwakerVoiceContent = {
    Text = "Teşekkür ederim... H-Ha? Neden mi bunu söylüyorum? Belli değil mi! Denizde benim için yaptığın her şey için...\nDur, neden gülüyorsun?! Sadece beni telaşlandırmak istiyorsun!"
  },
  Voice_36685_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında II"
  },
  Voice_36685_UnlockDesc = {
    Text = "Ana Hikâye 6. Bölüm tamamlandıktan sonra kilidi açılır"
  },
  Voice_36686_AwakerVoiceContent = {
    Text = "Bir zamanlar aramızda bir tür aile bağı olduğuna inanıyordum...\nAma şimdi, her şeyden sonra, o kısacık sıcak anların sadece benim hayal ürünüm olduğunu fark ettim.\nOnunla ne yaptığın senin bileceğin iş, sadece onu benden uzak tut."
  },
  Voice_36686_AwakerVoiceTitle = {
    Text = "Sohbet: Miryam Hakkında II"
  },
  Voice_36686_UnlockDesc = {
    Text = "Ana Hikâye 6. Bölüm tamamlandıktan sonra kilidi açılır"
  },
  Voice_36687_AwakerVoiceContent = {
    Text = "Ne tuhaf... Bu his çok garip.\nKalbim durmuş, ama bedenim hâlâ sıcak... Hey, buraya gel ve elime dokun. Bunun bir hile olmadığını söyle bana."
  },
  Voice_36687_AwakerVoiceTitle = {
    Text = "Sohbet: \"Uyandıranlar\" Hakkında"
  },
  Voice_36687_UnlockDesc = {
    Text = "Ana Hikâye 6. Bölüm tamamlandıktan sonra kilidi açılır"
  },
  Voice_45153_AwakerVoiceContent = {
    Text = "Leo Krallığı’nda doğmamış olabilirim, ama ikinci hayatımı Kurtuluş Büyük Katedrali’nde aldım. Öyleyse neden burayı yuvam sayamayayım?"
  },
  Voice_45153_AwakerVoiceTitle = {
    Text = "Sohbet: Ev Hakkında"
  },
  Voice_45154_AwakerVoiceContent = {
    Text = "Bu görünmez vebanın yıllarından sonra, Ulu Baba nihayet dualarımı duydu ve bana acıya karşı koyabilecek \"Lütuf\"u bahşetti. Gerçekten hayat veriyor, ama bir bedel de gerektiriyor. O'nun uygulayıcısı olarak, bu yükü kutsananlar adına taşımam gerekir."
  },
  Voice_45154_AwakerVoiceTitle = {
    Text = "Sohbet: Onun \"Lütfu\" Hakkında"
  },
  Voice_45155_AwakerVoiceContent = {
    Text = "Benim için Uyandırıcı olma hâli, Ulu Babamız'ın kucağındaki ruhlara verdiği bir armağandır. İkinci bir hayattır, geçmişteki pişmanlıkları telafi etme fırsatıdır. O'nun işini sürdüreceğim, O'nun vekili olarak görevlerimi yerine getireceğim ve daha fazla acıyı dindireceğim."
  },
  Voice_45155_AwakerVoiceTitle = {
    Text = "Sohbet: \"Uyandıranlar\" Hakkında"
  },
  Voice_45156_AwakerVoiceContent = {
    Text = "Dileklerime saygı duyup sırrımı Komite’den sakladığın için sana bir kez daha şükranlarımı sunmama izin ver, Koruyucu. Müdahaleleri, Yaşam Kilisesi’ne hizmetimi sürdürmemi engelleyecek diye korkuyorum."
  },
  Voice_45156_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında: II"
  },
  Voice_45156_UnlockDesc = {
    Text = "Özel Operasyon \"Kan Rengi\" tamamlandıktan sonra açılır"
  },
  Voice_45157_AwakerVoiceContent = {
    Text = "O çocuk içten, Metanetli ve nazik; nadir rastlanan parlak bir ruha sahip. Böyle bir ruhla en son, hayatımın ilk bölümünde karşılaşmıştım."
  },
  Voice_45157_AwakerVoiceTitle = {
    Text = "Sohbet: Ogier Hakkında"
  },
  Voice_45157_UnlockDesc = {
    Text = "Özel Operasyon \"Kan Rengi\" tamamlandıktan sonra açılır"
  },
  Voice_45158_AwakerVoiceContent = {
    Text = "Görüşümü kaybetmiş olmam, kör olduğum anlamına gelmez. Ulu Baba üzerime Karanlık’ı indirdi ama aynı zamanda ruhların solgun ışığını görmeme de izin verdi."
  },
  Voice_45158_AwakerVoiceTitle = {
    Text = "Sohbet: Görüş Alanı Hakkında"
  },
  Voice_45159_AwakerVoiceContent = {
    Text = "O zamanlar, \"Lütuf\"u almış olmama rağmen sıradan bir adamdım. Acı çeken çok fazla insan vardı, ona ihtiyaç duyan çok fazla kişi. Hepsini kurtarmak istedim ama başaramadım. Bu benim en büyük pişmanlığım ve sonsuz suçluluğum."
  },
  Voice_45159_AwakerVoiceTitle = {
    Text = "Sohbet: Onun İlk Hayatı Hakkında"
  },
  Voice_45160_AwakerVoiceContent = {
    Text = "Hayat Kilisesi'ndeki pek çok kişi, Kutsal Yazıtlar'daki \"beyaz alevin\" ay ışığını ifade ettiğine inanır: Solgun bir Elçi ondan belirip bizi acıdan kurtaracaktır.\nAma ben gerçek alevin senin ve benim içimizde yanan ruh olduğunu biliyorum."
  },
  Voice_45160_AwakerVoiceTitle = {
    Text = "Sohbet: \"Solgun Alev\" Hakkında"
  },
  Voice_45161_AwakerVoiceContent = {
    Text = "Aslında gerçek kimliğimi gizlemem Başpiskopos tarafından söylendi. Ayrıntıya girmedi, ama beni uyardı: en saf yerlerde bile gölgeler olabilir ve iyilik yaparken bile dikkatli olunmalıdır. Elbette, sana tamamen güveniyorum."
  },
  Voice_45161_AwakerVoiceTitle = {
    Text = "Sohbet: Kimliği Gizlemek Hakkında"
  },
  Voice_45161_UnlockDesc = {
    Text = "Özel Operasyon \"Kan Rengi\" tamamlandıktan sonra açılır"
  },
  Voice_4908_AwakerVoiceContent = {
    Text = "Şarkım sana hiç yardımcı oldu mu?"
  },
  Voice_4908_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_4909_AwakerVoiceContent = {
    Text = "Lanet olsun, o sadece bir çocuk! Neden ona bu kadar saygı gösteriyorsunuz?! Aynı saygıyı bana da göstereceksiniz, anlaşıldı mı?!"
  },
  Voice_4909_AwakerVoiceTitle = {
    Text = "Sohbet: Tulu Hakkında"
  },
  Voice_4909_UnlockDesc = {
    Text = "\"Tulu\" Uyandıranı edinince açılır"
  },
  Voice_4910_AwakerVoiceContent = {
    Text = "Hey, diğer Uyandırıcılar genelde ne yapar biliyor musun? Yanlış anlama, arkadaş falan istemiyorum, ben sadece... Sadece bir teftiş yapıyorum!"
  },
  Voice_4910_AwakerVoiceTitle = {
    Text = "Sohbet: Günlük Hayat Hakkında"
  },
  Voice_4911_AwakerVoiceContent = {
    Text = "Lanet olsun! Bir dahaki sefere cesetlerini akşam yemeği niyetine örümceklere atacağım!"
  },
  Voice_4911_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_4912_AwakerVoiceContent = {
    Text = "Akşamartısı."
  },
  Voice_4912_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_4913_AwakerVoiceContent = {Text = "Ritim."},
  Voice_4913_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_4914_AwakerVoiceContent = {
    Text = "Oldukça cüretkârsın."
  },
  Voice_4914_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_4915_AwakerVoiceContent = {
    Text = "Biraz yavaşlayalım... Senin için yapabileceğim, en ufak bir şey bile var mı?"
  },
  Voice_4915_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_4916_AwakerVoiceContent = {
    Text = "Buna nasıl cüret edersin!"
  },
  Voice_4916_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_4917_AwakerVoiceContent = {
    Text = "(Büyük bir ilgiyle sorgular)"
  },
  Voice_4917_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_4918_AwakerVoiceContent = {
    Text = "Neyi sevdiğim mi? Elbette, bana itibar kazandıran bebeğimi, Kutsal Cenin’i. Bunu söylemem sana bana yakışmıyormuş gibi mi geliyor?"
  },
  Voice_4918_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_4919_AwakerVoiceContent = {
    Text = "Niyetin nedir?"
  },
  Voice_4919_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_4920_AwakerVoiceContent = {
    Text = "Fena değildi, ha? Şimdi, ödemem.—Ne? Bunun bedava bir ziyafet olduğunu mu sandın?!"
  },
  Voice_4920_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_4921_AwakerVoiceContent = {Text = "Uzak dur!"},
  Voice_4921_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_4922_AwakerVoiceContent = {Text = "Dikkat et!"},
  Voice_4922_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_4923_AwakerVoiceContent = {
    Text = "Ne muazzam bir zafer... Bu anı ebediyete kazıyacağım."
  },
  Voice_4923_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_4924_AwakerVoiceContent = {
    Text = "Hissediyorum... Kirlilik Kaynağı’nı... Gerçek suretimize bir adım daha... Ahhh, bu dünyayı paramparça edeceğim!"
  },
  Voice_4924_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_4924_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_4925_AwakerVoiceContent = {
    Text = "Biz... hazırız. Lütfen emri ver, Koruyucu."
  },
  Voice_4925_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_4925_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_4926_AwakerVoiceContent = {
    Text = "{Male=Efendim,Female=Hanımefendi}, siz gerçekten çok iyisiniz. Ne yazık ki, ben değersiz biri olduğumdan size karşılık verecek hiçbir şeyim yok..."
  },
  Voice_4926_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_4926_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_4927_AwakerVoiceContent = {
    Text = "... Sadece biraz daha, sonra \"onlardan\" tamamen ayrılmış mı olacağım?"
  },
  Voice_4927_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_4927_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_4928_AwakerVoiceContent = {
    Text = "Ha? Hâlâ hayattayım... Sen... Organlarımı çalmayacak ya da beni deneylerde kullanmayacak mısın, gerçekten?"
  },
  Voice_4928_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_4928_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_4929_AwakerVoiceContent = {
    Text = "Winkle’ın yerli türü, biyolojik beyne sızabilir ve benimle kaynaşmış Dış İrade’nin ondan dehşete kapılmasına neden olur. Ama artık, yalnızca bir kabuğa hapsedilmiş zavallı bir ruh o."
  },
  Voice_4929_AwakerVoiceTitle = {
    Text = "Sohbet: Winkle Hakkında"
  },
  Voice_4929_UnlockDesc = {
    Text = "\"Winkle\" Uyandıranı edinince açılır"
  },
  Voice_4930_AwakerVoiceContent = {
    Text = "Her şey. Her şeyi seviyorum. İster yemek ve Dua için masanın etrafında toplanan Herkes olsun, ister Koruyucu görevdeyken zaferle Dönüş'ünü bekleyiş anı olsun... Hava hep mutlulukla dolu... Gerçekten böyle bir sevince layık mıyım?"
  },
  Voice_4930_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_4931_AwakerVoiceContent = {Text = "Bat."},
  Voice_4931_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_4932_AwakerVoiceContent = {Text = "Aç."},
  Voice_4932_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_4933_AwakerVoiceContent = {
    Text = "\"Güven\", \"Kör İtaat\", \"Köle\", \"Şefkat\", \"Saygı\"... Dil modülü yeniden inşa edilip öğreniliyor. Lütfen, Koruyucu, bana yol gösterin."
  },
  Voice_4933_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_4933_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_4934_AwakerVoiceContent = {
    Text = "Erica şu anda bekleme modunda. Gövdenin soğuması 1 saat 15 dakika içinde tamamlanacak. <Del:Erica’yı çalıştırmak için atan kalbinizi sunun> Acil başlatma mı? ... Yetki doğrulaması sürüyor... Koruyucu’nun en yüksek otoritesi doğrulandı. Merhaba, Sır Koruyucusu."
  },
  Voice_4934_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_4934_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_4935_AwakerVoiceContent = {
    Text = "Soruşturma görevlerinin ortalama risk endeksi 7, ortalama 8 şişe simya takviyesi tüketimi ve ceset işleme için ortalama 10 saat gereklidir. Sonuç: Bir Koruyucu'nun işi son derece tehlikelidir. Lütfen operasyonlar sırasında güvende kalın."
  },
  Voice_4935_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_4935_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_4936_AwakerVoiceContent = {
    Text = "Öğretmen kayıtları aranıyor: Erica Layfield, Gümüş Mekatronik ve Otomasyon Öğretim Görevlisi, Ölü—Aradığınız bu değil miydi? Peki, \"Erica\" anahtar kelimesiyle yeniden aranıyor."
  },
  Voice_4936_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_4936_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_4937_AwakerVoiceContent = {
    Text = "Bilgiye bakmanız gerekiyorsa, lütfen dosyanın tam adını verin. Bulanık arama işlevi şu anda kullanılamıyor."
  },
  Voice_4937_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_4937_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_4938_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_4938_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_4939_AwakerVoiceContent = {Text = "Ah!"},
  Voice_4939_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_4940_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_4940_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_4941_AwakerVoiceContent = {Text = "Ah!"},
  Voice_4941_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_4942_AwakerVoiceContent = {
    Text = "Şarj tamamlandı, patlatmaya hazır."
  },
  Voice_4942_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_4943_AwakerVoiceContent = {
    Text = "Şarj tamamlandı, patlatmaya hazır."
  },
  Voice_4943_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_4944_AwakerVoiceContent = {
    Text = "Dinlenişimi bir daha böyle önemsiz şeylerle bölme."
  },
  Voice_4944_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_4945_AwakerVoiceContent = {
    Text = "Tinktur'u nasıl koruduysam, seni de öyle koruyacağım."
  },
  Voice_4945_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_4946_AwakerVoiceContent = {
    Text = "Ben kayda değer biri değilim, yalnızca sayısız kişi arasında adanmış bir ruhum. Hayatımı o görkemli varlığa adadım ve bir tek bakışını kazanmak için her şeyimi sunmaktan asla vazgeçmeyeceğim."
  },
  Voice_4946_AwakerVoiceTitle = {
    Text = "Sohbet: Geçmiş Üzerine"
  },
  Voice_4946_UnlockDesc = {
    Text = "\"Tulu\" Uyandıranı edinince açılır"
  },
  Voice_4947_AwakerVoiceContent = {
    Text = "İzle beni!"
  },
  Voice_4947_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_4948_AwakerVoiceContent = {
    Text = "İzle beni!"
  },
  Voice_4948_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_4949_AwakerVoiceContent = {
    Text = "...Beni uyandırmadıkları sürece önemi yok. Aynı mekânı paylaşmak katlanılabilir."
  },
  Voice_4949_AwakerVoiceTitle = {
    Text = "Sohbet: Denizciler Hakkında"
  },
  Voice_4949_UnlockDesc = {
    Text = "Uyanışçılardan \"Miryam\", \"Golyat\", \"Caecus\", \"Sanga\" ya da \"Faros\"tan herhangi birini edindikten sonra açılır."
  },
  Voice_4950_AwakerVoiceContent = {
    Text = "Kalbim oyulup alınmış gibi olan o karanlık histen nefret ediyorum. Doymamışlık duygusu bütün bedenimi kaşındırıyor..."
  },
  Voice_4950_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_4951_AwakerVoiceContent = {
    Text = "Hayır, hayır, hayır, yapma! Ondan söz etme..."
  },
  Voice_4951_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_4953_AwakerVoiceContent = {Text = "Ha!"},
  Voice_4953_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_4954_AwakerVoiceContent = {Text = "Elbette."},
  Voice_4954_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_4955_AwakerVoiceContent = {
    Text = "İlahi Diyar’ın çöküşünü ilan eden tarihçiler, varsayımlarında ne kadar da yorucu... Yine de sırf sözler anlamsız köpüklerdir; görkemli dirilişi hiç kimse durduramayacak."
  },
  Voice_4955_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_4956_AwakerVoiceContent = {
    Text = "Aslında... sana bir sır vereyim. Şu anki motosikletimden pek memnun değilim—sevmediğimden değil! Sadece sanki bir şeyler eksikmiş gibi hissediyorum..."
  },
  Voice_4956_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_4957_AwakerVoiceContent = {Text = "Ha!"},
  Voice_4957_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_4958_AwakerVoiceContent = {Text = "Çat!"},
  Voice_4958_AwakerVoiceTitle = {
    Text = "Beceri: II: Mani"
  },
  Voice_4959_AwakerVoiceContent = {
    Text = "Üzgünüm... Bunun olmasını istememiştim..."
  },
  Voice_4959_AwakerVoiceTitle = {
    Text = "Beceri: II: Depresyon"
  },
  Voice_4960_AwakerVoiceContent = {
    Text = "(Merak dolu bir fısıltı)"
  },
  Voice_4960_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_4961_AwakerVoiceContent = {
    Text = "@1@2 yılında, Bay Ward Philips, Bay Khlarcus ve Bayan Tawil birlikte Mythag Koleji’ni kurdu. Uzun bir gelişim sürecinin ardından, <Del:bu lanet zindana> Mythag Üniversitesi’ne dönüştü."
  },
  Voice_4961_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_4962_AwakerVoiceContent = {
    Text = "Adalet, sadakat, Dayanıklılık Azmi, disiplin. Bunlar çoktan kalbime kazınmış durumda."
  },
  Voice_4962_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_4963_AwakerVoiceContent = {
    Text = "Bana verdiğiniz görevi layıkıyla Tamamlayacağım."
  },
  Voice_4963_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_4964_AwakerVoiceContent = {
    Text = "Ne tür sorumsuz ebeveynler kızlarına Gorgon’un başından yapılmış bir karakter kalkanının adını verir? ...Ebeveynleri yok mu? Hımm... Bu konuşma aramızda kalsın."
  },
  Voice_4964_AwakerVoiceTitle = {
    Text = "Sohbet: Aigis Hakkında"
  },
  Voice_4964_UnlockDesc = {
    Text = "\"Aigis\" Uyandıranı edinince açılır"
  },
  Voice_4965_AwakerVoiceContent = {
    Text = "Canın sıkılıyorsa, neden gelip labirentte \"bana eşlik etmiyorsun\"? Nasıl olsa senin umutsuz hayatın da bu sonsuz labirentten farksız!"
  },
  Voice_4965_AwakerVoiceTitle = {
    Text = "Sohbet: Labirent Hakkında"
  },
  Voice_4966_AwakerVoiceContent = {
    Text = "Kukla etraftayken müfettişlerin verimliliği %78,312 artıyor, fakat daha fazla kişi de duygusal çöküşlere sürükleniyor. Onun dediği gibi: “Bazı insanlar çenelerini kapalı tutabilseydi, dünya çok daha düzgün işlerdi.”"
  },
  Voice_4966_AwakerVoiceTitle = {
    Text = "Sohbet: Doll Hakkında"
  },
  Voice_4966_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Doll\" elde edildikten sonra açılır"
  },
  Voice_4967_AwakerVoiceContent = {Text = "İn!"},
  Voice_4967_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_4968_AwakerVoiceContent = {
    Text = "Nasıl buldun?"
  },
  Voice_4968_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_4969_AwakerVoiceContent = {
    Text = "Macerayı kim sevmez ki? Keşfedilmemiş esrarengiz diyarlara dalmak, Bilinmeyen Yaratık’ı keşfetmek ve kendi Hikâye’ni örmek... Ne kadar da heyecan verici!"
  },
  Voice_4969_AwakerVoiceTitle = {
    Text = "Sohbet: Maceralar Hakkında"
  },
  Voice_4970_AwakerVoiceContent = {
    Text = "Selamlar. Ben Febvre’den Nymphaea. Bana yeni bir beden bahşettiniz, nihayet özgürce nefes alabiliyorum… Bu lütfun karşılığını nasıl ödeyebilirim?"
  },
  Voice_4970_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_4971_AwakerVoiceContent = {
    Text = "Az önce kendilerine efendim diyenlerin yine ağlayışlarını duydum sanki. Ne hoş."
  },
  Voice_4971_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_4971_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_4972_AwakerVoiceContent = {
    Text = "Sebzeleri atlayabilir miyim? Tinktur seçici olmamamı söyledi ama, onların ana renklerini sevmiyorum..."
  },
  Voice_4972_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_4973_AwakerVoiceContent = {
    Text = "Yaratıcı Tanrı bir keresinde şöyle demişti: “Acı benim yaratımım değildir. Ey elçilerim, onu taşıyın ve Çözünme’ye uğratın, acının olmadığı bir diyar kurun.” Bunun için her şeyimi veririm. Can’ımı bile."
  },
  Voice_4973_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_4973_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_4974_AwakerVoiceContent = {
    Text = "Her şeyi yutan Çözünme lanetinin karşısında, diğer acılar sönük kalır. Laneti başkaları adına taşıyamayacak olsam da, onların Pain’ini hafifletmek için elimden gelenin en iyisini yapacağım."
  },
  Voice_4974_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_4974_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_4975_AwakerVoiceContent = {
    Text = "Artık onların Pain’ini dindirebiliyor, Ruh’larını teselli edebiliyor muyum?"
  },
  Voice_4975_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_4975_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_4976_AwakerVoiceContent = {
    Text = "Öyleyse, tüm acıyı ben taşıyacağım; bütün varlıklar için Pain’den azade bir diyara giden Yolu döşemek adına."
  },
  Voice_4976_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_4976_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_4977_AwakerVoiceContent = {
    Text = "Ruh’umun derinliklerindeki bu sıcaklık... Bu Hediye için sağ ol, Soluk Alev. Bu Güç’le, belki sonunda O’nun elçisi olarak görevimi yerine getirip daha çok Çocuklar’ını kurtarabilirim."
  },
  Voice_4977_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_4977_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_4978_AwakerVoiceContent = {
    Text = "Bunların hepsini gerçekten yiyebilir miyim?"
  },
  Voice_4978_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_4978_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_4979_AwakerVoiceContent = {
    Text = "Heh. Baktığın şey ölüm değil. Sadece senin geleceğin. Benimki. Ve Herkes’inki."
  },
  Voice_4979_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_4980_AwakerVoiceContent = {
    Text = "Tinktur... Onun o yaslı şarkısını duymak, içimde Dans etme isteği uyandırıyor..."
  },
  Voice_4980_AwakerVoiceTitle = {
    Text = "Sohbet: Tinktur Hakkında"
  },
  Voice_4980_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Tinct\" elde edildikten sonra açılır"
  },
  Voice_4981_AwakerVoiceContent = {
    Text = "Dünyevi sınavlar gerçekten de kan soyumun potansiyelini uyandırabilir mi? Bunu hiç öngörmemiştim."
  },
  Voice_4981_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_4982_AwakerVoiceContent = {
    Text = "Silah artık elde daha kullanışlı geliyor."
  },
  Voice_4982_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_4983_AwakerVoiceContent = {
    Text = "Bunun minnettarlığımı kazanacağını sanma. Asil soyum buna asla izin vermez."
  },
  Voice_4983_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_4984_AwakerVoiceContent = {Text = "Ah, uh!"},
  Voice_4984_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_4985_AwakerVoiceContent = {
    Text = "O adam... Hey, dur biraz, bahsimiz daha bitmedi, değil mi?"
  },
  Voice_4985_AwakerVoiceTitle = {
    Text = "Sohbet: Diğerleri Hakkında"
  },
  Voice_4986_AwakerVoiceContent = {
    Text = "Akademinin kayıt cihazını gerçekten seviyorum. Keşke unuttuklarımı bana gerçek zamanlı hatırlatacak taşınabilir bir versiyon yapabilsem..."
  },
  Voice_4986_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_4987_AwakerVoiceContent = {
    Text = "Hıh, bir karınca cemaati... Hayır, karınca bile değilsiniz—sizin gibiler yalnızca, O’nun topraktan yeniden doğuşuna besin sağlayan ekmek kırıntıları."
  },
  Voice_4987_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_4988_AwakerVoiceContent = {
    Text = "Erzaklar geldi."
  },
  Voice_4988_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_4989_AwakerVoiceContent = {
    Text = "Erzaklar geldi."
  },
  Voice_4989_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_4990_AwakerVoiceContent = {
    Text = "Hmm... Daha sert, daha sert. Evet, işte böyle..."
  },
  Voice_4990_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_4991_AwakerVoiceContent = {
    Text = "Zafer, kan soyum tam uyanışa ermeden önce bile zahmetsizce geldi."
  },
  Voice_4991_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_4992_AwakerVoiceContent = {
    Text = "Eyvah, şapkam yamulmuş… Hmm, böyle daha iyi mi? Evet! Mükemmel!"
  },
  Voice_4992_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_4992_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_4993_AwakerVoiceContent = {
    Text = "\"Bu yeteneklerle, gerçekten hâlâ insan mıyım?\" Savaş eğitimine başladığımdan beri her gün bunu kendime sordum. Bu dünyayı seviyorum, karanlığına, pisliğine ve tekdüzeliğine rağmen, ama senin varlığın onu tozun arasındaki elmaslar gibi parlatıyor. Bir zamanlar gücüm arttıkça insan olarak duruşumun değişeceğinden korkuyordum... Şimdi, yanımda olduğun için minnettarım. Aramızdaki bağ beni insan dünyasına sıkıca bağlıyor. Lütfen beni gözetmeye devam et, Koruyucu."
  },
  Voice_4993_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_4993_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_4994_AwakerVoiceContent = {
    Text = "Ah... Endişelerin olması doğal. Bunu en başta düşünemedim. Ortağın olarak, sana en baştan açıklamalıydım. Gördüğün gibi, muhtemelen geçmişimle bağlantılı bazı alışılmadık özelliklere sahibim. Merak etmemek imkânsız, değil mi? Ama akademi gibi bir yere sahip olmak benim için bir lütuf, bu yüzden kaderin örtüsünü kaldırmamayı seçiyorum."
  },
  Voice_4994_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_4994_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_4995_AwakerVoiceContent = {
    Text = "O kadınla tanıştın, değil mi? Beyaz peçeli Uyandırıcı—üniversitenin kurucularından biri... Ama açıkçası, ondan hoşlanmıyorum. O mesafeli tavrı, sanki dünyayı hiç umursamıyormuş gibi davranması, gerçekten sinirlerimi bozuyor... Ha, bana benzediğini mi düşünüyorsun? Hadi kampüs kliniğine gidip gözlerini kontrol ettirelim."
  },
  Voice_4995_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_4995_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_4996_AwakerVoiceContent = {
    Text = "Profesör Dexter’la ilişkimi mi merak ediyorsun? Gizli saklı bir şey yok. O benim üvey babam. Anneme gelince... Bu okulda büyüdüm, tüm hocalar bana baktı. Yine de, aralarında Profesör Doll’a en yakınım."
  },
  Voice_4996_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_4996_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_4997_AwakerVoiceContent = {
    Text = "İster Uyandıran İşleri Bürosu’nun prosedürleri olsun, ister kantinde Hint yemeği için ayarladığın randevu tarihi, Mythag hakkında her sorunu yanıtlayabilirim. Merak etme, beni rahatsız etmiyorsun. Gerçekten bu kadar ulaşılmaz mı görünüyorum?"
  },
  Voice_4997_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_4997_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_4998_AwakerVoiceContent = {
    Text = "Ayna ayna, dünyadaki en büyük sihirbaz kim? Ben mi? Bu, doğru!"
  },
  Voice_4998_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_4998_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_4999_AwakerVoiceContent = {
    Text = "Fena değil."
  },
  Voice_4999_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5000_AwakerVoiceContent = {Text = "Harika!"},
  Voice_5000_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5001_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_5001_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5002_AwakerVoiceContent = {
    Text = "Bu... gerçekten işe yaradı mı? Gerçekten en ufak bir yardımım dokundu mu?"
  },
  Voice_5002_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5003_AwakerVoiceContent = {
    Text = "İşe yaramaz!"
  },
  Voice_5003_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5004_AwakerVoiceContent = {
    Text = "(Tahammül)"
  },
  Voice_5004_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5005_AwakerVoiceContent = {
    Text = "Buraya bak!"
  },
  Voice_5005_AwakerVoiceTitle = {
    Text = "Özel Beceri: I"
  },
  Voice_5006_AwakerVoiceContent = {
    Text = "Burası bizim coşkun mutluluk denizimiz olsun!"
  },
  Voice_5006_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5007_AwakerVoiceContent = {
    Text = "Sana muhafız olarak eşlik etmemi mi istiyorsun? Avın adilse, sana Destek olacağım."
  },
  Voice_5007_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5008_AwakerVoiceContent = {
    Text = "Alevler beni tüketmeyecek."
  },
  Voice_5008_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5009_AwakerVoiceContent = {
    Text = "Alevler beni tüketmeyecek."
  },
  Voice_5009_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5010_AwakerVoiceContent = {
    Text = "Ah... Sarılmak ister misin?"
  },
  Voice_5010_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5011_AwakerVoiceContent = {
    Text = "Şu üzerimdeki zincirlere bak—süs değiller, hatırlatıcılar. İhanetin ve aşağılanmanın hatırlatıcıları."
  },
  Voice_5011_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5012_AwakerVoiceContent = {
    Text = "Akademinin geçmişini öğrenmek istiyorsan, arşivlere bakmanı öneririm. Hadi ama, selefi de dahil olmak üzere, 300 yıllık bir tarihten bahsediyoruz! Gerçekten yıl yıl anlatmamı beklemiyorsun, değil mi?"
  },
  Voice_5012_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5013_AwakerVoiceContent = {
    Text = "Bu bir tahrik mi? Her an hazırım!"
  },
  Voice_5013_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5014_AwakerVoiceContent = {
    Text = "Derin deniz sana ebedi bir huzur bahşetsin."
  },
  Voice_5014_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5015_AwakerVoiceContent = {
    Text = "Derin deniz sana ebedi bir huzur bahşetsin."
  },
  Voice_5015_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5016_AwakerVoiceContent = {
    Text = "Bat ve yan! Yıkıma Dans!"
  },
  Voice_5016_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5017_AwakerVoiceContent = {
    Text = "İşte sunuyorum: Ölümsüz Yeşil Alev’in Yıkıma Dans’ı!"
  },
  Voice_5017_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5018_AwakerVoiceContent = {
    Text = "O hanımefendi bir deniz fenerine benziyor... Ebedi Gece Uzun Yolculuğu sırasında onun göz kamaştırıcı ışığını görebilseydim, belki de yolumu kaybetmezdim."
  },
  Voice_5018_AwakerVoiceTitle = {
    Text = "Sohbet: Faros Hakkında"
  },
  Voice_5018_UnlockDesc = {
    Text = "\"Faros\" Uyandıranı edinince açılır"
  },
  Voice_5019_AwakerVoiceContent = {
    Text = "Beni laboratuvardan çıkarmaya değecek kadar işe yarar olduğunu kanıtlasan iyi edersin, yeni Koruyucu."
  },
  Voice_5019_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5020_AwakerVoiceContent = {
    Text = "Efendi benim, hizmetkâr sensin. Ne istersem derhal bana getirileceksin. Ne? Ödül mü bekliyorsun? Pekâlâ, al o zaman!"
  },
  Voice_5020_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5021_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_5021_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5022_AwakerVoiceContent = {
    Text = "Şimdi bu utancı üzerimden temizleyeceğim!"
  },
  Voice_5022_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5023_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_5023_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5024_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_5024_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5025_AwakerVoiceContent = {
    Text = "Vermek, almaktır."
  },
  Voice_5025_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5026_AwakerVoiceContent = {
    Text = "Vermek, almaktır."
  },
  Voice_5026_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5027_AwakerVoiceContent = {
    Text = "Canın yanacak!"
  },
  Voice_5027_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5028_AwakerVoiceContent = {
    Text = "Daha fazla yaklaşma!"
  },
  Voice_5028_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5029_AwakerVoiceContent = {
    Text = "Dolunayın altın ışığı beni her zaman büyüler: onun altında deniz ışığı yakalar ve gizemli, yumuşak bir rüzgâr eserken, romantik ve rüya gibi bir görüş alanı dokur."
  },
  Voice_5029_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5030_AwakerVoiceContent = {
    Text = "Yuvamız Çözünme yaşamamış olsaydı, Tinktur ve ben ayrılmazdık... Çözünme'den sebzelerden nefret ettiğimden daha çok nefret ediyorum."
  },
  Voice_5030_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5031_AwakerVoiceContent = {
    Text = "Varış noktası ister gizli hazine olsun, ister liman, benim için fark etmez. Amacım yalnızca senin sağ salim dönüşünü güvenceye almak."
  },
  Voice_5031_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5031_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5032_AwakerVoiceContent = {
    Text = "Lütfen cennet kuşlarının izini takip et; varış noktası, ilham mavisinde ileride seni bekliyor."
  },
  Voice_5032_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5032_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5033_AwakerVoiceContent = {
    Text = "Sık sık ufka bakar, o uzak diyardaki sahneleri hayal ederim—yaklaştığım, ama asla erişemediğim o yer. O gün bir gün gelirse, lütfen benimle birlikte görmeye gel."
  },
  Voice_5033_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5033_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5034_AwakerVoiceContent = {
    Text = "Lütfun sayesinde, azgın denizler bile artık daha az ürkütücü geliyor. Sana metanetli lütuflarımı getirmek için onlara göğüs gereceğim."
  },
  Voice_5034_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5034_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5035_AwakerVoiceContent = {
    Text = "Sanki kürekçilerin türkülerini yine duyuyorum... ve yuvanın o tanıdık kokusunu hissediyorum."
  },
  Voice_5035_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5035_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5036_AwakerVoiceContent = {
    Text = "Beni kurtarmaya mı geldin? Çürüyen dünyadan, gözlerimi lekeleyen Nefret’ten, Ölümsüz Yeşil Alev’in sonsuzluğundan..."
  },
  Voice_5036_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5037_AwakerVoiceContent = {
    Text = "Küstah haydut!"
  },
  Voice_5037_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5038_AwakerVoiceContent = {
    Text = "Bunu sana olan sadakat yeminim say."
  },
  Voice_5038_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5038_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5039_AwakerVoiceContent = {
    Text = "Dersini al!"
  },
  Voice_5039_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5040_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_5040_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5041_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_5041_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5042_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_5042_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5043_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5044_AwakerVoiceContent = {
    Text = "Sana bir farenin neler yapabileceğini göstereceğim!"
  },
  Voice_5044_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5045_AwakerVoiceContent = {
    Text = "Sana bir farenin neler yapabileceğini göstereceğim!"
  },
  Voice_5045_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5046_AwakerVoiceContent = {
    Text = "Zar atıldı. Şimdi, bunu çabucak bitir!"
  },
  Voice_5046_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5047_AwakerVoiceContent = {
    Text = "Teşekkür yazıma adını da ekleyeceğim. Bu karanlık Kan’la lekelenmiş ayakların, balenin harikalarla dolu dünyasına yeniden adım atmasına izin veren sendin. Bundan böyle, lütfen Dans edişimi izle, Koruyucu."
  },
  Voice_5047_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5047_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5048_AwakerVoiceContent = {
    Text = "Nasıl çırpınırsan çırpın, Kader’e karşı gelemezsin. Ama o kısacık parlaklık anı, sonsuzluğa çivilenecek."
  },
  Voice_5048_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5048_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5049_AwakerVoiceContent = {
    Text = "Bu başarısızlarla ne yapmalıyız?"
  },
  Voice_5049_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5050_AwakerVoiceContent = {
    Text = "Kalbimde artık özlem kalmamış olsa bile, yine de kuğunun rolünü oynayacağım."
  },
  Voice_5050_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5050_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5051_AwakerVoiceContent = {
    Text = "Gözlerini kapa ve söyle, ne görüyorsun? Lekesiz ay ışığı, dingin bir göl..."
  },
  Voice_5051_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5051_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5052_AwakerVoiceContent = {
    Text = "Ah, Yıkımın ve talihsizliğin felaketi... Neden gidip de kız kardeşimi ve beni azap içinde bırakmak zorundaydı?"
  },
  Voice_5052_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5053_AwakerVoiceContent = {
    Text = "Sevgimi kabul et."
  },
  Voice_5053_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5054_AwakerVoiceContent = {
    Text = "Sevgimi kabul et."
  },
  Voice_5054_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5055_AwakerVoiceContent = {
    Text = "Şimdi kendimi çok daha iyi hissediyorum, nezaketiniz için teşekkür ederim."
  },
  Voice_5055_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5056_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_5056_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5057_AwakerVoiceContent = {
    Text = "Eğer uygun görürseniz, içten şükranımın nişanesi olarak solgun mor bir nilüfer sunmak isterim."
  },
  Voice_5057_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5058_AwakerVoiceContent = {
    Text = "Sence ben de daha güçlü olabilir miyim?"
  },
  Voice_5058_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5059_AwakerVoiceContent = {
    Text = "Başlıyoruz...!"
  },
  Voice_5059_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5060_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_5060_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5061_AwakerVoiceContent = {
    Text = "Bu yaralı bacak mı? Umursayacağını beklemiyordum. Uyandırıcı olmadan önce savaş alanında aldım bu yarayı.\nEndişelenme, artık bir Uyandırıcı olduğuma göre savaş yeteneğimi etkilemiyor.\nAcıyor mu diye mi soruyorsun? Hayır. Hiç düşünmedim."
  },
  Voice_5061_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5061_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5062_AwakerVoiceContent = {
    Text = "Sylvia ruh hâlimi sordu. Onu sen yollamadın mı? Kabul ediyorum, hayalet ağrı ara sıra alevleniyor. Ama bunu dert etme. Ben senin kılıcın, senin bıçağınım. Adalet için savaşabildiğim sürece, ufak acıların önemi yok."
  },
  Voice_5062_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5062_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5063_AwakerVoiceContent = {
    Text = "Çay partisi, çay partisi! Hadi çay partisi yapalım! Sylvia’dan bir sürü çay yaprağı ve atıştırmalık aldım! Evet, karşılığında Futterwacken Dansı yaptım!"
  },
  Voice_5063_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5064_AwakerVoiceContent = {
    Text = "Unvanım mı? Kişisel işlerimle gerçekten bu kadar ilgileniyor musun? Sadece sohbet etmek istiyorsun... Pekâlâ.\nOrduda, yoldaşları cinsiyete göre ayırt etmeyiz—bu güç, hız ve doğal olarak saç stilleri ve unvanları da kapsar. Zamanla bu ifade biçimine alıştım."
  },
  Voice_5064_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5064_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5065_AwakerVoiceContent = {
    Text = "İlginç… Güç kazandığımda seni parçalara ayırıp balıklara yem edeceğimden korkmuyor musun?"
  },
  Voice_5065_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5066_AwakerVoiceContent = {
    Text = "Görüyorum ki benim için layık bir Koruyucu olmak adına gerçekten çok çalışıyorsun."
  },
  Voice_5066_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5067_AwakerVoiceContent = {
    Text = "Bunu denemenin zamanı geldi. Hmph. Önce birkaç zayıfın boğazını kesmek nasıl olur?"
  },
  Voice_5067_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5068_AwakerVoiceContent = {
    Text = "Dans Saf tır. Sözler yanlış anlaşılmalara yol açabilir, ama Dans adımları asla."
  },
  Voice_5068_AwakerVoiceTitle = {
    Text = "Sohbet: Dans Etmek Hakkında"
  },
  Voice_5069_AwakerVoiceContent = {
    Text = "Denizden nefret ediyorum ve bunun iyi bir sebebi var. Okyanus, sevdiğim her şeyi Yuttu..."
  },
  Voice_5069_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5070_AwakerVoiceContent = {
    Text = "İster unutkanlık olsun ister kayboluş, bu sefer mutlaka döneceğiz!"
  },
  Voice_5070_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5071_AwakerVoiceContent = {
    Text = "İster unutkanlık olsun ister kayboluş, bu sefer mutlaka döneceğiz!"
  },
  Voice_5071_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5072_AwakerVoiceContent = {
    Text = "Lütfen, lütfen daha fazla yaklaşma. Bu tehlikeli... senin için."
  },
  Voice_5072_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5073_AwakerVoiceContent = {
    Text = "Touch me all you like... These are the scars I earned at the arena, a man's badges of honor!\nİstediğin kadar dokun bana... Bunlar arenada kazandığım yaralar, bir erkeğin onur nişanları!"
  },
  Voice_5073_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5074_AwakerVoiceContent = {
    Text = "(Pain çığlığı)"
  },
  Voice_5074_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5075_AwakerVoiceContent = {Text = "Ah! Ah!"},
  Voice_5075_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5076_AwakerVoiceContent = {
    Text = "(Yumuşak, bastırılmış bir nefes alış)"
  },
  Voice_5076_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5077_AwakerVoiceContent = {
    Text = "(Sinirli homurtu)"
  },
  Voice_5077_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5078_AwakerVoiceContent = {
    Text = "İçimde bir şey kaynıyormuş gibi hissediyorum. Aydınlanma’dan geçmek böyle bir şey mi?"
  },
  Voice_5078_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5078_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5079_AwakerVoiceContent = {
    Text = "Bu bir tür yeni teknoloji mi? Protez uzvum çok daha hafif hissettiriyor."
  },
  Voice_5079_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5079_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5080_AwakerVoiceContent = {
    Text = "Tuzlu deniz meltemi, yurdumun çok uzakta olmadığını fısıldıyor."
  },
  Voice_5080_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5080_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5081_AwakerVoiceContent = {
    Text = "Bu ışığı takip ederek, ölü ruh soydaşlarım yurtlarına geri dönebilecekler mi?"
  },
  Voice_5081_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5081_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5082_AwakerVoiceContent = {
    Text = "On binlerce yıldır arıyorum; gelip geçen bir yüzyıl bunun yanında hiçbir şey. Sen canının sonuna ulaşana dek, sana Destek olmaya devam edeceğim."
  },
  Voice_5082_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5082_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5083_AwakerVoiceContent = {
    Text = "Yalnızca Beyaz Kuş Diyarı için parlayacağım. Sana gelince..."
  },
  Voice_5083_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5083_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5084_AwakerVoiceContent = {
    Text = "Ayaklarımın üzerinden ince kumlar taşıyan esintiyi hissettim."
  },
  Voice_5084_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5084_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5085_AwakerVoiceContent = {
    Text = "Gücüne yaptığım katkı Burada Son Bulur. Fazla tamah etmek iyi bir şey değildir, bilirsin."
  },
  Voice_5085_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5085_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5086_AwakerVoiceContent = {
    Text = "Benden karşılığında ne bekliyorsun? Savaşlarda sana ödünç güç vermekten başka bir şey mi?"
  },
  Voice_5086_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5086_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5087_AwakerVoiceContent = {
    Text = "Sevginin Kafatası, Kin Kafatası, Nefret Kafatası, Arzu Kafatası... Ah, yine geldiniz mi, sevgili konuk?"
  },
  Voice_5087_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5087_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5088_AwakerVoiceContent = {
    Text = "Bu bir alışveriş olduğuna göre, hediyeni öylece kabul edemem. Dükkânımdan bir şey seçmek ister misin?"
  },
  Voice_5088_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5088_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_50898_AwakerVoiceContent = {
    Text = "Sana hazza varmayı, o sarhoş edici zirvede gezinmenin coşkusunu öğreteceğim... Karşılığında, arzularını bana çıplak hâliyle göstereceksin."
  },
  Voice_50898_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında - 2"
  },
  Voice_50899_AwakerVoiceContent = {
    Text = "Ben Ana Ağaç’ım. Ana Ağaç benim. Onun özsuyu damarlarımda akıyor, onun iradesi zihnimde fısıldıyor..."
  },
  Voice_50899_AwakerVoiceTitle = {
    Text = "Sohbet: Bereket Ana Ağacı Hakkında"
  },
  Voice_50899_UnlockDesc = {
    Text = "Ana Hikâye 7. Bölüm tamamlanınca açılır"
  },
  Voice_5089_AwakerVoiceContent = {
    Text = "İhanetinin bedelini öde!"
  },
  Voice_5089_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_50900_AwakerVoiceContent = {
    Text = "Anahtar Mezarı’nın gölgelerinde mezar taşını bir anlığına gördüm... Bir gün benim mumyalanmış etim de burada dinlenecek mi? Hayır mı? Ne yazık."
  },
  Voice_50900_AwakerVoiceTitle = {
    Text = "Sohbet: Anahtar Mezarı Hakkında"
  },
  Voice_50900_UnlockDesc = {
    Text = "Ana Hikâye 7. Bölüm tamamlanınca açılır"
  },
  Voice_50901_AwakerVoiceContent = {
    Text = "Şu kurt-oğlan... Biliyor muydun? O ve şu N’in arasında... tarif edilemez bir şeyler olup bitiyor."
  },
  Voice_50901_AwakerVoiceTitle = {
    Text = "Sohbet: Ryker Hakkında"
  },
  Voice_50901_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Ryker\" elde edildikten sonra açılır"
  },
  Voice_50902_AwakerVoiceContent = {
    Text = "Daha da yaklaş. Kucakla beni. Tadına bak... Asla Unutma beni."
  },
  Voice_50902_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında - 3"
  },
  Voice_50902_UnlockDesc = {
    Text = "Ana Hikâye 7. Bölüm tamamlanınca açılır"
  },
  Voice_50903_AwakerVoiceContent = {
    Text = "O, fazlasıyla tedbirli bir çocuk. Onu suçladığım yok—o olmasaydı, benim özgür ruhlu halkım çoktan yok olup gitmiş olmaz mıydı?"
  },
  Voice_50903_AwakerVoiceTitle = {
    Text = "Sohbet: Alva Hakkında"
  },
  Voice_50903_UnlockDesc = {
    Text = "\"Alva\" Uyandıranı edinince açılır"
  },
  Voice_50904_AwakerVoiceContent = {
    Text = "Sarı kumlardan doğdun ve sarı kumlara döneceksin. Bu kısa yolculukta, yol boyunca birkaç hatıra bırakmamalı mısın? Biraz tohum ekimi yapmalısın?"
  },
  Voice_50904_AwakerVoiceTitle = {
    Text = "Sohbet: Çöl Hakkında"
  },
  Voice_50905_AwakerVoiceContent = {
    Text = "Tüm arzular sevgiden filizlenir; sevgi, o ulu bereket ağacından önce gelen tohumdur."
  },
  Voice_50905_AwakerVoiceTitle = {
    Text = "Sohbet: Arzu Hakkında"
  },
  Voice_50906_AwakerVoiceContent = {
    Text = "Ah canım, küçük bir fare yanımızdan fırlayıp geçti... Yasak şeyleri kemirmeye bayılırlar, değil mi? Ama bu olan hâlâ fazlasıyla genç."
  },
  Voice_50906_AwakerVoiceTitle = {
    Text = "Sohbet: Jenkin Hakkında"
  },
  Voice_50906_UnlockDesc = {
    Text = "\"Jenkin\" Uyandıranı edinince açılır"
  },
  Voice_50907_AwakerVoiceContent = {
    Text = "Onlar kanımı, soyumu taşıdılar; Remouahe’nin serpilmiş suları oldular... Şimdi, sevgilim, mirasımın tahammül ettiğini, sürüp gittiğini görmelisin."
  },
  Voice_50907_AwakerVoiceTitle = {
    Text = "Sohbet: Aram Hakkında"
  },
  Voice_50907_UnlockDesc = {
    Text = "Ana Hikâye 7. Bölüm tamamlanınca açılır"
  },
  Voice_50908_AwakerVoiceContent = {
    Text = "Örümcekler... Mmm~ Onlara bayılırım. Yürüyerek doğarlar ve kıskandıracak kadar bereketlidirler..."
  },
  Voice_50908_AwakerVoiceTitle = {
    Text = "Sohbet: Agrippa Hakkında"
  },
  Voice_50908_UnlockDesc = {
    Text = "\"Agrippa\" Uyandıranı edinince açılır"
  },
  Voice_50909_AwakerVoiceContent = {
    Text = "Akan ağacın kanını taşıyanların hepsi benim Çocuklar’ım—onun tohumlarını Yutulma ile içine çekmiş olan sen de elbette buna dahilsin."
  },
  Voice_50909_AwakerVoiceTitle = {
    Text = "Sohbet: Soylar Hakkında"
  },
  Voice_50909_UnlockDesc = {
    Text = "Ana Hikâye 7. Bölüm tamamlanınca açılır"
  },
  Voice_5090_AwakerVoiceContent = {
    Text = "Eşyalarım mı? Tüm arzularını tatmin edecek her şeye sahip olduğum söylenebilir... elbette bir bedel karşılığında."
  },
  Voice_5090_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5090_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_50910_AwakerVoiceContent = {
    Text = "Ah canım, bu kez ona yenildim... Ama madem seni seçti, Kutsal Ağaç’ın özsuyunu içecek ve kanımı, tohumlarımı yeni bir dünyaya taşıyacaksın, öyle değil mi?"
  },
  Voice_50910_AwakerVoiceTitle = {
    Text = "Sohbet: Tawil Hakkında"
  },
  Voice_50910_UnlockDesc = {
    Text = "\"Ramona\" Uyandıranı edinince açılır"
  },
  Voice_50911_AwakerVoiceContent = {
    Text = "Üç Aeon’dan şu olanı, bilmecelere sarınmış bir canavar. Lütfen onun ballı sözlerinin seni saptırmasına izin verme, yoksa kalbim kırılır..."
  },
  Voice_50911_AwakerVoiceTitle = {
    Text = "Sohbet: \"N\" Hakkında"
  },
  Voice_50912_AwakerVoiceContent = {
    Text = "Tüm şuurlu varlıkların arzuları vardır. Makinelerin bile, öyle değil mi?"
  },
  Voice_50912_AwakerVoiceTitle = {
    Text = "Sohbet: Erica Hakkında"
  },
  Voice_50912_UnlockDesc = {
    Text = "\"Erica\" Uyandıranı edinince açılır"
  },
  Voice_5091_AwakerVoiceContent = {
    Text = "İhanetinin bedelini öde!"
  },
  Voice_5091_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5092_AwakerVoiceContent = {
    Text = "Harikalar diyarına Hoş Geldin!"
  },
  Voice_5092_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5093_AwakerVoiceContent = {
    Text = "(Homurdanır)"
  },
  Voice_5093_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5094_AwakerVoiceContent = {
    Text = "Oyma acısına ve dönüşümün yakıcı ateşine fazlasıyla aşinayım. Yine de tüm bunlar, ebedi güzelliğin yanında silinip gidiyor."
  },
  Voice_5094_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5094_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5095_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5096_AwakerVoiceContent = {
    Text = "Bu söylenmemiş sözleri sana eserlerim aracılığıyla ileteceğim."
  },
  Voice_5096_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5096_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5097_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_5097_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5098_AwakerVoiceContent = {
    Text = "Uyuyan egemenlik kulağıma mırıldanıyor, derin denizin harabeleri gözlerimin önünde durmadan yeniden şekilleniyor... Sayısız rüya sahnesi sonunda gerçeğe mi dönüştü?"
  },
  Voice_5098_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5098_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5099_AwakerVoiceContent = {
    Text = "Benim için bu stüdyoyu hazırladığın için teşekkür ederim. Buradaki her şey güneş ışığına batmış; sanki her eser, her oyma bıçağı altın bir ışıkla parlıyor. Ah, bahar altın renginde."
  },
  Voice_5099_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5099_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5100_AwakerVoiceContent = {
    Text = "Mizaçlarımız farklı olsa da, o çocuğa gerçekten hayranım. Tüm zorlukları ve sınırlamaları Aşmak için gereken cesarete sahip. Eğer ben de onun kadar cesur ve dayanıklı olsaydım, belki hayatıma denizde son vermeyi seçmezdim..."
  },
  Voice_5100_AwakerVoiceTitle = {
    Text = "Sohbet: Murphy Hakkında"
  },
  Voice_5100_UnlockDesc = {
    Text = "Uyanışçı \"Murphy\" edinildiğinde açılır"
  },
  Voice_5101_AwakerVoiceContent = {
    Text = "Kırmızılı Madam, hizmet ettiğim hiçbir lord’a benzemiyor... Hayır, ondan hoşlanmadığım için değil; sadece... sadece bazen onunla yüzleşmek bana biraz zor geliyor..."
  },
  Voice_5101_AwakerVoiceTitle = {
    Text = "Sohbet: Sorel Hakkında"
  },
  Voice_5101_UnlockDesc = {
    Text = "\"Sorel\" Uyandıranı edinince açılır"
  },
  Voice_5102_AwakerVoiceContent = {
    Text = "Deliliği kucaklayın!"
  },
  Voice_5102_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5103_AwakerVoiceContent = {
    Text = "Can çekişen sıçanlar."
  },
  Voice_5103_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5104_AwakerVoiceContent = {Text = "Yok edin!"},
  Voice_5104_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5105_AwakerVoiceContent = {
    Text = "Bunu benim için yapmak zorunda değilsin..."
  },
  Voice_5105_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5106_AwakerVoiceContent = {
    Text = "Kalbim dipsiz bir çukur, asla dolmayacak."
  },
  Voice_5106_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5107_AwakerVoiceContent = {
    Text = "Bu bana hiçbir şey hissettirmedi ama... yine de size son derece minnettarım."
  },
  Voice_5107_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5108_AwakerVoiceContent = {
    Text = "Ah... Benimle mi konuşuyordunuz? Özür dilerim, direğe bağlıyken gördüğüm manzaranın anıları arasında kaybolmuştum. Soru­nuzu tekrar eder misiniz?"
  },
  Voice_5108_AwakerVoiceTitle = {
    Text = "Sohbet: Geçmiş Üzerine"
  },
  Voice_5109_AwakerVoiceContent = {
    Text = "Sen benim Ustamsın... Benim Annem."
  },
  Voice_5109_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5110_AwakerVoiceContent = {
    Text = "Bir açık yakaladım!"
  },
  Voice_5110_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5111_AwakerVoiceContent = {
    Text = "Bir açık yakaladım!"
  },
  Voice_5111_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5112_AwakerVoiceContent = {Text = "Hazır—"},
  Voice_5112_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5113_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5113_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5114_AwakerVoiceContent = {
    Text = "Evet, daha sert!"
  },
  Voice_5114_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5115_AwakerVoiceContent = {
    Text = "Bu, aşkımın harareti!"
  },
  Voice_5115_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5116_AwakerVoiceContent = {
    Text = "Çözünme... Onun hakkında özgürce konuşamam. Ama şunu bil: Göründüğünden çok daha önce ortaya çıktı."
  },
  Voice_5116_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5118_AwakerVoiceContent = {
    Text = "Hıııh—"
  },
  Voice_5118_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5119_AwakerVoiceContent = {Text = "Elbette."},
  Voice_5119_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5120_AwakerVoiceContent = {
    Text = "Hadi yola koyulalım."
  },
  Voice_5120_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5121_AwakerVoiceContent = {
    Text = "Ah, kukla prensesimiz yine ağlıyor. Yoksa biberon mu uymuyor, yoksa ninni mi yeterince yatıştırıcı değil?"
  },
  Voice_5121_AwakerVoiceTitle = {
    Text = "Sohbet: Murphy Hakkında"
  },
  Voice_5121_UnlockDesc = {
    Text = "Uyanışçı \"Murphy\" edinildiğinde açılır"
  },
  Voice_5122_AwakerVoiceContent = {
    Text = "Hü-hü... O şeylerle yüzleşmek istemiyorum..."
  },
  Voice_5122_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5123_AwakerVoiceContent = {
    Text = "Şimdi, sana borcumu ödeme sırası bende."
  },
  Voice_5123_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5124_AwakerVoiceContent = {
    Text = "Bu güç dalgalanması, iliklerime işleyen yakıcı alevler gibi hissediliyor."
  },
  Voice_5124_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5125_AwakerVoiceContent = {
    Text = "Ah... Özür dilerim, l-lütfen kıpırdama!"
  },
  Voice_5125_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5126_AwakerVoiceContent = {
    Text = "Bu sıcaklık, ne kadar da yakın..."
  },
  Voice_5126_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5127_AwakerVoiceContent = {
    Text = "Avludaki güller tam açmış durumda."
  },
  Voice_5127_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5128_AwakerVoiceContent = {
    Text = "İyi iş çıkardın! Devam edecek gücün hâlâ var mı?"
  },
  Voice_5128_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5129_AwakerVoiceContent = {
    Text = "Şövalye fikri biçimsizdir; sadakat, cesaret ve erdemle şekillenir. Silahım da öyle; koruma iradesiyle biçim bulur: bir mızrak ve bir kalkan."
  },
  Voice_5129_AwakerVoiceTitle = {
    Text = "Sohbet: Şövalye Hakkında"
  },
  Voice_5130_AwakerVoiceContent = {
    Text = "Jenkin, Diana, Mac, T'yog, Brown... Vaaah! Özür dilerim, kendi kendime konuşuyordum! Bu isimleri neden tekrarladığımı mı soruyorsun? Çünkü onları unutmak istemiyorum..."
  },
  Voice_5130_AwakerVoiceTitle = {
    Text = "Sohbet: Dostluk Üzerine"
  },
  Voice_5131_AwakerVoiceContent = {Text = "Defol!"},
  Voice_5131_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5132_AwakerVoiceContent = {
    Text = "Bu dayanılmaz!"
  },
  Voice_5132_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5133_AwakerVoiceContent = {Text = "Haaah!"},
  Voice_5133_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5134_AwakerVoiceContent = {Text = "Haaah!"},
  Voice_5134_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5135_AwakerVoiceContent = {
    Text = "Çağrı’n için teşekkür ederim. Eğer sesime ihtiyaç duyulacak bir durum olursa, lütfen beni önceden haberdar et."
  },
  Voice_5135_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5137_AwakerVoiceContent = {
    Text = "O... damarlarımda dolaşan siyah, koyu sıvı; tüm acı çığlıklarını susturan nihai güç! \"Ben\" bundan doğdum, imha etmek için doğdum! HAHAHA!"
  },
  Voice_5137_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5138_AwakerVoiceContent = {
    Text = "N’aber, gidip kumar mı oynayalım? ...Bir soruşturma mı? Aah, yok, bu şans serisini heba etmek olur..."
  },
  Voice_5138_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5139_AwakerVoiceContent = {
    Text = "Teori dersleri epey sıkıcı. Sınıfın arkasında gizlice Soruşturma kayıtları okurum. Bunu Doll’a söyleme. Bu bizim sırrımız, tamam mı?"
  },
  Voice_5139_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5140_AwakerVoiceContent = {
    Text = "Acı sonuçların tadına bak!"
  },
  Voice_5140_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5141_AwakerVoiceContent = {
    Text = "Acı sonuçların tadına bak!"
  },
  Voice_5141_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5142_AwakerVoiceContent = {
    Text = "Juliette’i asla suçlamadım; o yalnızca kara ızdırabın bir kurbanıydı. Ama... bunu benden duymak istemiyor gibi. Bunu onun yerine ona iletebilir misin, Haberci?"
  },
  Voice_5142_AwakerVoiceTitle = {
    Text = "Sohbet: Juliette Hakkında"
  },
  Voice_5142_UnlockDesc = {
    Text = "Ses henüz uygulanmadı"
  },
  Voice_5143_AwakerVoiceContent = {
    Text = "Daha yavaş."
  },
  Voice_5143_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5144_AwakerVoiceContent = {Text = "Elbette."},
  Voice_5144_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5145_AwakerVoiceContent = {
    Text = "Hey! Ellerini Elbisemden çek, kırıştırıyorsun! ...Pekâlâ, bu seferlik izin veriyorum, ne kadar cömert olduğumu biliyorsun."
  },
  Voice_5145_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5146_AwakerVoiceContent = {Text = "Gerek yok!"},
  Voice_5146_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5147_AwakerVoiceContent = {Text = "Tsk!"},
  Voice_5147_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5148_AwakerVoiceContent = {
    Text = "Beni Karanlık’tan Uyandırdığın günden beri, herkesi Çözünme’nin umutsuzluğundan kurtarabileceğine ve onları günahsız diyara ulaştırabileceğine eminim. O günü umut dolu bir kalple bekliyorum."
  },
  Voice_5148_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında: I"
  },
  Voice_5149_AwakerVoiceContent = {
    Text = "Kokluyorum... kan kokusu."
  },
  Voice_5149_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5150_AwakerVoiceContent = {
    Text = "Hedef nerede? Beni uyandırmana bir minnet göstergesi olarak, senin için onunla ilgileneceğim."
  },
  Voice_5150_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5151_AwakerVoiceContent = {
    Text = "Şapkam artık daha fazla bekleyemiyor!"
  },
  Voice_5151_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5152_AwakerVoiceContent = {
    Text = "Bu kabuk O’ndan başkası için kıpırdamamalıydı... Ama yine de... senin sıcaklığın..."
  },
  Voice_5152_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5153_AwakerVoiceContent = {
    Text = "Ne. Dövüşmek ister misin?"
  },
  Voice_5153_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5154_AwakerVoiceContent = {
    Text = "Nâmahrem..."
  },
  Voice_5154_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5155_AwakerVoiceContent = {
    Text = "Affedilemez."
  },
  Voice_5155_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5156_AwakerVoiceContent = {
    Text = "Erica normal şekilde işliyor ve Mythag Üniversitesi’ndeki elektrikli ekipmanla iyi bağlantı hâlinde. Yurt ışıklarını açmamı ister misiniz?"
  },
  Voice_5156_AwakerVoiceTitle = {
    Text = "Sohbet: Erica Hakkında"
  },
  Voice_5157_AwakerVoiceContent = {
    Text = "Ah, beslenme vakti. Hehe..."
  },
  Voice_5157_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5159_AwakerVoiceContent = {
    Text = "O geniş kenarlı mor şapkalı kadını sakın sahnenin yakınına yaklaştırma! Soru sorma—sadece onu uzak tut, yoksa şapkamdan fışkıran yapış yapış gri beyin parçalarını görmek zorunda kalırsın!"
  },
  Voice_5159_AwakerVoiceTitle = {
    Text = "Sohbet: Nergis Hakkında"
  },
  Voice_5159_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Nergis\" elde edildikten sonra açılır"
  },
  Voice_5160_AwakerVoiceContent = {
    Text = "Hep böyle misin? Herkese güvenip sonra onlara sırtını mı dönüyorsun? Safsın."
  },
  Voice_5160_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5161_AwakerVoiceContent = {
    Text = "Nefret hafifleyebilir, ama asla silinemez."
  },
  Voice_5161_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5162_AwakerVoiceContent = {
    Text = "Uyandıran mı? Hmm... Evet, sabah 7 uyanmak için en iyi saat! Yarın sabah 7’de sahilde deniz kabuğu toplayalım!"
  },
  Voice_5162_AwakerVoiceTitle = {
    Text = "Sohbet: \"Uyandıranlar\" Hakkında"
  },
  Voice_5163_AwakerVoiceContent = {
    Text = "Şimdi sana ebedî bir Can bahşediyorum!"
  },
  Voice_5163_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5164_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5164_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5165_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5165_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5166_AwakerVoiceContent = {
    Text = "Üzgünüm, sana sorun çıkarıyorsam hemen giderim!"
  },
  Voice_5166_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5166_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5167_AwakerVoiceContent = {
    Text = "Bana kalacak bir yer sağladın ve minnettarım. Ama bağışla, artık sahnede yeniden durmayı hak etmiyorum."
  },
  Voice_5167_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5168_AwakerVoiceContent = {
    Text = "Burada kalmama izin verdiğin için teşekkür ederim. Eğer borcumu ödeyebileceğim bir yol varsa, lütfen Aigis'e söyle. Biraz çay ister misin?"
  },
  Voice_5168_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5168_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5169_AwakerVoiceContent = {
    Text = "O kadar sıcak ki gitmek istemiyorum. Yalnız kaldığımda her şey gerçekten karanlık, soğuk ve korkutucu oluyor..."
  },
  Voice_5169_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5169_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5170_AwakerVoiceContent = {
    Text = "Aigis... Gerçekten Halk'ın arasına dönebilir miyim? Henüz hazır değilim ama sen beni çoktan kabul ettin... Öyleyse, lütfen bana bakmaya devam et... Koruyucu."
  },
  Voice_5170_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5170_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5171_AwakerVoiceContent = {
    Text = "Ah... Her şeyi hatırlıyorum! Ben... O pis insan Kan'ı tarafından hapsedildim ve dönüşümü tamamlayamadım! Bu nasıl olabilir? Solungaçlarım nerede? Neden hareket etmiyorlar?! Neden!"
  },
  Voice_5171_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5172_AwakerVoiceContent = {
    Text = "Izgara ahtapotu severim, haşlanmış ahtapotu severim, kızarmış ahtapotu severim... Bazıları bunun küfür olduğunu söylüyor. Ha, affedin ama ahtapot fazlasıyla lezzetli, hahahaha!"
  },
  Voice_5172_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5173_AwakerVoiceContent = {
    Text = "Worms. Stars. I am... Uvhash! Kill... let me kill!\nKurtlar. Yıldızlar. Ben... Uvhash’ım! Öldür... bırak öldüreyim!"
  },
  Voice_5173_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5173_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5174_AwakerVoiceContent = {
    Text = "Crimson body, pulsating tentacles, mouthparts constantly opening and closing... Great! I can't wait to tear a throat apart!\nKızıl beden, atan Dokunaçlar, durmadan açılıp kapanan ağız parçaları... Harika! Bir boğazı parçalamak için sabırsızlanıyorum!"
  },
  Voice_5174_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5174_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5175_AwakerVoiceContent = {
    Text = "Hahaha, that's the feeling! Give me more... double, no, ten times the dose!\nHahaha, işte bu his! Daha ver... iki kat, yok, on kat doz ver!"
  },
  Voice_5175_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5175_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5176_AwakerVoiceContent = {
    Text = "Tahammül edeceğim."
  },
  Voice_5176_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5177_AwakerVoiceContent = {
    Text = "This strange feeling... not bad. Better than that Levantine wizard's nightshade.\nBu tuhaf his... fena değil. O Levanten Büyücü’nün güzelavratotudundan bile iyi."
  },
  Voice_5177_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5177_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5178_AwakerVoiceContent = {
    Text = "Yoldaşlar mı? Hmph… Hiç ihtiyacım yok. Aynı yükün altında ikinci kez ezilmeyeceğim."
  },
  Voice_5178_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5178_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5179_AwakerVoiceContent = {
    Text = "Sana hatırlatmalıyım ki işbirliğimiz bütünüyle Güç’üne bağlı. Güç’ün zayıfladığı anda bu Sözleşme derhal sona erecek ve ben tereddüt etmeden başını gövden’den ayıracağım."
  },
  Voice_5179_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5179_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5180_AwakerVoiceContent = {
    Text = "Gözlerinde ışığı görüyorum. O arzuyu, o hırsı... yanıyor. İtiraf et, ölümlü! Biz aynı türdeniz."
  },
  Voice_5180_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5180_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5181_AwakerVoiceContent = {
    Text = "Albatrosu biliyor musun? Fırtınalara cesurca göğüs gererler, ama bir kez yere sürgün edildiklerinde, alayla çevrelendiklerinde, o devasa, sarkık kanatları ironik bir şekilde acınası bir engele dönüşür. Her neyse, bu hikâyenin bir anlamı yok... Seninle birlikte olmak çok rahatlatıcı, aklıma geldi sadece — sıradan bir sohbet."
  },
  Voice_5181_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5181_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5182_AwakerVoiceContent = {
    Text = "Belki de zamanlar gerçekten değişti. Günümüzde zayıflar bile kayalıkları aşabiliyor, dalgalara hükmedebiliyor ve gökyüzünün kralı olabiliyor. Ey fani, tarihi yeniden yazacağın günü bekliyorum. Elindeki güçlü kılıç olmak benim için bir onur olacaktır!"
  },
  Voice_5182_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5182_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5183_AwakerVoiceContent = {
    Text = "Dönüşüm oranı fazlasıyla düşük. Yarın yeniden eğitim için ofisime rapor ver."
  },
  Voice_5183_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5184_AwakerVoiceContent = {
    Text = "Diğer Doll? ile karşılaştın mı? Sözde \"dünyanın gerçeği\", sakin bir zihni tamamen paramparça edebilir. Biz de... sen ve ben de aynı şeye mi dönüşeceğiz?"
  },
  Voice_5184_AwakerVoiceTitle = {
    Text = "Sohbet: @2 Hakkında"
  },
  Voice_5184_UnlockDesc = {
    Text = "Uyanıklaştırıcı@2 elde edildikten sonra açılır"
  },
  Voice_5185_AwakerVoiceContent = {
    Text = "Usta... Emre ihtiyacım var. Lütfen bana emir verin."
  },
  Voice_5185_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5186_AwakerVoiceContent = {
    Text = "Mekanın performansı artırıldı."
  },
  Voice_5186_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5189_AwakerVoiceContent = {Text = "Ehehe!"},
  Voice_5189_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5190_AwakerVoiceContent = {
    Text = "Daha çok dost!"
  },
  Voice_5190_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5191_AwakerVoiceContent = {
    Text = "Daha çok dost!"
  },
  Voice_5191_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5192_AwakerVoiceContent = {
    Text = "Üzgünüm, beşikten ayrılamam... Herkesin görüşünü engelleyebilirim, bu yüzden sınıfın arkasında duracağım."
  },
  Voice_5192_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5193_AwakerVoiceContent = {
    Text = "Ne?! Tek bir tane bile alamadın mı?! Ne Konstantinopolis halısını, ne Seylan Çayı’nı, ne de Endülüs churros’unu...? Of, o kadın onları her seferinde ne kadar kolay elde ediyor! Ben de yaygın şeyler sanmıştım!"
  },
  Voice_5193_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5194_AwakerVoiceContent = {
    Text = "Hâlâ gerçek kaba gücümün soluk bir gölgesi sadece."
  },
  Voice_5194_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5194_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5195_AwakerVoiceContent = {
    Text = "Ne kadar da heveslisin. Senin kalibresindeki biri için bu biraz kaba kaçıyor."
  },
  Voice_5195_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5196_AwakerVoiceContent = {
    Text = "Bu yaratık, irademin yalnızca bir parçası. Biçimi değişmeyebilir, ama gücümün sınırı yok."
  },
  Voice_5196_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5196_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5197_AwakerVoiceContent = {
    Text = "Ah, yine kaotik okyanustayım. Hoşuma gidiyor."
  },
  Voice_5197_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5197_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5198_AwakerVoiceContent = {
    Text = "Pekâlâ. Yeterince çaba gösterdin. Sanırım seni bir yoldaş olarak kabulleneceğim."
  },
  Voice_5198_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5198_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5199_AwakerVoiceContent = {
    Text = "Bu güç bariyerlerini paramparça et; tıpkı bir labirentin duvarını kırıp geçer gibi!"
  },
  Voice_5199_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5199_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5200_AwakerVoiceContent = {
    Text = "Yemeği parçalamak yok, kafeteryanın koltuklarını ezmek yok... Tamam. Lily bir daha yapmayacak."
  },
  Voice_5200_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5200_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5201_AwakerVoiceContent = {
    Text = "Sana Anne diyebilir miyim?"
  },
  Voice_5201_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5201_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5202_AwakerVoiceContent = {
    Text = "Benim için bir emriniz var mı, Efendim?\n\"Siğillerle dışarı çıkma. İnsanlar korkar,\" mı diyorsunuz?\nAnlaşıldı. Lily onları hemen saklayacak."
  },
  Voice_5202_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5202_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5203_AwakerVoiceContent = {
    Text = "Demek Uyanışçı olmak böyle bir şey."
  },
  Voice_5203_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5203_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5204_AwakerVoiceContent = {
    Text = "Anneciğim, yanında uyuyabilir miyim? Yalnızken karanlık, korkunç rüyalar görüyorum. Ellerim ve ayaklarım düşüyor... Gerçekten, gerçekten çok acıyor..."
  },
  Voice_5204_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5204_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5205_AwakerVoiceContent = {
    Text = "Ah! İhsanınız için teşekkürler, Karen sadece mütevazı bir hizmetçi..."
  },
  Voice_5205_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5205_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5206_AwakerVoiceContent = {Text = "Hehe..."},
  Voice_5206_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5207_AwakerVoiceContent = {
    Text = "Biraz oyma malzemesi toplamam gerekiyor, tercihen taze olanlardan."
  },
  Voice_5207_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5208_AwakerVoiceContent = {
    Text = "Lütfen sessiz olun."
  },
  Voice_5208_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5209_AwakerVoiceContent = {
    Text = "Ahmaklığında inat edenler, beyhude işler yapar."
  },
  Voice_5209_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5209_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5210_AwakerVoiceContent = {
    Text = "Peki öyle. Bu noktada amacını az çok kavrayabiliyorum. Devam et."
  },
  Voice_5210_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5210_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5211_AwakerVoiceContent = {
    Text = "Kararlılığını görüyorum. Boşluğa dönmeden önce, bu Varlık, insanlığın varisinin kadere meydan okuyuşuna tanıklık edecek. Ama şimdi... dinlenmek gerek."
  },
  Voice_5211_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5211_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5212_AwakerVoiceContent = {
    Text = "Göklerin iradesine uymak güzel değil mi? Kaderin hükmüne neden direnesin?"
  },
  Voice_5212_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5212_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5213_AwakerVoiceContent = {
    Text = "Dileğini gerçekleştirmek için, ne çok şeyi feda etmeye razısın..."
  },
  Voice_5213_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5213_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5214_AwakerVoiceContent = {
    Text = "Off, bu sinir bozucu değil mi? Bununla ilgili dırdır etmeyi kes! ...Pekâlâ, ne istiyorsan yap. Sonuçta bu sadece vakit öldürmenin bir yolu."
  },
  Voice_5214_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5215_AwakerVoiceContent = {
    Text = "Çözünme... O iğrenç kara gelgitler rüyalarıma sızıyor. Dayanılmaz."
  },
  Voice_5215_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5216_AwakerVoiceContent = {
    Text = "Güç, iki ucu keskin bir kılıçtır. Bunu nasıl anlamamış olabilirim ki? Çok geç fark ettim. Bir kez bırakırsam, beni paramparça edecekler... Keşke en başından senin kadar berrak bir zihne sahip olsaydım da, böyle trajik bir sona kavuşmasaydım. Ha? Bundan sonra müdürün salonunda toplantılar düzenleyebileceğimi mi söylüyorsun?! Bu... Sana bizzat hizmet etmekten başka, bunu nasıl ödeyebilirim ki...?"
  },
  Voice_5216_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5216_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5217_AwakerVoiceContent = {
    Text = "Epey inatçı bir konuksun. Elindeki ayrıcalıktan vazgeçmeni sağlamak için ne yapmalıyım? Güç yalnızca belayı davet eder—böylesine basit bir gerçeği, elbette sen de anlamışsındır?"
  },
  Voice_5217_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5217_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5218_AwakerVoiceContent = {
    Text = "Salon başlamadan önce bir hikâye dinlemek ister misin? Bir köy kızının gücün tacını nasıl ele geçirdiğinin öyküsü... Nereden başlayalım? Anne babasının onu yaşlı bir adamla evlenmeye zorlamasından mı, yoksa asil bahçede serpilip açtığı kısımdan mı?"
  },
  Voice_5218_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5218_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5219_AwakerVoiceContent = {
    Text = "Geçmişte konuklar bana \"Kırmızılı Madam\" derdi. Elbette, sen bana \"Sorel\" de diyebilirsin—sonuçta, sen benim en özel konuğumsun..."
  },
  Voice_5219_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5219_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5220_AwakerVoiceContent = {
    Text = "Ev sahibesi olarak, her konuğun memnuniyetini sağlamak benim görevimdir."
  },
  Voice_5220_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5220_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5221_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5221_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5222_AwakerVoiceContent = {
    Text = "Efendim? Duruşumda bir terslik mi var?"
  },
  Voice_5222_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5223_AwakerVoiceContent = {Text = "Eyvah!"},
  Voice_5223_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5224_AwakerVoiceContent = {
    Text = "Ah, talihsizlik~"
  },
  Voice_5224_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5225_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5225_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5226_AwakerVoiceContent = {
    Text = "Bu hissi hatırlıyorum—o görkemli an yaklaşıyor..."
  },
  Voice_5226_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5226_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5227_AwakerVoiceContent = {
    Text = "Hâlâ solungaçlarım çıkmadı, ama artık bunun için kaygılanmıyorum. Koruyucu, ben senin Karakter Kalkanı’n olacağım ve seni yüzgeçlerimle koruyacağım."
  },
  Voice_5227_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5227_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5228_AwakerVoiceContent = {
    Text = "Bana bunca şey yatırdın... diğer insanlardan gerçekten de daha sabırlısın. Gerçekten... benden tiksinmiyor musun?"
  },
  Voice_5228_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5228_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5229_AwakerVoiceContent = {
    Text = "Neden? Neden ayinden sonra hâlâ solungaçlarım çıkmadı? Dönüşüm yine mi başarısız oldu?! Kahretsin! Kahretsin! Kahretsin!"
  },
  Voice_5229_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5229_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5230_AwakerVoiceContent = {
    Text = "O ses yine beni çağırıyor... derin uçurumdan gelen o dünyevi olmayan tını!"
  },
  Voice_5230_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5230_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5231_AwakerVoiceContent = {
    Text = "Yanlış! Burada değil!"
  },
  Voice_5231_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5232_AwakerVoiceContent = {
    Text = "Cité’den heykeltıraş Sanga, sana keski uzatıyor. Kusurlu olabilirsin, ama yine de yontulmaya değersin."
  },
  Voice_5232_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5238_AwakerVoiceContent = {
    Text = "Etrafıma toplanın, söz dinlemeyen veletler~"
  },
  Voice_5238_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5239_AwakerVoiceContent = {
    Text = "Gerçek Sanat açıklamaya ihtiyaç duymaz."
  },
  Voice_5239_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5240_AwakerVoiceContent = {
    Text = "Gerçek Sanat açıklamaya ihtiyaç duymaz."
  },
  Voice_5240_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5241_AwakerVoiceContent = {
    Text = "Size nasıl yardımcı olabilirim?"
  },
  Voice_5241_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5242_AwakerVoiceContent = {
    Text = "Boruyu çalın!"
  },
  Voice_5242_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5243_AwakerVoiceContent = {
    Text = "Ne pahasına olursa olsun!"
  },
  Voice_5243_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5244_AwakerVoiceContent = {
    Text = "Yeniden güneş ışığına bürünmek... Bunun bu kadar hoş, bu kadar sıcak hissettirdiğini bilmiyordum. Gözlerimi yaşlarla dolduruyor."
  },
  Voice_5244_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5244_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5245_AwakerVoiceContent = {
    Text = "Minnetimi ifade etmek için... Acımın derinliklerinde senin için gizli bir sunak inşa edeceğim."
  },
  Voice_5245_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5245_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5246_AwakerVoiceContent = {
    Text = "Sevgili kardeşimin etiyle benimki gitgide daha kusursuz biçimde kaynaşıyor..."
  },
  Voice_5246_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5246_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5247_AwakerVoiceContent = {
    Text = "Düşündüğünüzden daha dayanıklıyım. Beni kullanırken daha güçlü olun. Lütfen, kendinizi tutmayın."
  },
  Voice_5247_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5247_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5248_AwakerVoiceContent = {
    Text = "Sadece bana mı öyle geliyor? Yoksa... Kana duyduğum açlık biraz azaldı mı?"
  },
  Voice_5248_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5248_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5249_AwakerVoiceContent = {
    Text = "Resmen kabul edilmeden önce bile gelişini dört gözle bekliyordum. Görünüşe bakılırsa birlikte gayet iyi çalışıyoruz, ha? Ortak."
  },
  Voice_5249_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5250_AwakerVoiceContent = {
    Text = "Bu utanç verici."
  },
  Voice_5250_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5251_AwakerVoiceContent = {Text = "Aaah!"},
  Voice_5251_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5252_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_5252_AwakerVoiceTitle = {
    Text = "Darbe: Mani"
  },
  Voice_5253_AwakerVoiceContent = {Text = "Hımm..."},
  Voice_5253_AwakerVoiceTitle = {
    Text = "Darbe: Depresyon"
  },
  Voice_5254_AwakerVoiceContent = {
    Text = "Canımı istediğin kadar yak!"
  },
  Voice_5254_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5255_AwakerVoiceContent = {
    Text = "Gerçekten çok korkuyorum. Hayır, senden korkmuyorum ama... Sana yeniden Dehşet ve Ağıt getirebilirim diye kaygılanıyorum."
  },
  Voice_5255_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5256_AwakerVoiceContent = {
    Text = "Bu çağın masal kitapları, uzun zaman önce okuduklarımdan çok daha eğlenceli! Aa, aa! Efendim, lütfen yanlış anlamayın! Artık yatmadan önce masal dinleyecek yaşta değilim!"
  },
  Voice_5256_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5257_AwakerVoiceContent = {
    Text = "Canımı istediğin kadar yak!"
  },
  Voice_5257_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5258_AwakerVoiceContent = {
    Text = "Off... Sana bir sıkıntı çıkardım mı?"
  },
  Voice_5258_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5259_AwakerVoiceContent = {
    Text = "O eğlenceli güvenine hep sıkı sıkıya tutundun ve yanımda kaldın... Pekâlâ, belki seni kullanmak o kadar da kötü bir fikir değildir. Ama şunu unutma: Hiçbir ihanete tahammül edemem, hele ki senden gelene asla."
  },
  Voice_5259_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5259_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5260_AwakerVoiceContent = {
    Text = "Tek pişmanlığım, cesetlerini kazıklara geçirmeyip surlara asmamış olmam! Beni satan, çiğneyen ya da aşağılayan hiç kimseyi sağ bırakmayacağım!"
  },
  Voice_5260_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5260_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5261_AwakerVoiceContent = {
    Text = "Evet, o insanların önünde süründüm; bunu inkâr edemem. Cehaletimden faydalandılar, ben de bunun bedelini onlara ödetim."
  },
  Voice_5261_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5261_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5262_AwakerVoiceContent = {
    Text = "Birkaç tatlı söz ve birkaç günlük sahte iyilikle, yeniden Zincirler’i takıp senin oyuncağın olmaya razı olacağımı mı sanıyorsun?"
  },
  Voice_5262_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5262_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5263_AwakerVoiceContent = {
    Text = "Beni kontrol etmeye ya da kullanmaya çalışanların hepsi, kendi elimle yeraltına gönderildi—seni de oraya yollamaktan çekinmem."
  },
  Voice_5263_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5263_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5264_AwakerVoiceContent = {
    Text = "Ah... Özür dilerim, l-lütfen kıpırdama!"
  },
  Voice_5264_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5265_AwakerVoiceContent = {
    Text = "Çekil üstümden!"
  },
  Voice_5265_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5266_AwakerVoiceContent = {
    Text = "Küstahlık!"
  },
  Voice_5266_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5267_AwakerVoiceContent = {
    Text = "Teslim ol... Hoş geldin, ince zevklerin ve rüyaların diyarına."
  },
  Voice_5267_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5268_AwakerVoiceContent = {
    Text = "Bu, sayısız kayıp ruhun dolaştığı, asla yuvalarına dönemeyecekleri şehirdir."
  },
  Voice_5268_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5269_AwakerVoiceContent = {
    Text = "B-Ben... Ben yapabilirim!"
  },
  Voice_5269_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5270_AwakerVoiceContent = {
    Text = "Şey... Can gücünü absorbe etme yeteneğimi kontrol edemiyorum, bu yüzden lütfen elini beşiğe sokma, yoksa hasta olursun."
  },
  Voice_5270_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5271_AwakerVoiceContent = {
    Text = "Konuşmamız sırasında arızalanmamasını içtenlikle diliyorum. O sevimli ama bir o kadar da sinir bozucu asistanım için artık yanlışlıkla havaya uçurabileceği yedek laboratuvar kalmadı."
  },
  Voice_5271_AwakerVoiceTitle = {
    Text = "Sohbet: Erica Hakkında"
  },
  Voice_5271_UnlockDesc = {
    Text = "\"Erica\" Uyandıranı edinince açılır"
  },
  Voice_5272_AwakerVoiceContent = {
    Text = "Kollar, şu baş belası kollar! Saçlarıma sürekli yapışıyorlar. Kendi ellerimi bile kontrol edemiyorum—ne işe yaramaz bir kadınım ben... Belki de..."
  },
  Voice_5272_AwakerVoiceTitle = {
    Text = "Sohbet: Helot’un Kendisi Hakkında"
  },
  Voice_5274_AwakerVoiceContent = {
    Text = "Rehberliğin için teşekkür ederim. Sonunda Faint'in Seçimini anladım. Her şeyi kendiliğinden oluyor sandım, bunun ona yüklediği zihinsel yükü fark etmedim. Bundan sonra, Sadece Kendim İçin yaşamaya çalışacağım."
  },
  Voice_5274_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5274_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5275_AwakerVoiceContent = {
    Text = "Uzun, sonu gelmeyen zamanlar boyunca, Faint ve ben yalnızca birbirimize sahiptik. Ama şimdi, hayatımda yeni ve önemli biri var. Koruyucu, lütfen daha önce söylediklerimi geri almama izin ver. Sen farklısın. Benim şarkılarımdan ve görünüşümden fazlasını görüyorsun; beni gerçekten görüyorsun. Bu yüzden ben de seni koruyacağım. Gözlerimi senden asla çevirmeyeceğim."
  },
  Voice_5275_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5275_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5276_AwakerVoiceContent = {
    Text = "Benim uyuyan yıldızlarımın düşleri şimdi kıpırdanıyor—bırak, yazgılı kaderlerine doğru birleşsinler. Yolunu İlahi Âlem’e çevir!"
  },
  Voice_5276_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5277_AwakerVoiceContent = {
    Text = "Neden hep bu elbiseyle giyinmişim? Çünkü sana her an şarkı söyleyebileyim diye."
  },
  Voice_5277_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5277_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5278_AwakerVoiceContent = {
    Text = "Sadece Kendim İçin ne yapmak istiyorum? Üzgünüm, ne demek istediğini anlamıyorum. Aslında Faint bana bu Soruyu defalarca sordu, ama benim tek istediğim onun bir an önce iyileşmesi."
  },
  Voice_5278_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5278_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5279_AwakerVoiceContent = {
    Text = "Issız gezegendeki günlerimiz boyunca, o nüfuzlu kişilerin merhameti, kız kardeşimle bana hayatta kalmamız için gereken kaynakları sağladı. Sonunda, gezegenden kaçma fırsatını da verdiler bana, her ne kadar yalnızca bir kişiyle sınırlı olsa da. Onların hepsi benim iyilikçilerim; tıpkı bana kalacak bir yer veren sen, Koruyucu, gibi."
  },
  Voice_5279_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5279_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5280_AwakerVoiceContent = {
    Text = "Bana kalacak bir yer sağlayan nazik kişi sensin. Dediğin gibi yapacağım. Keşke biraz daha işe yarayabilseydim..."
  },
  Voice_5280_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5281_AwakerVoiceContent = {
    Text = "Mekânı ayırtmayı unutma. Bana, Elworth’tekinden bile küçük olduğunu söyleme sakın?"
  },
  Voice_5281_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5281_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5282_AwakerVoiceContent = {
    Text = "Harika! Şimdi daha da motive oldum! Günde yirmi oda temizleyebilirim!"
  },
  Voice_5282_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5282_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5283_AwakerVoiceContent = {
    Text = "Bu, göl suyu kadar kadim, \"bize\" ait bir müzik. Efendim, hadi birlikte dans edelim! Sesim \"O\" tarafından alınmadan önce dans edip şarkı söyleyelim..."
  },
  Voice_5283_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5283_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5284_AwakerVoiceContent = {
    Text = "Usta! Sesim... sönüyor... Yardım edin..."
  },
  Voice_5284_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5284_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5285_AwakerVoiceContent = {
    Text = "Görüşüm düzeldi... Efendim, yine saçınızı taramayı mı unuttunuz?!"
  },
  Voice_5285_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5285_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5286_AwakerVoiceContent = {
    Text = "Belki daha güçlü oldum, ama hiç intikam istemiyorum. Sadece şarkı söylemek istiyorum! Dans! Parti!"
  },
  Voice_5286_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5286_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5287_AwakerVoiceContent = {
    Text = "Yok Oluş'tan sağ çıkmak için ruhumu ve kanımı çok fazla kişiyle paylaştım. Şimdiki gücüm, bu Yüce İrade’yi ilk kucakladığım zamanki hâlinin yalnızca bir hayaleti..."
  },
  Voice_5287_AwakerVoiceTitle = {
    Text = "Sohbet: Geçmiş Üzerine"
  },
  Voice_5288_AwakerVoiceContent = {
    Text = "Don't expect to find me in the teaching building. It stinks of musty old scholars; I can't stand that place.\nBeni derslik binasında bulmayı bekleme. Küflü, yaşlı bilgin kokuyor orası; o yere katlanamıyorum."
  },
  Voice_5288_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5289_AwakerVoiceContent = {Text = "Kaçma."},
  Voice_5289_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5290_AwakerVoiceContent = {
    Text = "Benim Beyaz Kuş Diyarı’m Tanrımız’a tapar. Buna karşılık, takip ettiğim Kral da elbette “ilahi bir iletişimci”dir."
  },
  Voice_5290_AwakerVoiceTitle = {
    Text = "Sohbet: Ebedî Krallık Hakkında"
  },
  Voice_5291_AwakerVoiceContent = {
    Text = "Burada epey yetenek toplamışsın, görkemli bir salonu hak ediyor... İçin rahat olsun, Davet sana hizmetkârım tarafından ulaştırılacak."
  },
  Voice_5291_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5292_AwakerVoiceContent = {Text = "Hadi ama!"},
  Voice_5292_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5293_AwakerVoiceContent = {
    Text = "Keşke daha fazla Dost olsaydı..."
  },
  Voice_5293_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5294_AwakerVoiceContent = {
    Text = "Ben onun gibi değilim. O sadece seni ürpertmeyi ve dehşete boğmayı biliyor. Ama ben mi? Sana kutsal, kavurucu bir aşk vereceğim."
  },
  Voice_5294_AwakerVoiceTitle = {
    Text = "Sohbet: Wanda Hakkında"
  },
  Voice_5294_UnlockDesc = {
    Text = "\"Wanda\" Uyandıranı edinince açılır"
  },
  Voice_5295_AwakerVoiceContent = {
    Text = "Sakın bunun bittiğini sanma! Bu aşağılanmanın her zerresinin hesabını sana ödeteceğim!"
  },
  Voice_5295_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5296_AwakerVoiceContent = {
    Text = "Ellerin sıcak, tıpkı ruhun gibi. Ben... dokunuşunu takdir ediyorum, Solgun Alev."
  },
  Voice_5296_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5297_AwakerVoiceContent = {
    Text = "Sınıfta briç oynamakta ne sakınca var? Masa var, insanlar burada, kartları da getirdim! Bu da demek oluyor ki \"Oyun Başlasın!\""
  },
  Voice_5297_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5299_AwakerVoiceContent = {Text = "Yapma..."},
  Voice_5299_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5300_AwakerVoiceContent = {
    Text = "Uçuruma bak!"
  },
  Voice_5300_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5301_AwakerVoiceContent = {
    Text = "Uçuruma bak!"
  },
  Voice_5301_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5302_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_5302_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5303_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_5303_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5304_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_5304_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5305_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_5305_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5306_AwakerVoiceContent = {
    Text = "Onun ilahi ışığında yıkanın!"
  },
  Voice_5306_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5307_AwakerVoiceContent = {Text = "Hey!"},
  Voice_5307_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5308_AwakerVoiceContent = {
    Text = "Zayıf ruhların bir araya gelişi... Gürültü çıkarmaktan başka ne işe yararız ki? Ah..."
  },
  Voice_5308_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5311_AwakerVoiceContent = {
    Text = "Savaş daima Pain getirir ve acıya katlanmak bir savaşçının görevidir. Ellerimi, ayaklarımı, her şeyimi kaybetsem bile, senin ve Adalet için savaşmaya devam edeceğim."
  },
  Voice_5311_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5312_AwakerVoiceContent = {
    Text = "Bu mu O’na sunduğun ziyaret?"
  },
  Voice_5312_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5313_AwakerVoiceContent = {
    Text = "Gerçekten bunun geleceği değiştirmeye yeteceğini mi sanıyorsun?"
  },
  Voice_5313_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5314_AwakerVoiceContent = {
    Text = "Artık o... rahmimin içinde..."
  },
  Voice_5314_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5315_AwakerVoiceContent = {
    Text = "Heh. Düşündüğümden biraz daha zekisin."
  },
  Voice_5315_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5316_AwakerVoiceContent = {
    Text = "Benim kölem olarak, efendine ziyaretini sunman son derece doğal."
  },
  Voice_5316_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5317_AwakerVoiceContent = {
    Text = "Beni memnun etmeye çalışırken oldukça eğlenceli görünüyorsun."
  },
  Voice_5317_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5318_AwakerVoiceContent = {
    Text = "Brownie, karamelli puding, Sachertorte, çikolatalı mus, kurabiyeler... Her bir masada mutlaka olacak!"
  },
  Voice_5318_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5318_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5319_AwakerVoiceContent = {
    Text = "Elbisemi benim için kontrol et, çabuk! Ne kırışıklık olacak, ne de bir yerinden sökülmüş... Ne? Bir sorun mu var?"
  },
  Voice_5319_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5319_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5320_AwakerVoiceContent = {
    Text = "Son Aydınlanma Törenime Hoş Geldin! Bunların hepsi titizlikle benim tarafımdan tasarlandı. Elbette sen de katkıda bulundun... ufacık da olsa."
  },
  Voice_5320_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5320_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5321_AwakerVoiceContent = {
    Text = "Masa ve sandalyelerde zevkime uygun danteller olmalı, saksı Bitkileri ise kırmızı örümcek zambakları... Şimdi, çabuk ol ve bunları hazırla!"
  },
  Voice_5321_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5321_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5322_AwakerVoiceContent = {
    Text = "Git ve Konukları davet et! Şu basit Görev bile sana fazla mı geliyor?"
  },
  Voice_5322_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5322_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5323_AwakerVoiceContent = {
    Text = "Kaçış yok!"
  },
  Voice_5323_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5324_AwakerVoiceContent = {
    Text = "Kaçış yok!"
  },
  Voice_5324_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5325_AwakerVoiceContent = {
    Text = "Umutlarını boşa çıkarmamak için elimden gelenin en iyisini yapacağım, efendim!"
  },
  Voice_5325_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5325_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5326_AwakerVoiceContent = {
    Text = "O kadını epey seviyorum. Bizim… bizim… evet, ortak bir dilimiz var!"
  },
  Voice_5326_AwakerVoiceTitle = {
    Text = "Sohbet: Wanda Hakkında"
  },
  Voice_5326_UnlockDesc = {
    Text = "\"Wanda\" Uyandıranı edinince açılır"
  },
  Voice_5327_AwakerVoiceContent = {Text = "Küstah!"},
  Voice_5327_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5328_AwakerVoiceContent = {Text = "Küstah!"},
  Voice_5328_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5329_AwakerVoiceContent = {
    Text = "Enkaz yığınına dönüş."
  },
  Voice_5329_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5330_AwakerVoiceContent = {
    Text = "Paramparça ol."
  },
  Voice_5330_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5331_AwakerVoiceContent = {
    Text = "Gerçekliğin bariyerini delip geç!"
  },
  Voice_5331_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5332_AwakerVoiceContent = {
    Text = "Yakında yelken açmayı mı planlıyorsun? Mütevazı ricamı kabul edip beni de yanına alır mısın? Yeter ki denize ulaşabileyim..."
  },
  Voice_5332_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5332_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5333_AwakerVoiceContent = {
    Text = "Hâlâ bana güveniyorsan, lütfen bu yolculukta Kılavuz Işığın olmama izin ver. Oysa böylesine basit bir Görevde bile daha önce başarısız oldum..."
  },
  Voice_5333_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5333_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5334_AwakerVoiceContent = {
    Text = "Benimle birlikte denize açılmak ister misin? Şu anki haritaya bakmama izin ver... 47°9' G, 126°43' B, tam oraya gideceğiz."
  },
  Voice_5334_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5334_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5335_AwakerVoiceContent = {
    Text = "Geçmişte birçok felakete sebep oldum, bazı uygarlıkları neredeyse Yıkımın eşiğine getirdim... Bunu kasıtlı yapmadığımı söylersem, artık çok mu geç?"
  },
  Voice_5335_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5335_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5336_AwakerVoiceContent = {
    Text = "Ben Ebedi Krallığın girişinin koruyucusuyum, eve dönenlere rehberlik ederim. Ne ironik ki böyle bir görevi olan ben, dönüş yolunu unutmuşum...\nSen... benim fenerim olur musun?"
  },
  Voice_5336_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5336_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5337_AwakerVoiceContent = {
    Text = "Yıldız kümesine bak."
  },
  Voice_5337_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5338_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5338_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5339_AwakerVoiceContent = {
    Text = "Yoğun sis çöküyor."
  },
  Voice_5339_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5340_AwakerVoiceContent = {Text = "Hıh."},
  Voice_5340_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5341_AwakerVoiceContent = {
    Text = "Çoğu insan için uzun yolculuğu kutsamak benim için fark etmez... o kadın hariç. Mümkünse, lütfen benim için başka bir rota ayarlayın."
  },
  Voice_5341_AwakerVoiceTitle = {
    Text = "Sohbet: Miryam Hakkında"
  },
  Voice_5341_UnlockDesc = {
    Text = "Uyanışçı \"Miryam\" elde edildikten sonra açılır"
  },
  Voice_5342_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5342_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5343_AwakerVoiceContent = {Text = "Her neyse."},
  Voice_5343_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5344_AwakerVoiceContent = {
    Text = "Ellerini benden çek."
  },
  Voice_5344_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5345_AwakerVoiceContent = {
    Text = "Denizin dibindeki sarayımıza dönmeden önce, sıradan bir insan olan sana Aequor’un gücünden biraz ödünç vereceğim, ama yalnızca bu kez."
  },
  Voice_5345_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5346_AwakerVoiceContent = {Text = "Git!"},
  Voice_5346_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5347_AwakerVoiceContent = {
    Text = "Neyi severim? Izdırabın incecik Gerçek’ini severim. Şişmiş etin o güzel, yakan kızarıklığını... Bir iniltiyle hazzın mı yoksa ızdırabın mı anlatıldığının ayırt edilemediği anı. Sahip olduğumuz tek dürüst arzu bu, sence de öyle değil mi?"
  },
  Voice_5347_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5348_AwakerVoiceContent = {
    Text = "Hadi! Aurita’ya katıl!"
  },
  Voice_5348_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5349_AwakerVoiceContent = {
    Text = "Hadi! Aurita’ya katıl!"
  },
  Voice_5349_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5350_AwakerVoiceContent = {
    Text = "Bana hep o kızgın bakışı atıyor. Ama nedense, tanıdık geliyor. Güvenli. Anne gibi hissettirdiği için mi?"
  },
  Voice_5350_AwakerVoiceTitle = {
    Text = "Sohbet: Helot Hakkında"
  },
  Voice_5350_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Helot\" elde edildikten sonra açılır"
  },
  Voice_5351_AwakerVoiceContent = {
    Text = "Zihnim daha keskin; hiç de fena değil."
  },
  Voice_5351_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5351_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5352_AwakerVoiceContent = {
    Text = "Saha görevindense laboratuvar çalışmalarını çok daha fazla tercih ederim—o destek araçlarının gerçekten de denizden gelen birer mucize gibi ansızın belirdiğine mi inanıyordun?"
  },
  Voice_5352_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5352_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5353_AwakerVoiceContent = {
    Text = "İster vida olsun ister çivi, ne kadar çok olursa o kadar iyi!"
  },
  Voice_5353_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5354_AwakerVoiceContent = {
    Text = "Bu beden bu Güç’ü zar zor taşıyor, ama kukla değiştirme vakti henüz gelmedi. Öylece dikilip duracağına neyi bekliyorsun? Şu bacağıma yardım et; bazı ayarlamalar gerekiyor."
  },
  Voice_5354_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5354_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5355_AwakerVoiceContent = {
    Text = "Kılavuz ışığın yükü, en saf azizleri bile ezebilir. Kendini yorgun hissedersen, solgun alevim, lütfen içini bana aç. Yükünü hafifletmek ve bu sayısız lütfun ağırlığını seninle paylaşmak için elimden gelen her şeyi yapacağım."
  },
  Voice_5355_AwakerVoiceTitle = {
    Text = "Sohbet: Yorgunluk Hakkında"
  },
  Voice_5356_AwakerVoiceContent = {
    Text = "Sizin güveniniz, benim bir Şövalye olarak var oluş sebebimdir."
  },
  Voice_5356_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5356_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5357_AwakerVoiceContent = {
    Text = "Böylesine kutsal bir aydınlıkla yıkanmak… Bu, Onun taşıdığı ilahi güç mü? Ne kadar hudutsuz… ne kadar yüce…"
  },
  Voice_5357_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5357_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5358_AwakerVoiceContent = {
    Text = "Onun diyarına açılan kapı neredeyse erişimde."
  },
  Voice_5358_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5358_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5359_AwakerVoiceContent = {
    Text = "Daha parlak... ve daha berrak..."
  },
  Voice_5359_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5359_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5360_AwakerVoiceContent = {
    Text = "Bir Uyanış sahibi olarak bütünüyle eski hâlime döndüm... Şimdi İlahi Diyar’ın korosu içimde yankılanıyor..."
  },
  Voice_5360_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5360_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5361_AwakerVoiceContent = {
    Text = "Beni kendi mabedine, sükûnetinin düşlerimi örttüğü yere o yöneltsin..."
  },
  Voice_5361_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5361_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5362_AwakerVoiceContent = {
    Text = "Merak etmeyin, hepimiz oldukça işe yararız. Ben dikebilirim, temizlik yapabilirim; başka bir ben dövüşte çok iyidir, diğerleri ise..."
  },
  Voice_5362_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5363_AwakerVoiceContent = {
    Text = "Parlak, yumuşak şeylerden tiksinirim. Nezaket bir Yansıma gibidir; tüm çirkinliğimi, tamahımı ve kırılganlığımı açığa vurur."
  },
  Voice_5363_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5364_AwakerVoiceContent = {
    Text = "Brown’u sevmek mi istiyorsun? Bana kalmış bir şey değil. Gidip ona kendin soracaksın."
  },
  Voice_5364_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5365_AwakerVoiceContent = {
    Text = "Want to please me? Then kneel, offer your neck, and shut up until I finish draining you.\nBeni memnun etmek mi istiyorsun? O zaman diz çök, boynunu uzat ve seni tamamen Tükenme’ye sürükleyip bitirene kadar sus."
  },
  Voice_5365_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5366_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5366_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5367_AwakerVoiceContent = {
    Text = "Dün, yeniden Yıldızlar arasında sürüklenmeye başladığım günü rüyamda gördüm."
  },
  Voice_5367_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5367_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5368_AwakerVoiceContent = {
    Text = "Size ne konuda yardımcı olabilirim...?"
  },
  Voice_5368_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5368_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5369_AwakerVoiceContent = {
    Text = "Hissedebiliyorum~"
  },
  Voice_5369_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5370_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5370_AwakerVoiceTitle = {
    Text = "Yetenek: III"
  },
  Voice_5371_AwakerVoiceContent = {Text = "Dikkat et!"},
  Voice_5371_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5372_AwakerVoiceContent = {
    Text = "Geri çekil."
  },
  Voice_5372_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5373_AwakerVoiceContent = {
    Text = "Kimsenin incinmeyeceği... bir dünya... gelecek."
  },
  Voice_5373_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5374_AwakerVoiceContent = {Text = "(İnler)"},
  Voice_5374_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5375_AwakerVoiceContent = {
    Text = "Lütfen bu yere O’nun suretine adanmış bir sunak yerleştirmeme izin verin. Dindar ellerce yontulmuş bir heykeldir ve hiçbir lanet taşımaz."
  },
  Voice_5375_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5376_AwakerVoiceContent = {
    Text = "Belki... sadece birazcık..."
  },
  Voice_5376_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5377_AwakerVoiceContent = {
    Text = "Anahtarım hâlâ yerinde değil!"
  },
  Voice_5377_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5378_AwakerVoiceContent = {
    Text = "Kimya, Fizik, Gümüş Çekirdek Uygulamaları... Bu çağda artık Yedi Şövalye Sanatı’nı öğrenmek gerekmiyor mu? Anladım. Öyleyse, lütfen benim için uygun dersleri ayarlayın, efendim!"
  },
  Voice_5378_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5379_AwakerVoiceContent = {
    Text = "Yolculuk yaptım! Dalgalar beni sürüklemedi, gerçekten bir kervana bindim!"
  },
  Voice_5379_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5379_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5380_AwakerVoiceContent = {
    Text = "Fener denizanası, taç denizanası, şeftali çiçeği denizanası—hepsi sürü halinde hareket eder. Elbette Aurita da öyle! Herkes’le birlikte olmak istiyorum!"
  },
  Voice_5380_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5380_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5381_AwakerVoiceContent = {
    Text = "Geçmiş Etkinlikler mi? Hatırlaması zor... Ama bir akvaryumda çalıştığımı hatırlıyorum! Günde 2 Pensh alıyordum!"
  },
  Voice_5381_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5381_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5382_AwakerVoiceContent = {
    Text = "Sana bir Sır vereyim: Aslında Atlan...tis’ten... ıı, kısacası, ben bir deniz insanıyım! Uslu durduğum, sebzelerimi yediğim ve daha çok arkadaş edindiğim sürece, o Atlan-her-neydiyse orası beni Hoş Geldin’le karşılayacak!"
  },
  Voice_5382_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5382_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5383_AwakerVoiceContent = {
    Text = "Benim Yurt’um, akvaryumdaki arkadaşlarım, en sevdiğim denizanaları—hepsi yok oldu... Sen de mi yok olacaksın? Benimle sonsuza dek kalamaz mısın?"
  },
  Voice_5383_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5383_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5384_AwakerVoiceContent = {
    Text = "Üstün mü geldik? Bu... iyi."
  },
  Voice_5384_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5387_AwakerVoiceContent = {
    Text = "Barış için!"
  },
  Voice_5387_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5388_AwakerVoiceContent = {
    Text = "Adalet için!"
  },
  Voice_5388_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5389_AwakerVoiceContent = {
    Text = "Evet... İçimde olduğunu biliyorum!"
  },
  Voice_5389_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5390_AwakerVoiceContent = {
    Text = "İnsanlar, sahte tanrılar, Uyananlar, hatta Çözünme bile... Hepsi İlahi Âlemi yeniden inşa edişimin temeli olacak."
  },
  Voice_5390_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5391_AwakerVoiceContent = {
    Text = "Uyanış, uyanış! İçimde olduğunu biliyorum!"
  },
  Voice_5391_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5392_AwakerVoiceContent = {
    Text = "Uvhash... Bana kardeşimi hatırlatıyor; Karanlık, soğuk ve Uykusuz günlerin Anılarını geri getiriyor."
  },
  Voice_5392_AwakerVoiceTitle = {
    Text = "Sohbet: Uvhash Hakkında"
  },
  Voice_5392_UnlockDesc = {
    Text = "\"Uvhash\" Uyandıranı edinince açılır"
  },
  Voice_5393_AwakerVoiceContent = {
    Text = "Bizim ilişkimiz Sherlock’la Watson gibi, değil mi? Son çıkan dergilere baktın mı?"
  },
  Voice_5393_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5394_AwakerVoiceContent = {
    Text = "Güzelliğin önünde eğil."
  },
  Voice_5394_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5395_AwakerVoiceContent = {
    Text = "Güzelliğin önünde eğil."
  },
  Voice_5395_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5396_AwakerVoiceContent = {
    Text = "Tiksinti, betimleyici bir fiil; bir şeyden hoşlanmamaya başlama anlamına gelir. Hoşlanmamak, bir fiil; bir şeyden tiksinildiğinde ve ondan kaçınıldığında hissedilen duyguyu ifade eder. Nefret, bir isim; hoşlanmama duygusu, <Del:Nefret edilmekten nefret ediyorum! Bırakın imha edeyim imha imha İMHA> —Üzgünüm, ama sanırım \"nefret\" in ne olduğunu anlamıyorum."
  },
  Voice_5396_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5397_AwakerVoiceContent = {
    Text = "Sonunda, ben sadece..."
  },
  Voice_5397_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5398_AwakerVoiceContent = {
    Text = "...eski benliğimden daha da uzağa savruluyorum."
  },
  Voice_5398_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5399_AwakerVoiceContent = {
    Text = "Adımı unutma, Golyat. Bu isim, İnsanlığın Işığı’nın önemsiz tarihini çiğnemek için yazgılanmış."
  },
  Voice_5399_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5400_AwakerVoiceContent = {
    Text = "Lütfen kaygılanmayın."
  },
  Voice_5400_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5401_AwakerVoiceContent = {
    Text = "Umarım potansiyelini ve İnsanlığın Işığı’nın beklentilerini heba etmezsin, yeni Koruyucu."
  },
  Voice_5401_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5402_AwakerVoiceContent = {
    Text = "Aşırı yüklenme."
  },
  Voice_5402_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5403_AwakerVoiceContent = {
    Text = "Aşırı sürüş."
  },
  Voice_5403_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5404_AwakerVoiceContent = {
    Text = "Hımm? Cüzdanımdaki o fotoğrafı mı soruyorsun? Ah, o eski ben. Şimdiki görünüşüm, kumar ortağım ve rakibimden gelen bir... hediye."
  },
  Voice_5404_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5404_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5405_AwakerVoiceContent = {
    Text = "Mükemmel—bir kumar oynamaya ne dersin? Kazanırsan, bir sır paylaşırım.\nAma dikkat et, Alva seni yakalayabilir~"
  },
  Voice_5405_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5405_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5406_AwakerVoiceContent = {
    Text = "Bu kürkü beğendin mi? Dokunmak ister misin? Merak etme, benim için sakıncası yok!"
  },
  Voice_5406_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5406_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5407_AwakerVoiceContent = {
    Text = "Elbette faydaları var. Sonuçta kendi Watson’ımla tanıştım, değil mi? Bunun yanında, ölmek ve görünüş değiştirmek pek de önemli sayılmaz."
  },
  Voice_5407_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5407_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5408_AwakerVoiceContent = {
    Text = "Hiç pişman olur muyum? Asla. Her şey tıkır tıkır gitse hayat fazlasıyla sıkıcı olmaz mıydı?"
  },
  Voice_5408_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5408_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5409_AwakerVoiceContent = {
    Text = "Benim zamanımda okullar savaşçı yetiştirme yerleriydi. Görünen o ki şimdi de öyle."
  },
  Voice_5409_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5410_AwakerVoiceContent = {
    Text = "Mason… Yok, böyle iyi. En azından yine birlikteyiz, \"24\"."
  },
  Voice_5410_AwakerVoiceTitle = {
    Text = "Sohbet: \"24\" Hakkında"
  },
  Voice_5410_UnlockDesc = {
    Text = "\"24\" Uyandıranı edinince açılır"
  },
  Voice_5411_AwakerVoiceContent = {
    Text = "Fena değildi, ha? Şimdi, ödemem.—Ne? Bunun bedava bir ziyafet olduğunu mu sandın?!"
  },
  Voice_5411_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5412_AwakerVoiceContent = {
    Text = "Ben Cité’denim. Orada herkes aktör olmak ister; kimse yalnızca izlemekle yetinmez. Gerçekteyse biz, şehrin zavallı dipnotlarından ibaretiz."
  },
  Voice_5412_AwakerVoiceTitle = {
    Text = "Sohbet: Geçmiş Üzerine"
  },
  Voice_5413_AwakerVoiceContent = {
    Text = "Şu kadim taş oymalarını gördün mü? Sıradağlar ile kaynaşmış, zamana direnen, ne muhteşem kalıntılar... ama yine de yeterince uzun süre dayanamıyorlar..."
  },
  Voice_5413_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5414_AwakerVoiceContent = {
    Text = "Güvercinler dönmedi..."
  },
  Voice_5414_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5415_AwakerVoiceContent = {Text = "Geri dur!"},
  Voice_5415_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5416_AwakerVoiceContent = {Text = "Hıh!"},
  Voice_5416_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5417_AwakerVoiceContent = {
    Text = "Emrettiğiniz gibi!"
  },
  Voice_5417_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5418_AwakerVoiceContent = {Text = "Aptal"},
  Voice_5418_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5419_AwakerVoiceContent = {
    Text = "...Ha? Bana mı seslendin? Motosikleti tamir ederken duymadım... Bu arada, iyi yürekli yabancı, İngiliz anahtarımı gördün mü?"
  },
  Voice_5419_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5419_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5420_AwakerVoiceContent = {
    Text = "Hafızam hep bulanık, sadece gözümün önündekine odaklanabiliyorum. Yine de adını zihnime kazımak için elimden geleni yapacağım... Neydi tekrar?"
  },
  Voice_5420_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5420_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5421_AwakerVoiceContent = {
    Text = "Biraz tanıdık görünüyorsun ama adını hatırlayamıyorum... Benim Destek’im misin? Bana yedi civata getirebilir misin?"
  },
  Voice_5421_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5421_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5422_AwakerVoiceContent = {
    Text = "Adını motoruma, Hayalet’e kazıdım! Bir gün maceralara çıktığımızda, sana nasıl hitap edeceğimi unutmayacağım."
  },
  Voice_5422_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5422_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5423_AwakerVoiceContent = {
    Text = "Ne kadar da tanıdık, ne kadar da tanıdık. Aramızda bir şeyler geçmiş olmalı, değil mi? Hatırlamam için bana biraz zaman ver... Ah, sendin, Koruyucu!"
  },
  Voice_5423_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5423_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5424_AwakerVoiceContent = {
    Text = "Gerçekten de ne kadar dürüst olmayan bir çocuksun. Neyse ki seni beklemek için sonsuzluğa sahibim..."
  },
  Voice_5424_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5425_AwakerVoiceContent = {
    Text = "Ne kadar güzel bir \"Mutlu Son.\" Öyle değil mi?"
  },
  Voice_5425_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5426_AwakerVoiceContent = {
    Text = "Bu, ganimet için fena sayılmayacak bir kafatasıydı... En iyi koleksiyonumla boy ölçüşemese de, avın heyecanı her zaman büyüleyicidir. Bir dahaki sefere de beni davet et."
  },
  Voice_5426_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5427_AwakerVoiceContent = {Text = "Hımm..."},
  Voice_5427_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5428_AwakerVoiceContent = {
    Text = "Profesyonel bir hizmetçi, efendisi için her şeyi tamamlar, kötü adamlar da dahil~"
  },
  Voice_5428_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5429_AwakerVoiceContent = {
    Text = "Artık suç ortağıyız, değil mi? Bir gün kendini sokakta bulursan, seni artıklara mahkûm bırakmam."
  },
  Voice_5429_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5430_AwakerVoiceContent = {
    Text = "Büyü ve serpıl, küçük fidem."
  },
  Voice_5430_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5431_AwakerVoiceContent = {
    Text = "Büyü ve serpıl, küçük fidem."
  },
  Voice_5431_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5432_AwakerVoiceContent = {
    Text = "Zarlarım bugün biraz daha sıcak yuvarlanıyor gibi!"
  },
  Voice_5432_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5433_AwakerVoiceContent = {
    Text = "Vay canına! Şansın şu an cayır cayır yanıyor!"
  },
  Voice_5433_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5434_AwakerVoiceContent = {
    Text = "Şanslısın~"
  },
  Voice_5434_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5435_AwakerVoiceContent = {
    Text = "Bana yaklaşma!"
  },
  Voice_5435_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5436_AwakerVoiceContent = {
    Text = "Bana yaklaşma!"
  },
  Voice_5436_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5437_AwakerVoiceContent = {
    Text = "Seni suçlamak zorundayım, Koruyucu. Şefkatin beni huzursuz ediyor—yalnızca fiziksel Pain bana gerçek ve sağlam geliyor."
  },
  Voice_5437_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5438_AwakerVoiceContent = {
    Text = "Gerçekten de epey iyi."
  },
  Voice_5438_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5439_AwakerVoiceContent = {
    Text = "Bu seviye pek de yeterli sayılmaz."
  },
  Voice_5439_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5440_AwakerVoiceContent = {
    Text = "Peki, hangi ödülü istiyorsun?"
  },
  Voice_5440_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5441_AwakerVoiceContent = {
    Text = "Ugh! Her yerde sefalet ve keşmekeş... Ayağımı koyacak düzgün bir yer bile bulamıyorum. Pekâlâ, bana yumuşak sırtını sun, ölümlü."
  },
  Voice_5441_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5442_AwakerVoiceContent = {
    Text = "Sonunda... İşte orada."
  },
  Voice_5442_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5443_AwakerVoiceContent = {
    Text = "Brown’un tüyleri bile ipek gibi oldu."
  },
  Voice_5443_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5443_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5444_AwakerVoiceContent = {
    Text = "Bak, belki en iyi Güvenlik Görevlisi değilim, ama bana her türlü ayak işini ya da teslimatı emanet edebilirsin."
  },
  Voice_5444_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5444_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5445_AwakerVoiceContent = {
    Text = "Brown'a bakışına bak.\n...Heh heh, büyük Brown bu gece bir korkağın ayak parmaklarını kemirmek istiyor. Şanslı zavallı kim acaba?"
  },
  Voice_5445_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5445_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5446_AwakerVoiceContent = {
    Text = "Sonunda boyum uzayacak mı, dersin?"
  },
  Voice_5446_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5446_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5447_AwakerVoiceContent = {
    Text = "O hâlde işe koyulma zamanı, ha? Hadi Brown, kendine gel!"
  },
  Voice_5447_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5447_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5448_AwakerVoiceContent = {
    Text = "Agrippa? Who was that? Oops, I've killed too many. Most of them weren't worth remembering.\nAgrippa mı? Kimdi o? Aaa, çok fazla öldürdüm. Çoğu hatırlanmaya değmezdi zaten."
  },
  Voice_5448_AwakerVoiceTitle = {
    Text = "Sohbet: Agrippa Hakkında"
  },
  Voice_5448_UnlockDesc = {
    Text = "\"Agrippa\" Uyandıranı edinince açılır"
  },
  Voice_5449_AwakerVoiceContent = {
    Text = "Bu, gemide bulunması tehlikeli biri olurdu... Hayır, tamamen seyir güvenliği açısından söylüyorum..."
  },
  Voice_5449_AwakerVoiceTitle = {
    Text = "Sohbet: Faros Hakkında"
  },
  Voice_5449_UnlockDesc = {
    Text = "\"Faros\" Uyandıranı edinince açılır"
  },
  Voice_5450_AwakerVoiceContent = {
    Text = "Daha fazla yaklaşma!"
  },
  Voice_5450_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5451_AwakerVoiceContent = {Text = "Dikkat et!"},
  Voice_5451_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5452_AwakerVoiceContent = {
    Text = "Talimat Tamamlandı... Ah. Yine ortalığı berbat ettim..."
  },
  Voice_5452_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5453_AwakerVoiceContent = {
    Text = "Ah, tam da ihtiyacım olan parça bu, sağ ol! ...Ha? Onu bulmanı ben mi istedim? Bunu hiç hatırlamıyorum. Yanılmıyor musun?"
  },
  Voice_5453_AwakerVoiceTitle = {
    Text = "Sohbet: Yedek Parçalar Hakkında"
  },
  Voice_5454_AwakerVoiceContent = {
    Text = "İlhamlar sonsuzca akıyor..."
  },
  Voice_5454_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5455_AwakerVoiceContent = {Text = "İyi zevk."},
  Voice_5455_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5456_AwakerVoiceContent = {
    Text = "Benim için mükemmel oyma bıçağını seçtin."
  },
  Voice_5456_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5457_AwakerVoiceContent = {
    Text = "Kontrolü kaybetmekten nefret ederim. Ne var ki, varlığın bana gösterdi ki hafif bir Kaos dokunuşu, eşsiz bir haz getirebiliyor."
  },
  Voice_5457_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5458_AwakerVoiceContent = {
    Text = "Biraz büyüdün mü yoksa?"
  },
  Voice_5458_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5459_AwakerVoiceContent = {
    Text = "Affet, bedenimi büyütmem benim için zor..."
  },
  Voice_5459_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_54601_AwakerVoiceContent = {
    Text = "Dünyanın gizemlerini böyle kavrayacağız."
  },
  Voice_54601_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_54602_AwakerVoiceContent = {
    Text = "Dünyanın gizemlerini böyle kavrayacağız."
  },
  Voice_54602_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_54605_AwakerVoiceContent = {
    Text = "Buyrun, Afiyet Olsun!"
  },
  Voice_54605_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_54606_AwakerVoiceContent = {
    Text = "Buyrun, Afiyet Olsun!"
  },
  Voice_54606_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_54607_AwakerVoiceContent = {
    Text = "Sırada, dünyanın özünü parçalara ayırmak var!"
  },
  Voice_54607_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_54608_AwakerVoiceContent = {
    Text = "Sırada, dünyanın özünü parçalara ayırmak var!"
  },
  Voice_54608_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_54609_AwakerVoiceContent = {
    Text = "Kurban! Bedenimi onun tahtına geri ver—"
  },
  Voice_54609_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_5460_AwakerVoiceContent = {
    Text = "Y-yemek için teşekkürler..."
  },
  Voice_5460_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_54610_AwakerVoiceContent = {
    Text = "Kurban! Bedenimi onun tahtına geri ver—"
  },
  Voice_54610_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_54611_AwakerVoiceContent = {
    Text = "Beni engelleme!"
  },
  Voice_54611_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_54612_AwakerVoiceContent = {
    Text = "Uçurumda... bir adalet ışığı olacak."
  },
  Voice_54612_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_54613_AwakerVoiceContent = {
    Text = "Beni engelleme!"
  },
  Voice_54613_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_54614_AwakerVoiceContent = {
    Text = "Bu eşi benzeri olmayan acının tadını çıkar!"
  },
  Voice_54614_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_54615_AwakerVoiceContent = {
    Text = "Bu eşi benzeri olmayan acının tadını çıkar!"
  },
  Voice_54615_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_54616_AwakerVoiceContent = {
    Text = "<Italic:\"...Oui tu mourus, enfant, par un fleuve emportée!\">"
  },
  Voice_54616_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_54617_AwakerVoiceContent = {
    Text = "<Italic:\"...Oui tu mourus, enfant, par un fleuve emportée!\">"
  },
  Voice_54617_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_54618_AwakerVoiceContent = {
    Text = "Ey Şekilsiz Yaratıklar, efendim için bir Karakter Kalkanı olun!"
  },
  Voice_54618_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_54619_AwakerVoiceContent = {
    Text = "Ey Şekilsiz Yaratıklar, efendim için bir Karakter Kalkanı olun!"
  },
  Voice_54619_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_5461_AwakerVoiceContent = {
    Text = "Çaban için minnettar olurum."
  },
  Voice_5461_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5461_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_54620_AwakerVoiceContent = {
    Text = "Uçurumun yaban hayvanı, hepsini yut!"
  },
  Voice_54620_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_54621_AwakerVoiceContent = {
    Text = "Uçurumun yaban hayvanı, hepsini yut!"
  },
  Voice_54621_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_54622_AwakerVoiceContent = {
    Text = "Uçurumda... bir adalet ışığı olacak."
  },
  Voice_54622_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_54623_AwakerVoiceContent = {
    Text = "Ben... zincirleri koparanım! Tekeli—Li!"
  },
  Voice_54623_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_54624_AwakerVoiceContent = {
    Text = "Ben... zincirleri koparanım! Tekeli—Li!"
  },
  Voice_54624_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_54625_AwakerVoiceContent = {
    Text = "Geleceği açığa çıkaracak olan ben olacağım!"
  },
  Voice_54625_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_54626_AwakerVoiceContent = {
    Text = "Geleceği açığa çıkaracak olan ben olacağım!"
  },
  Voice_54626_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_54627_AwakerVoiceContent = {
    Text = "Eğil ve ayaklarımın uçlarını öp!"
  },
  Voice_54627_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_54628_AwakerVoiceContent = {
    Text = "Tüm vidalar yerinde!"
  },
  Voice_54628_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_54629_AwakerVoiceContent = {
    Text = "Tüm vidalar yerinde!"
  },
  Voice_54629_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_5462_AwakerVoiceContent = {
    Text = "Böylesine yüce bir gücü yalnızca bir Aequor taşıyabilir. Kıskanıyorsun, değil mi? Zayıf bir insan olman senin suçun değil; sadece bununla yüzleş."
  },
  Voice_5462_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5462_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_54630_AwakerVoiceContent = {
    Text = "Eğil ve ayaklarımın uçlarını öp!"
  },
  Voice_54630_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_5463_AwakerVoiceContent = {
    Text = "Bu yenilmiş bireyleri kölelerim hâline getirebilir miyim?"
  },
  Voice_5463_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5464_AwakerVoiceContent = {Text = "Heh."},
  Voice_5464_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5465_AwakerVoiceContent = {
    Text = "Tam da beklediğim gibi."
  },
  Voice_5465_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5466_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5466_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5467_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5467_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5468_AwakerVoiceContent = {
    Text = "O insanların bu her şeyi yutan lanet tarafından işkenceye uğradığını daha önce bilseydim, ben... Hayır, henüz çok geç değil. Onu kökünden kazımalıyım, tüm acıları yok etmeliyim, gerekirse hayatımı bir kez daha vererek."
  },
  Voice_5468_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5469_AwakerVoiceContent = {
    Text = "Cesaretini yitirme. Deniz hepimizi kucaklar."
  },
  Voice_5469_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5470_AwakerVoiceContent = {
    Text = "Böylesine cılız bir bedenle, senden yoldaşım olmanı istemek fazla olur. Fazla zayıfsın; antrenmanını kat kat artırmalısın. Gel, seni akademinin spor kulübüne götüreyim de gözlerini açayım."
  },
  Voice_5470_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5471_AwakerVoiceContent = {
    Text = "Bana Güç’ünü ödünç veren o kişi Çözünme yüzünden işkence çekiyor... Ne biçim bakış o? Sakın aklından bile geçirme! Sana Onun nerede olduğunu söylemeyeceğim!"
  },
  Voice_5471_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5472_AwakerVoiceContent = {
    Text = "Yeterince şansla, herkes yenilmez olabilir."
  },
  Voice_5472_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5473_AwakerVoiceContent = {
    Text = "Ah, sana acı mı veriyorum?"
  },
  Voice_5473_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5474_AwakerVoiceContent = {
    Text = "Aman Tanrım, buradakilerin çoğu hâlâ çocuk. O beyaz saçlı centilmen, o sert mizaçlı tek kollu delikanlı—hiçbiri Çocuklar için uygun değil... Off, bu gerçekten zor bir durum."
  },
  Voice_5474_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5475_AwakerVoiceContent = {
    Text = "Ah, sana acı mı veriyorum?"
  },
  Voice_5475_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5476_AwakerVoiceContent = {
    Text = "İtina ile kazınmış rünler, huşu içinde oyulmuş putlar, defalarca arıtılmış yasak iksirler... tek bir tanesi bile eksik olamaz."
  },
  Voice_5476_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5476_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5477_AwakerVoiceContent = {
    Text = "Taht, okyanusun uçurumundan çıkarılan kadim mavi taştan inşa edilmeli ve sunak insan kurbanlarının kanıyla kaplanmalı... Şimdi git, hazırlan!"
  },
  Voice_5477_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5477_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5478_AwakerVoiceContent = {
    Text = "Hepsini buraya getirin! Titreyerek diz çökmeli ve O’nun gelişini karşılamalılar."
  },
  Voice_5478_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5478_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5479_AwakerVoiceContent = {
    Text = "O uçurumvari harabeye gideceğim ve O’nun doğuşunun deniz suyunda yıkanacağım..."
  },
  Voice_5479_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5479_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5480_AwakerVoiceContent = {
    Text = "Nihayet. O’nun ilahî doğuşuna tanıklık edeceğimiz ayine hoş geldin... Ne? O’nun yok oluşunun da yazgı olduğunu mu söylüyorsun? ...Hayır! Bu olamaz... Ben zaten böylesine büyük fedakârlıklar yaptım..."
  },
  Voice_5480_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5480_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5481_AwakerVoiceContent = {
    Text = "İlahi buyruğa uy."
  },
  Voice_5481_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5482_AwakerVoiceContent = {
    Text = "Senin tarafın, Faint ve benim sonunda aidiyet bulacağımız yer mi olacak?"
  },
  Voice_5482_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5482_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5483_AwakerVoiceContent = {
    Text = "Evet... O zamanlar sesimi kaybetmiştim. Senin lütfun onu geri getirdi."
  },
  Voice_5483_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5483_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5484_AwakerVoiceContent = {
    Text = "İlahi buyruğa uy."
  },
  Voice_5484_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5485_AwakerVoiceContent = {
    Text = "Uçsuz bucaksız kozmos, sınırsız derin uzay ve bitmeyecekmiş gibi görünen yolculuk... O zamanlar kendimi öylesine kaybolmuş hissediyordum."
  },
  Voice_5485_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5485_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5486_AwakerVoiceContent = {
    Text = "Kestirme yöntemler bir itiş sağlayabilir, ama beceri eğitimini sakın ihmal etme."
  },
  Voice_5486_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5487_AwakerVoiceContent = {
    Text = "Demek bu yöntem bana da uygulanabiliyor..."
  },
  Voice_5487_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5488_AwakerVoiceContent = {
    Text = "Harika bir his."
  },
  Voice_5488_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5492_AwakerVoiceContent = {
    Text = "O’nun zuhuru, bu karanlık ölüm sıvısının sebep olduğu acıyı mutlaka sona erdirecek, öyle değil mi?"
  },
  Voice_5492_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5493_AwakerVoiceContent = {
    Text = "İyi günler, efendim. Eğer araştırma için dışarı çıkacaksanız, lütfen muhafızınız olarak benim de gelmeme izin verin."
  },
  Voice_5493_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5493_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5494_AwakerVoiceContent = {
    Text = "Ne yapacağını mı bilmiyorsun? Canın sıkılıyorsa git birkaç görev raporu yaz."
  },
  Voice_5494_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5495_AwakerVoiceContent = {
    Text = "Nihayet başlıyor mu? Küçük sevgililerim çok ama çok uzun zamandır açlıktan kıvranıyor..."
  },
  Voice_5495_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5496_AwakerVoiceContent = {
    Text = "Soyumun gücü kabarıyor."
  },
  Voice_5496_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5497_AwakerVoiceContent = {
    Text = "Bir dakika... Bunu daha önce görmüştüm. Bana içinde bu siyah pislikten olan su içirmişlerdi. Ölümsüz Yeşil Alev’in Güç’ünü kazanmamla ilgili olabilir mi? Sanırım bu, kötü görünen bir şeyin içindeki bir Lütuf."
  },
  Voice_5497_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5498_AwakerVoiceContent = {
    Text = "Ramona Dexter, bana sadece Ramona de. Seninle çalışmayı dört gözle bekliyorum, Koruyucu."
  },
  Voice_5498_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5499_AwakerVoiceContent = {Text = "Evet."},
  Voice_5499_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5500_AwakerVoiceContent = {
    Text = "Komut alındı."
  },
  Voice_5500_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5501_AwakerVoiceContent = {
    Text = "Hıh. Saygısızlık! Pekâlâ, seni küçük bir oyunla eğlendireceğim."
  },
  Voice_5501_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5502_AwakerVoiceContent = {
    Text = "Nelerden hoşlanmam mı? Sönen bir pipo, kaçırılmış bir fayton, yeni ayakkabıya yağan yağmur. Kısacası, her türlü talihsizlik tam bir Pain."
  },
  Voice_5502_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5503_AwakerVoiceContent = {
    Text = "İngiliz anahtarı, ayarlı anahtar, yıldız anahtar, düz tornavida, yıldız tornavida, havşa başlı vida, silindirik başlı vida... Kırık şeyleri onarabiliyorsa, onu severim."
  },
  Voice_5503_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5504_AwakerVoiceContent = {
    Text = "Ah hayır~ Beni yakaladın~ \nSorun değil, Uyandırıcıların ruh gücü o kadar bol ki. Onları akılsız kuklalara dönüştürmek için en az 365 kez çalmam lazım~ Yapamaz mıyım? Peki, bir dahaki sefere daha dikkatli olurum! Kesme sırasında sadece küçücük bir \"korku\" hissedeceksin, olur mu?"
  },
  Voice_5504_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5504_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5505_AwakerVoiceContent = {
    Text = "Hey, sen artık Casiah’ın sihrinin sırlarını biliyorsun, değil mi? Hmm, sırları ifşa etmemen için, turnede nereye gidersem peşimden geleceksin~ Haha, duygularını topladığımı mı düşünüyorsun? Doğrusu, gözünden hiçbir şey kaçmıyor!"
  },
  Voice_5505_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5505_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5506_AwakerVoiceContent = {
    Text = "Sen, sen Casiah'ın sihir asistanı olacaksın! Korkma~ Sadece bir anlığına sihir kutuma gir!\nİyi saklandın mı? Kılıcı sokmak üzereyim~ Oh, içeride hiç tuzak olmadığına söz veriyorum~"
  },
  Voice_5506_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5506_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5507_AwakerVoiceContent = {
    Text = "Al, şu silindir şapkayı tak! Sonra da bana en çok arzu ettiğin hediyeyi söyle. Ah, anladım! Şimdi elini şapkanın içine uzat—"
  },
  Voice_5507_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5507_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5508_AwakerVoiceContent = {
    Text = "Ne kadar sıkıntılı. O çocuklar her gösteriye geliyor, stoklarım tükenmek üzere… Hmm, bir sihirbaz aynı numaraları aynı seyirciye sergilememeli. Yeni sihir mi yaratayım? Üzgünüm, bende o tür bir yetenek yok; ben sadece taklitte iyiyim!"
  },
  Voice_5508_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5508_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5509_AwakerVoiceContent = {
    Text = "Bu akademinin... acilen yenilenmeye ihtiyacı var; yalnızca müdürün salonu az çok göze hoş görünüyor. Sence nasıl?"
  },
  Voice_5509_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5509_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5510_AwakerVoiceContent = {
    Text = "O kibirli, aşağılık ahmaklar benim elimle ölecek."
  },
  Voice_5510_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5511_AwakerVoiceContent = {
    Text = "İntikam Kılıcım gitgide daha da keskinleşiyor."
  },
  Voice_5511_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5512_AwakerVoiceContent = {
    Text = "Benim salonum bir balo kadar masum değildir. Hazır mısın?"
  },
  Voice_5512_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5512_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5513_AwakerVoiceContent = {
    Text = "Benim salonum, sarhoş edici güzellik ve gücün serpileceği toprak, bahçedir..."
  },
  Voice_5513_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5513_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5514_AwakerVoiceContent = {
    Text = "İpek yastıklar, siyah çay, makaronlar... Bir de kabul salonumu süslemek için sabah çiyi taşıyan taze güllere ihtiyacım var."
  },
  Voice_5514_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5514_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5515_AwakerVoiceContent = {
    Text = "Lütfen dışarıdan konuklara izin verin. Salonlarımı düzenlemem gerek. Onlara benim için bir istisna yapmalarını söyleyin, olur mu?"
  },
  Voice_5515_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5515_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5516_AwakerVoiceContent = {
    Text = "Çalışma zamanı hatası, hata, hata, hata..."
  },
  Voice_5516_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5517_AwakerVoiceContent = {
    Text = "Ah! Saat kaç oldu?! Özür dilerim, Efendim... Böyle yan çizmemeliydim! Ama... öyle yorgunum ki... Ne olurrr?"
  },
  Voice_5517_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5518_AwakerVoiceContent = {
    Text = "Tek seçeneğim ölümü beklemek miydi? Biri bana yardım edebilir miydi? Gerçekten direniş gösterebilir miydim? Her gün bunu kendime sordum. Cevap aklımdaydı—sadece görmeye hiç cesaret edemedim... Sen ortaya çıkmasaydın, karşı koymaya cesaretim olur muydu bilmiyorum.\nT-Teşekkür ederim—yanlış anlama, bu bir itiraf falan değil!"
  },
  Voice_5518_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5518_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5519_AwakerVoiceContent = {
    Text = "Onların sahte Rüyalarında yaşarken, normal olma hakkımdan soyunmuş, elimde hiçbir Seçim yokken... hepsi saçma bir Kehanet uğruna... Bu hayattan Kaçış için her şeyi yapmaya razıydım!"
  },
  Voice_5519_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5519_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5520_AwakerVoiceContent = {
    Text = "<Italic:\"Dalgalanan nilüferler etrafında iç çekiyor;\nZaman zaman uyuklayan bir kızılağaçta,\nKüçük bir kanat hışırtısının kaçtığı bir yuvayı uyandırıyor;\nAltın yıldızlardan gizemli bir ilahi süzülüyor.\">\nAh, özür dilerim—çok mu yüksek sesle okuyordum? En sevdiğim şiirlerden biri... Benimle birlikte okumak ister misin?"
  },
  Voice_5520_AwakerVoiceTitle = {
    Text = "Sohbet: Okuma Üzerine"
  },
  Voice_5521_AwakerVoiceContent = {
    Text = "Bir hanımefendinin Odasına öylece dalma ve tavırları hakkında yorum yapma. Şimdi çık, Dinlenmem gerek."
  },
  Voice_5521_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5521_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5522_AwakerVoiceContent = {
    Text = "Sakın bana karşı artistlik yapmaya kalkma. Haddini bil! Bu Odada kuralları ben koyarım."
  },
  Voice_5522_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5522_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5523_AwakerVoiceContent = {
    Text = "Ah, eşyaları senin için sergilemem mi gerekiyor?"
  },
  Voice_5523_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5524_AwakerVoiceContent = {
    Text = "İyi iş çıkardın. Zaferi bir fıçı romla kutlama zamanı!"
  },
  Voice_5524_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5525_AwakerVoiceContent = {Text = "Yok ol."},
  Voice_5525_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5526_AwakerVoiceContent = {
    Text = "Bana bırakın!"
  },
  Voice_5526_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5527_AwakerVoiceContent = {
    Text = "Ayaklarımın altında ezilme hissi, herhâlde tarifsiz derecede ilahî olmalı~"
  },
  Voice_5527_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5528_AwakerVoiceContent = {Text = "Dayan!"},
  Voice_5528_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5529_AwakerVoiceContent = {
    Text = "Göz bandının altında ne olduğunu merak mı ediyorsun? Sana göstereceğim... ortam daha uygun olduğunda. Acele etme."
  },
  Voice_5529_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5530_AwakerVoiceContent = {
    Text = "Şimdiden bitti mi? ... Oysa heyecanım yeni yeni kabarmaya başlamıştı."
  },
  Voice_5530_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5531_AwakerVoiceContent = {
    Text = "Hey, stop meddling with my body. True warriors never rely on external aids.\nHey, bedenimle oynamayı kes. Gerçek savaşçılar asla dışsal yardımlara bel bağlamaz."
  },
  Voice_5531_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5531_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5532_AwakerVoiceContent = {
    Text = "Daha da Güçlü oldum... Bu Gözler'i düşmanı felce uğratmak için kullanacağım!"
  },
  Voice_5532_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5533_AwakerVoiceContent = {
    Text = "Mythag Üniversitesi, ordudan farksız. Her birimiz, silahlarımızı parlatıp Savaş’a hazırlanan ön saflardayız."
  },
  Voice_5533_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5534_AwakerVoiceContent = {Text = "Kusursuz!"},
  Voice_5534_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5535_AwakerVoiceContent = {Text = "Kusursuz!"},
  Voice_5535_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5536_AwakerVoiceContent = {
    Text = "Beni zincirle, saçlarımdan sürükle, beni kölen gibi diz çöktür... Umurumda değil, bana istediğini yap. Yeter ki öldüreyim. Heykeltıraşlar, o Leydi Fener, nefes darlıklı rastgele bir kocakarı... fark etmez! Söz veriyorum, gırtlaklarını koparıp kanlarını içeceğim."
  },
  Voice_5536_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5536_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5537_AwakerVoiceContent = {
    Text = "Çözünme Yarası’ndan yalnızca siyah bir sümüksü sıvı değil, Sonsuz İlham da akar. Doğrusu, biraz daha olmasına itiraz etmezdim."
  },
  Voice_5537_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5538_AwakerVoiceContent = {
    Text = "Scared? Hahaha, that's right! To hell with everything. I just want to savor your fear.\nKorktun mu? Hahaha, aynen öyle! Her şeyin canı cehenneme. Ben sadece dehşetinin tadını çıkarmak istiyorum."
  },
  Voice_5538_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5538_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5539_AwakerVoiceContent = {
    Text = "Interesting, your blood tastes... sweet, like mead.\nİlginç, kanın... tatlı, bal şarabı gibi."
  },
  Voice_5539_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5539_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5540_AwakerVoiceContent = {
    Text = "Back then, tens of thousands cheered my name. The loud roars of \"Uvhash\" drowned everything else, celebrating me breaking a bald weakling's neck. It felt incredible. As my partner, you should understand.\nO zamanlar on binlerce kişi adımı haykırırdı. “Uvhash” diye yükselen uğultu, kel bir zayıfın boynunu kırışımı kutlarken her şeyi bastırırdı. Tarifi imkânsız bir histi. Ortak olarak, bunu anlamalısın."
  },
  Voice_5540_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5540_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5541_AwakerVoiceContent = {Text = "B-bekle!"},
  Voice_5541_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5542_AwakerVoiceContent = {Text = "Hayır!"},
  Voice_5542_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5543_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5543_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5544_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_5544_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5545_AwakerVoiceContent = {
    Text = "Geniş Arşiv’de “Çözünme” aranıyor... Gerek yok mu? Çözünme konusundaki tutumumu mu bilmek istiyorsunuz? Anlaşıldı. Uyanan’ın gizli diyarında “Çözünme Karşıtı silahlar” aranıyor... Sonuç: “Boş.”"
  },
  Voice_5545_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5546_AwakerVoiceContent = {
    Text = "Sahte putlar, kurumuş kil kadar kırılgan, en hafif rüzgârda bile saçılır..."
  },
  Voice_5546_AwakerVoiceTitle = {
    Text = "Sohbet: Murphy Hakkında"
  },
  Voice_5546_UnlockDesc = {
    Text = "Uyanışçı \"Murphy\" edinildiğinde açılır"
  },
  Voice_5547_AwakerVoiceContent = {
    Text = "Biraz gürültülü olmaya başladı... öğrenciler mi bunlar? Albatroslar gibi, görüyor musun? Sonsuz bir enerjileri var, sanki yolculukları hiç bitmeyecekmiş gibi..."
  },
  Voice_5547_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5548_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5548_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5549_AwakerVoiceContent = {Text = "Hımpf"},
  Voice_5549_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5550_AwakerVoiceContent = {
    Text = "Burada zaman ayırmaya değer tek kişi Ramona. Bıçak konusunda epey yetenekli. Geri kalanlar ise öyle katı, öyle sıkıcı ki... Sen de onlar gibi misin? O yorucu görev raporlarını yazmaktan gerçekten keyif alıyor musun?"
  },
  Voice_5550_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5551_AwakerVoiceContent = {
    Text = "Söze bile değmez."
  },
  Voice_5551_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5552_AwakerVoiceContent = {
    Text = "Bütün anneler aynı değil. Bazıları iyi, bazıları kötü.\nSen iyi bir annesin."
  },
  Voice_5552_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5552_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5553_AwakerVoiceContent = {
    Text = "Çok özür dilerim, efendim, sizi koruyamadım..."
  },
  Voice_5553_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5554_AwakerVoiceContent = {
    Text = "Mekânı ayırttın mı? En az 150 metrekarelik bir bahçe olmalı!"
  },
  Voice_5554_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5554_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5555_AwakerVoiceContent = {
    Text = "Can çekişenin kanı kaygan bir sıvıdır. Boynuna hafif bir kesik atman yeter; kan dişlerin arasından akarak sıcak ırmaklara dönüşür, yavaşça karnımı doldurur... Heh. Lezzetli."
  },
  Voice_5555_AwakerVoiceTitle = {
    Text = "Sohbet: Kan Hakkında"
  },
  Voice_5556_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5556_AwakerVoiceTitle = {
    Text = "Özel Beceri: I"
  },
  Voice_5557_AwakerVoiceContent = {Text = "Hey!"},
  Voice_5557_AwakerVoiceTitle = {
    Text = "Özel Beceri: I"
  },
  Voice_5558_AwakerVoiceContent = {Text = "Ha?"},
  Voice_5558_AwakerVoiceTitle = {
    Text = "Özel Beceri: I"
  },
  Voice_5559_AwakerVoiceContent = {
    Text = "Bana sığınak sağlama nezaketin için teşekkür ederim. Umarım sana trajik bir Kader getirmem..."
  },
  Voice_5559_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5560_AwakerVoiceContent = {
    Text = "Uzak, yabancı bir gezegenden geliyorum; amansız kar fırtınalarının ve aşırı soğuğun diyarından. Ama bunun bir önemi yok; malikanemde, binlerce hizmetkâr yalnızca varlıklarıyla iç ısıtan bir sıcaklık sunar."
  },
  Voice_5560_AwakerVoiceTitle = {
    Text = "Sohbet: Geçmiş Üzerine"
  },
  Voice_5561_AwakerVoiceContent = {
    Text = "Varışınızdan önce sendelememeliyim, efendim..."
  },
  Voice_5561_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5562_AwakerVoiceContent = {
    Text = "Varışınızdan önce sendelememeliyim, efendim..."
  },
  Voice_5562_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5563_AwakerVoiceContent = {
    Text = "Nasıl böyle küstah bir konuk olabilir, \"dünyanın en güçlü silahını\" isteyecek kadar? Ona, karşılığında nefretle yoğrulmuş bir kafa gerektiğini söyledim; suratını asıp çekip gitti..."
  },
  Voice_5563_AwakerVoiceTitle = {
    Text = "Sohbet: Golyat Hakkında"
  },
  Voice_5563_UnlockDesc = {
    Text = "\"Golyat\" Uyandıranı edinince açılır"
  },
  Voice_5564_AwakerVoiceContent = {
    Text = "Yüzündeki o kahramanca, şehit edası... Sanki her an \"daha büyük bir dava\" uğruna ölmeye hazırsın... eklemlerimi kaşındırıyor."
  },
  Voice_5564_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5564_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5565_AwakerVoiceContent = {
    Text = "Elimin altında, bu sözde mabedi yutmaya hazır bir Yok Oluş vardı... Sonra Araştırma yasağı geldi. Ne yazık."
  },
  Voice_5565_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5565_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5566_AwakerVoiceContent = {
    Text = "Evet, sayısız yedek bedenim ve Çözünme'den kaçmak için türlü planlarım vardı. Ama ben gerçeğin peşine düşmeyi seçtim ve buna değdi."
  },
  Voice_5566_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5566_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5567_AwakerVoiceContent = {
    Text = "Dünyanın gerçeği, başlangıcı ve sonu—hepsi anlamsız. Ama peşine düşmekte ısrar ediyorsan... Sana yol göstereceğim. Eskiden yaptığım gibi."
  },
  Voice_5567_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5567_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5568_AwakerVoiceContent = {
    Text = "Beni durdurabilirsin, ama son yine de geliyor... Bu okulu—ve seni—en sona saklayacağım. Zamanın alacakaranlığına bulanmış hâlde, kampanileden insanlığın çöküşünü izleyeceğiz... Şiirsel, değil mi? En azından kıymetli bağımızı israf etmemiş olacağız."
  },
  Voice_5568_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5568_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5569_AwakerVoiceContent = {Text = "Peki."},
  Voice_5569_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5570_AwakerVoiceContent = {Text = "Yok ol."},
  Voice_5570_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5571_AwakerVoiceContent = {
    Text = "Dualarım sabah çanı gibi çalsın, hafif uykudaki Beyaz Kuş Diyarı'nı uyandırsın..."
  },
  Voice_5571_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5572_AwakerVoiceContent = {
    Text = "Tinktur dışında birinin beni kabul edeceğini hiç düşünmemiştim. Seninle tanıştığıma sevindim, Koruyucu. Sana sarıldığımda Canını tüketmeyeyim diye gücümü kontrol etmeyi öğrenmek için elimden geleni yapacağım... Sarılmak, değil mi? İnsanların minnettarlık ifade etme biçimi?"
  },
  Voice_5572_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5572_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5573_AwakerVoiceContent = {
    Text = "Burada kalırsam, hiçbir bedel ödemem gerekmiyor mu? Burada statü kazanman için sana yardım edebilirim. Onların canlarını tüketeceğinle tehdit et—basit, Tinktur için yaptığım gibi... Ah! Bunu kimseye söyleme!"
  },
  Voice_5573_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5573_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5574_AwakerVoiceContent = {
    Text = "Üzgünüm, ben diğerleri gibi değilim... Kusurlu bir ürünüm."
  },
  Voice_5574_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5574_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5575_AwakerVoiceContent = {
    Text = "Usta bir hizmetçi salonu büyük ölçüde zenginleştirebilir, ama mavimsi-yeşil bir hizmetçi... bunu bir kez daha düşünmeliyim..."
  },
  Voice_5575_AwakerVoiceTitle = {
    Text = "Sohbet: Karen Hakkında"
  },
  Voice_5575_UnlockDesc = {
    Text = "Uyanışçı \"Karen\" edinildiğinde açılır"
  },
  Voice_5576_AwakerVoiceContent = {
    Text = "Tinktur benim ikiz kız kardeşim. Benim aksime, o her zaman parlak bir şekilde ışıldar... Ben onu engellemesem, çok daha parlak bir geleceği olurdu, şarkısı galaksinin her köşesinde yankılanırdı..."
  },
  Voice_5576_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5576_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5577_AwakerVoiceContent = {
    Text = "Beşik dar, bedenimi uzatacak yer yok... Ama Tinktur, herkesin güvenliği için beşikte kalmam gerektiğini söyledi... Bu onun dileği olduğuna göre, uyacağım."
  },
  Voice_5577_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5577_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5578_AwakerVoiceContent = {
    Text = "Çoğu zaman, yaşamla ölüm arasındaki boşlukta var oluyormuşum gibi hissediyorum. Nerede olursam olayım, hüzün bir gelgit gibi yayılıyor ve trajediler, peş peşe sahneleniyor. Yine de, benim senin için bir şiir yazmamı ister miydin? Hımm... belki de en tatlısını hak ediyorsun..."
  },
  Voice_5578_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5578_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5579_AwakerVoiceContent = {
    Text = "<Italic:\"Yaklaş biraz daha, küçük Bülbül, yoksa gül bitmeden Gün doğacak...\">"
  },
  Voice_5579_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5579_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5580_AwakerVoiceContent = {
    Text = "Neyi arzuluyorsun? Zarif sözcüklerin güzelliğini mi, dört bir yana yayılmış şöhreti mi, yoksa o sözcüklerin içine dokunan içten samimiyeti mi?"
  },
  Voice_5580_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5580_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5581_AwakerVoiceContent = {
    Text = "Görünmez mürekkeple, biçimsiz tomurcukları tasvir ediyorum... Bu hayaletimsi ve eterimsi gül dalı, gerçekten şiirsel dizelere ilham veriyor..."
  },
  Voice_5581_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5581_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_55825_AwakerVoiceContent = {
    Text = "Onun ilahi sözlerini dinleyin."
  },
  Voice_55825_AwakerVoiceTitle = {
    Text = "Uyanış·II"
  },
  Voice_55826_AwakerVoiceContent = {
    Text = "Kurban! İlahi Diyarı yeniden inşa et—"
  },
  Voice_55826_AwakerVoiceTitle = {
    Text = "Uyanış·Üçüncü"
  },
  Voice_5582_AwakerVoiceContent = {
    Text = "Eğer gerçekten ısrar ediyorsan, yeniden güneş ışığına adım atacağım... Cité’den ayrıldığım günle aynı güneş ışığına..."
  },
  Voice_5582_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5582_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5583_AwakerVoiceContent = {
    Text = "Hehe, bir evrenin yok oluşunu görmek ister misin? Ah, artık geri dönmek için çok geç!"
  },
  Voice_5583_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5583_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5584_AwakerVoiceContent = {
    Text = "Tadını çıkar... ölümün o tatlı lezzetinin."
  },
  Voice_5584_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5585_AwakerVoiceContent = {
    Text = "Tadını çıkar... ölümün o tatlı lezzetinin."
  },
  Voice_5585_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5586_AwakerVoiceContent = {
    Text = "Yeter artık!"
  },
  Voice_5586_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5587_AwakerVoiceContent = {Text = "Hayır..."},
  Voice_5587_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5588_AwakerVoiceContent = {
    Text = "Bu Varlığın kaba gücünün ihtişamına tanık ol."
  },
  Voice_5588_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5589_AwakerVoiceContent = {
    Text = "Kampüste sabah 4’teki hava ne kadar zinde ruh verici. Benimle idman yapmaya istekli olman iyi oldu. Şunu söylemeliyim, heykel yontmak da başlı başına bir antrenman."
  },
  Voice_5589_AwakerVoiceTitle = {
    Text = "Sohbet: Sabah Üzerine"
  },
  Voice_5590_AwakerVoiceContent = {
    Text = "Bu gücü kullanmak iyi hissettiriyor."
  },
  Voice_5590_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5590_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5591_AwakerVoiceContent = {
    Text = "Aldığının bedelini ödemeyen insanlardan nefret ederim. Bir dükkânı yeterince uzun süre işletirsen, bu dertle mutlaka karşılaşırsın. Mecburen bizzat ilgilenir, hak ettiğim ödemeyi geri alırım."
  },
  Voice_5591_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5592_AwakerVoiceContent = {
    Text = "Onları yavaşça işkenceyle tüketin."
  },
  Voice_5592_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5593_AwakerVoiceContent = {
    Text = "Onları yavaşça işkenceyle tüketin."
  },
  Voice_5593_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5594_AwakerVoiceContent = {Text = "Yükle."},
  Voice_5594_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5595_AwakerVoiceContent = {Text = "Başla."},
  Voice_5595_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5596_AwakerVoiceContent = {
    Text = "Burası bizim coşkun mutluluk denizimiz olsun!"
  },
  Voice_5596_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5597_AwakerVoiceContent = {
    Text = "Ne? Benden gerçekten bir \"teşekkür\" mü bekliyorsun?"
  },
  Voice_5597_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5598_AwakerVoiceContent = {
    Text = "Bir Ziyaret olarak, pek de yeterli sayılmaz... ama samimiyetini görünce, sanırım kabul edeceğim. Sadece bu seferlik."
  },
  Voice_5598_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5599_AwakerVoiceContent = {
    Text = "Bunun beni sana kulak vermeye ikna edeceğine gerçekten inandın mı?"
  },
  Voice_5599_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5600_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5600_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5601_AwakerVoiceContent = {Text = "Git!"},
  Voice_5601_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5602_AwakerVoiceContent = {
    Text = "Nankör canavarlar, suikastçılar ve katiller—onlarda tanıdığın herhangi bir değer var mı? Ucubeler."
  },
  Voice_5602_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5602_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5603_AwakerVoiceContent = {
    Text = "Kaç yastık yığarsan yığ, lacivert taş bir taht, tüy yastıklı bir yatakla boy ölçüşemez. Bu bakımdan, senin mekânında takdire şayan bir yan var."
  },
  Voice_5603_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5604_AwakerVoiceContent = {
    Text = "Ufak bir cezalandırma."
  },
  Voice_5604_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5605_AwakerVoiceContent = {
    Text = "Yalnızlıktan ve sonsuz Karanlıkta kaybolma endişesinden korkuyorum... O yüzden lütfen, yanımdan ayrılmayacağına söz ver."
  },
  Voice_5605_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5606_AwakerVoiceContent = {
    Text = "Senin yerinde olsam, tüm Uyandırıcıları kafeslere kilitlerdim! Delirmiş köpekler bir kez serbest kaldı mı, önce her zaman efendilerini ısırırlar!"
  },
  Voice_5606_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5606_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5607_AwakerVoiceContent = {
    Text = "Bu buluşmaya bir saat geç kaldım—ve bunun suçunu köleliği kaldıran o tatsız iyilikseverlere yüklüyorum! Artık saçlarımı tarayacak kimse yok!"
  },
  Voice_5607_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5607_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5608_AwakerVoiceContent = {
    Text = "İnanılır gibi değil. Yurdum böylece yok olup gitti... O, yüce Roma’ydı! Elbette duymuşsundur!"
  },
  Voice_5608_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5608_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5609_AwakerVoiceContent = {
    Text = "Pekâlâ, bunu bir zaferle başlatalım!"
  },
  Voice_5609_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5610_AwakerVoiceContent = {
    Text = "Onun lütfuna tanık olun."
  },
  Voice_5610_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5611_AwakerVoiceContent = {
    Text = "Acımanı kendine sakla! Ondan tiksiniyorum ve kesinlikle kimsenin merhametine ihtiyacım yok! Bana böyle bakmaya devam edersen, seni işkenceye boğma isteğime karşı koyamayacağım. İşlerin kontrolden çıkmasını istemezsin, değil mi? Öyleyse, uslu bir köle ol, dinle ve itaatkâr biçimde gladyatörüm ol..."
  },
  Voice_5611_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5611_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5612_AwakerVoiceContent = {
    Text = "Bunu bana bir daha sorma! Dikkatsiz davrandım, gladyatörün kaçmasına izin verdim ve bütün ailemin öldürülmesine sebep oldum! Küllere karıştık, tıpkı Roma İmparatorluğu gibi!"
  },
  Voice_5612_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5612_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5613_AwakerVoiceContent = {
    Text = "Başkalarıyla karşılaştırıldığında, Nymphaea hiçbir başarısı ya da değeri olmayan sıradan bir insandır. Neden bir Uyandırıcı oldum... küçük, mütevazı bir dilek yüzünden olmalı."
  },
  Voice_5613_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5614_AwakerVoiceContent = {
    Text = "Bugün yine okul Kurallarını çiğnedim, derse beş dakika geç gelerek... Bu nedenle, en ağır Cezalandırma’yı içtenlikle talep ediyorum; tercihen bizzat senin tarafından uygulanmasını."
  },
  Voice_5614_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5615_AwakerVoiceContent = {
    Text = "Aletlerin de bakıma ihtiyacı vardır. Kullanışlı bir takım çantası, bir tamircinin ruhudur."
  },
  Voice_5615_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5615_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5616_AwakerVoiceContent = {
    Text = "(Aşağılayıcı Tahammül)"
  },
  Voice_5616_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5617_AwakerVoiceContent = {
    Text = "Bu bir kez daha yaşanırsa, disiplin gözetimi için başvuruda bulunacağım."
  },
  Voice_5617_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5618_AwakerVoiceContent = {
    Text = "Görevlerim dövüşmekle sınırlı değil. Arkeen Devri’nde bile öylece boş boş oturmuyordum... Hey, bana yalnızca kılıç sallamayı bilen bir kaba kuvvet yığını gözüyle baktığını söyleme sakın?!"
  },
  Voice_5618_AwakerVoiceTitle = {
    Text = "Sohbet: Çalışmak Hakkında"
  },
  Voice_5619_AwakerVoiceContent = {
    Text = "İnsanlar bana yaklaştığında, daima en hüzünlü Anılarını hatırlar ve gözyaşlarını tutamazlar. Benim gibi biri hâlâ büyümeyi umut edebilir mi?"
  },
  Voice_5619_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5619_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5620_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5621_AwakerVoiceContent = {
    Text = "Bu nasıl hoşuna gitti?"
  },
  Voice_5621_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5622_AwakerVoiceContent = {
    Text = "Burası o pis, iğrenç Yeni Kapı Hapishanesi’nden çok daha iyi! İster kanepede yayılmış olayım, ister bir köşeye sıkışmış, her türlü gayet rahat, değil mi?"
  },
  Voice_5622_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5623_AwakerVoiceContent = {Text = "Brown...!"},
  Voice_5623_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5624_AwakerVoiceContent = {
    Text = "Vidam... nereye gitti..."
  },
  Voice_5624_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5625_AwakerVoiceContent = {
    Text = "Hey! Bu hile!"
  },
  Voice_5625_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5626_AwakerVoiceContent = {
    Text = "Vidalarım nereye gitti?!"
  },
  Voice_5626_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5627_AwakerVoiceContent = {
    Text = "Ak benim için, yıldızlardan nehir..."
  },
  Voice_5627_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5628_AwakerVoiceContent = {
    Text = "Aurita, arkadaşların aniden gitmesinden hoşlanmaz... Ama, eğer Dönüş yaparlarsa, onları affedeceğim!"
  },
  Voice_5628_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5629_AwakerVoiceContent = {
    Text = "Tek başına okyanusu aşacak bir kadın her zaman ilahi bir varlık değildir. Aynı ihtimalle delidir de. Miryam’ı bir tanrıça sanmıştım, bu da aptalca bir hataydı."
  },
  Voice_5629_AwakerVoiceTitle = {
    Text = "Sohbet: Miryam Hakkında"
  },
  Voice_5629_UnlockDesc = {
    Text = "Uyanışçı \"Miryam\" elde edildikten sonra açılır"
  },
  Voice_5630_AwakerVoiceContent = {Text = "Elbette."},
  Voice_5630_AwakerVoiceTitle = {
    Text = "Özel Beceri: I"
  },
  Voice_56313_AwakerVoiceContent = {
    Text = "Miss Casiah’nın sihir gösterisini gizlice izledim. Onun gösterisi seyircilere neşe getiriyor, oysa ben hep hüzün getiririm... Sence gözyaşları ve gülümsemeler eşit derecede kıymetli midir? Belki de..."
  },
  Voice_56313_AwakerVoiceTitle = {
    Text = "Sohbet: Casiah Hakkında"
  },
  Voice_56313_UnlockDesc = {
    Text = "\"Casiah\" Uyandıranı edinince açılır"
  },
  Voice_56314_AwakerVoiceContent = {
    Text = "Şiir, alevler ve ağıt birbirine benzer; seni fark ettirmeden sarıp sarmalarlar... Kendine geldiğinde, çoktan Şiir Dünyası’na nüfuz etmişsindir..."
  },
  Voice_56314_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_56315_AwakerVoiceContent = {
    Text = "Geçmişin şiirleri, kalbinin içinde saklı bahçeyi uyandırsın."
  },
  Voice_56315_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_56316_AwakerVoiceContent = {
    Text = "Şiirle çiçek muhtemelen aynı şeydir, değil mi? İkisi de hem gelip geçici hem de ebedidir. Bu hudutsuz dünyada, en unutulmaz anları küçük bir mekâna sığdırırlar... Sanırım herkes bir şiir karşısında susup kalmıştır, tıpkı bir çiçeğin açışını seyretmek için durakladığı gibi."
  },
  Voice_56316_AwakerVoiceTitle = {
    Text = "Sohbet: Onun Şiirleri Hakkında"
  },
  Voice_56317_AwakerVoiceContent = {
    Text = "Az kalsın unutuyordum... Cité’de bu mevsimde ne tür çiçekler açar?"
  },
  Voice_56317_AwakerVoiceTitle = {
    Text = "Sohbet: Cité Hakkında"
  },
  Voice_56318_AwakerVoiceContent = {
    Text = "Varlığın, kalemimdeki mürekkebi yeniden tutuşturdu; onun bir kez daha usul bir dere gibi akmasına izin verdi. Senin hikâyen için şiirler yazmayı sürdüreceğim."
  },
  Voice_56318_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında - 1"
  },
  Voice_56319_AwakerVoiceContent = {
    Text = "Açan çiçeklerin güzelliğine, soluşlarının hüznü eşlik eder. Kaç kez ağıt yakarsam yakayım, durup onlar için yas tutmaktan kendimi alamam. Acıdan korkup onları görmezden gelseydim, bu çiçekler ne kadar da üzgün olurdu..."
  },
  Voice_56319_AwakerVoiceTitle = {
    Text = "Sohbet: Onun Acısı Hakkında"
  },
  Voice_5631_AwakerVoiceContent = {
    Text = "Erica \"uyurken\" bu bedenin iç yapısını araştırmak için Winkle geceleri onun ofisinde dinlenmemi istedi. Erica'nın uyurken bilincinin bir kısmını koruduğunu söylemeli miyim?"
  },
  Voice_5631_AwakerVoiceTitle = {
    Text = "Sohbet: Winkle Hakkında"
  },
  Voice_5631_UnlockDesc = {
    Text = "\"Winkle\" Uyandıranı edinince açılır"
  },
  Voice_56320_AwakerVoiceContent = {
    Text = "Madam Sorel gerçekten güzel. Gücü ve özgüveni, kader karşısındaki zarif gülümseyişi ve canlı ama azimli yaşam gücü—bunların hepsi beni kıskandırıyor."
  },
  Voice_56320_AwakerVoiceTitle = {
    Text = "Sohbet: Sorel Hakkında"
  },
  Voice_56320_UnlockDesc = {
    Text = "\"Sorel\" Uyandıranı edinince açılır"
  },
  Voice_56321_AwakerVoiceContent = {
    Text = "Dün yeni bir şiir yazdım, ama kimseye göstermedim. Pek iyi sayılmaz, ama... {Male=Bay,Female=Bayan} Koruyucu, ona bir göz atmak ister misiniz?"
  },
  Voice_56321_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında - 2"
  },
  Voice_56322_AwakerVoiceContent = {
    Text = "Mythag’ın Öğrenci Şiir Kulübü benden danışman olmamı istiyor... Kabul edemem. Heveslerini kırmak istemem, ama onlara yalnızca hayal kırıklığı ve cesaret kaybı getireceğimden korkuyorum."
  },
  Voice_56322_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_56323_AwakerVoiceContent = {
    Text = "Bu dünyada nefret edilecek hiçbir şey yok. Altın yıllar övgüyü hak eder, yaşlılığın çöküşü acımayı; gençliğin görkemi kıskanılacak kadar güzeldir, yıpranmış kalıntılar ise derin bir tefekküre çağırır."
  },
  Voice_56323_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_56324_AwakerVoiceContent = {
    Text = "Her Miss Nymphaea’yı gördüğümde, o nilüfer tablosu aklıma gelir. Nilüferlerin dingin acılığını ve kokusunu üzerinde taşır... Onun dünyası gerçekte nasıl bir yer, merak ediyorum."
  },
  Voice_56324_AwakerVoiceTitle = {
    Text = "Sohbet: Nymphaea Hakkında"
  },
  Voice_56324_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Nymphaea\" elde edildikten sonra açılır"
  },
  Voice_56325_AwakerVoiceContent = {
    Text = "Her zaman etrafımda “hayaletlerin” varlığını hissettim; açıklanamaz bir musallat ya da büyülenme gibi, dünyaya dair umudumu emip tüketiyorlar. Ama eğer bu bir hayaletse, süt ve suyun havaya karışıp kaybolmasını nasıl açıklarsın...?"
  },
  Voice_56325_AwakerVoiceTitle = {
    Text = "Sohbet: Hayaletler Hakkında"
  },
  Voice_56326_AwakerVoiceContent = {
    Text = "Bedenim Çözünme’den etkilenmedi; o siyah sıvılar sadece mürekkep. Ama dürüst olmak gerekirse, Çözünme olmasa bile her şey eninde sonunda Düş’e dönüşmüyor mu?"
  },
  Voice_56326_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_56327_AwakerVoiceContent = {
    Text = "Anahtar Mezarı’nda, mezar taşlarından birinde senin adını gördüm... Hayatın anıları acı vericiydi, ama onları unutmak hiç niyetim değildi. Koruyucu için, yitip gitmiş o anılar da en az diğerleri kadar kıymetli olmalı, öyle değil mi?"
  },
  Voice_56327_AwakerVoiceTitle = {
    Text = "Sohbet: Geçmiş Anılar Hakkında"
  },
  Voice_56328_AwakerVoiceContent = {
    Text = "Eğer şiir güzelliği övmek için varsa, onun varlığının kendisi şiir gibidir. Şarkı söylemeye başladığında, ihtiyarların bülbül sesi diye tarif ettiği şeyi birdenbire anlarım..."
  },
  Voice_56328_AwakerVoiceTitle = {
    Text = "Sohbet: Tinktur Hakkında"
  },
  Voice_56328_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Tinct\" elde edildikten sonra açılır"
  },
  Voice_56329_AwakerVoiceContent = {
    Text = "O güzel balerin hanımefendi... Onun zümrüt yeşili alevleri, insanı küle çevirse bile karşı konulamaz..."
  },
  Voice_56329_AwakerVoiceTitle = {
    Text = "Sohbet: Liz Hakkında"
  },
  Voice_56329_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Liz\" elde edildikten sonra açılır"
  },
  Voice_5632_AwakerVoiceContent = {
    Text = "Artık Sepirot yerine bununla mı besleneceğim?"
  },
  Voice_5632_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5633_AwakerVoiceContent = {
    Text = "Lezzetli. Tam anlamıyla lezzetli."
  },
  Voice_5633_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5634_AwakerVoiceContent = {
    Text = "Karşılığında ne istiyorsun, sevgili Konuk?"
  },
  Voice_5634_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5635_AwakerVoiceContent = {
    Text = "Çabuk, toparlan! Sokaklarda oyalanma."
  },
  Voice_5635_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5636_AwakerVoiceContent = {
    Text = "Kaçınılmaz kurban."
  },
  Voice_5636_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5637_AwakerVoiceContent = {
    Text = "(Bastırılmış bir tahammül iniltisi)"
  },
  Voice_5637_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_56386_AwakerVoiceContent = {
    Text = "Mevcut girdi tamamlandı. Akım veriliyor."
  },
  Voice_56386_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_56387_AwakerVoiceContent = {
    Text = "Londinium'un en iyi hırsızıyla uğraşma!"
  },
  Voice_56387_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_56388_AwakerVoiceContent = {
    Text = "İlk Ziyaret geliyor!"
  },
  Voice_56388_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_56389_AwakerVoiceContent = {
    Text = "Bin Yüzlü Serap burada!"
  },
  Voice_56389_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_5638_AwakerVoiceContent = {
    Text = "Yaklaşıyor..."
  },
  Voice_5638_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5638_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_56390_AwakerVoiceContent = {
    Text = "Bat ve yan! Yıkıma Dans!"
  },
  Voice_56390_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_56391_AwakerVoiceContent = {
    Text = "Bu, sayısız kayıp ruhun dolaştığı, asla yuvalarına dönemeyecekleri şehirdir."
  },
  Voice_56391_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_56392_AwakerVoiceContent = {
    Text = "İşte bu da kalan son, dalgalanan gücüm... Sen alabilirsin!"
  },
  Voice_56392_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_56393_AwakerVoiceContent = {
    Text = "Londinium'un en iyi hırsızıyla uğraşma!"
  },
  Voice_56393_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_5639_AwakerVoiceContent = {
    Text = "Düşman mı? Lütfen saldırmamı emredin.\nDüşmanınız siyah balçık mı... O zaman... Ben de düşmanınız mıyım?"
  },
  Voice_5639_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5640_AwakerVoiceContent = {
    Text = "Otomaton Erica, Gövde No. EA307881, Motor No. MF311028. Hizmetinizde olmaktan memnuniyet duyarım."
  },
  Voice_5640_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5641_AwakerVoiceContent = {
    Text = "Savaş! Hiçbir şeyi ayakta bırakma!"
  },
  Voice_5641_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5642_AwakerVoiceContent = {
    Text = "Merhaba, ben... şey... Bana adımı söyleyebilir misin?"
  },
  Voice_5642_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5643_AwakerVoiceContent = {
    Text = "Okula geldikten sonra, beni enfekte eden Çözünme denen hastalığı nihayet anladım. Ailem, hayattayken beni hep denizden uzak tutardı ve şimdi, bu enfeksiyonun gerçekten de denize olan yakınlığımla bağlantılı olabileceği anlaşılıyor..."
  },
  Voice_5643_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5644_AwakerVoiceContent = {
    Text = "Pekâlâ. Seni hayal kırıklığına uğratmayacağım... Söz."
  },
  Voice_5644_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5645_AwakerVoiceContent = {
    Text = "Ah, kavurucu nefesim..."
  },
  Voice_5645_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5646_AwakerVoiceContent = {Text = "Git."},
  Voice_5646_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5647_AwakerVoiceContent = {Text = "Dön."},
  Voice_5647_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5648_AwakerVoiceContent = {Text = "Hey!"},
  Voice_5648_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5650_AwakerVoiceContent = {
    Text = "O gün nihayet geldi..."
  },
  Voice_5650_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5651_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5651_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5652_AwakerVoiceContent = {
    Text = "Henüz işim bitmedi... Ne dersin, kalk da seni bir kez daha Öldürüyeyim?"
  },
  Voice_5652_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5654_AwakerVoiceContent = {
    Text = "Koruyucu, seninle konuşmalıyım. Nihai zafere ulaşmadan önce, bazıları bu kadar müsrif olmamalı. Unutma, ben böyle insanların lüks hayatları için savaşmıyorum!"
  },
  Voice_5654_AwakerVoiceTitle = {
    Text = "Sohbet: Sorel Hakkında"
  },
  Voice_5654_UnlockDesc = {
    Text = "\"Sorel\" Uyandıranı edinince açılır"
  },
  Voice_5655_AwakerVoiceContent = {
    Text = "Eğer rehin alınırsam, beni nasıl zalim bir kader bekler?"
  },
  Voice_5655_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5656_AwakerVoiceContent = {Text = "Şuna bak!"},
  Voice_5656_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5657_AwakerVoiceContent = {Text = "Hıh!"},
  Voice_5657_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5658_AwakerVoiceContent = {
    Text = "Off... öyle uykum var ki. Dinlenmeden önce doğru dürüst ikramlar hazırladın mı?"
  },
  Voice_5658_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5659_AwakerVoiceContent = {
    Text = "Anneciğim, onları sevmek ister misin? Çok yumuşak oldukları söyleniyor."
  },
  Voice_5659_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5659_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5660_AwakerVoiceContent = {
    Text = "Hehehe, lalalla~ Temizlik, temizlik, temizliği severim, temizliği öyle çok severim ki~"
  },
  Voice_5660_AwakerVoiceTitle = {
    Text = "Sohbet: Çalışmak Hakkında"
  },
  Voice_5661_AwakerVoiceContent = {
    Text = "(Pain içinde inler)"
  },
  Voice_5661_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5662_AwakerVoiceContent = {
    Text = "Hmm... Fena değil."
  },
  Voice_5662_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5663_AwakerVoiceContent = {
    Text = "(Pain içinde inler)"
  },
  Voice_5663_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5664_AwakerVoiceContent = {
    Text = "(Pain içinde inler)"
  },
  Voice_5664_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5665_AwakerVoiceContent = {
    Text = "Yanan Öfke!"
  },
  Voice_5665_AwakerVoiceTitle = {
    Text = "Özel Beceri: I"
  },
  Voice_5666_AwakerVoiceContent = {
    Text = "I've seen many go mad from Dissolution. Truth is, I'm already mad enough. Bet that thing can't affect me.\nÇözünme yüzünden deliren çok kişi gördüm. Gerçek şu ki, ben zaten fazlasıyla deliyim. Bahse girerim o şey bana etki edemez."
  },
  Voice_5666_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5667_AwakerVoiceContent = {
    Text = "Heh... Hahaha!"
  },
  Voice_5667_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5668_AwakerVoiceContent = {
    Text = "İyi aletler başarının yarısıdır!"
  },
  Voice_5668_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5669_AwakerVoiceContent = {
    Text = "Bu, topraktan yeniden doğuş gibi hissettiriyor."
  },
  Voice_5669_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5670_AwakerVoiceContent = {
    Text = "Fena değil."
  },
  Voice_5670_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5671_AwakerVoiceContent = {
    Text = "Şimdi bıçağım güçle şarkı söylüyor!"
  },
  Voice_5671_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5672_AwakerVoiceContent = {
    Text = "Yoklama dengeleme, araştırma ilerlemesini sürdürme ve öğretim görevlerini tamamlama... Görünüşe göre ters zaman sıkıştırma deneyi derhâl önceliklendirilmek zorunda."
  },
  Voice_5672_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5672_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5673_AwakerVoiceContent = {
    Text = "Resmen maceraya çıkmaya bir adım daha yaklaştık!"
  },
  Voice_5673_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5674_AwakerVoiceContent = {
    Text = "Beni suya yaklaştırma, tamam mı? Sana duyduğum bu nefis, yakan aşkın... söndürülmesini istemem."
  },
  Voice_5674_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5675_AwakerVoiceContent = {
    Text = "Sona kadar savaş!"
  },
  Voice_5675_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5676_AwakerVoiceContent = {
    Text = "Cesaretin gerçekten takdire şayan. Şu dokunaçlara bak—taşıdıkları delilikten hiç mi korkmuyorsun?"
  },
  Voice_5676_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5676_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5677_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5677_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5678_AwakerVoiceContent = {Text = "Ah..."},
  Voice_5678_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5679_AwakerVoiceContent = {
    Text = "Lütfen dur!"
  },
  Voice_5679_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5680_AwakerVoiceContent = {
    Text = "Dokunmak ister misin? Kalbim, senin varlığın yüzünden atıyor."
  },
  Voice_5680_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5680_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5681_AwakerVoiceContent = {
    Text = "Neşeyle cıvıldıyorlar. Teşekkür ederim, Usta."
  },
  Voice_5681_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5681_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5682_AwakerVoiceContent = {
    Text = "Göğsümde sıcacık bir his var... Lily, Lily çok mutlu, gözyaşları...\nAnneciğim, birlikte kutlayalım."
  },
  Voice_5682_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5682_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5683_AwakerVoiceContent = {
    Text = "Senin yanında mutluyum, Anne."
  },
  Voice_5683_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5683_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5684_AwakerVoiceContent = {
    Text = "Tıka basa doydum... Karnım çok tok.\nBu ritüelden sonra Lily daha güçlü olacak mı?"
  },
  Voice_5684_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5684_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5685_AwakerVoiceContent = {
    Text = "Denizi seviyorum. Bu ironik mi? Sahip olduğum her şey şimdi Derin Deniz’in dibine gömülü..."
  },
  Voice_5685_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5686_AwakerVoiceContent = {Text = "Dikkat et!"},
  Voice_5686_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5687_AwakerVoiceContent = {
    Text = "Nefret ettiğim şeyler mi...? Hiç yok. Bir toz zerresinden ya da bir yapraktan nefret eder miydin?"
  },
  Voice_5687_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5688_AwakerVoiceContent = {
    Text = "Hizmetçinin şölen davetlerini birkaç kez geri çevirdim. Biraz üzülmüş gibiydi... Ama sadece eğlenmekle kıyaslandığında, efendim, sizin güvenliğiniz çok daha önemli!"
  },
  Voice_5688_AwakerVoiceTitle = {
    Text = "Sohbet: Karen Hakkında"
  },
  Voice_5688_UnlockDesc = {
    Text = "Uyanışçı \"Karen\" edinildiğinde açılır"
  },
  Voice_5689_AwakerVoiceContent = {
    Text = "Bir efendi, bir Şövalye’nin var oluş sebebidir; bu yüzden, lütfen, bana dilediğiniz gibi emir verin!"
  },
  Voice_5689_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5690_AwakerVoiceContent = {
    Text = "...Bunun için bir tork anahtarına ihtiyacımız olabilir... Hm, pardon, az önce bana mı seslendin?"
  },
  Voice_5690_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5691_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5692_AwakerVoiceContent = {
    Text = "Buna nasıl cüret edersin!"
  },
  Voice_5692_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5693_AwakerVoiceContent = {
    Text = "(Zarif, bastırılmış bir Pain nefesi)"
  },
  Voice_5693_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5694_AwakerVoiceContent = {
    Text = "(Bastırılmış bir tahammül iniltisi)"
  },
  Voice_5694_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5695_AwakerVoiceContent = {
    Text = "Yeter artık."
  },
  Voice_5695_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5696_AwakerVoiceContent = {Text = "Nazik ol."},
  Voice_5696_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5697_AwakerVoiceContent = {
    Text = "Off, hâlâ odaklanmak epey zor..."
  },
  Voice_5697_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5698_AwakerVoiceContent = {
    Text = "Geceleri sık sık yanıma sokulur. Sadece başım çok göze çarpıyor diye mi acaba?"
  },
  Voice_5698_AwakerVoiceTitle = {
    Text = "Sohbet: Winkle Hakkında"
  },
  Voice_5698_UnlockDesc = {
    Text = "\"Winkle\" Uyandıranı edinince açılır"
  },
  Voice_5699_AwakerVoiceContent = {
    Text = "Ben hep yıkımın varışını bekledim, hiç “direnç” göstermeyi düşünmedim... Sığ ruhumun uçurumu aşmasına yardım eder misin? Kıl payı hayatta kaldığım bir dünyada bile bana hâlâ kurtuluş bahşediyorsun..."
  },
  Voice_5699_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5699_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5700_AwakerVoiceContent = {
    Text = "Senin havarin olarak Uyandırıldığım günden beri, barışından ve neşenden başka bir şey aramıyorum, işte bu benim dileğim... Ugh... Ahh... Evet, evet, hayatta kalmayı, azmi, üremeyi diliyorum, yaşamalıyız, YAŞAMALIYIZ..."
  },
  Voice_5700_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5700_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5701_AwakerVoiceContent = {
    Text = "Neden kendini sevgimde kaybetmiyorsun? Beni, kucaklayışımın sıcaklığı için uyandırmadın mı?"
  },
  Voice_5701_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5701_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5702_AwakerVoiceContent = {
    Text = "Hmm? Kökeni bilinmeyen bir kadın olduğum için mi benden sakınıyorsun? Pekâlâ... Ben, Ninova’nın tahttan indirilmiş kraliçesiydim; göğün kapısını tırmalayan Şinar’lıydım; Fırat’ın kutsal dallarının altında bilinci çalınan kız çocuktum... Nereden başlayayım, temkinli sevgilim?"
  },
  Voice_5702_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5702_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5703_AwakerVoiceContent = {
    Text = "Neden hep benden kaçıyorsun? Utanıyor musun? Ne kadar sevimli, arzularınla yüzleşmekten bu çekingen kaçışın."
  },
  Voice_5703_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5703_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5704_AwakerVoiceContent = {
    Text = "Burası tam anlamıyla dehşet verici! Nasıl olur da benden öğleden sonra çayında başkalarıyla aynı masayı paylaşmamı beklerler?! ...Ev yapımı kurabiyeler fena değil gerçi. Akşam yemeğinden sonra odama bir tabak gönder."
  },
  Voice_5704_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5705_AwakerVoiceContent = {Text = "Selam!"},
  Voice_5705_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5706_AwakerVoiceContent = {Text = "Şuna bak!"},
  Voice_5706_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5707_AwakerVoiceContent = {
    Text = "Çözünme... Evet, memleketimdeki okullarda bununla ilgili kayıtlar var, ama, şey, okumayı sevmem. Hiçbir şey hatırlamıyorum!"
  },
  Voice_5707_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5708_AwakerVoiceContent = {
    Text = "Yeniden yelken açmamı diliyor musun? Geçmişteki başarısızlığımı dert etmezsen... buna hazırım."
  },
  Voice_5708_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5708_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5709_AwakerVoiceContent = {
    Text = "Sevmediklerim mi? Bir sürü. Seni geç saatlere kadar çalıştıran reisler, kendini beğenmiş rahibeler, hırlayan mideler, cam taneleriyle dolu kara ekmek…"
  },
  Voice_5709_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5710_AwakerVoiceContent = {
    Text = "Hepsi benim suçum... Her şey benim suçum..."
  },
  Voice_5710_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5711_AwakerVoiceContent = {
    Text = "Bunu şimdi bitireceğiz!"
  },
  Voice_5711_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5712_AwakerVoiceContent = {
    Text = "Hannah Hanım sayesinde koro provasını izleyebildim. İlahilerle denizci türkülerinin farkı büyük; yıllar boyunca uzun yolculukları kutsarken böylesine benzersiz bir melodi hiç duymamıştım..."
  },
  Voice_5712_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5713_AwakerVoiceContent = {Text = "BUNU YE!"},
  Voice_5713_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5714_AwakerVoiceContent = {Text = "BUNU YE!"},
  Voice_5714_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5715_AwakerVoiceContent = {
    Text = "Vaaah, ne korkunç!"
  },
  Voice_5715_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5716_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_5716_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5717_AwakerVoiceContent = {
    Text = "Merhaba, sevgili yeni Efendim! Bugünün menüsünde sümüklüböcek pudingi, Kurbağa Yahnisi ve yeşil alev şarabı var. Hangisini arzu edersiniz?"
  },
  Voice_5717_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5718_AwakerVoiceContent = {
    Text = "Buna mı Genesis Form diyorlar…? Hayır, hayal ettiğimden biraz farklı. Ama ben de öyle olabilseydim, harika olurdu."
  },
  Voice_5718_AwakerVoiceTitle = {
    Text = "Sohbet: Derin Deniz Soyu Hakkında"
  },
  Voice_5718_UnlockDesc = {
    Text = "Uyanışçılardan \"Tulu\", \"Murphy\", \"Miryam\" ya da \"Golyat\"tan herhangi birini edindikten sonra açılır."
  },
  Voice_5719_AwakerVoiceContent = {
    Text = "Doğru anı bekle."
  },
  Voice_5719_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5720_AwakerVoiceContent = {Text = "Şuna bak!"},
  Voice_5720_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5721_AwakerVoiceContent = {
    Text = "Kuzular, Ulu Baba'nın iradesi sizi kurtuluşa erdirecek."
  },
  Voice_5721_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5722_AwakerVoiceContent = {
    Text = "Kuzular, Ulu Baba'nın iradesi sizi kurtuluşa erdirecek."
  },
  Voice_5722_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5723_AwakerVoiceContent = {Text = "Geber!"},
  Voice_5723_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5724_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5724_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5725_AwakerVoiceContent = {Text = "Hıh!"},
  Voice_5725_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5726_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5726_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5727_AwakerVoiceContent = {
    Text = "O, kadersel işkenceye mahkûm, acınası bir Kadın. Bir bakıma ona acıyorum, çünkü O’nun gerçek doğuşu vuku bulduğunda, ona ölümün merhametini bahşedeceğim."
  },
  Voice_5727_AwakerVoiceTitle = {
    Text = "Sohbet: Miryam Hakkında"
  },
  Voice_5727_UnlockDesc = {
    Text = "Uyanışçı \"Miryam\" elde edildikten sonra açılır"
  },
  Voice_5728_AwakerVoiceContent = {
    Text = "Kanla lekelen!"
  },
  Voice_5728_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5729_AwakerVoiceContent = {
    Text = "İntikam...!"
  },
  Voice_5729_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5730_AwakerVoiceContent = {
    Text = "Acıtıyor..."
  },
  Voice_5730_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5731_AwakerVoiceContent = {
    Text = "(Bastırılmış bir acı iniltisi)"
  },
  Voice_5731_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5732_AwakerVoiceContent = {
    Text = "(Bastırılmış bir acı iniltisi)"
  },
  Voice_5732_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5733_AwakerVoiceContent = {Text = "Ah..."},
  Voice_5733_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5734_AwakerVoiceContent = {
    Text = "Benimle birlikte batmak ister misin?"
  },
  Voice_5734_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5735_AwakerVoiceContent = {Text = "Uzak dur!"},
  Voice_5735_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5736_AwakerVoiceContent = {
    Text = "Nefret ettiğim şeyler... dağınık bir masa, karmakarışık bir gardırop, tozlu pencere pervazları—evet, odanı tarif ediyorum. Yarın sabah saat 7’ye kadar burayı, yerleşmeden önceki hâline geri dönmüş olarak görmek istiyorum."
  },
  Voice_5736_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5737_AwakerVoiceContent = {
    Text = "(İlgili bir mırıldanma)"
  },
  Voice_5737_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5738_AwakerVoiceContent = {Text = "İlginç!"},
  Voice_5738_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5739_AwakerVoiceContent = {
    Text = "(Tiksintiyle küçümser)"
  },
  Voice_5739_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5740_AwakerVoiceContent = {
    Text = "Gerekirse, Beşikten ayrılabilirim ben de..."
  },
  Voice_5740_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5741_AwakerVoiceContent = {
    Text = "Biraz ilgiye muhtaç mıyız yoksa?"
  },
  Voice_5741_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5742_AwakerVoiceContent = {
    Text = "Al bakalım!"
  },
  Voice_5742_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5743_AwakerVoiceContent = {
    Text = "İkiye katla! Bir daha katla!"
  },
  Voice_5743_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5744_AwakerVoiceContent = {
    Text = "Bu bana sekiz yaşındayken aldığım ilk kırmızı dans ayakkabısını hatırlatıyor. Onları gerçekten çok seviyorum. Teşekkür ederim, Koruyucu."
  },
  Voice_5744_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5744_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5745_AwakerVoiceContent = {
    Text = "Nedir... arkadaş? Usta? Anne?"
  },
  Voice_5745_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5746_AwakerVoiceContent = {
    Text = "Demek benim korumam da bazen başarısız olabiliyor..."
  },
  Voice_5746_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5747_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_5747_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5748_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_5748_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5749_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_5749_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5750_AwakerVoiceContent = {
    Text = "Sevdiğim şeyler mi? Bir zamanlar bana bunu Peloponez savaş alanlarında sormuşlardı... Artık çok geç. Böyle kişisel tercihleri çoktan bir kenara bıraktım."
  },
  Voice_5750_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5751_AwakerVoiceContent = {
    Text = "Şşşt... Lütfen \"onların\" daha Güçlü olduğumu keşfetmesine izin verme."
  },
  Voice_5751_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5752_AwakerVoiceContent = {
    Text = "\"Onların\" hepsi... Teşekkür etti."
  },
  Voice_5752_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5753_AwakerVoiceContent = {
    Text = "Uh... Bu da ne?"
  },
  Voice_5753_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5754_AwakerVoiceContent = {
    Text = "Bu yalnızca beni Uçurum’a daha da yaklaştıracak."
  },
  Voice_5754_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5754_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5755_AwakerVoiceContent = {
    Text = "Sen benim sevgili uşağımsın. Sen buna arkadaş, ortak, yoldaş diyorsun... Nasıl adlandırırsan adlandır."
  },
  Voice_5755_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5756_AwakerVoiceContent = {
    Text = "Cevabımı aldım. İstediğim cevap değildi... ama yine de bir cevaptı."
  },
  Voice_5756_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5756_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5757_AwakerVoiceContent = {
    Text = "Yüzündeki o ifade korku mu? Yoksa keder mi? Gerçekten büyüleyici."
  },
  Voice_5757_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5757_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5758_AwakerVoiceContent = {
    Text = "Ölümün ve yok oluşun kokusu... Ne kadar da canlı."
  },
  Voice_5758_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5758_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5759_AwakerVoiceContent = {
    Text = "Burayı sevip sevmediğim mi? F-fena değil. Mekanik bilim ve ruh araştırması bilgimden birazını Bayan Bebek’le paylaştığım sürece, ışıkları açık tutmama izin veriyor."
  },
  Voice_5759_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5760_AwakerVoiceContent = {
    Text = "Umarım Jenkin ve Brown akademideki zamanlarının tadını çıkarıyordur. Babamın Kol Düğmeleri önemsiz şeyler. Jenkin onları istiyorsa, alabilir. Eminim yedeklerle dolu bir kutusu vardır."
  },
  Voice_5760_AwakerVoiceTitle = {
    Text = "Sohbet: Jenkin Hakkında"
  },
  Voice_5760_UnlockDesc = {
    Text = "\"Jenkin\" Uyandıranı edinince açılır"
  },
  Voice_5761_AwakerVoiceContent = {
    Text = "Buradan ayrılamam..."
  },
  Voice_5761_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5762_AwakerVoiceContent = {
    Text = "Aşağı ırkları Aşmış biri olarak, böyle bir etkinin karşısında korku duymam. Konak bedeni paramparça olsa bile, asil kan soyu yok olmayacak."
  },
  Voice_5762_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5763_AwakerVoiceContent = {
    Text = "Sahte gülüşlü insanlardan nefret ederim! Onlardan hiçbir duygu çalamazsın!"
  },
  Voice_5763_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5764_AwakerVoiceContent = {
    Text = "Hmm? Neden herkes suskun? Karen sessizlikten nefret eder. Size bir hikâye anlatayım. Evvel zaman içinde, kalbur saman içinde, bir dağ varmış..."
  },
  Voice_5764_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5765_AwakerVoiceContent = {
    Text = "Lily geleceğe el koyacak... Tekeli—Li!"
  },
  Voice_5765_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5766_AwakerVoiceContent = {
    Text = "Lily geleceğe el koyacak... Tekeli—Li!"
  },
  Voice_5766_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5767_AwakerVoiceContent = {
    Text = "Bunu O’nun varlığını hissetmek için yapıyorsan, küstahlığını geçici olarak bağışlayacağım."
  },
  Voice_5767_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5768_AwakerVoiceContent = {
    Text = "Bunu yapmak istemiyorum..."
  },
  Voice_5768_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5769_AwakerVoiceContent = {Text = "Uzak dur!"},
  Voice_5769_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5770_AwakerVoiceContent = {
    Text = "Yavaş yavaş, emirlerinle kendi ritmimi buluyorum!"
  },
  Voice_5770_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5771_AwakerVoiceContent = {
    Text = "Gerçek bir şövalye olmaya biraz daha yaklaştım!"
  },
  Voice_5771_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5772_AwakerVoiceContent = {
    Text = "Bu onur için teşekkür ederim, efendim. Benim için çok şey ifade ediyor."
  },
  Voice_5772_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5773_AwakerVoiceContent = {
    Text = "Hamam zamanı geçirmek için harika bir yer! Yemekler leziz, kas gevşetme hizmetleri de sunuyorlar! Cazip geldi mi? Öyleyse hemen bu okula da bir tane inşa et!"
  },
  Voice_5773_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5774_AwakerVoiceContent = {
    Text = "Hayır... B-Beni bırakma!"
  },
  Voice_5774_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5775_AwakerVoiceContent = {Text = "Hazır."},
  Voice_5775_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5776_AwakerVoiceContent = {
    Text = "(Yumuşak, bastırılmış bir nefes alış)"
  },
  Voice_5776_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5777_AwakerVoiceContent = {
    Text = "(Aşağılayıcı Tahammül)"
  },
  Voice_5777_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5778_AwakerVoiceContent = {
    Text = "(Aşağılayıcı Tahammül)"
  },
  Voice_5778_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5779_AwakerVoiceContent = {
    Text = "(Aşağılayıcı Tahammül)"
  },
  Voice_5779_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5780_AwakerVoiceContent = {
    Text = "Bana bırak."
  },
  Voice_5780_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_57818_AwakerVoiceContent = {
    Text = "Bana hakaret eden herkes bedelini ödeyecek!"
  },
  Voice_57818_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_57819_AwakerVoiceContent = {
    Text = "Bana hakaret eden herkes bedelini ödeyecek!"
  },
  Voice_57819_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_5781_AwakerVoiceContent = {
    Text = "Bana bırak."
  },
  Voice_5781_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_57820_AwakerVoiceContent = {
    Text = "Beyaz Kuş Diyarı’nı arayıştaki adımlarımı hiç kimse durduramaz!"
  },
  Voice_57820_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_57821_AwakerVoiceContent = {
    Text = "Bu katliam şöleninin tadını çıkarın! Sonuna kadar!"
  },
  Voice_57821_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_57822_AwakerVoiceContent = {
    Text = "Beyaz Kuş Diyarı’nı arayıştaki adımlarımı hiç kimse durduramaz!"
  },
  Voice_57822_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_57823_AwakerVoiceContent = {
    Text = "Sahte görevler, yazgıya kazınmış gelecekler... Onlarla Son ana kadar savaşacağım!"
  },
  Voice_57823_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_57824_AwakerVoiceContent = {
    Text = "Sahte görevler, yazgıya kazınmış gelecekler... Onlarla Son ana kadar savaşacağım!"
  },
  Voice_57824_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_57825_AwakerVoiceContent = {
    Text = "Bu katliam şöleninin tadını çıkarın! Sonuna kadar!"
  },
  Voice_57825_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_57826_AwakerVoiceContent = {
    Text = "Ritüelime katıl ve tohumum ol!"
  },
  Voice_57826_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_57827_AwakerVoiceContent = {
    Text = "Hain, umutsuzluğumun ve öfkemin tadına bak!"
  },
  Voice_57827_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_57828_AwakerVoiceContent = {
    Text = "Hain, umutsuzluğumun ve öfkemin tadına bak!"
  },
  Voice_57828_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_57829_AwakerVoiceContent = {
    Text = "Ritüelime katıl ve tohumum ol!"
  },
  Voice_57829_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_5782_AwakerVoiceContent = {
    Text = "Aurita’ya, sandığı kadar genç olmadığımı söylemeye hep utandım. Onun \"küçük kız kardeşi\" değilim. Bunu ona açmama belki sen yardım edebilir misin?"
  },
  Voice_5782_AwakerVoiceTitle = {
    Text = "Sohbet: Aurita Hakkında"
  },
  Voice_5782_UnlockDesc = {
    Text = "\"Aurita\" Uyandıranı edinince açılır"
  },
  Voice_57830_AwakerVoiceContent = {
    Text = "Uzun zaman önce yitip gitmiş Lemuria şehri, nihayet gün yüzüne çıktı."
  },
  Voice_57830_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_57831_AwakerVoiceContent = {
    Text = "Uzun zaman önce yitip gitmiş Lemuria şehri, nihayet gün yüzüne çıktı."
  },
  Voice_57831_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_57832_AwakerVoiceContent = {
    Text = "Saat geldi. Sözüm yerine getirilecek."
  },
  Voice_57832_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_57833_AwakerVoiceContent = {
    Text = "Saat geldi. Sözüm yerine getirilecek."
  },
  Voice_57833_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_57834_AwakerVoiceContent = {
    Text = "Bütün bunların hepsi O'nun ilahi planının bir parçası."
  },
  Voice_57834_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_57835_AwakerVoiceContent = {
    Text = "Bütün bunların hepsi O'nun ilahi planının bir parçası."
  },
  Voice_57835_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_57836_AwakerVoiceContent = {
    Text = "Yıldızlardan Gelen Sürüngen davetini uzatıyor... sana."
  },
  Voice_57836_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_57837_AwakerVoiceContent = {
    Text = "Ben hâlâ... Uzaydan Gelen Ana Renk'im!"
  },
  Voice_57837_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_57838_AwakerVoiceContent = {
    Text = "Ben hâlâ... Uzaydan Gelen Ana Renk'im!"
  },
  Voice_57838_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_57839_AwakerVoiceContent = {
    Text = "Yıldızlardan Gelen Sürüngen davetini uzatıyor... sana."
  },
  Voice_57839_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_5783_AwakerVoiceContent = {Text = "Geri dur!"},
  Voice_5783_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_57840_AwakerVoiceContent = {
    Text = "Herkes, hadi birlikte saldırıya geçelim!"
  },
  Voice_57840_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_57841_AwakerVoiceContent = {
    Text = "Yeraltı Labirenti’nin Tanrısı, hepiniz hakkında yargı veriyor!"
  },
  Voice_57841_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_57842_AwakerVoiceContent = {
    Text = "Yeraltı Labirenti’nin Tanrısı, hepiniz hakkında yargı veriyor!"
  },
  Voice_57842_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_57843_AwakerVoiceContent = {
    Text = "İlham mavisi gökte süzülen kuş, lütfen duama kulak ver."
  },
  Voice_57843_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_57844_AwakerVoiceContent = {
    Text = "İlham mavisi gökte süzülen kuş, lütfen duama kulak ver."
  },
  Voice_57844_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_57845_AwakerVoiceContent = {
    Text = "Kıpırdama! Kıpırdama! Hayır!"
  },
  Voice_57845_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_57846_AwakerVoiceContent = {
    Text = "Kan zincirlerinin altında titreyin... Kan zincirlerinin altında yok olun!"
  },
  Voice_57846_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_57847_AwakerVoiceContent = {
    Text = "Kan zincirlerinin altında titreyin... Kan zincirlerinin altında yok olun!"
  },
  Voice_57847_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_57848_AwakerVoiceContent = {
    Text = "Herkes, hadi birlikte saldırıya geçelim!"
  },
  Voice_57848_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_57849_AwakerVoiceContent = {
    Text = "Kıpırdama! Kıpırdama! Hayır!"
  },
  Voice_57849_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_5784_AwakerVoiceContent = {Text = "Hehe..."},
  Voice_5784_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_57850_AwakerVoiceContent = {
    Text = "Bak iyi izle! Filistin’in bel bağladığı Güç işte budur!"
  },
  Voice_57850_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_57851_AwakerVoiceContent = {
    Text = "Bak iyi izle! Filistin’in bel bağladığı Güç işte budur!"
  },
  Voice_57851_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_5785_AwakerVoiceContent = {
    Text = "Çok zayıf."
  },
  Voice_5785_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5786_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5786_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5787_AwakerVoiceContent = {
    Text = "Hmm... Efendim üzgün mü görünüyor? Karen seni komik bir yüzle neşelendirsin, hehe! Şimdi daha iyi hissediyor musun?"
  },
  Voice_5787_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5788_AwakerVoiceContent = {
    Text = "Dünyanın sırlarını insan zekâsıyla açığa çıkar!"
  },
  Voice_5788_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5789_AwakerVoiceContent = {
    Text = "Koridorda içimi huzursuz eden bazı kişilerle karşılaştım. Şartlar gereği onlarla iş birliği yapman gerekebilir, ama tetikte kal! İnsan kalbi savaştan daha zalimdir ve en kötü ihanetler çoğu zaman içeriden gelir."
  },
  Voice_5789_AwakerVoiceTitle = {
    Text = "Sohbet: @2 Hakkında"
  },
  Voice_5789_UnlockDesc = {
    Text = "\"Helot\" ya da \"Lily\" Uyanışçısı edinildikten sonra açılır."
  },
  Voice_5790_AwakerVoiceContent = {
    Text = "Ödevin bitti, değil mi? Benimle şehir merkezine gelebilir misin... Ha? Matematik ödevin henüz bitmedi mi?! Ah... özür dilerim, kalkülüsü anlamayan biri olacağını beklemiyordum... Yardım edeyim."
  },
  Voice_5790_AwakerVoiceTitle = {
    Text = "Sohbet: Çalışmak Üzerine"
  },
  Voice_5791_AwakerVoiceContent = {
    Text = "Sana yemin ederim, o dükkâncı Fontainebleau’daki salonlardan birinde kesinlikle görünmüştü... Anlıyorum, görünüşü hiç değişmemiş. Acaba ondan kaç tane Sır koparabiliriz?"
  },
  Voice_5791_AwakerVoiceTitle = {
    Text = "Sohbet: Nergis Hakkında"
  },
  Voice_5791_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Nergis\" elde edildikten sonra açılır"
  },
  Voice_5792_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_5792_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5793_AwakerVoiceContent = {
    Text = "Onu kırma."
  },
  Voice_5793_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5794_AwakerVoiceContent = {
    Text = "Aurita, Herkes’le oyna-mayı çok sever! Sen de katılır mısın? Bu Jelly, şu Hela, şuradaki de Jelly... ha?"
  },
  Voice_5794_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5795_AwakerVoiceContent = {
    Text = "Şimdi bu utancı üzerimden temizleyeceğim!"
  },
  Voice_5795_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5796_AwakerVoiceContent = {
    Text = "Nergis’in dükkânı artık açık. Hazırlanmamış Çocuklar, lütfen öylesine içeri dalmayın."
  },
  Voice_5796_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5796_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5797_AwakerVoiceContent = {
    Text = "Lütfen, boynuma dokunmayın... Onu göremiyor olmanız, orada olmadığı anlamına gelmez."
  },
  Voice_5797_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5798_AwakerVoiceContent = {
    Text = "Kararlılığa saygı duyarım; ister bir canavarda, ister bir Uyandıran’da, ister bir insanda olsun. Bir de savaşabiliyorlarsa, daha da iyi."
  },
  Voice_5798_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5799_AwakerVoiceContent = {Text = "Git."},
  Voice_5799_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5800_AwakerVoiceContent = {
    Text = "Endişelenmeyin!"
  },
  Voice_5800_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5801_AwakerVoiceContent = {
    Text = "Ramona... yani, vedaları sevmem. Fazla hüzünlüler."
  },
  Voice_5801_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5802_AwakerVoiceContent = {
    Text = "Din adamlarıyla aram pek iyi değildir. Sıkıcı ve katıdırlar, kemerlerini de sevgili “Tanrı”larına vermişler. Ne yazık, Bay Salvador ne de güzel kokuyor..."
  },
  Voice_5802_AwakerVoiceTitle = {
    Text = "Sohbet: Salvador Hakkında"
  },
  Voice_5802_UnlockDesc = {
    Text = "Uyanışçı \"Salvador\" elde edildikten sonra açılır"
  },
  Voice_5803_AwakerVoiceContent = {
    Text = "Savaş’ın verdiği heyecan her şeyden üstün—kazanmak bile yanına yaklaşamaz."
  },
  Voice_5803_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5804_AwakerVoiceContent = {
    Text = "Kim yumuşak bir yatağı, fırtınasız, cereyansız bir… yani, odayı sevmez ki."
  },
  Voice_5804_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5805_AwakerVoiceContent = {
    Text = "Bana hatırlatma... Elworth’te hapsedildiğim günleri..."
  },
  Voice_5805_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5806_AwakerVoiceContent = {
    Text = "Hepsini yakın!"
  },
  Voice_5806_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5807_AwakerVoiceContent = {
    Text = "Hepsini yakın!"
  },
  Voice_5807_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5808_AwakerVoiceContent = {
    Text = "Kan kokusunu takip ederek buraya geldim. Söyler misiniz... benim için taze kanınız var mı?"
  },
  Voice_5808_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5809_AwakerVoiceContent = {
    Text = "Hmm... Agrippa’nın birçok Dostu var, ama hepsi ondan korkuyor gibi. Yoksa onların yemeklerini mi çalıyor?"
  },
  Voice_5809_AwakerVoiceTitle = {
    Text = "Sohbet: Agrippa Hakkında"
  },
  Voice_5809_UnlockDesc = {
    Text = "\"Agrippa\" Uyandıranı edinince açılır"
  },
  Voice_5810_AwakerVoiceContent = {
    Text = "Hayatım Dans etrafında dönüyor. Başka Bilgi ler öğrenmek, benim için gelişmeyi zorlaştırıyor. Ama buradaki Herkes iyi kalpli; beni ne gösteriş ne de para için satmazlar—bunu hissedebiliyorum."
  },
  Voice_5810_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5811_AwakerVoiceContent = {
    Text = "Korkak! Benimkine benzer bir Güç’e sahipsin ama kendini dizginliyorsun. Bu, kendi isteğinle tasma takmaktan ne farkı var?"
  },
  Voice_5811_AwakerVoiceTitle = {
    Text = "Sohbet: Lily Hakkında"
  },
  Voice_5811_UnlockDesc = {
    Text = "\"Lily\" Uyandıranı edinince açılır"
  },
  Voice_5812_AwakerVoiceContent = {
    Text = "Yeterli değil... Hâlâ yeterince güçlü değilim."
  },
  Voice_5812_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5813_AwakerVoiceContent = {Text = "Geri dön."},
  Voice_5813_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5814_AwakerVoiceContent = {Text = "Argh!"},
  Voice_5814_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5815_AwakerVoiceContent = {
    Text = "Top hats, bowler hats, deerstalker hats, berets... Gotta say it's funny how those high and mighty \"gentlemen\" would do everything to hide their bald heads.\nSilindir Şapkalar, melon şapkalar, avcı şapkaları, bereler... Şu yüce “beyefendilerin” kel kafalarını saklamak için her şeyi yapmaları gerçekten komik."
  },
  Voice_5815_AwakerVoiceTitle = {
    Text = "Sohbet: Görgü Üzerine"
  },
  Voice_5816_AwakerVoiceContent = {
    Text = "Ona derinden hayranlık duyuyorum—denizlerin Tanrıça’sına, nilüfer kadar saf ve zarif olana... Diyorsun ki, o bile kendi Kaderini kontrol edememiş ve sonunda denize gömülmüş? Bunu hayal etmek bile gerçekten güç..."
  },
  Voice_5816_AwakerVoiceTitle = {
    Text = "Sohbet: Celeste Hakkında"
  },
  Voice_5816_UnlockDesc = {
    Text = "\"Celeste\" Uyandıranı edinince açılır"
  },
  Voice_5817_AwakerVoiceContent = {
    Text = "Hiçbir şey bir Dev’in gücüyle boy ölçüşemez!"
  },
  Voice_5817_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5818_AwakerVoiceContent = {
    Text = "Hiçbir şey bir Dev’in gücüyle boy ölçüşemez!"
  },
  Voice_5818_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5819_AwakerVoiceContent = {
    Text = "Lanet olsun! Lanet olsun! Bu güç beni sadece bu bedene hapsediyor!"
  },
  Voice_5819_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5819_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5820_AwakerVoiceContent = {
    Text = "Hep aydınlık olan bir yerde kalmak istiyorum... Evet, kutuplar. Bu gezegende, yalnızca kutuplar."
  },
  Voice_5820_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5820_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5821_AwakerVoiceContent = {
    Text = "Ben... ağır sorumluluklara katlanamam. Yalnızca ışığın peşinden gidebilirim. O yüzden, lütfen, parlamayı bırakma..."
  },
  Voice_5821_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5821_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5822_AwakerVoiceContent = {
    Text = "Boyutları bir kez daha kaydırabilseydim, bir yıldız olmak isterdim..."
  },
  Voice_5822_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5822_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5823_AwakerVoiceContent = {
    Text = "Ne kadar hesaplama yaparsam yapayım, bilinç aktarımının formülü çözümsüz kalıyor..."
  },
  Voice_5823_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5823_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5824_AwakerVoiceContent = {
    Text = "Hoş Geldin! Birlikte çılgınca eğlenelim!"
  },
  Voice_5824_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5825_AwakerVoiceContent = {
    Text = "Buyrun, Afiyet Olsun!"
  },
  Voice_5825_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5826_AwakerVoiceContent = {
    Text = "Hehe... Merhaba! Benim, Aurita! Bir, iki, üç... Vay! Hoş Geldin, hoş geldin! Yeni arkadaşlar bize katıldı! Ha? Bu sefer de sen mi benim yeni arkadaşımsın? Eh, bu da iş görür!"
  },
  Voice_5826_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5827_AwakerVoiceContent = {
    Text = "You call this little toy a handgun? Hiding in shadows to ambush enemies... Hmph. A weapon for cowards only.\nBu küçük oyuncağa tabanca mı diyorsun? Gölgelerde saklanıp düşmana Pusu kurmak... Hıh. Yalnızca korkakların silahı."
  },
  Voice_5827_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5828_AwakerVoiceContent = {
    Text = "Anlamsız. Hepsi. Neden uğraşasın ki?"
  },
  Voice_5828_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5829_AwakerVoiceContent = {
    Text = "Hiçbir şey bilmiyorsun. Hiç."
  },
  Voice_5829_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5830_AwakerVoiceContent = {
    Text = "Hâlâ beni yedeğin olarak görüyorsun, \"Kurtarıcı\"?"
  },
  Voice_5830_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5831_AwakerVoiceContent = {
    Text = "Affedersin, vidamı gördün mü? Garip ama, o fare kulaklı velet buralardayken, eşyaları nereye koyduğumu daha sık unutuyorum sanki..."
  },
  Voice_5831_AwakerVoiceTitle = {
    Text = "Sohbet: Jenkin Hakkında"
  },
  Voice_5831_UnlockDesc = {
    Text = "\"Jenkin\" Uyandıranı edinince açılır"
  },
  Voice_5832_AwakerVoiceContent = {
    Text = "Onunla Kavuşma'm için yaptığın katkıları asla unutmayacağım..."
  },
  Voice_5832_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5833_AwakerVoiceContent = {
    Text = "Yontulmuş Kantat'ı dinle!"
  },
  Voice_5833_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5834_AwakerVoiceContent = {
    Text = "Dileğimi kabul ettin mi?"
  },
  Voice_5834_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5835_AwakerVoiceContent = {
    Text = "Emirlerin beni hayal kırıklığına uğratmaz umarım."
  },
  Voice_5835_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5836_AwakerVoiceContent = {
    Text = "Gelişen bedenim mi, bilincim mi? Analiz için hayli ilgi çekici bir konu."
  },
  Voice_5836_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5836_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5837_AwakerVoiceContent = {
    Text = "Geri çekil."
  },
  Voice_5837_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5838_AwakerVoiceContent = {
    Text = "Çekil önümden."
  },
  Voice_5838_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5839_AwakerVoiceContent = {
    Text = "Damarlarım hayatta kalma iradesiyle kabarıyor, çığlık atarak beni bu gezegenin her karışına kanımı saçmaya zorluyor... Ah, fazla gevezelik ettim; lütfen bağışla. Ben Thais. Beni çağırdın mı? Benimle birleşmeye hazır mısın?"
  },
  Voice_5839_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5840_AwakerVoiceContent = {
    Text = "Keşke Aigis bu kara sıvıyı Herkes için taşıyabilseydi... Sonuçta Aigis hiç var olmadı, bu da Bu dünya için iyi bir şey olabilir, değil mi?"
  },
  Voice_5840_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5841_AwakerVoiceContent = {
    Text = "Hobilerim arasında Riemann Hipotezi’ni çözmeye çalışmak da var—ama bu, bizim Bay Tavuskuşu’nun sloganı, benim değil. Şahsen, atomik kütle standartlarını çok daha ilgi çekici buluyorum."
  },
  Voice_5841_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5842_AwakerVoiceContent = {
    Text = "Sürgün edilip denizde başıboş bırakılmanın tadı… Bir kez yaşamak yeter de artar."
  },
  Voice_5842_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5844_AwakerVoiceContent = {
    Text = "Dikkatle izle!"
  },
  Voice_5844_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5845_AwakerVoiceContent = {
    Text = "Dikkatle izle!"
  },
  Voice_5845_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5846_AwakerVoiceContent = {
    Text = "Bu adaleti sürdürebildiğin sürece, bıçağın yükünü omuzlarımda taşımaya her zaman hazırım."
  },
  Voice_5846_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5847_AwakerVoiceContent = {
    Text = "Buradaki o belli \"Ressam\" efsanesini duydun mu? Şu dışavurumcu graffitilerden tanıdık bir dokunuş hissediyorum..."
  },
  Voice_5847_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5848_AwakerVoiceContent = {
    Text = "Acıyor! O kadar, o kadar iyi hissediyorum ki!"
  },
  Voice_5848_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5849_AwakerVoiceContent = {
    Text = "Öfkemi hisset!"
  },
  Voice_5849_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5850_AwakerVoiceContent = {
    Text = "Bu zafer şiire kazınsın."
  },
  Voice_5850_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5851_AwakerVoiceContent = {Text = "Güçlen~"},
  Voice_5851_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5852_AwakerVoiceContent = {Text = "Şuna bak!"},
  Voice_5852_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5853_AwakerVoiceContent = {Text = "Hey!"},
  Voice_5853_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5854_AwakerVoiceContent = {
    Text = "Belki büyüyünce kendimi kontrol edebilir, başkalarının Canını tüketmemeyi başarabilirim... Hayatta kalmam için minicik bir parça yeter."
  },
  Voice_5854_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5854_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5855_AwakerVoiceContent = {
    Text = "Galiba ağırlaştım. Beşik hâlâ ağırlığımı taşıyabilir mi?"
  },
  Voice_5855_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5855_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5856_AwakerVoiceContent = {
    Text = "O kadar çok güç yedim ki, neredeyse taşacak. Sırtım da kaşınıyor. Yoksa... büyüyor muyum?"
  },
  Voice_5856_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_5856_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_5857_AwakerVoiceContent = {
    Text = "Her ne kadar hâlâ bir çocuğa benzesem de... Artık seni koruyacak güce sahibim."
  },
  Voice_5857_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5857_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5858_AwakerVoiceContent = {
    Text = "Büyümek için elimden geleni yapacağım."
  },
  Voice_5858_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_5858_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_5859_AwakerVoiceContent = {
    Text = "Kendini bilmez sefih, neden ille de beni uyandırmakta ısrar ediyorsun?"
  },
  Voice_5859_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5860_AwakerVoiceContent = {
    Text = "İlahi Ana olacağım!"
  },
  Voice_5860_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5861_AwakerVoiceContent = {
    Text = "Kaç kere Çağrı’ldım ben... İnsan, umarım yeterince \"yemek\" hazırlamışsındır, yoksa hiçbir şey için garanti veremem."
  },
  Voice_5861_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5862_AwakerVoiceContent = {
    Text = "Kapıların Ötesinde!"
  },
  Voice_5862_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5863_AwakerVoiceContent = {
    Text = "Ne kadar da budalaca."
  },
  Voice_5863_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5864_AwakerVoiceContent = {Text = "Haha!"},
  Voice_5864_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5865_AwakerVoiceContent = {
    Text = "Hıh, hiç de fena değil. Bir sonraki düellomuz efsanevi olacak."
  },
  Voice_5865_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5866_AwakerVoiceContent = {Text = "Küstah!"},
  Voice_5866_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5867_AwakerVoiceContent = {
    Text = "Bazen sanatın güzelliği, onun yok oluşunda yatar. Ama senin başarısızlığın... açıkça o kategoriye girmiyor."
  },
  Voice_5867_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5868_AwakerVoiceContent = {
    Text = "Sen benim en önemli dinleyicimsin. Ne zaman ihtiyaç duyarsan, şarkı söylemeye ve sana her şeyimi vermeye hazırım."
  },
  Voice_5868_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5869_AwakerVoiceContent = {
    Text = "En sevdiğim şeyler mi? Deniz yosunu, balık sürüleri, sütun dizileri, labirentler... Elbette gördüm onları! Hepsi Ornn Amca’nın kitabında!"
  },
  Voice_5869_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5870_AwakerVoiceContent = {
    Text = "Bu bir soruşturma görevi için hazırlık mı? Anladım."
  },
  Voice_5870_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5870_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5871_AwakerVoiceContent = {
    Text = "Benim adım Celeste. Bana ihtiyaç duyduğun sürece, daima burada olacağım."
  },
  Voice_5871_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5872_AwakerVoiceContent = {
    Text = "Dersini al!"
  },
  Voice_5872_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5873_AwakerVoiceContent = {
    Text = "Biraz saygı göster, çaylak. Orduda kıdem mutlakttır ve emirlere istisnasız uyulur. Bu tür uygunsuz davranışlar cezalandırılır."
  },
  Voice_5873_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5874_AwakerVoiceContent = {
    Text = "Yaptığım o \"küçük zımbırtılar\" için tamir hizmeti sunabilirim, ama asıl soru şu... Satış sonrası hizmetimi kabul etmeye cesaretin var mı?"
  },
  Voice_5874_AwakerVoiceTitle = {
    Text = "Sohbet: Onun Buluşları Hakkında"
  },
  Voice_5875_AwakerVoiceContent = {
    Text = "Burada efendi sensin, ama aynı zamanda salonumda bir konuksun. Ziyaretin için en ince misafirperverliği hazırlayacağım—al kanatlı bir iç etek mi, yoksa beyaz gül renginde bir gecelik mi tercih edersin?"
  },
  Voice_5875_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5876_AwakerVoiceContent = {
    Text = "Üzgünüm, buradaki güneş ışığı biraz göz alıcı... Benim gibi yeraltı faresi için alışmak hâlâ zaman alıyor."
  },
  Voice_5876_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5877_AwakerVoiceContent = {
    Text = "Her şeyi aşındırıp her şeyi silip süpürebilen, her şeyi yok eden... Epey silah sayılırdı. Keşke o zamanlar bilseydim... Heh."
  },
  Voice_5877_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5878_AwakerVoiceContent = {
    Text = "Söylentiye göre, alevlerin içinde seğiren bedenler, sanki Dans ediyormuş gibi görünürmüş..."
  },
  Voice_5878_AwakerVoiceTitle = {
    Text = "Sohbet: Alevler Hakkında"
  },
  Voice_5880_AwakerVoiceContent = {
    Text = "Gece dışarı çıkma! 2000 lümenlik bir ışıkla bile tamamen güvende değilsin... Bir kez karanlığa adım attığında, görüş alanının ötesinde pusuda bekleyen kötülük seni kovalayacak, yutacak, kovalayacak, yutacak... ta ki hiçbir şey kalmayana dek!"
  },
  Voice_5880_AwakerVoiceTitle = {
    Text = "Sohbet: Gece Hakkında"
  },
  Voice_5881_AwakerVoiceContent = {
    Text = "Çığlık at."
  },
  Voice_5881_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5882_AwakerVoiceContent = {
    Text = "Ödemenizi aldım."
  },
  Voice_5882_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5883_AwakerVoiceContent = {
    Text = "Kuğuyu uzak gökyüzüne Dönüş için çırpınmaya iten, yaşama duyduğu o özlemdir."
  },
  Voice_5883_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5883_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5884_AwakerVoiceContent = {
    Text = "Sihir zamanı!"
  },
  Voice_5884_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5885_AwakerVoiceContent = {
    Text = "Yardım edin!"
  },
  Voice_5885_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5886_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_5886_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_5887_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_5887_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5888_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5888_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5889_AwakerVoiceContent = {
    Text = "Ah, Brown! Ben... biraz geri çekilsem iyi olacak galiba... Onunla arkadaş olmak istemiştim ama onun kabusu olmayı başardım... Zaten muhtemelen beni görmek istemiyordur..."
  },
  Voice_5889_AwakerVoiceTitle = {
    Text = "Sohbet: Jenkin Hakkında"
  },
  Voice_5889_UnlockDesc = {
    Text = "\"Jenkin\" Uyandıranı edinince açılır"
  },
  Voice_5890_AwakerVoiceContent = {
    Text = "Bir şapel mi? Teşekkür ederim, ama o kadar da eski kafalı değilim. Yeter ki Şefkat Tanrısı’nın öğretilerini kalbimde taşıyıp O’nun iradesine uyayım; ruhum asla O’nun ihtişamından sapmayacaktır."
  },
  Voice_5890_AwakerVoiceTitle = {
    Text = "Sohbet: Şapel Hakkında"
  },
  Voice_5891_AwakerVoiceContent = {
    Text = "Benim adım Ogier. Aramızdaki Sözleşme uyarınca, seni korumak ve düşmanlarını ezip geçmek için şövalyece Sadakatimi sana adıyorum. Bu ağır yemini ediyorum ve Asla Unutma."
  },
  Voice_5891_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5892_AwakerVoiceContent = {
    Text = "O cılız, çift göz bebeğine sahip kadın, tıpkı bir Spartalı haşere gibi kokuyor."
  },
  Voice_5892_AwakerVoiceTitle = {
    Text = "Sohbet: Agrippa Hakkında"
  },
  Voice_5892_UnlockDesc = {
    Text = "\"Agrippa\" Uyandıranı edinince açılır"
  },
  Voice_5893_AwakerVoiceContent = {
    Text = "Sevdiklerim mi? Tabii ki iyi şans. Dışarı çıkmadan önce mutlaka iyi bir alamet ararım."
  },
  Voice_5893_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5894_AwakerVoiceContent = {
    Text = "L-Lütfen, Miss Hannah’ya burada saklandığımı söylemeyin. Henüz hazır değilim..."
  },
  Voice_5894_AwakerVoiceTitle = {
    Text = "Sohbet: Hanna Hakkında"
  },
  Voice_5895_AwakerVoiceContent = {
    Text = "Buna ne dersin?"
  },
  Voice_5895_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5896_AwakerVoiceContent = {
    Text = "Sen benim kıymetli konuğumsun. Unutma, veresiye yazdırmana izin verilen tek kişi sensin. Ne de olsa, böylesine kusursuz bir kafatasını en son görmemin üzerinden yıllar geçti..."
  },
  Voice_5896_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5897_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5897_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5898_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_5898_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5899_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5899_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5900_AwakerVoiceContent = {
    Text = "Tercihler mi? Bir kral kendini şımartmamalı... yine de, o sıkıcı ayinlerden kaçınabilirsem, yumuşak bir divan yeterli olabilir."
  },
  Voice_5900_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5901_AwakerVoiceContent = {
    Text = "Senin küstahlığını... Bu Varlık, ebedî dinlenme için yakarış olarak yorumlayacak."
  },
  Voice_5901_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5902_AwakerVoiceContent = {
    Text = "Nefret mi? Ben, kaçınılmaz bir Kaderi ve önüne geçilemeyen bir trajediyi nefretle anıyorum."
  },
  Voice_5902_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5903_AwakerVoiceContent = {Text = "Hıh!"},
  Voice_5903_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5904_AwakerVoiceContent = {
    Text = "(Bastırılmış, acı dolu bir inleme)"
  },
  Voice_5904_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5905_AwakerVoiceContent = {
    Text = "Daha fazla yaklaşma!"
  },
  Voice_5905_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5906_AwakerVoiceContent = {
    Text = "Ah, sırrımı mı merak ediyorsun? Bu isim, bu beden, bu yüz, bu Ses—hepsi, bir zamanlar kafataslarımdan birine sahip olan San Pedro’lu bir Kadın’dan geldi. Benimle bir anlaşma yaptı... Ölümünden sonra ben onun yerine geçtim. Nerede olduğuna gelince... işte o, en zarif koleksiyonumdur."
  },
  Voice_5906_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5906_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5907_AwakerVoiceContent = {
    Text = "Sen ne hoş bir konuksun; senin o eşsiz kafatasına ben bile kapıldım... Bir gün ondan ayrılmayı düşünürsen, mutlaka küçük dükkânıma uğra. Haha... sadece bir şaka."
  },
  Voice_5907_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5907_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5908_AwakerVoiceContent = {
    Text = "Gerçek kimliğimi mi merak ediyorsun? Bunun için hâlâ çok erken. Şuna inan yeter: Kaybolmuş her Çocuk, yolunu benim dükkânımda bulabilir. Belki buna sen de dahilsin?"
  },
  Voice_5908_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5908_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5909_AwakerVoiceContent = {
    Text = "Kimse zarar görmeyecek."
  },
  Voice_5909_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5910_AwakerVoiceContent = {
    Text = "Henüz bitmedi!"
  },
  Voice_5910_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5911_AwakerVoiceContent = {
    Text = "Ne kadar çok çalıştığını görünce, ödülümü çok erken topladığım için neredeyse suçluluk duyuyorum. Bu yüzden başının şimdilik yerinde kalmasına izin vereceğim. Ama unutma, o çoktan benim kişisel mülküm olarak ayrıldı, tamam mı?"
  },
  Voice_5911_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5911_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5912_AwakerVoiceContent = {
    Text = "Her zaman böyle değildim; bana yeni bir hayat veren oydu. Bu bakımdan, sen de bana ikinci bir hayat verdin, bu yüzden senin başını da bir Gizli Hazine gibi saklayacağım."
  },
  Voice_5912_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5912_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5913_AwakerVoiceContent = {
    Text = "Karanlıktan kaçmalıyım!"
  },
  Voice_5913_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5914_AwakerVoiceContent = {
    Text = "Demek macera bu kadar tehlikeli..."
  },
  Voice_5914_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_5915_AwakerVoiceContent = {
    Text = "O aptal kız beni görür görmez neden tüymeye başlıyor? Bir dahaki sefere ipliğinin üstüne basacağım da bakalım nereye kaçıyor."
  },
  Voice_5915_AwakerVoiceTitle = {
    Text = "Sohbet: Aigis Hakkında"
  },
  Voice_5915_UnlockDesc = {
    Text = "\"Aigis\" Uyandıranı edinince açılır"
  },
  Voice_5916_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_5916_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5917_AwakerVoiceContent = {
    Text = "Heh... AHAHAHA!"
  },
  Voice_5917_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5918_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_5918_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5919_AwakerVoiceContent = {
    Text = "O velet çok zeki; sokakta böyle bir kıvrak zekâya ihtiyacın olur. Hâlâ dışarıda soruşturma peşinde olsaydım, kesin onunla ortaklık kurardım."
  },
  Voice_5919_AwakerVoiceTitle = {
    Text = "Sohbet: Jenkin Hakkında"
  },
  Voice_5919_UnlockDesc = {
    Text = "\"Jenkin\" Uyandıranı edinince açılır"
  },
  Voice_5920_AwakerVoiceContent = {
    Text = "O Piskopos, Herkes’i kurtaramaz. Belki bataklıktan bir talihsiz ruhu çekip alabilir, ama gerisi? ...İnancının paramparça olmasını izlemek için sabırsızlanıyorum."
  },
  Voice_5920_AwakerVoiceTitle = {
    Text = "Sohbet: Salvador Hakkında"
  },
  Voice_5920_UnlockDesc = {
    Text = "Uyanışçı \"Salvador\" elde edildikten sonra açılır"
  },
  Voice_5921_AwakerVoiceContent = {
    Text = "Londinium'un lağımlarında her şeyi bulabilirsin: somon, sabun, yarısı içilmiş viski... Bunu nereden biliyorum mu diye soruyorsun? Bir keresinde kardeşimin cesedini orada sekiz kilometre boyunca sürükledim..."
  },
  Voice_5921_AwakerVoiceTitle = {
    Text = "Sohbet: Lağım Hakkında"
  },
  Voice_5922_AwakerVoiceContent = {
    Text = "Önümde diz çök!"
  },
  Voice_5922_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5923_AwakerVoiceContent = {
    Text = "Önümde diz çök."
  },
  Voice_5923_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5924_AwakerVoiceContent = {
    Text = "Cephe hattının ötesindeki gerçek dünyaya göz attıktan sonra, bir zamanlar \"kahramanların\" değerini sorguladım. Ama neyse ki seninle tanıştım—dürüst, cesur ve saf. Senin komutanlığında, barış ve istikrar için yorulmadan savaşacağım. Bu kez, kendi Kurtuluş’umu sağlayacağım."
  },
  Voice_5924_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5924_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5925_AwakerVoiceContent = {
    Text = "Vay! Aman..."
  },
  Voice_5925_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5926_AwakerVoiceContent = {
    Text = "Kirli, pis, kaotik—işte bizim gücümüz bu."
  },
  Voice_5926_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5927_AwakerVoiceContent = {
    Text = "Sahte tavırından tiksiniyorum. Beni deli mi sanıyorsun? Acınası mı? Asıl İkarus sensin burada, \"Kurtarıcı\". Sen ve o küçük sürün, peşine düştüğünüz o görkemli güneşe bakmaktan gözleriniz bembeyaz kavrulmuş."
  },
  Voice_5927_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5928_AwakerVoiceContent = {
    Text = "Bırak, yolu ben açayım!"
  },
  Voice_5928_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_5929_AwakerVoiceContent = {
    Text = "Yabansı hissediliyorlar. Bu gezegene ait olmadıklarına bahse girerim."
  },
  Voice_5929_AwakerVoiceTitle = {
    Text = "Sohbet: Dünya Dışı Varlıklar Hakkında"
  },
  Voice_5929_UnlockDesc = {
    Text = "Uyanışçılardan \"Winkle\", \"Tinktur\", \"Faint\" ya da \"Wanda\"dan herhangi birini edindikten sonra açılır."
  },
  Voice_5931_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_5931_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_5932_AwakerVoiceContent = {Text = "Kaybol!"},
  Voice_5932_AwakerVoiceTitle = {
    Text = "Özel Beceri: I"
  },
  Voice_5933_AwakerVoiceContent = {
    Text = "Lütfen yapma..."
  },
  Voice_5933_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5934_AwakerVoiceContent = {
    Text = "Canavar olmak sorun değil. Hayatım boyunca tek istediğim şey intikam için güçtü."
  },
  Voice_5934_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5934_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5935_AwakerVoiceContent = {
    Text = "Rakibini ortadan kaldırmanın dışında başka arzuların da var mı? Karşılığında, dileğini yerine getireceğim... elbette kendi yeteneğim elverdiğince."
  },
  Voice_5935_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_5935_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_5936_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_5936_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_5937_AwakerVoiceContent = {
    Text = "Bir yoldaş mı? ... Düşüneceğim. Kararımı vermeden önce sakın ölme."
  },
  Voice_5937_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_5937_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_5938_AwakerVoiceContent = {
    Text = "İlk net kayda geçtiğinden bu yana, Çözünme bir milyondan fazla hayatı etkiledi. Yaptıklarımız, tüm insan nüfusunun hayatta kalması için kritik önemde."
  },
  Voice_5938_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5939_AwakerVoiceContent = {Text = "Tam gaz!"},
  Voice_5939_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5940_AwakerVoiceContent = {
    Text = "Okyanusun gazabından sakın."
  },
  Voice_5940_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5941_AwakerVoiceContent = {
    Text = "Okyanusun gazabından sakın."
  },
  Voice_5941_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5942_AwakerVoiceContent = {Text = "Hey!"},
  Voice_5942_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5943_AwakerVoiceContent = {
    Text = "Ben O’nun Kızı’yım, aynı zamanda O’nun Annesi’yim. Sana gelince, O’nun huzurunda sen yalnızca önemsiz bir böceksin."
  },
  Voice_5943_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5944_AwakerVoiceContent = {
    Text = "Her şey yolunda gitti. Zafer yelkenlerini kaldırabilirsiniz."
  },
  Voice_5944_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_5945_AwakerVoiceContent = {
    Text = "Uzak dur. Benim oyuncağım mı olmak istiyorsun? Yoksa İlahi Doğuş için bir kurban mı?"
  },
  Voice_5945_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5945_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_59463_AwakerVoiceContent = {
    Text = "Kolay bir zafer olsun! Bu, mutlak zaferimiz!"
  },
  Voice_59463_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_59464_AwakerVoiceContent = {
    Text = "Kolay bir zafer olsun! Bu, mutlak zaferimiz!"
  },
  Voice_59464_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_5946_AwakerVoiceContent = {
    Text = "Sana tanıklık etme onurunu bahşediyorum. Ölümlü etiğini hiçe sayan o görkemli ana şahit olacaksın."
  },
  Voice_5946_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5946_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5947_AwakerVoiceContent = {
    Text = "Bir oyuk mu? Telekinezi sırasında sık sık buna benzer şeyler yaratırım. Benim açtıklarım başka bir Boyut’a bağlanır; Çözünme’ninkiler de aynı şeyi yapar mı dersin?"
  },
  Voice_5947_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_5948_AwakerVoiceContent = {
    Text = "Koruyucu, İlahi Ana’nın otoritesiyle, Taht’ın yanındaki yerini güvence altına alıyorum. Yıkımdan sonra yeniden doğan çağa tanıklık edeceksin—bu, İlahi Ana’nın vaadidir. Şimdi sevin! Minnetle sevin!"
  },
  Voice_5948_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5948_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5949_AwakerVoiceContent = {
    Text = "Bu kadar saygılı olduğuna göre, sana bir cevap vereceğim. Başta, gerçekten isteksizdim. Ama artık anladım: Bu savurgan hayatı yalnızca O’nun sayesinde yaşıyorum. Ölüm asla son değildir. O beni sırasıyla topraktan yeniden doğuracak ve biz bu hastalıklı döngüyle ebedi hayata kavuşacağız..."
  },
  Voice_5949_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5949_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5950_AwakerVoiceContent = {
    Text = "O kadının dileği gülünç. Yok Oluş’tan hiçbir şey sağ çıkamaz, onun \"tanrısı\" bile."
  },
  Voice_5950_AwakerVoiceTitle = {
    Text = "Sohbet: Thais Hakkında"
  },
  Voice_5950_UnlockDesc = {
    Text = "\"Thais\" Uyandıranı edinince açılır"
  },
  Voice_5951_AwakerVoiceContent = {
    Text = "Her şeye kadir değilim. Ben bile yanılırım. O kadının yıkıma götüren eylemi, benim yanlış hesabımdı... Bu yüzden yardımına ihtiyacım var. Çağrımı işitebilesin diye, odama, buraya bir yatak koyabilirsin."
  },
  Voice_5951_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5951_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5952_AwakerVoiceContent = {
    Text = "Felaketin yükünü omuzlamak... yaşına göre ağır bir yük olmalı. Söyle—eğer en başından yazgının değişmez olduğunu bilseydin... yine de böyle amansızca savaşır mıydın? Cevabını sakla. Ben dinlenirken düşün. Senin yanıtın... ilgimi çekiyor."
  },
  Voice_5952_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5952_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5953_AwakerVoiceContent = {
    Text = "Beni uyandıralı bir süre oldu. Hiç sorun yok mu? İlahi sırlar? Mutlak kehanet? Hatta batmış kıtanın hazineleri bile... Hiçbir şey merakını uyandırmıyor mu? Hmph... Sen gerçekten tuhafsın."
  },
  Voice_5953_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5953_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5954_AwakerVoiceContent = {
    Text = "Hiçbir zaman tapınma talep etmedim. Ölümlülerin harareti beni daha da tüketiyor... Geri çekil. Şimdi uyuyacağım."
  },
  Voice_5954_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5954_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5955_AwakerVoiceContent = {
    Text = "Sende kullarımın hiçbir özelliğini görmüyorum... Belki de böylesi daha hayırlıdır. Sırf o kadını anmak bile beni yoruyor."
  },
  Voice_5955_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5955_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5956_AwakerVoiceContent = {
    Text = "Tanrı, tüm Çocuklarını eşit görür."
  },
  Voice_5956_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5957_AwakerVoiceContent = {
    Text = "Biliyorum, sen özel bir seyircisin. Seni öylece başka bir Boyut’a ışınlayamam; büyük sorun çıkar. Hey, sen hiç başkasına bunu yaptın mı? Sormamalısın, bu benim Sırrım!"
  },
  Voice_5957_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_5958_AwakerVoiceContent = {
    Text = "Aa, yeni görünüşümle ilgileniyorsun ha? Demek ki her şeyin bir bedeli var. Herhalde bu da şanslı kırılmalarımdan biri—bu, Ryker’ın şansı!"
  },
  Voice_5958_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_5959_AwakerVoiceContent = {
    Text = "Mythag benim için en çok Anı barındıran yer... aynı zamanda en sıcak yuvam."
  },
  Voice_5959_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_5960_AwakerVoiceContent = {
    Text = "Bana bırak."
  },
  Voice_5960_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5961_AwakerVoiceContent = {
    Text = "Ne kadar da saf!"
  },
  Voice_5961_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5962_AwakerVoiceContent = {
    Text = "Uçurum İlahileri!"
  },
  Voice_5962_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5963_AwakerVoiceContent = {
    Text = "Bana bahşedileni seyredin—"
  },
  Voice_5963_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5964_AwakerVoiceContent = {
    Text = "Eğer hâlâ beni \"\"Ramona\"\" olarak görebiliyorsan... lütfen o ismi kullanmaya devam et."
  },
  Voice_5964_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5965_AwakerVoiceContent = {
    Text = "Ne? Öfkemi de mi sömürmek istiyorsun?"
  },
  Voice_5965_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_5965_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_5966_AwakerVoiceContent = {
    Text = "Gerçek... tam burada açığa çıkıyor."
  },
  Voice_5966_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5967_AwakerVoiceContent = {
    Text = "Ne kaparsan, o anda mideye indirirsin. Sokağın kanunu budur."
  },
  Voice_5967_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_5968_AwakerVoiceContent = {
    Text = "Şimdi biraz doymuş hissediyorum."
  },
  Voice_5968_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_5969_AwakerVoiceContent = {
    Text = "Hımm... Kaşındım. Brown, gel de sırtımı kaşı."
  },
  Voice_5969_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_5970_AwakerVoiceContent = {
    Text = "Yeni mekanik parçalar, sistemimin çalışmasına büyük ölçüde yardımcı olacak—bu bir şeyi sevmek sayılmaz mı? Özür dilerim, sanırım sorunuzu anlamıyorum. Tercihlerin mekanik kuklalar için hiçbir anlamı yoktur."
  },
  Voice_5970_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_5971_AwakerVoiceContent = {Text = "Şuna bak."},
  Voice_5971_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5972_AwakerVoiceContent = {Text = "Şuna bak!"},
  Voice_5972_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5974_AwakerVoiceContent = {
    Text = "İyice düşün."
  },
  Voice_5974_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_5975_AwakerVoiceContent = {
    Text = "Sakin kal ve düşün."
  },
  Voice_5975_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_5976_AwakerVoiceContent = {
    Text = "Bayan Winkle da benim gibi bu Gezegen’den değil... Beni Yurt’uma bağlayan Tinktur’dan başka hiçbir şey yok. Acaba Bayan Winkle, Beyaz Kuş Diyarı hakkında ne hissediyor?"
  },
  Voice_5976_AwakerVoiceTitle = {
    Text = "Sohbet: Winkle Hakkında"
  },
  Voice_5976_UnlockDesc = {
    Text = "\"Winkle\" Uyandıranı edinince açılır"
  },
  Voice_5977_AwakerVoiceContent = {
    Text = "Arkamdan yaklaşma, yoksa kırılan kendi boynun olur."
  },
  Voice_5977_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_5977_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_5978_AwakerVoiceContent = {
    Text = "Ha? Nasıl olur da başıboş kedilerin kampüste dolaşmasına izin verirsin?! Ya o vahşi yaratık birini tırmalarsa?!"
  },
  Voice_5978_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5979_AwakerVoiceContent = {
    Text = "Gözlerim seni rahatsız mı ediyor? İyi. Beni o cehennemde hayatta tutan vahşilik tam da buydu."
  },
  Voice_5979_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_5979_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_5980_AwakerVoiceContent = {
    Text = "O yüksek perdeden lafları bana esirge. Benden ne istiyorsun? Aklımı yerinde tutmanızın bir sebebi olmalı."
  },
  Voice_5980_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_5980_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_5981_AwakerVoiceContent = {
    Text = "İntikamım her zaman Spartalılara yönelmişti, ama artık o şehir devleti bile yok... Pekâlâ. Senin bıçağın olmak imkânsız değil. Seni isteksizce ortağım olarak kabul ediyorum, ama bana ihanet etmeye kalkarsan kalbini söküp alırım."
  },
  Voice_5981_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_5981_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_5982_AwakerVoiceContent = {
    Text = "Ellerim kana bulanmış. Zayıf soydaşlarım intikamımı anlamıyor; acımasızlığım, nankörlüğüm ve ihanetim hakkında fısıldaşıyorlar... İntikam her zaman sadece kendim için olmuştur, başkası için değil."
  },
  Voice_5982_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_5982_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_5983_AwakerVoiceContent = {
    Text = "Daha fazla çelik kullanma zamanı."
  },
  Voice_5983_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5984_AwakerVoiceContent = {
    Text = "Daha fazla çelik kullanma zamanı."
  },
  Voice_5984_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5985_AwakerVoiceContent = {Text = "Geber."},
  Voice_5985_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5986_AwakerVoiceContent = {
    Text = "Ben... bana Winkle de. Herkes bana böyle seslenir. Evet, sen de öyle çağır, tıpkı onların yaptığı gibi..."
  },
  Voice_5986_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5987_AwakerVoiceContent = {
    Text = "Bu beden efendimin Karakter Kalkanı olacak!"
  },
  Voice_5987_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5988_AwakerVoiceContent = {
    Text = "Bu beden efendimin Karakter Kalkanı olacak!"
  },
  Voice_5988_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_5989_AwakerVoiceContent = {
    Text = "\"Fındıkkıran\" Kız Çocuk lar için romantik bir peri masalı olmalıydı, ama o iğrenç yaratıklar yalnızca hareket hâlindeki zarif uzuvları ve bayağı Arzu larını gördüler... Tiksindirici."
  },
  Voice_5989_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_5990_AwakerVoiceContent = {
    Text = "Onu... ortadan kaldırmalıyım!"
  },
  Voice_5990_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_5991_AwakerVoiceContent = {
    Text = "Pandia... O varlığa hâkim dişi mi diyor? Haha... İzin ver, biraz eğleneyim. İnsanlar hâlâ fazla yufka yürekli; yaptıkları her şey çocuk oyuncağı gibi duruyor."
  },
  Voice_5991_AwakerVoiceTitle = {
    Text = "Sohbet: Pandia Hakkında"
  },
  Voice_5991_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Pandia\" elde edildikten sonra açılır"
  },
  Voice_5992_AwakerVoiceContent = {
    Text = "Daha fazla yaklaşma!"
  },
  Voice_5992_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5993_AwakerVoiceContent = {
    Text = "Ne? Yine tanışma mı? Peki. Ben Jenkin, bu da Brown. \"Cıyak!\"\nSakın unutma! İsimlerimizi karıştırırsan, fenerimle *Bip* kafana geçiririm!\n\"Cıyak cıyak?!\""
  },
  Voice_5993_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_5994_AwakerVoiceContent = {
    Text = "Hadi dans edelim! Hadi dans edelim!"
  },
  Voice_5994_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_5995_AwakerVoiceContent = {
    Text = "Hadi dans edelim! Hadi dans edelim!"
  },
  Voice_5995_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_5996_AwakerVoiceContent = {
    Text = "İlk Ziyaret geliyor!"
  },
  Voice_5996_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_5997_AwakerVoiceContent = {Text = "Hıh."},
  Voice_5997_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_5998_AwakerVoiceContent = {
    Text = "Bana yalnızca biraz taş, iki keski ve güneşe bakan üç iris çiçeği gerek... senin için her şeyi yaratabilirim."
  },
  Voice_5998_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_5998_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_5999_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_5999_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6000_AwakerVoiceContent = {
    Text = "Hepsi bu mu?"
  },
  Voice_6000_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6001_AwakerVoiceContent = {Text = "Elbette."},
  Voice_6001_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_6002_AwakerVoiceContent = {
    Text = "Bu anlamsız çırpınış..."
  },
  Voice_6002_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6003_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_6003_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6004_AwakerVoiceContent = {
    Text = "After Tiberius's death, the Romans finally had their long-time wish granted: they got to dump him into the Tiber to feed the fish. The price was small: Caligula threw those people to me in the arena for my amusement.\nTiberius öldükten sonra, Romalıların uzun zamandır taşıdığı dilek sonunda gerçekleşti: Onu balıklara yem olsun diye Tiber’e atabildiler. Bedel ise küçüktü: Caligula o insanları arenada eğlencem için bana attı."
  },
  Voice_6004_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6005_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_6005_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6006_AwakerVoiceContent = {
    Text = "O küçük kızın benimkine benzer güçlere sahip olduğunu hissedebiliyorum. Güçlerinin sınırını henüz tam kavrayamamış. Senin hatırın için onu uygun şekilde eğiteceğim."
  },
  Voice_6006_AwakerVoiceTitle = {
    Text = "Sohbet: Lily Hakkında"
  },
  Voice_6006_UnlockDesc = {
    Text = "\"Lily\" Uyandıranı edinince açılır"
  },
  Voice_6007_AwakerVoiceContent = {
    Text = "Lanet olsun! Sen—sen hâlâ bana tepeden bakıyorsun, değil mi?!"
  },
  Voice_6007_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6008_AwakerVoiceContent = {
    Text = "Bu, varoluşumun kanıtı."
  },
  Voice_6008_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_6009_AwakerVoiceContent = {
    Text = "Bu, varoluşumun kanıtı."
  },
  Voice_6009_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6010_AwakerVoiceContent = {
    Text = "Her şeyin bir sebep için olduğuna inanırım, ama... anlamsız şiddet, kardeşleri birbirine kırdıran önyargılar... bunlar beni gerçekten kederlendiriyor. Nefret ettiğim bir şey varsa, işte budur."
  },
  Voice_6010_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_6011_AwakerVoiceContent = {
    Text = "Keşke bu gücü kullanmak zorunda kalmasaydım."
  },
  Voice_6011_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6012_AwakerVoiceContent = {
    Text = "Muhafızını indirme."
  },
  Voice_6012_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_6013_AwakerVoiceContent = {Text = "Hımpf"},
  Voice_6013_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_6014_AwakerVoiceContent = {Text = "Dur!"},
  Voice_6014_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6015_AwakerVoiceContent = {Text = "Dur!"},
  Voice_6015_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_6016_AwakerVoiceContent = {
    Text = "Casiah inanılmaz! Göz açıp kapayıncaya kadar bir tavşan ortaya çıkarabiliyor!"
  },
  Voice_6016_AwakerVoiceTitle = {
    Text = "Sohbet: Casiah Hakkında"
  },
  Voice_6016_UnlockDesc = {
    Text = "\"Casiah\" Uyandıranı edinince açılır"
  },
  Voice_6017_AwakerVoiceContent = {
    Text = "Sihirim hazır!"
  },
  Voice_6017_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6018_AwakerVoiceContent = {
    Text = "Çözünme... İtiraf etmeliyim ki, bu dünyada gücün kontrolünün ötesinde şeyler de var."
  },
  Voice_6018_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_6019_AwakerVoiceContent = {Text = "Ah—"},
  Voice_6019_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6020_AwakerVoiceContent = {
    Text = "Zümrüt alevlerin ortasında dans et."
  },
  Voice_6020_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6021_AwakerVoiceContent = {
    Text = "Tasa etme; yaralar bir savaşçının onur nişanıdır!"
  },
  Voice_6021_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6022_AwakerVoiceContent = {
    Text = "Bu kasların önünde titreyin... Başınızı koparmaya her zaman hazırlar."
  },
  Voice_6022_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_6024_AwakerVoiceContent = {
    Text = "Yemek vakti mi? Yoksa etkinlik vakti mi?"
  },
  Voice_6024_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_6024_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_6025_AwakerVoiceContent = {
    Text = "Haha! Artık Aurita’nın Dostları bir daha kaybolmayacak!"
  },
  Voice_6025_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_6025_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_6026_AwakerVoiceContent = {
    Text = "Sylvia Hanım, bir şey aldığımda “teşekkür ederim” demem gerektiğini söyledi... Teşekkür ederim, teşekkür ederim, teşekkür ederim!!"
  },
  Voice_6026_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_6026_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_6027_AwakerVoiceContent = {
    Text = "Bu sefer hayalet olma sırası bende! Saklanmak için sadece 5 saniyen var! 5, 4—"
  },
  Voice_6027_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_6027_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_6028_AwakerVoiceContent = {
    Text = "Saklanmanın ardından herkes kayboldu. Bu sefer, Herkes’i bulmaya kararlıyım!"
  },
  Voice_6028_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_6028_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_6029_AwakerVoiceContent = {
    Text = "Kemiklerimi dalgaların altında bulmuşlar ve sudan hoşlandığımı mı sanıyorlar? Şimdi de odamın dışına bir havuz inşa etmek istiyorlarmış? ...Ha. İstediklerini yapsınlar. Yeter ki beni önemsiz şeylerle rahatsız etmeyi bıraksınlar."
  },
  Voice_6029_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_6030_AwakerVoiceContent = {
    Text = "Dalgalar içinde bir damla, ölümsüz Miryam’ın sığ bir takipçisi... seni selamlıyor."
  },
  Voice_6030_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6031_AwakerVoiceContent = {
    Text = "Harekete geçme sırası bende."
  },
  Voice_6031_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6032_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6032_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6033_AwakerVoiceContent = {
    Text = "Tamamen büyüleyici... Rastgele söylediğin bir söz, aylardır beni rahatsız eden yaratıcı bir sorunu çözdü."
  },
  Voice_6033_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_6033_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_6034_AwakerVoiceContent = {
    Text = "O partideki asil hanımlarla kıyaslandığında, Murphy’nin huysuzluğu oldukça sevimli kalıyor."
  },
  Voice_6034_AwakerVoiceTitle = {
    Text = "Sohbet: Murphy Hakkında"
  },
  Voice_6034_UnlockDesc = {
    Text = "Uyanışçı \"Murphy\" edinildiğinde açılır"
  },
  Voice_6035_AwakerVoiceContent = {
    Text = "Bana usta bir danışman mı diyorlar? O çocuklar fazla nazik. Ben yalnızca onları dinlemek ve içlerindeki sıkıntıyı salıvermelerine yardım etmek için elimden geleni yapıyorum—her zaman yapmaya çalıştığım gibi."
  },
  Voice_6035_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_6036_AwakerVoiceContent = {
    Text = "Beni asla küçümseme!"
  },
  Voice_6036_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6037_AwakerVoiceContent = {
    Text = "Beni asla küçümseme!"
  },
  Voice_6037_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_6038_AwakerVoiceContent = {
    Text = "Susadın mı? Temiz su, hapishanede nadir bulunan bir lükstür."
  },
  Voice_6038_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_6038_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_6039_AwakerVoiceContent = {
    Text = "Şimdi, kim uslu {Male=oğlan,Female=kız çocuk}? Uslu {Male=oğlan,Female=kız çocuk}lar yolun yarısında vazgeçme~"
  },
  Voice_6039_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_6039_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_6040_AwakerVoiceContent = {
    Text = "Bu noktada çoktan tatlı tuzağıma düşmüş olmalısın, değil mi?"
  },
  Voice_6040_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_6040_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_6041_AwakerVoiceContent = {
    Text = "Devam et, azıcık daha~ Neredeyse coşkunun zirvesindeyiz~"
  },
  Voice_6041_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_6041_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_6042_AwakerVoiceContent = {
    Text = "On dört yaşında Mythag’e katıldım. Sorunsuzca mezun olsaydım, şimdi bana Müdür diye hitap ediyor olurdun."
  },
  Voice_6042_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_6043_AwakerVoiceContent = {
    Text = "Bu cılız beynin, dersleri sakla(ya)mayacak kadar yetersiz görünüyor."
  },
  Voice_6043_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_6044_AwakerVoiceContent = {
    Text = "Dileğim mi? Güvenli ve huzurlu bir yolculuk sağlamak—bu yeterli değil mi? Başka bir dileğim hiç olmadı... ama dikkatle düşünüp sana sonra söyleyeceğim."
  },
  Voice_6044_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6044_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6045_AwakerVoiceContent = {
    Text = "\"Öğrenmek istediğim, göklerin ve yerin sırlarıydı. Beni hangi gücün kontrol ettiğini anlamak istiyordum.\" ...Her ne kadar bu romanın kurgusunu tatmin edici bulmasam ve sözde bilimi gülünç derecede safça olsa da, okuduktan sonra benim motivasyonlarımı kavramış olman gerekirdi... Bir dakika, bu kitabı okumadın mı?"
  },
  Voice_6045_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6045_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6046_AwakerVoiceContent = {
    Text = "Görev ve kader birbirine çok benzer. Ne kolayca bir kenara atılabilirler, ne de onları bir kenara atmaya gerek vardır."
  },
  Voice_6046_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_6046_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_6047_AwakerVoiceContent = {
    Text = "Sürekli meşgul mü görünüyorum? Evet. Asistanlar ara sıra işe yarayabilir, ama bazı araştırmalarda yerim doldurulamaz. Yardım etmek mi istiyorsun? O hâlde ara ara hâlâ hayatta olup olmadığımı kontrol et."
  },
  Voice_6047_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6047_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_6048_AwakerVoiceContent = {
    Text = "Kızgın mı görünüyorum? Bir gülümseme için kaç kasın devreye girdiğini idrak ediyor musun? Bunu derste bir kez açıklamıştım, belli ki o ders pürüzsüz beyninden kayıp gitmiş. Cevap en az on yedi, ve sana kızgın olmam için mantıklı hiçbir sebep yok."
  },
  Voice_6048_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6048_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6049_AwakerVoiceContent = {
    Text = "Bayan Ramona bir keresinde, herkesin hatırını gözetmek zorunda olmadığımı söylemişti. Bunu anlamıyorum... Bu, artık korumama ihtiyaç olmadığı anlamına mı geliyor?"
  },
  Voice_6049_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6049_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6050_AwakerVoiceContent = {
    Text = "Acil onay bekleyen on üç rapor, onarım sırasını bekleyen altı hasarlı İletişimci ve sonuçlarını izlemem gereken beş ayrı Gümüş çıkarım deneyi var... Bu yüzden, sınırlı vaktimi beni rahatsız ederek heba edeceğine, o cılız beyin dokunu çalıştırmayı denesen nasıl olur?"
  },
  Voice_6050_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_6050_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_6051_AwakerVoiceContent = {
    Text = "Bir dahaki sefere, umarım çağrıma Beyaz Kuş Diyarı karşılık verir."
  },
  Voice_6051_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_6052_AwakerVoiceContent = {
    Text = "Kilit açıldı."
  },
  Voice_6052_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6054_AwakerVoiceContent = {
    Text = "Öyle mutluyum ki... Bana bu kadar yanlı ve bu kadar lütufkâr davranıyorsun."
  },
  Voice_6054_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_6054_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_6055_AwakerVoiceContent = {
    Text = "Başkaları, onlara haksızlık ettiğini, kayırdığını düşünürse kızabilir."
  },
  Voice_6055_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_6055_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_6056_AwakerVoiceContent = {
    Text = "Sen de bana özlem duyuyor musun?"
  },
  Voice_6056_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_6056_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_6057_AwakerVoiceContent = {
    Text = "Sonunda bitti. Artık o siyah, sümüksü şeyleri görmek yok..."
  },
  Voice_6057_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_6058_AwakerVoiceContent = {
    Text = "Bana verdiğin her şeyle, sevgin artık benimkiyle bir oldu..."
  },
  Voice_6058_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_6058_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_6059_AwakerVoiceContent = {Text = "Hey!"},
  Voice_6059_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_6060_AwakerVoiceContent = {
    Text = "Oo, bu kıl payıydı."
  },
  Voice_6060_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_6061_AwakerVoiceContent = {
    Text = "Çok zor çalıştın; artık emeğinin meyvelerini tatma zamanı, öyle değil mi? Yaklaş biraz, seni hayal kırıklığına uğratmayacağım~"
  },
  Voice_6061_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_6061_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_6062_AwakerVoiceContent = {
    Text = "B-Ben... Niyetini anladım. Hâlâ beceriksiz olsam da, senin için sahip olduğum her şeyle savaşacağım!"
  },
  Voice_6062_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_6062_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_6063_AwakerVoiceContent = {
    Text = "Bakış'ın beni yakıyor... Sana herhangi bir sıkıntı verdim mi?"
  },
  Voice_6063_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_6063_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_6064_AwakerVoiceContent = {
    Text = "Çok endişeliyim... beklentilerini hiç karşılayamayacakmışım gibi hissediyorum..."
  },
  Voice_6064_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_6064_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_6065_AwakerVoiceContent = {
    Text = "Ç-çok huzursuz hissediyorum... böyle bakılınca... Lanet'imden korkmuyor musun?"
  },
  Voice_6065_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_6065_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_6066_AwakerVoiceContent = {
    Text = "L-lütfen Gözlerimin içine bakma... Sana zarar vermek istemiyorum... Sonuçta ben bir Canavarım..."
  },
  Voice_6066_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_6066_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_6067_AwakerVoiceContent = {
    Text = "Bu yaban hayvanının koku alma duyusu mu? O sadece şans, tamam mı? Yanlış anlamayın."
  },
  Voice_6067_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_6067_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_6068_AwakerVoiceContent = {
    Text = "Henüz duramam..."
  },
  Voice_6068_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6069_AwakerVoiceContent = {
    Text = "Sonsuz gücümü tadın!"
  },
  Voice_6069_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_6070_AwakerVoiceContent = {
    Text = "Sonsuz gücümü tadın!"
  },
  Voice_6070_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6071_AwakerVoiceContent = {
    Text = "Denizi sever misin? Ben denizi her şeye rağmen seviyorum. Talihsiz benliğime, yıllar önce o gün, denizin uzun zamandır beklenen ölümü usulca getirişini hâlâ hatırlıyorum."
  },
  Voice_6071_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6073_AwakerVoiceContent = {
    Text = "Az önce daha önce hiç tatmadığım bir haz duygusu hissettim… nedense…"
  },
  Voice_6073_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6074_AwakerVoiceContent = {
    Text = "Bu Akıntı düşmanlarımızı paramparça edecek."
  },
  Voice_6074_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6075_AwakerVoiceContent = {
    Text = "Bu Akıntı düşmanlarımızı paramparça edecek."
  },
  Voice_6075_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_6076_AwakerVoiceContent = {
    Text = "Bana gerçek sevgiyi, ızdırabı ve arzuyu öğretecek birini bekliyordum. Dileğimi yerine getirebilir misin? Beni bu karanlık hapisten kurtarabilir misin?"
  },
  Voice_6076_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6076_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6077_AwakerVoiceContent = {
    Text = "Gerçeği bilmek mi istiyorsun? Hapisten nefret ediyorum, karanlıktan nefret ediyorum, o kadar nefret ediyorum ki ölebilirim. Fark edilmek istiyorum. Alevlenmek istiyorum..."
  },
  Voice_6077_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6077_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6078_AwakerVoiceContent = {
    Text = "Bütün bunların hepsi, geleceğin ebedî esenliği için."
  },
  Voice_6078_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6079_AwakerVoiceContent = {
    Text = "Benden zevk almak mı istiyorsun? Öyleyse benim kölem ol. Seni sıcaktan eriteceğim~"
  },
  Voice_6079_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_6079_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_6080_AwakerVoiceContent = {
    Text = "Pekâlâ. Bunu bir deneğin mütevazı sunusu sayacağım."
  },
  Voice_6080_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6081_AwakerVoiceContent = {
    Text = "Çok sıkıldım! Şu titreyen koca tutsaklarla kıyaslayınca, bu sadece evcilik oynamak gibi. Neden bana eşlik etmiyorsun~"
  },
  Voice_6081_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6081_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6082_AwakerVoiceContent = {
    Text = "Daha fazla köle istiyorum, inlemelerini ve yalvarışlarını duymak istiyorum—Bana daha fazla köle getirin, lütfen lütfen?"
  },
  Voice_6082_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6082_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_6083_AwakerVoiceContent = {
    Text = "Affet, yine Anılar içinde kayboldum. Lütfen, hüzünlü görünme. Şimdi, kendi Hikâyeni anlatma sırası sende. Bir şiir yazmak ister misin? Maceraların, deneyimlerin, sevinçlerin, Ağıtların, zihninden parmak uçlarına doğru usulca akan bir dere gibi akacak mı?"
  },
  Voice_6083_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6083_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6084_AwakerVoiceContent = {
    Text = "Ben yalnızca parşömen üzerinde gelip geçen bir su izi gibiydim, ama karşılaşmamız beni burada oyaladı. Belki de bu bir mucizedir. Bu mucizeyi bir gizli hazine gibi saklayacağım ve senin için zamansız şiirler yazacağım."
  },
  Voice_6084_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6084_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6085_AwakerVoiceContent = {
    Text = "Bir zamanlar biri bana, şiirin takdir edilmek için yazıldığını söylemişti... Bu konudaki düşüncelerini duyabilir miyim?"
  },
  Voice_6085_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_6085_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_6086_AwakerVoiceContent = {
    Text = "Hiç böyle hissettin mi? Bir başkasının suçunu bağışlayıp Sunu sunduğunda, arzuladığın sonuç avuçlarının arasından kayıp gider. Bir gül uzatırsın, ama ellerinde kalan, kokusunun kalıcı hoşluğu değil, yalnızca keskin dikenlerin kanlı izleridir."
  },
  Voice_6086_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6086_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_6087_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6088_AwakerVoiceContent = {
    Text = "Kalemim ve mürekkebim..."
  },
  Voice_6088_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6089_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_6089_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6090_AwakerVoiceContent = {
    Text = "Bu yanlış bir kafiye..."
  },
  Voice_6090_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6091_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_6091_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_6092_AwakerVoiceContent = {
    Text = "Bu, Yüce Olan'dan gelen bir lütuf!"
  },
  Voice_6092_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6093_AwakerVoiceContent = {
    Text = "Büyük Soluk Olan’ın Lütfu..."
  },
  Voice_6093_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_6094_AwakerVoiceContent = {
    Text = "Dinlenmeye ayıracak vaktim yok. Çözünme şimdiden iki bedenimi aldı. Kaçınılmaz son beni yakalamadan önce anlamam gereken çok şey var... Bana yardım et, deney malzemelerinin hazırlanmasından başla. Dengeyi yanlış hesaplamayacağına güveniyorum."
  },
  Voice_6094_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6094_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6095_AwakerVoiceContent = {
    Text = "Fontainebleau’daki vitrayları severim. İnsanların yüzlerine farklı tonlar düşürürler: umutsuz mor, yağcı mavi ve elbette, favorim—hırslı kırmızı..."
  },
  Voice_6095_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6096_AwakerVoiceContent = {
    Text = "Burada sıklıkla Rabbimin varlığını hissediyorum, ama belki de henüz O'nunla yüzleşmeye hazır değilim... Her halükârda, bana sığınak sunduğun için teşekkür ederim."
  },
  Voice_6096_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_6097_AwakerVoiceContent = {
    Text = "İhanet, insanları hangi tarafta olurlarsa olsunlar canavara dönüştürür. Bu yüzden hainlerden tiksinirim."
  },
  Voice_6097_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_60985_AwakerVoiceContent = {
    Text = "Hameln, hizmetinizde."
  },
  Voice_60985_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_60986_AwakerVoiceContent = {
    Text = "Bir zamanlar, müziği neredeyse içgüdüsel olarak kavrayan biriyle tanışmıştım. Bu kişinin yarattığı konçertolar ve senfoniler unutulmazdı.\nGerçek bir dâhiydi."
  },
  Voice_60986_AwakerVoiceTitle = {
    Text = "Sohbet: Arkadaşı Hakkında"
  },
  Voice_60987_AwakerVoiceContent = {
    Text = "Strateji üzerinde vakit harcamaktan hoşlanmam. Müziğin yanında, Strateji sanatı pek az değer taşır. Yine de, engelleri temizleyen bir araç olarak gereklidir. Müziğin zirvesine ulaşmak uğruna onu kullanmaktan gocunmam."
  },
  Voice_60987_AwakerVoiceTitle = {
    Text = "Sohbet: Onun Stratejileri Hakkında"
  },
  Voice_60988_AwakerVoiceContent = {Text = "Kaba."},
  Voice_60988_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_60989_AwakerVoiceContent = {
    Text = "İşte yine duyuluyor. Bu nasıl bir ezgi? Onu son duyduğumdan beri zihnime mıhlanmış durumda, ne gitmeyi ne de dinlenmeyi kabul ediyor."
  },
  Voice_60989_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_60989_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_6098_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_6098_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_60990_AwakerVoiceContent = {
    Text = "Teknik açıdan bakıldığında, Stratejik Planlama ile orkestra şefliği arasında fark yoktur. İnsanlığın Işığı, duygu, arzu… hepsi gözlerimin önünde, bir portedeki notalar kadar berrak ve uysal, batonun izlediği Fitil Yolu boyunca dans ediyor. Müziği anlamak, her şeyi anlamaktır."
  },
  Voice_60990_AwakerVoiceTitle = {
    Text = "Sohbet: Ortak Noktalarınız Hakkında"
  },
  Voice_60991_AwakerVoiceContent = {
    Text = "Neredeyse bitti, az kaldı. Bitirmeliyim; onu duymalıyım!"
  },
  Voice_60991_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_60991_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_60992_AwakerVoiceContent = {Text = "Hımm."},
  Voice_60992_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_60993_AwakerVoiceContent = {Text = "Kaba."},
  Voice_60993_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_60994_AwakerVoiceContent = {Text = "Hımm."},
  Voice_60994_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_60995_AwakerVoiceContent = {
    Text = "Müzik, dili, yazıyı ve her şeyi aşar. Eğer bu mükemmellik değilse, başka ne olabilir bilmiyorum."
  },
  Voice_60995_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_60995_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_60996_AwakerVoiceContent = {
    Text = "Ritme dikkat edin."
  },
  Voice_60996_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_60997_AwakerVoiceContent = {
    Text = "Ayar tamamlandı."
  },
  Voice_60997_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_60998_AwakerVoiceContent = {
    Text = "Eğitimin önemini kavramış olmanıza sevindim."
  },
  Voice_60998_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_60999_AwakerVoiceContent = {
    Text = "Kusursuz bir performans sergileyeceğim."
  },
  Voice_60999_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6099_AwakerVoiceContent = {
    Text = "Kıskanıyor musun? Bu sert pullar, asil bir soyun kanıtı."
  },
  Voice_6099_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_61000_AwakerVoiceContent = {
    Text = "Bir zamanlar övülmüştüm, ama... bu gerçek Yetenek değildi.\nEserlerim, benden öncekilerin basit taklitleriydi."
  },
  Voice_61000_AwakerVoiceTitle = {
    Text = "Sohbet: Onun Eserleri Hakkında"
  },
  Voice_61001_AwakerVoiceContent = {
    Text = "Nefesliler ve yaylılar… Yukarı aşağı iç içe geçiyor, motif yeniden beliriyor… Şimdi hatırladım, bu benim erken ölmüş dâhi, o Düşen Yıldız için bestelediğim ağıt."
  },
  Voice_61001_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_61001_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_61002_AwakerVoiceContent = {
    Text = "Hmm? Bana göstereceğin yeni bir eser mi var?"
  },
  Voice_61002_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_61003_AwakerVoiceContent = {
    Text = "Bu ezgi, ölü ruhların anısına adanmıştır."
  },
  Voice_61003_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_61004_AwakerVoiceContent = {
    Text = "Yeşil dansçı, saray kumpanyasının başrolüne yaraşır bir zarafete sahipti.\nFırsat verilse, gerçekten Ortak Yaratım yapmayı umardım."
  },
  Voice_61004_AwakerVoiceTitle = {
    Text = "Sohbet: Liz Hakkında"
  },
  Voice_61004_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Liz\" elde edildikten sonra açılır"
  },
  Voice_61005_AwakerVoiceContent = {Text = "Arioso!"},
  Voice_61005_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_61006_AwakerVoiceContent = {
    Text = "Bir orkestrada bir başkemancı vardır, ama tek bir başkemancı tam bir orkestra etmeye yetmez. Benim orkestramda, yalnızca gösteriş peşinde koşanlara yer yok."
  },
  Voice_61006_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_61007_AwakerVoiceContent = {
    Text = "Sanırım bir ezgi duydum. Yakında biri prova mı yapıyor?"
  },
  Voice_61007_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_61007_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_61008_AwakerVoiceContent = {Text = "Dal Segno!"},
  Voice_61008_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_61009_AwakerVoiceContent = {Text = "Da Capo!"},
  Voice_61009_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_6100_AwakerVoiceContent = {
    Text = "Kendi sonunla yüzleşmeye hazırlan!"
  },
  Voice_6100_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_61010_AwakerVoiceContent = {
    Text = "Evet, evet, işte bu—son ayin, bizzat müziğin kendisi için yazılmış bir ağıt!"
  },
  Voice_61010_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_61010_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_61011_AwakerVoiceContent = {
    Text = "Ah, Koruyucu, tam zamanında geldin. Söyle bana, bu bölüm hakkında ne düşünüyorsun?"
  },
  Voice_61011_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_61012_AwakerVoiceContent = {
    Text = "Yaylılar, başlayın."
  },
  Voice_61012_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_61013_AwakerVoiceContent = {
    Text = "Yükselen Ezgi, yüksel!"
  },
  Voice_61013_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_61014_AwakerVoiceContent = {
    Text = "O dolanıp duran ezgi, bir ruhun ağlayışı gibi… Artık açıkça görüyorum. Eminim onu daha önce bir yerde duydum."
  },
  Voice_61014_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_61014_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_61015_AwakerVoiceContent = {
    Text = "Akıl ve düzen yolu döşedi. Yukarı doğru yürüdüm ve salonun kapılarını açtım. Ötesinde ikisi de yoktu—gerçekten ebedî müzik, aklı da aşar."
  },
  Voice_61015_AwakerVoiceTitle = {
    Text = "Sohbet: Akıl ve Düzen Hakkında"
  },
  Voice_61016_AwakerVoiceContent = {
    Text = "Ellerime bakın, bir, iki, üç."
  },
  Voice_61016_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_61017_AwakerVoiceContent = {
    Text = "Sözde orkestranın icrasını duydum; hatalarla doluydu. Ama endişe etme, Gümüş Ayaz Festivali’nden önce kusursuz bir gösteri sahnelemek için ayrıntılı bir planım var."
  },
  Voice_61017_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_61018_AwakerVoiceContent = {
    Text = "Bilinçimin derinliklerinde duyduğum o müziği ilk kez işittiğim anı asla unutamam. O notalar ve akorlar içinde gerçek dünya silinmişti; geriye yalnızca saf ve yüce bir müzik kalmıştı."
  },
  Voice_61018_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_61019_AwakerVoiceContent = {
    Text = "Yazık. Görünüşe göre daha fazla prova gerekiyor."
  },
  Voice_61019_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6101_AwakerVoiceContent = {
    Text = "Bu bir emir."
  },
  Voice_6101_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_61020_AwakerVoiceContent = {
    Text = "Genelde böyle davetlerde bulunmam ama… denemek ister misin? Batonu tutup müziğe yeni bir hayat üflemek?"
  },
  Voice_61020_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_61020_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_61021_AwakerVoiceContent = {
    Text = "Kendimi kelimelerden çok müzikle ifade etmeyi tercih ederim. Ama seninle iletişim kurmak, sayısız kez prova edilmiş bir orkestrayı yönetmek gibi—akıcı ve sık sık hoş sürprizlerle dolu.\nHem müzikte hem bende senin için özel bir yer var."
  },
  Voice_61021_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_61021_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_61022_AwakerVoiceContent = {
    Text = "Bir senfonide çalgılar arasındaki uyum hayati önem taşır; her bölümün sahneye giriş ve çıkışı, müziğe bambaşka bir deneyim kazandırır.\nDemek istediğim şu: Eğer Uyandıranları komuta etmek bir icraysa, sen bunu iyi yapıyorsun."
  },
  Voice_61022_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_61022_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_61023_AwakerVoiceContent = {
    Text = "Bu parçayı beğendin mi? Motifi yalnızca dört ölçüde bütünüyle sunuyor; nefesli çalgılar ezgiyi temaya ulaşana dek yukarı doğru itiyor. Böylesi bir tasarım sayısız ardılı etkilemiştir… Affedersin, çok mu konuşuyorum?"
  },
  Voice_61023_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_61023_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_61024_AwakerVoiceContent = {
    Text = "Kusursuz performans."
  },
  Voice_61024_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_61025_AwakerVoiceContent = {Text = "Forte!"},
  Voice_61025_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_61026_AwakerVoiceContent = {Text = "Aksan!"},
  Voice_61026_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_61027_AwakerVoiceContent = {
    Text = "Her birimiz kalbimizde bir ezgiyi saklarız; akıl ve beden tarafından tutsak edilen bu ezgi, ancak Delilik içinde bütünüyle dile gelir."
  },
  Voice_61027_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_61028_AwakerVoiceContent = {
    Text = "Yalnızca müzik övgüyü hak eder."
  },
  Voice_61028_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_61029_AwakerVoiceContent = {
    Text = "Yalnızca müzik övgüyü hak eder."
  },
  Voice_61029_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_6102_AwakerVoiceContent = {Text = "Git."},
  Voice_6102_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_61030_AwakerVoiceContent = {
    Text = "Dinle, bu son ağıt!"
  },
  Voice_61030_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_6103_AwakerVoiceContent = {
    Text = "Merhamet için yalvar!"
  },
  Voice_6103_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_61049_AwakerVoiceContent = {
    Text = "Dinle, bu son ağıt!"
  },
  Voice_61049_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_6104_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_6104_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6105_AwakerVoiceContent = {
    Text = "Sen de Yeşil Alevler tarafından tüketilmeyi diliyor musun?"
  },
  Voice_6105_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_6107_AwakerVoiceContent = {
    Text = "Nasıl cüret edip başka yere bakarsın!"
  },
  Voice_6107_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6108_AwakerVoiceContent = {Text = "Odaklan!"},
  Voice_6108_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6109_AwakerVoiceContent = {
    Text = "Aaa, ne tatlı bir oğlan varmış burada! Ona sadık kölem olmak isteyip istemediğini sordum, kızardı, kekeleyerek sana bağlılık yemini ettiğini söyledi... Sanki gerçek bağlılık paylaşılamazmış gibi!"
  },
  Voice_6109_AwakerVoiceTitle = {
    Text = "Sohbet: Ogier Hakkında"
  },
  Voice_6109_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Ogier\" elde edildikten sonra açılır"
  },
  Voice_6110_AwakerVoiceContent = {
    Text = "Bana yaklaşabileceğini sanma."
  },
  Voice_6110_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_6111_AwakerVoiceContent = {
    Text = "Kaderini kabullen."
  },
  Voice_6111_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_6112_AwakerVoiceContent = {
    Text = "Yurdumun kapıları sürüklenip uzaklaşıyor... Hayır... Yine değil..."
  },
  Voice_6112_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6113_AwakerVoiceContent = {
    Text = "Çekil önümden!"
  },
  Voice_6113_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6114_AwakerVoiceContent = {
    Text = "Çekil önümden!"
  },
  Voice_6114_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_6115_AwakerVoiceContent = {
    Text = "Yaptıklarının bedelini öde."
  },
  Voice_6115_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6116_AwakerVoiceContent = {
    Text = "Ölüm dileğin mi var?"
  },
  Voice_6116_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_6117_AwakerVoiceContent = {
    Text = "Sanırım yine Çözünme’ye yakalandım... Kalbim Çözündürülmüş hale geliyor! Birkaç aspirin, bir kırbaç ve biraz Pain, beni iyileştirmeye yetecektir..."
  },
  Voice_6117_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_6118_AwakerVoiceContent = {
    Text = "Sen bile bu lanet çürüğü iyileştiremiyor musun? O zaman neden Çözünme’nin peşinden koşuyorsun? Tamamen delirmişsin."
  },
  Voice_6118_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_6119_AwakerVoiceContent = {
    Text = "Ben son Roma savaşçısıyım—Uvhash!"
  },
  Voice_6119_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6120_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_6120_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6121_AwakerVoiceContent = {
    Text = "Ben son Roma savaşçısıyım—Uvhash!"
  },
  Voice_6121_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_6122_AwakerVoiceContent = {
    Text = "Çözünme...? Elbette biliyorum! Sadece kölenin tasmasının kopması demek. Bunun nesi zor?"
  },
  Voice_6122_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_6123_AwakerVoiceContent = {
    Text = "Çağrıldım; tanrı ile yalvaran arasındaki çizgi şimdi kanıyor."
  },
  Voice_6123_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_6123_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_6124_AwakerVoiceContent = {
    Text = "Hmm... Masajda gitgide ustalaşıyorsun. Baskıyı güzel uyguluyorsun~"
  },
  Voice_6124_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_6125_AwakerVoiceContent = {
    Text = "Buradaki dekor fazla eski püskü değil mi? Uğursuz, sanki perili bir yermiş gibi."
  },
  Voice_6125_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_6126_AwakerVoiceContent = {
    Text = "Burada gür Bitkiler, dingin bir hava ve kız kardeşimin hastalığına deva olacak bir Tinktur var. İkimiz için de, burası en muhteşem yeni Yurt."
  },
  Voice_6126_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_6127_AwakerVoiceContent = {
    Text = "Faint'i bir daha göreceğimi hiç beklemiyordum... O zamandan beri nasıl olduğunu merak ediyorum. Ne kadar sorarsam sorayım, sadece iyi olduğunu söyleyip beni teskin ediyor... Off. Ah, affedersin, kendimi kaptırdım. Önce bizi yeniden bir araya getirdiğin için sana teşekkür etmeliyim."
  },
  Voice_6127_AwakerVoiceTitle = {
    Text = "Sohbet: Faint Hakkında"
  },
  Voice_6127_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Faint\" elde edildikten sonra açılır"
  },
  Voice_6128_AwakerVoiceContent = {
    Text = "Onun iradesine sunulan bir sunu."
  },
  Voice_6128_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_6129_AwakerVoiceContent = {
    Text = "Onun iradesine sunulan bir sunu."
  },
  Voice_6129_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6130_AwakerVoiceContent = {
    Text = "Sakin ol, sakin ol..."
  },
  Voice_6130_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6131_AwakerVoiceContent = {
    Text = "İçimde birçok \"ben\" var. Mutlu, üzgün, öfkeli... Sünger keki severler, Londinium’un yağmurlu günlerinden nefret ederler. Hepsinin adı \"24\" ve hepsi size tapar."
  },
  Voice_6131_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6131_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6132_AwakerVoiceContent = {
    Text = "Eskiden her gün gece yarısına kadar çalışırdım—iplik eğirmek, yıkamak, temizlemek, çocuk bakmak, hatta çöp toplamak... Para kazanmak için her şeyi yapardım. O zamanlar yaşamak sadece hayatta kalmaktı. Şimdi ise taze yiyeceklerimiz, sıcak yatağımız ve senin gibi iyi kalpli bir efendimiz var... Hayallerimin bile ötesinde."
  },
  Voice_6132_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6132_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6133_AwakerVoiceContent = {
    Text = "Lütfen endişelenmeyin. Hepimiz bir bifteği ve bir yatağı paylaşırız, size asla sorun çıkarmayız."
  },
  Voice_6133_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6133_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6134_AwakerVoiceContent = {
    Text = "Heh, o kadın benim dışarı çıkmamdan o kadar korkuyor ki geceleri uyumaya bile cesaret edemiyor. Rahat ol, seni öldürmem—bana hediye verdiğin sürece. Ben kimim mi? Tabii ki ben \"24\"üm, hahaha!"
  },
  Voice_6134_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6134_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_6135_AwakerVoiceContent = {
    Text = "Şu an kendimi harika hissediyorum. Ne? Aklımın başka bir şey tarafından ele geçirildiğini mi söylüyorsun? O-olamaz... uh..."
  },
  Voice_6135_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_6135_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_6136_AwakerVoiceContent = {
    Text = "Bir tebaya göre keskin gözlem yapıyorsun. Bir sonraki uzun uykuma dalmadan önce, bu çağı... varlığımla onurlandıracağım."
  },
  Voice_6136_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_6137_AwakerVoiceContent = {
    Text = "Hmm... bu gece deniz suyu epey sıcak..."
  },
  Voice_6137_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6138_AwakerVoiceContent = {
    Text = "Geldi... rüyamda dolanan beyaz kuş."
  },
  Voice_6138_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6139_AwakerVoiceContent = {
    Text = "Dilediğin gibi, varlığım daha da somutlaştı."
  },
  Voice_6139_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6140_AwakerVoiceContent = {
    Text = "Ne kadar tatmin edici, ahaha!"
  },
  Voice_6140_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_6141_AwakerVoiceContent = {Text = "Harika!"},
  Voice_6141_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6142_AwakerVoiceContent = {
    Text = "Bana bırakın!"
  },
  Voice_6142_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_6143_AwakerVoiceContent = {
    Text = "Bana bırakın!"
  },
  Voice_6143_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6144_AwakerVoiceContent = {
    Text = "Hoş Geldin—büyük ziyafetimize!"
  },
  Voice_6144_AwakerVoiceTitle = {
    Text = "Taşkınlık: Mani"
  },
  Voice_6145_AwakerVoiceContent = {
    Text = "Bu kız... damarlarında şüphesiz benim kanım akıyor. Hayır—bu topraklarda evlat bırakacak kadar uzun yürümedim. Ve yine de... gücü benimkine bir yansıma."
  },
  Voice_6145_AwakerVoiceTitle = {
    Text = "Sohbet: İlahi Soy Hakkında"
  },
  Voice_6145_UnlockDesc = {
    Text = "\"Aigis\" ya da \"Murphy\" Uyanışçılarından biri edinildikten sonra açılır."
  },
  Voice_6146_AwakerVoiceContent = {
    Text = "Efendimin iyiliğini, Karen bir an olsun unutmaya cüret edemez!"
  },
  Voice_6146_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6147_AwakerVoiceContent = {
    Text = "—Ah, ne kadar tatlı ve lezzetli!"
  },
  Voice_6147_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6148_AwakerVoiceContent = {
    Text = "Şey... Diyetteyim, bugün çok fazla yiyemem~"
  },
  Voice_6148_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6149_AwakerVoiceContent = {
    Text = "Bu zayıflar, bıçağıma bile değmez."
  },
  Voice_6149_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_6150_AwakerVoiceContent = {
    Text = "Sanatı açıklamak, demiryolu hisselerini açıklamak kadar gülünçtür—lütfen biz sanatçıların hayatını daha da zorlaştırma."
  },
  Voice_6150_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_6151_AwakerVoiceContent = {
    Text = "Aigis... Yanlış bir şey mi yaptım?"
  },
  Voice_6151_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_6152_AwakerVoiceContent = {
    Text = "Duaların işitildi."
  },
  Voice_6152_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_6153_AwakerVoiceContent = {
    Text = "Duaların işitildi."
  },
  Voice_6153_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6154_AwakerVoiceContent = {
    Text = "Hıh, saygısız mahlûk."
  },
  Voice_6154_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6155_AwakerVoiceContent = {
    Text = "Ah, az önce yanımızdan geçen Bay N miydi o? Yok, boş ver. En son onu selamladığımda beni tanımadı... Onu hapiste bekledim, beni götürmesini umarak, ama hiç gelmedi, isyan sırasında bile."
  },
  Voice_6155_AwakerVoiceTitle = {
    Text = "Sohbet: \"N\" Hakkında"
  },
  Voice_6155_UnlockDesc = {
    Text = "Ana Hikâye 7. Bölüm tamamlanınca açılır"
  },
  Voice_6156_AwakerVoiceContent = {
    Text = "Çağrına neden cevap verdim biliyor musun? Elbette başladığımı bitirmek için. Ve eğer bana meydan okuyacak kadar güçlenirsen, bu da cabası."
  },
  Voice_6156_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_6157_AwakerVoiceContent = {
    Text = "Ablamı aldım, Brown'u aldım, bir de iş evindeki o korkak kızı... İşte benim ekibim. Tamam... seni de sayarım. Brown, {Male=him,Female=her} ile bir parça şeker paylaş.\n\"Cıyak?!\""
  },
  Voice_6157_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6157_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6158_AwakerVoiceContent = {
    Text = "Doğu Bölge Gecekondusu çocuklara göre bir yer değil. Kurnaz yaşlı ustabaşları gazete çocuklarının parasını kesmek için her yolu bulur, süt çocuklarının hızına da d-didik didik bahane arar! Orada hayatta kalmak istiyorsan, yalnızca kendine güvenirsin. Başka kimse güvene değmez."
  },
  Voice_6158_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6158_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6159_AwakerVoiceContent = {
    Text = "Benim \"kötü alışkanlıklarım\" bir gecede değişmez, anladın mı? Köprülerin altında ve tükenmelerde uyuyup, artıklardan hayatta kalmak... Sırf yaşamak bile yeterince zordu... Uyanır uyanmaz yatağımı toplamamı bekleyemezsin! En azından uyumam için bana iki hafta ver!"
  },
  Voice_6159_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6159_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6160_AwakerVoiceContent = {
    Text = "Uzayda kaybolmak midemi bulandırdı. Beni sen çıkardın, o yüzden neye ihtiyacın varsa söyle, ama mucize bekleme.\nBen sadece bir çocuğum, beni çok zorlamazsın, değil mi?"
  },
  Voice_6160_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6160_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_6161_AwakerVoiceContent = {
    Text = "Hey, Batı Bölgeli! Brown’u gördün mü? O küçük obur yine yiyecek kokusunu almış."
  },
  Voice_6161_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_6161_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_6162_AwakerVoiceContent = {
    Text = "\"Gücü olan, Güç’ünü başkalarını ezmek için kullanmamalıdır; zira hepiniz benim Kan’ımı paylaşıyorsunuz.\" Merhametkâr Baba Tanrı’mızın öğretilerini hatırlıyorum. Bu Güç’ü yalnızca çevremdekileri korumak için kullanacağım."
  },
  Voice_6162_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_6162_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_6163_AwakerVoiceContent = {
    Text = "Evrenin başlangıcında ne gördüğümü merak mı ediyorsun? Elbette, söyleyebilirim. Hiçbir şey gördüm."
  },
  Voice_6163_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_6163_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_6164_AwakerVoiceContent = {
    Text = "Gittikçe parlaklaşıyor."
  },
  Voice_6164_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6165_AwakerVoiceContent = {
    Text = "Ebedi lamba..."
  },
  Voice_6165_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6166_AwakerVoiceContent = {
    Text = "Beyaz Kuş Diyarı’yla bağım güçlendi."
  },
  Voice_6166_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6167_AwakerVoiceContent = {
    Text = "Bu dünyayı acılarından kurtarabilirsem, gönlüm huzur bulur."
  },
  Voice_6167_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6168_AwakerVoiceContent = {
    Text = "Emirlerini ver bana, Soluk Haberci. Alevlerin daima Yol’umu aydınlatsın."
  },
  Voice_6168_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6169_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_6169_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_6170_AwakerVoiceContent = {
    Text = "Bir insanın çelikleşmesi yalnızca Beden’le değil, kalple de ilgilidir."
  },
  Voice_6170_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6171_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_6171_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6172_AwakerVoiceContent = {Text = "Ah!"},
  Voice_6172_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6173_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_6173_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6174_AwakerVoiceContent = {
    Text = "Ugh! Sıcaklığın mercan için biraz fazla yüksek. Ama... sıcak ve yoğun. Hoşuma gidiyor."
  },
  Voice_6174_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_6175_AwakerVoiceContent = {
    Text = "Lah... Ah, bir şeye mi ihtiyacın var? Mümkünse, kuliste konuşalım."
  },
  Voice_6175_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_6176_AwakerVoiceContent = {
    Text = "Açmadan solan, nilüfer misali... Soğuk, azgın dalgalarda huzur arayan, kendi \"Sevinç\"ini kovalamaya bile ürken... Ben böyle biriyim, Koruyucu."
  },
  Voice_6176_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6176_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6177_AwakerVoiceContent = {
    Text = "Bir zamanlar şu ikilemle boğuşmuştum: Pain, hayatın kendisinden daha uzun mu sürer? Öyleyse, huzurlu bir Hafif Uyku, işkence dolu bir uyanıklıktan daha mı mutludur? Uyandıktan sonra ben de bu tuzağa düşmüştüm, ta ki sen bana bu güvenli sığınağı getirene dek..."
  },
  Voice_6177_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6177_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6178_AwakerVoiceContent = {
    Text = "Sanatoryumda kaldığım süre boyunca arkadaş edinmeye çalıştım, ama insanlar bana yaklaşmaya pek istekli değildi... Bunun sebebi bu kemiği kemiren \"Zehir\" mi? Lütfen, yanıma gelirken dikkatli ol."
  },
  Voice_6178_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_6178_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_6179_AwakerVoiceContent = {
    Text = "Gece rüzgârının taşıdığı çan sesi insana ne büyük huzur veriyor. Taş Sandalye’ye oturup bir süre dinlemek ister misin? Atkıyla yerini güzelce hazırlayacağım."
  },
  Voice_6179_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6179_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_6180_AwakerVoiceContent = {
    Text = "\"Deniz definini\" duydun mu? Eski kasabamda, ölüleri denize bırakma geleneği vardı; okyanus, herkesin son dinlenme yeri olurdu. Benimse, onun kucaklayışına erken döndüm..."
  },
  Voice_6180_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6180_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6181_AwakerVoiceContent = {Text = "Hıh!"},
  Voice_6181_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6182_AwakerVoiceContent = {Text = "Ah!"},
  Voice_6182_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6183_AwakerVoiceContent = {Text = "Argh!"},
  Voice_6183_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6184_AwakerVoiceContent = {Text = "Ah!"},
  Voice_6184_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_6185_AwakerVoiceContent = {
    Text = "Çarpışma kaydı arşivlendi. Sıkı çalışmanız için teşekkürler, Koruyucu."
  },
  Voice_6185_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_6186_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_6186_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_6187_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_6187_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6188_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_6188_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6189_AwakerVoiceContent = {
    Text = "Devam edebilirim."
  },
  Voice_6189_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6190_AwakerVoiceContent = {
    Text = "Salonumun konukları en ince misafirperverlikle ağırlanır... Giriş bileti olarak, bu görkemli şölenin hakkını verecek sırlar hazırladın mı?"
  },
  Voice_6190_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6191_AwakerVoiceContent = {
    Text = "Yeni şeyleri severim. Bin yıllık yolculuklarım boyunca, şiirsel biçimler ve sinematik sahneler gibi pek çok büyüleyici yenilik ve icada tanık oldum. İnsanlar gerçekten de tuhaf ve ilgi çekici varlıklar."
  },
  Voice_6191_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6192_AwakerVoiceContent = {
    Text = "Evet. Lily hatırlıyor. Anne dışarıdayken Lily onun evinde kaldı."
  },
  Voice_6192_AwakerVoiceTitle = {
    Text = "Sohbet: Nergis Hakkında"
  },
  Voice_6192_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Nergis\" elde edildikten sonra açılır"
  },
  Voice_6195_AwakerVoiceContent = {
    Text = "Kim cüret eder de Bu Varlığın hafif uykusunu bozar?"
  },
  Voice_6195_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6196_AwakerVoiceContent = {
    Text = "Tanrılar mı? Ancak ahmaklar hayatlarını böyle soyut varlıklara emanet eder. Sözde tanrılara canını bahse koyacağına, nasıl daha güçlü olacağına odaklansan daha iyi."
  },
  Voice_6196_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_6197_AwakerVoiceContent = {
    Text = "Şu “köle efendisi”, “gladyatörlerin sahibi”... Ha. O sadece değersiz bir böcek."
  },
  Voice_6197_AwakerVoiceTitle = {
    Text = "Sohbet: Agrippa Hakkında"
  },
  Voice_6197_UnlockDesc = {
    Text = "\"Agrippa\" Uyandıranı edinince açılır"
  },
  Voice_6198_AwakerVoiceContent = {
    Text = "Zaferden sonra, lütfen üreme için gereken malzemeleri almama izin ver."
  },
  Voice_6198_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6199_AwakerVoiceContent = {
    Text = "Kocaman dost! Yoldaşım! Huhuu, sonsuza dek en iyi arkadaş olalım, olur mu?"
  },
  Voice_6199_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_6200_AwakerVoiceContent = {
    Text = "Şu anda gerçekten, gerçekten heyecanlıyım... Hâlâ yaşamak istiyorsan, benden uzak dursan iyi olur."
  },
  Voice_6200_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6201_AwakerVoiceContent = {
    Text = "O... Başkalarına gerçekten böyle davranabilir mi? Bayan Sarah, çocukların öyle öfke nöbeti geçirmemesi gerektiğini söylemişti..."
  },
  Voice_6201_AwakerVoiceTitle = {
    Text = "Sohbet: Murphy Hakkında"
  },
  Voice_6201_UnlockDesc = {
    Text = "Uyanışçı \"Murphy\" edinildiğinde açılır"
  },
  Voice_6202_AwakerVoiceContent = {
    Text = "Zaferin görkemi sizin, efendim."
  },
  Voice_6202_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_6203_AwakerVoiceContent = {
    Text = "L-Lütfen, tamamen dolup taşıyorum~"
  },
  Voice_6203_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6204_AwakerVoiceContent = {
    Text = "İçimdeki boşluk dolduruldu~"
  },
  Voice_6204_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6205_AwakerVoiceContent = {
    Text = "Evet, gitgide daha da ısınıyorum..."
  },
  Voice_6205_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6206_AwakerVoiceContent = {
    Text = "O çocuğu tanıyorum. Bazen uzakta durup gösterimi izler. Yakına gelmemesi iyi, yoksa küçük seyircilerim zihnen ve bedenen tükenir!"
  },
  Voice_6206_AwakerVoiceTitle = {
    Text = "Sohbet: Faint Hakkında"
  },
  Voice_6206_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Faint\" elde edildikten sonra açılır"
  },
  Voice_6207_AwakerVoiceContent = {
    Text = "Tinktur, “İyiliği karşılıksız bırakma,” dedi. Bu yüzden, yardım etmem gücüm dahilindeyse, bir el uzatırım..."
  },
  Voice_6207_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_6208_AwakerVoiceContent = {
    Text = "Merhaba, Sır Koruyucusu. Size nasıl Destek olabilirim?"
  },
  Voice_6208_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_6209_AwakerVoiceContent = {
    Text = "Bir gün, ön saflarda lider olarak savaş alanına Dönüş yapacağım."
  },
  Voice_6209_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_6209_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_6210_AwakerVoiceContent = {
    Text = "İnanabiliyor musun? Kırık bacağımın kemiğinin iyileştiğini hissedebiliyorum."
  },
  Voice_6210_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_6210_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_6211_AwakerVoiceContent = {
    Text = "Beni bu Seviyeye kadar eğitip yetiştirdiğin için içtenlikle teşekkür ederim. Sen de mutlaka adalet peşinde koşan birisin; bu yüzden burada davamıza şan getirmeye devam edeceğim."
  },
  Voice_6211_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_6211_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_6212_AwakerVoiceContent = {
    Text = "Yeni bir sefere çıkılacak gün hızla yaklaşıyor ve kanım amaçla kaynıyor."
  },
  Voice_6212_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_6212_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_6213_AwakerVoiceContent = {
    Text = "Savaşçı olmanın onuru yeniden tesis ediliyor."
  },
  Voice_6213_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_6213_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_6214_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_6214_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_6215_AwakerVoiceContent = {Text = "Ah!"},
  Voice_6215_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6216_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_6216_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6217_AwakerVoiceContent = {Text = "Hileci!"},
  Voice_6217_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6218_AwakerVoiceContent = {
    Text = "Hop, benim hatam! Bir dahaki sefere halledeceğim, söz!"
  },
  Voice_6218_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6219_AwakerVoiceContent = {
    Text = "Birinin adımı çağırdığını duyuyorum: Agrippa, Agrippa, Agrippina..."
  },
  Voice_6219_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_6219_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_6220_AwakerVoiceContent = {
    Text = "Gördüm... Kuyunun karanlığından tırmanarak yükseliyordu; etten yumurtasının üzerinde sayısız göz belirdi. Bana dikildiler, beni çağırdılar... Labirent Tanrısı!"
  },
  Voice_6220_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_6220_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_6221_AwakerVoiceContent = {
    Text = "İçimde çok güçlü bir düello izleme isteği var... Bir de labirentte olursa, tadından yenmez!"
  },
  Voice_6221_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_6221_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_6222_AwakerVoiceContent = {
    Text = "Sözleşme... Evet, seninle bir sözleşme imzalamak istiyorum; ebedi bir efendi-köle sözleşmesi..."
  },
  Voice_6222_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_6222_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_6223_AwakerVoiceContent = {
    Text = "Hıh... Fena değil. Daha ver. Bu küçük örümcek yavrularını beslemem gerek."
  },
  Voice_6223_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_6223_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_6224_AwakerVoiceContent = {
    Text = "Ne pislik, ne iğrenç bir şey! Ah—yeter! Lütfen! Bana onu gösterme, ondan yanımda söz etme..."
  },
  Voice_6224_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_6225_AwakerVoiceContent = {
    Text = "Geçmişim, ekvator yakınlarındaki denizler gibi sıradan ve sakindi; bahsetmeye değer hiçbir şey yok."
  },
  Voice_6225_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6225_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_6226_AwakerVoiceContent = {
    Text = "Hımm...? Anne, kucağa? ...Çok sıcaksın..."
  },
  Voice_6226_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_6227_AwakerVoiceContent = {
    Text = "Ey Yıldız Tozu..."
  },
  Voice_6227_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_6228_AwakerVoiceContent = {
    Text = "Aaa, yoksa tümüyle kaybolduk mu?"
  },
  Voice_6228_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6229_AwakerVoiceContent = {Text = "Yararsız."},
  Voice_6229_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6230_AwakerVoiceContent = {
    Text = "O hainlerin diz çöküp merhamet için çığlık attığını her hatırladığımda, içimi bir tatmin dalgası kaplıyor ve kalbimdeki alevler sanki diniveriyor."
  },
  Voice_6230_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6231_AwakerVoiceContent = {
    Text = "Yıllar önce gemiye getirildim ve geminin genç kızına biçilen görev bana emanet edildi. O zamandan beri hayatım—ve anlamı—kontrolümün ötesine geçti. En azından bir Uyandıran olarak bu ikinci hayatımda kendi dileklerim için yaşamam gerektiği söylendi bana... Bana yardım eder misin? Bana Bencillik kazanmamda yardım et, kendi dileğimi bulmama yardım et."
  },
  Voice_6231_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6231_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6232_AwakerVoiceContent = {
    Text = "Bu, Agrippa. Seninle konuşacak hiçbir şeyim yok—ta ki gladyatörüm olmaya gönüllü olacak kadar cesur olana dek."
  },
  Voice_6232_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6233_AwakerVoiceContent = {
    Text = "Tawil... düşündüğümüzden çok daha tehlikeli. Ben artık burada olmadığımda, ondan son derece sakınmalısın."
  },
  Voice_6233_AwakerVoiceTitle = {
    Text = "Sohbet: Tawil Hakkında"
  },
  Voice_6235_AwakerVoiceContent = {
    Text = "Bu çıkarımsal akıl yürütme cihazıyla... dünyayı yorumlayacağım!"
  },
  Voice_6235_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6236_AwakerVoiceContent = {
    Text = "Bu çıkarımsal akıl yürütme cihazıyla... dünyayı yorumlayacağım!"
  },
  Voice_6236_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_6237_AwakerVoiceContent = {
    Text = "Benim için parılda!"
  },
  Voice_6237_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6238_AwakerVoiceContent = {
    Text = "Gücümün yettiğince."
  },
  Voice_6238_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6239_AwakerVoiceContent = {
    Text = "Gücümün yettiğince."
  },
  Voice_6239_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_6240_AwakerVoiceContent = {
    Text = "Çürüyeceğiz... birlikte."
  },
  Voice_6240_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6241_AwakerVoiceContent = {
    Text = "Çürüyeceğiz... birlikte."
  },
  Voice_6241_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_6242_AwakerVoiceContent = {
    Text = "Gülümsemeler ve görgü kuralları bir katman zırh görevi görür; başkalarıyla arama mesafe koymama ve sıkıcı rahatsızlıklardan kaçınmama yardım eder. Gerçek benliğime gelince... onu sana göstermekte sakınca görmüyorum."
  },
  Voice_6242_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6242_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6243_AwakerVoiceContent = {
    Text = "Düşüncelerim beyaz kireçtaşı gibi birikir ve güzel mercanlara dönüşerek yıkanır. Benimle birleşir, kalp atışımla birlikte nabız gibi atar... Dinler misin?"
  },
  Voice_6243_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6243_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6244_AwakerVoiceContent = {
    Text = "İlham, denizden yükselen kabarcıklar gibidir: hafif bir dokunuşla yok olurlar. Sen de öyle misin?"
  },
  Voice_6244_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6244_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_6245_AwakerVoiceContent = {
    Text = "Savaş, yağma ve şan, hepsi insani arzular. Mütevazı heykeltıraş, insanların peşinden koştuğu hiçbir şeye ilgi duymaz; o yalnızca güzelliğin kölesi olmak ister."
  },
  Voice_6245_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6245_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6246_AwakerVoiceContent = {
    Text = "Harika bir can, kendini kaptırmanın içinde yatar. Bazen, kendine bu kadar zor davranmamalısın."
  },
  Voice_6246_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_6246_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_6247_AwakerVoiceContent = {
    Text = "Sadece ufak bir çizik..."
  },
  Voice_6247_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6249_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_6249_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6250_AwakerVoiceContent = {
    Text = "Lanet olsun!"
  },
  Voice_6250_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6251_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_6251_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_6252_AwakerVoiceContent = {
    Text = "Çözünme, Kaos ve felaketler getirir. Belki de Beyaz Kuş Diyarı bu yüzden Derin Deniz’e gömüldü..."
  },
  Voice_6252_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_6253_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6253_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6254_AwakerVoiceContent = {Text = "Ah!"},
  Voice_6254_AwakerVoiceTitle = {
    Text = "Özel Beceri: I"
  },
  Voice_6255_AwakerVoiceContent = {
    Text = "Mutlak buyruk."
  },
  Voice_6255_AwakerVoiceTitle = {
    Text = "Özel Beceri: I"
  },
  Voice_6256_AwakerVoiceContent = {Text = "Bunu dene!"},
  Voice_6256_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6257_AwakerVoiceContent = {
    Text = "Kaçınılmaz kurban."
  },
  Voice_6257_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6258_AwakerVoiceContent = {
    Text = "Fena değil; bu bir savaşçının şanı!"
  },
  Voice_6258_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_6259_AwakerVoiceContent = {
    Text = "Sen! O kadının içeri girmesine nasıl izin verdin?! Hemen bir güvenlik hattı kur! Onu benden en az elli adım uzakta tut!"
  },
  Voice_6259_AwakerVoiceTitle = {
    Text = "Sohbet: Miryam Hakkında"
  },
  Voice_6259_UnlockDesc = {
    Text = "Uyanışçı \"Miryam\" elde edildikten sonra açılır"
  },
  Voice_6260_AwakerVoiceContent = {
    Text = "Daha Güçlü olmanın sebebi mi? Kabilemde zayıfların üzerindeki her şey alınır, başları kazınır ve akla gelebilecek en alçakça aşağılanmaya maruz bırakılır—Zayıflığın bedeli, Herkes’in taşıyabileceği türden değildir."
  },
  Voice_6260_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_6260_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_6261_AwakerVoiceContent = {
    Text = "Talih Tanrıçası, hiç değilse bu kez bana gülümse!"
  },
  Voice_6261_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6262_AwakerVoiceContent = {
    Text = "Demek ki... insan gücünün de bir sınırı var..."
  },
  Voice_6262_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6263_AwakerVoiceContent = {
    Text = "Güzel. Daha az yük, daha çok güç."
  },
  Voice_6263_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_6263_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_6264_AwakerVoiceContent = {
    Text = "Bu, arzunun tezahürü mü, sevgimi derinleştirmek için mi?"
  },
  Voice_6264_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_6264_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_6265_AwakerVoiceContent = {
    Text = "Zevke varın!"
  },
  Voice_6265_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6266_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_6266_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6267_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_6267_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6268_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_6268_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6269_AwakerVoiceContent = {
    Text = "Ah, affedilemez..."
  },
  Voice_6269_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6270_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_6271_AwakerVoiceContent = {
    Text = "Birazcık gözü kara olsak fena olmaz!"
  },
  Voice_6271_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6272_AwakerVoiceContent = {Text = "Bang!"},
  Voice_6272_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6273_AwakerVoiceContent = {
    Text = "Böyle devam et! Nihai notların umut verici."
  },
  Voice_6273_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_6274_AwakerVoiceContent = {
    Text = "Gecekondu mahallelerinden bir hırsız gelmiş, yanında da şişko bir sıçan getirmiş, duydum? Hehehe... Efendim için bu belayı nasıl ortadan kaldırdığımı izleyin!"
  },
  Voice_6274_AwakerVoiceTitle = {
    Text = "Sohbet: Jenkin Hakkında"
  },
  Voice_6274_UnlockDesc = {
    Text = "\"Jenkin\" Uyandıranı edinince açılır"
  },
  Voice_6275_AwakerVoiceContent = {
    Text = "Hadi, derin bir nefes al—"
  },
  Voice_6275_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6276_AwakerVoiceContent = {
    Text = "İlginç. Savaştaki gelişimin beklentilerimi fazlasıyla aşıyor. Zamanla, belki sen de... Tuhaf. Bunca zamandan sonra bile, senin kadar zayıf görünen bir varlıkta hâlâ umut buluyorum."
  },
  Voice_6276_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6276_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6277_AwakerVoiceContent = {
    Text = "Belki de şimdi tam zamanı. Dikkatle dinle. Yıldızlar'ın Canavarı Lotan, seni resmen düelloya davet ediyor. Endişelenme; zirvene ulaşana kadar hayatta kalmanı sağlayacağım. Seçtiğim rakibin aynı kaderi bir daha yaşamasına izin vermeyeceğim."
  },
  Voice_6277_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6277_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6278_AwakerVoiceContent = {
    Text = "Hıh... Ramona’nın seni neden ortağı olarak seçtiğini hâlâ aklım almıyor. Evet, güç kokuyorsun, ama benim seviyeme yaklaşamıyorsun bile."
  },
  Voice_6278_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6278_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_6279_AwakerVoiceContent = {
    Text = "Evet, bana bak. Ben bu gezegenin en kadim varlığıyım; önemsizlerden saygı talep eden. Bu gezegeni çağlar boyunca korudum. Karşılığında heyecan verici bir savaş istemem gerçekten de fazla mı?"
  },
  Voice_6279_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6279_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6280_AwakerVoiceContent = {
    Text = "Hah! Çocukça oyunlara ayıracak vaktim yok. Bir köşe bul ve yolumdan çekil."
  },
  Voice_6280_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_6280_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_6281_AwakerVoiceContent = {
    Text = "Korunmasız ruhlar, size son huzuru bahşedeceğim."
  },
  Voice_6281_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6282_AwakerVoiceContent = {Text = "Alarm."},
  Voice_6282_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_6283_AwakerVoiceContent = {Text = "Alarm."},
  Voice_6283_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_6284_AwakerVoiceContent = {
    Text = "Bir şey... zihnimin içinde ağlıyor."
  },
  Voice_6284_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_6284_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_6285_AwakerVoiceContent = {
    Text = "Sanki beyaz bir sis perdesi düşüncelerimi bulandırıyor."
  },
  Voice_6285_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_6285_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_6286_AwakerVoiceContent = {
    Text = "Ses şimdi daha yüksek. Sis koyulaşıyor."
  },
  Voice_6286_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_6286_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_6287_AwakerVoiceContent = {
    Text = "Bu ses... saatin akreple yelkovanının dönme sesi mi?"
  },
  Voice_6287_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_6287_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_6288_AwakerVoiceContent = {
    Text = "Son çan sesi çaldığında... hâlâ burada olacak mıyım?"
  },
  Voice_6288_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_6288_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_6289_AwakerVoiceContent = {
    Text = "Ne kadar sakar bir numara... Hıh. Saf ahmak. Beni bu kadar kolay bağlayabileceğini gerçekten mi sandın?"
  },
  Voice_6289_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6290_AwakerVoiceContent = {
    Text = "Affedersiniz... Kız kardeşim Jenkin’i gördünüz mü? Elinde bir fare taşıyan, oldukça hırçın olabilen bir kız çocuktur... Onu asla başka biriyle karıştırmam."
  },
  Voice_6290_AwakerVoiceTitle = {
    Text = "Sohbet: Jenkin Hakkında"
  },
  Voice_6290_UnlockDesc = {
    Text = "Ana Hikâye 2. Bölüm tamamlandıktan sonra açılır"
  },
  Voice_6292_AwakerVoiceContent = {
    Text = "Teşekkür ederim. Fazlasıyla naziksin."
  },
  Voice_6292_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6293_AwakerVoiceContent = {Text = "Hazır."},
  Voice_6293_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_6294_AwakerVoiceContent = {
    Text = "Lütfen performansımı sabırsızlıkla bekle."
  },
  Voice_6294_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6295_AwakerVoiceContent = {
    Text = "Senin için şarkı söyleyeceğim."
  },
  Voice_6295_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6296_AwakerVoiceContent = {
    Text = "Yeni Koruyucu mu? Hadi, her şeyini ortaya koy. Bakalım benimle yüzleşmeye layık mısın!"
  },
  Voice_6296_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6297_AwakerVoiceContent = {
    Text = "Her ne kadar pasifist olsam da, “onlar” belli ki öyle düşünmüyor..."
  },
  Voice_6297_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6298_AwakerVoiceContent = {Text = "Ha!"},
  Voice_6298_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6299_AwakerVoiceContent = {Text = "Geri dur!"},
  Voice_6299_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6300_AwakerVoiceContent = {
    Text = "Bana böyle bir aşağılanmayı nasıl reva görürsün..."
  },
  Voice_6300_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6301_AwakerVoiceContent = {
    Text = "Hazır mısın? Casiah’ın sihir gösterisi başlamak üzere! Gözünü ayırma, en önemli anları kaçırmak istemezsin. Gösteri başlasın!"
  },
  Voice_6301_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6302_AwakerVoiceContent = {
    Text = "Tekeli—Li!"
  },
  Voice_6302_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_6303_AwakerVoiceContent = {Text = "Ha!"},
  Voice_6303_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_6304_AwakerVoiceContent = {
    Text = "Programını Sylvia'dan aldım ve yeni gelenler için fazla ağır. Doğru olanı yaptığını anlıyorum, ama acemileri aşırı yüklemek ekip için gereksiz sorunlara yol açabilir.\nAcemi olmadığını mı söylüyorsun? Hayır, gözlerindeki bakıştan anlayabiliyorum; henüz deneyimlemediğin pek çok şey var."
  },
  Voice_6304_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6304_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6305_AwakerVoiceContent = {
    Text = "Kendi başarısızlıklarımdan gerçekten hoşlanmıyorum... Ah! Beni teselli etmenize gerek yok! O eski yaralar, büyümemi sağlayan itkiye dönüştü. Zaten sizin Metanetli dayanağınız haline gelmedim mi?"
  },
  Voice_6305_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_6306_AwakerVoiceContent = {
    Text = "O adamla bir türlü anlaşamıyorum. Can sadece günah ve Cezalandırma’dan ibaret değil ki. Anı yakalamakta ne sakınca var?"
  },
  Voice_6306_AwakerVoiceTitle = {
    Text = "Sohbet: Salvador Hakkında"
  },
  Voice_6306_UnlockDesc = {
    Text = "Uyanışçı \"Salvador\" elde edildikten sonra açılır"
  },
  Voice_6307_AwakerVoiceContent = {
    Text = "Zaman sınırlı. Harekete geçelim."
  },
  Voice_6307_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6308_AwakerVoiceContent = {
    Text = "Çabucak sönen mumlardan, kara ekmekten ve eteklerdeki sökük ipliklerden nefret ederim... Bir sebebi yok, sadece tiksiniyorum. Bu doğal değil mi?"
  },
  Voice_6308_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_6309_AwakerVoiceContent = {
    Text = "Madem beni Kutsal Bakiren olarak taçlandırdın, o hâlde boyun eğeceksin!"
  },
  Voice_6309_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6310_AwakerVoiceContent = {
    Text = "Madem beni Kutsal Bakiren olarak taçlandırdın, o hâlde boyun eğeceksin!"
  },
  Voice_6310_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_6311_AwakerVoiceContent = {
    Text = "Benim için söyle."
  },
  Voice_6311_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6312_AwakerVoiceContent = {
    Text = "\"Hanımefendinin Gardırobu\" ve \"Çalışan Kadının Rehberi\" ikisi de harika kitaplar... O güzel elbiseleri almaya gücüm yetmiyor gerçi, ama sadece onları seyretmek bile eğlenceli."
  },
  Voice_6312_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6313_AwakerVoiceContent = {
    Text = "Tuhaf. Normalde bir şeyleri hatırlamakta zorlanırım ama seni sadece birkaç günde ezberledim... Ne? Çoktan üç ay mı oldu? Özür dilerim, yine unuttum."
  },
  Voice_6313_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_6314_AwakerVoiceContent = {
    Text = "Tadını çıkar."
  },
  Voice_6314_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6316_AwakerVoiceContent = {
    Text = "Soğukkanlılığını geliştirmeye devam et."
  },
  Voice_6316_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6317_AwakerVoiceContent = {
    Text = "Fouette. Yirmi kez daha."
  },
  Voice_6317_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6318_AwakerVoiceContent = {
    Text = "Hareketlerim yeterince isabetli mi?"
  },
  Voice_6318_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6319_AwakerVoiceContent = {
    Text = "Lütfen, buyur!"
  },
  Voice_6319_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6320_AwakerVoiceContent = {
    Text = "Çabuk, Brown'ı kap ve toz ol!"
  },
  Voice_6320_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6321_AwakerVoiceContent = {
    Text = "Tahtın önünde diz çök."
  },
  Voice_6321_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6322_AwakerVoiceContent = {
    Text = "Tahtın önünde diz çök."
  },
  Voice_6322_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_6323_AwakerVoiceContent = {
    Text = "Arzu ile buruşmuş insan yüzleri beni eğlendirmekten hiç vazgeçmiyor. Ne kırılgan, ne küçükler... Sırf bu bile, sanki kalbimi bir kedinin tırmalıyormuş gibi hissettiriyor."
  },
  Voice_6323_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_6324_AwakerVoiceContent = {
    Text = "Onun Anılarında Çözünme’nin geçmişteki olaylarını gördüm... Ama her konuşmaya yeltendiğimde bilincim parçalanıyor. Bunun onun eseri olduğuna inanıyorum."
  },
  Voice_6324_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_6325_AwakerVoiceContent = {
    Text = "Güzel. Şimdi usulca unutuşa karışacağız."
  },
  Voice_6325_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6326_AwakerVoiceContent = {
    Text = "Nitelikli bir uşak yumuşak başlı ve boş olmalıdır—itaatkâr kuzuları tercih ederim."
  },
  Voice_6326_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6327_AwakerVoiceContent = {
    Text = "Karşılaşmamız, acı çekenlere Ulu Baba’dan verilmiş bir söz olmalı. Sen felaketi dağıtan Soluk Alev’sin, ben de sadakatle yanında duracak kolun olacağım."
  },
  Voice_6327_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6328_AwakerVoiceContent = {
    Text = "Yeter artık!"
  },
  Voice_6328_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6329_AwakerVoiceContent = {
    Text = "Hiç damarlarınıza zorla D-balçık basıldığını hissettiniz mi? Siyah sümüksü şey kalbinizin etrafına engerek gibi dolanır ve sonra... pat! Bedeniniz sıcak, pütürlü bir bulamaca dönüşerek infilak eder. İğrenç, ama etkili."
  },
  Voice_6329_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_6330_AwakerVoiceContent = {
    Text = "Hıh, zayıfların birbirine sokulup saklandığı bir sığınak."
  },
  Voice_6330_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_6331_AwakerVoiceContent = {
    Text = "Ara sıra, motosikletli kız çocuk protez uzvumu bakımını yapmama yardım ediyor. Yine de, son zamanlarda bu bakım kontrollerinin sıklığı fazlasıyla artmadı mı?"
  },
  Voice_6331_AwakerVoiceTitle = {
    Text = "Sohbet: Nautila Hakkında"
  },
  Voice_6331_UnlockDesc = {
    Text = "\"Nautila\" Uyandıranı edinince açılır"
  },
  Voice_6332_AwakerVoiceContent = {
    Text = "Bizim ilişkimiz mi? Bunu sormana bile gerek var mı? Tam da hayal ettiğin gibi!"
  },
  Voice_6332_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_6333_AwakerVoiceContent = {
    Text = "Bu, tercih ettiğim bir nazım türü değil; ama ısrar ediyorsanız, deneyeceğim."
  },
  Voice_6333_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6334_AwakerVoiceContent = {
    Text = "Göz altı halkaların daha da koyulaşıyor... Neden kendini böyle zorluyorsun? Benim gibi olmalı, tembelliğin keyfine varmayı öğrenmelisin."
  },
  Voice_6334_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_6334_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_6335_AwakerVoiceContent = {
    Text = "Dur, benim iznim olmadan..."
  },
  Voice_6335_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_6335_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_6336_AwakerVoiceContent = {
    Text = "Güzel... Asıl formuma biraz daha yaklaşıyorum."
  },
  Voice_6336_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_6336_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_6337_AwakerVoiceContent = {
    Text = "Bu, \"Yeşil Çürüme\" ye karşı koyma Gücü... Yasak olana dokundun. Bana gelince, seni bir daha asla bırakmayacağım."
  },
  Voice_6337_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_6337_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_6338_AwakerVoiceContent = {
    Text = "Şşş... Vadinin sabah kızıllığı—bunu ilk kez görüyorsun, değil mi? Bunu, sadakatinin mükâfatı say."
  },
  Voice_6338_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_6338_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_6339_AwakerVoiceContent = {
    Text = "Bu cilt, \"@1@2 Vahyi\", artık senin. Zihni aydınlatmaya yarar, yahut belki de seni hızla hafif uykuya davet etmeye."
  },
  Voice_6339_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_6339_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_6340_AwakerVoiceContent = {
    Text = "Ölümlülerin gürültüsü beni yoruyor. Bu akademide sessiz bir köşe yeterli olurdu... Hayır, şömineye ihtiyacım yok. Yalnızca sadelik, saygı duruşumu Ona ulaştırabilir..."
  },
  Voice_6340_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_6341_AwakerVoiceContent = {
    Text = "Bedenimden damlayan mum mu, yoksa bal mı? Neden bir yudum alıp kendin bakmıyorsun?"
  },
  Voice_6341_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_6341_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_6342_AwakerVoiceContent = {
    Text = "M-Merhaba... Tanıştığımıza memnun oldum. Benim adım Aigis... L-Lütfen beni dert etmeyin! Sanki hiç yokmuşum gibi davranın..."
  },
  Voice_6342_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6343_AwakerVoiceContent = {
    Text = "Ben hâlâ \"\"Ramona\"\" olduğum sürece... hâlâ ortaktık, değil mi?"
  },
  Voice_6343_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_6344_AwakerVoiceContent = {
    Text = "Koyu göz altı halkaları olan o hanım bana \"güneşte sonsuza dek yaşamak\" hakkında danıştı... Sadece iki boyut arasında göç etmesi yeterliydi. Ama Boyut Tüneli'ne adım atmayı reddediyor. Gerçekten baş ağrıtıcıydı."
  },
  Voice_6344_AwakerVoiceTitle = {
    Text = "Sohbet: Winkle Hakkında"
  },
  Voice_6344_UnlockDesc = {
    Text = "\"Winkle\" Uyandıranı edinince açılır"
  },
  Voice_6345_AwakerVoiceContent = {
    Text = "Paradise’ıma hoş geldin! Şimdi, kırbacıma hazır mısın?"
  },
  Voice_6345_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6346_AwakerVoiceContent = {
    Text = "Madem O seni layık gördü, artık seni bir hasım olarak görmeyeceğim."
  },
  Voice_6346_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_6347_AwakerVoiceContent = {
    Text = "“Ben aldım” da ne demek? Bu haksızlık! Onun aptal vidaları kaybolduğunda ben meşguldüm—Brown, dur! … Heh, ne gördüysen unut gitsin, tamam mı?"
  },
  Voice_6347_AwakerVoiceTitle = {
    Text = "Sohbet: Nautila Hakkında"
  },
  Voice_6347_UnlockDesc = {
    Text = "\"Nautila\" Uyandıranı edinince açılır"
  },
  Voice_6348_AwakerVoiceContent = {
    Text = "Maceralar, hikâyelerdeki kadar heyecan vericiymiş! Neydi o hikâye...?"
  },
  Voice_6348_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_6349_AwakerVoiceContent = {
    Text = "...Hıçk. Ah, özür dilerim, yine çok fazla enerji tükettim."
  },
  Voice_6349_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_6350_AwakerVoiceContent = {
    Text = "Bir insan kabına girdikten sonra, kendi soyumla tüm bağlantımı kaybettim. Diğerlerinin iblisten kaçamadığından ve türümün son üyesi olabileceğimden korkuyorum... Lütfen, Koruyucu, beni kurtar! Yanında kalmama izin ver, beni karanlığa bırakma..."
  },
  Voice_6350_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6350_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6351_AwakerVoiceContent = {
    Text = "Gezegenim imha edildiğinde bedenimi terk ettim ve bilincimi bir insan kabına aktardım... Ama kara iblis peşimi hiç bırakmadı, ruhumu bağlayıp kaçışımı engelledi! Bu dünyayı bir karanlık uçurumuna sürüklemek istiyor!"
  },
  Voice_6351_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6351_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6352_AwakerVoiceContent = {
    Text = "Lütfen, Koruyucu... Beni yer belirleyicide, kıpırdamadan kalmama izin verdiğin sürece, karanlığa girip o... o siyah şeyle yüzleşmek dışında her şeyi yaparım! Bu noktadan ayrılamam! Az kaldı, yurt gezegenimin kalıntı bedenini tespit edeceğim! Sadece 1,2 milyar Hesaplama kaldı!"
  },
  Voice_6352_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6352_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6353_AwakerVoiceContent = {
    Text = "Tedarik paylaşımını kullanıp bana iki paket kafein takviyesi alabilir misin?... Uyuyamıyorum. Neden uyuyayım ki? Asla uyumamalıyım! Gözlerimi bir kez kapattığımda her şey karanlığa dönüşüyor... sonsuz karanlığa..."
  },
  Voice_6353_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6353_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_6354_AwakerVoiceContent = {
    Text = "Hey! Benden uzak dur! İ-İlk önce, karanlığın bir hizmetkârı olmadığını kanıtlamalısın! Evet, sadece kıyafetlerini çıkar ve bedeninde o iğrenç siyah sümüksü şeyin olmadığını göster, o zaman kötü olmadığını anlarım..."
  },
  Voice_6354_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_6354_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_6355_AwakerVoiceContent = {
    Text = "Sorma! Sorma! En çok neden korkup nefret ettiğimi gayet iyi biliyorsun! Karanlık! Sonsuz karanlık!"
  },
  Voice_6355_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_6356_AwakerVoiceContent = {
    Text = "Çözünme'yi iyileştirmenin bir yolu mu? Böyle bir şey hiçbir yerde yok. Nasıl enfekte olmadan kaldığımı mı soruyorsun? Hehe... Sadece \"görülmemek\" yeterli."
  },
  Voice_6356_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_6357_AwakerVoiceContent = {
    Text = "Teşekkür ederim, Usta."
  },
  Voice_6357_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6358_AwakerVoiceContent = {
    Text = "Püstüller de mutlu."
  },
  Voice_6358_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6359_AwakerVoiceContent = {
    Text = "Lily büyüdü."
  },
  Voice_6359_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6360_AwakerVoiceContent = {
    Text = "Ezecek miyim?"
  },
  Voice_6360_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6361_AwakerVoiceContent = {
    Text = "Onu çağırmaya nasıl cüret edersin! O işe yaramaz, tembel herif! Bir zamanlar ona büyük saygı duyardım! Defolup gitsin! O budalaya bakmayı reddediyorum!"
  },
  Voice_6361_AwakerVoiceTitle = {
    Text = "Sohbet: Tulu Hakkında"
  },
  Voice_6361_UnlockDesc = {
    Text = "\"Tulu\" Uyandıranı edinince açılır"
  },
  Voice_6362_AwakerVoiceContent = {Text = "İğrenç!"},
  Voice_6362_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_6363_AwakerVoiceContent = {
    Text = "Tsk, sinir bozucu!"
  },
  Voice_6363_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_6364_AwakerVoiceContent = {
    Text = "Bir dahaki sefere, denizi birlikte görmeye gidelim. Febvre iyidir; rehberin olabilirim. Ya da başka herhangi bir yere, hatta dünyanın sonuna kadar—seninle gitmek istiyorum."
  },
  Voice_6364_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_6364_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_6365_AwakerVoiceContent = {
    Text = "Denizin kendine ait bir dili var. Tıpkı böyle... Bazen havuzdaki küçük balıklarla memleketimiz hakkında sohbet edebiliyorum. Merak ediyorsan, senin için tercüme edebilirim."
  },
  Voice_6365_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_6365_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_6366_AwakerVoiceContent = {
    Text = "Senin tarafından kurtarılmak, sık sık beni dehşete düşüren bir sevinç hissettiriyor... Lütfen bunun bir rüya olmadığını söyle, iz bırakmadan denize karışıp kaybolmayacaksın, değil mi?"
  },
  Voice_6366_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_6366_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_6367_AwakerVoiceContent = {
    Text = "Bu duyguya gerçekten \"Sevinç\" denebilir mi? Ben... daha önce bunu dilemeye bile cesaret edememiştim."
  },
  Voice_6367_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_6367_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_6368_AwakerVoiceContent = {
    Text = "Bedenim sıcak hissediyor, sanki nazikçe deniz tarafından sarılıyormuş gibi. Bu gerçekten inanılmaz."
  },
  Voice_6368_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_6368_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_6369_AwakerVoiceContent = {
    Text = "Şu oğlan O’nun bir Parçası mı? Fena değil. Kesinlikle soylu bir havası var."
  },
  Voice_6369_AwakerVoiceTitle = {
    Text = "Sohbet: Tulu Hakkında"
  },
  Voice_6369_UnlockDesc = {
    Text = "\"Tulu\" Uyandıranı edinince açılır"
  },
  Voice_6370_AwakerVoiceContent = {
    Text = "Hayır, yapma! Devam etme! O beni bulacak! O beni bulacak!"
  },
  Voice_6370_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6371_AwakerVoiceContent = {
    Text = "Bu beni uyanık tutmalı."
  },
  Voice_6371_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6372_AwakerVoiceContent = {
    Text = "Bitti! Bitti! Bitti! Kesinlikle öğrenecekler..."
  },
  Voice_6372_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6373_AwakerVoiceContent = {
    Text = "Kazandık. Mutlu musun? “Mutlu” olmak nasıl bir his?"
  },
  Voice_6373_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_6374_AwakerVoiceContent = {
    Text = "Sevdiğim şeyler mi? Tinktur'un ninnilerini seviyorum... Tabii, senin şarkıların da harika!"
  },
  Voice_6374_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6375_AwakerVoiceContent = {
    Text = "O, değerli bir bıçaktı. Bir zamanlar ona “yoldaş” adını vermiştim... Kullandığım kelimeye itirazın mı var? Öyleyse, elbette, beni aydınlat."
  },
  Voice_6375_AwakerVoiceTitle = {
    Text = "Sohbet: Golyat Hakkında"
  },
  Voice_6375_UnlockDesc = {
    Text = "\"Golyat\" Uyandıranı edinince açılır"
  },
  Voice_6378_AwakerVoiceContent = {
    Text = "Ey Meteor..."
  },
  Voice_6378_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6379_AwakerVoiceContent = {Text = "Ah—"},
  Voice_6379_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6380_AwakerVoiceContent = {
    Text = "Güç durmaksızın Dalgalanma halinde, tüm bedenimi dolduruyor..."
  },
  Voice_6380_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6381_AwakerVoiceContent = {
    Text = "Al bakalım! Uç!"
  },
  Voice_6381_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6382_AwakerVoiceContent = {
    Text = "Fena değil. Göründüğün kadar değersiz değilmişsin."
  },
  Voice_6382_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6383_AwakerVoiceContent = {
    Text = "Yirmi, yirmi bir, yirmi dört... Dur, kaçta kalmıştım ben? Bir, iki, üç..."
  },
  Voice_6383_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_6383_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_6384_AwakerVoiceContent = {
    Text = "Önceden elimde kaç malzeme olduğunu sonunda çözdüm, böylece onarımları daha hızlı bitirebilirim—Bir dakika, bunlar nereden çıktı?"
  },
  Voice_6384_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_6384_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_6385_AwakerVoiceContent = {
    Text = "Sayende son zamanlardaki onarımların verimi arttı. Yakında maceraya çıkabileceğiz!"
  },
  Voice_6385_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_6385_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_6386_AwakerVoiceContent = {
    Text = "Sanırım bazı şeyleri hatırlamaya başlıyorum... Dün bana 7 numara bir İngiliz anahtarı vermiş miydin?"
  },
  Voice_6386_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_6386_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_6387_AwakerVoiceContent = {
    Text = "Onarım tamamlandı! Bilinmeyen bir macera, esrarengiz bir dünya, geliyorum!"
  },
  Voice_6387_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_6387_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_6388_AwakerVoiceContent = {
    Text = "Gümbür—"
  },
  Voice_6388_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6389_AwakerVoiceContent = {
    Text = "Kendini kandırma. Zihinsel zincirler de hâlâ zincirlerdir ve adil olarak adlandırılamaz."
  },
  Voice_6389_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_6390_AwakerVoiceContent = {
    Text = "Artık benimle Uyandıran arasındaki çizgi daha da bulanık. Bana iyi bakarsın, değil mi?"
  },
  Voice_6390_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_6390_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_6391_AwakerVoiceContent = {
    Text = "Gidelim. Kurtaracak bir dünyamız var."
  },
  Voice_6391_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_6391_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_6392_AwakerVoiceContent = {
    Text = "\"Türlerin Kökeni\" ni tek seferde okumuş kadar zinde ruh hissettiriyor."
  },
  Voice_6392_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_6392_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_6393_AwakerVoiceContent = {
    Text = "Güçlendim. Bir sonraki görevi tek başıma halletmeyi deneyeyim, olur mu?"
  },
  Voice_6393_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_6393_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_6394_AwakerVoiceContent = {
    Text = "Savaş yeteneğimin dışında, hafızam ve mantıksal düşüncem pek gelişmedi. Gerçekten de, başkaca bir şeye düşünmem için bel bağlamamalıyım."
  },
  Voice_6394_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_6394_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_6395_AwakerVoiceContent = {
    Text = "Hayatlarının altüst edilmesinin, her şeylerini kaybetmelerinin ve Herkes tarafından çiğnenmelerinin nasıl bir his olduğunu tatmalarını istiyorum."
  },
  Voice_6395_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_6395_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_6396_AwakerVoiceContent = {
    Text = "Tahammül ettiğim aşağılanma, kaybettiğim her şey... Bedelini ödeteceğim. Hepsine bedelini ödeteceğim."
  },
  Voice_6396_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_6396_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_6397_AwakerVoiceContent = {
    Text = "Düşmanların kanıyla tatlandırılmış böylesine tatlı bir nefret, kuşkusuz dünyanın en nefis yemeğidir."
  },
  Voice_6397_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_6397_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_6398_AwakerVoiceContent = {
    Text = "Aaah! Bana arkadan sinsice yaklaşma!"
  },
  Voice_6398_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_6399_AwakerVoiceContent = {
    Text = "Yakan alevler göğsümde yanıyor... Evet, asla unutmadım ve asla da unutamam."
  },
  Voice_6399_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_6399_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_6400_AwakerVoiceContent = {
    Text = "Yan, ey şiirin ruhu."
  },
  Voice_6400_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6401_AwakerVoiceContent = {
    Text = "(Mırıldanır)"
  },
  Voice_6401_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6402_AwakerVoiceContent = {
    Text = "(Mırıldanır)"
  },
  Voice_6402_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6403_AwakerVoiceContent = {
    Text = "(Mırıldanır)"
  },
  Voice_6403_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6404_AwakerVoiceContent = {
    Text = "(Mırıldanır)"
  },
  Voice_6404_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_6405_AwakerVoiceContent = {
    Text = "Gıdıklanıyor! Tıpkı hizmetçi tüyle ayak tabanlarımı gıdıkladığında olduğu gibi. Bunu bilerek yapmadın, değil mi?!"
  },
  Voice_6405_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_6405_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_6406_AwakerVoiceContent = {
    Text = "Tatlı bir rüyan olsun."
  },
  Voice_6406_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_6407_AwakerVoiceContent = {
    Text = "Tatlı bir rüyan olsun."
  },
  Voice_6407_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6408_AwakerVoiceContent = {
    Text = "Sükûnet bahşet...!"
  },
  Voice_6408_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_6409_AwakerVoiceContent = {
    Text = "Zarafetle hareket et."
  },
  Voice_6409_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_6410_AwakerVoiceContent = {
    Text = "Beni duyabiliyor musun? Sesimi duy."
  },
  Voice_6410_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_6411_AwakerVoiceContent = {
    Text = "Beni duyabiliyor musun? Sesimi duy."
  },
  Voice_6411_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6412_AwakerVoiceContent = {
    Text = "Yağmur yağıyor. Yağmur her şeyi yıkayıp götürüyor: bozulmuş yiyecekleri, inatçı pisliği ve benim gibi insanları... yani vazgeçilebilir olanları."
  },
  Voice_6412_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_6413_AwakerVoiceContent = {
    Text = "Öç alan azgın gelgit asla dinmez!"
  },
  Voice_6413_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6414_AwakerVoiceContent = {
    Text = "Düşmanlarımın kanında yıkanın!"
  },
  Voice_6414_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6415_AwakerVoiceContent = {Text = "Argh!"},
  Voice_6415_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6416_AwakerVoiceContent = {
    Text = "Buraya bak!"
  },
  Voice_6416_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6417_AwakerVoiceContent = {
    Text = "Beni korkutamazsın."
  },
  Voice_6417_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_6418_AwakerVoiceContent = {Text = "Dikkat et!"},
  Voice_6418_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_6419_AwakerVoiceContent = {
    Text = "Ağıtın dokunmadığı, kederle lekelenmemiş, acıdan azade, ızdırapla yaralanmamış bir dünya... belki erişilmez bir düş, ama ömrüm boyunca peşinden koştuğum ideal bu oldu."
  },
  Voice_6419_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6420_AwakerVoiceContent = {
    Text = "Ebedi Krallık’ın ihtişamına tanık ol!"
  },
  Voice_6420_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_6421_AwakerVoiceContent = {
    Text = "Ebedi Krallık’ın ihtişamına tanık ol!"
  },
  Voice_6421_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6422_AwakerVoiceContent = {
    Text = "Yine usulca Ziyaretlerini sunuyorsun ha? Ne kadar uslu bir {Male=oğlan,Female=kız}."
  },
  Voice_6422_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_6422_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_6423_AwakerVoiceContent = {
    Text = "Acıyor mu?"
  },
  Voice_6423_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6424_AwakerVoiceContent = {
    Text = "Dikkatini toplu tut."
  },
  Voice_6424_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6425_AwakerVoiceContent = {
    Text = "Bin yılların geçişi beni biraz dikkatsiz kıldı."
  },
  Voice_6425_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6426_AwakerVoiceContent = {
    Text = "O gün, kıskançlığın alevleri, tam çiçek açmış kan Kızıl güllerden oluşan bir deniz gibi yayıldı... Tüm şiirler, kızıl ateş dillerinin arasında paramparça Küllere dönüştü."
  },
  Voice_6426_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6426_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6427_AwakerVoiceContent = {
    Text = "Yeni bir teknik öğrendim!"
  },
  Voice_6427_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6428_AwakerVoiceContent = {
    Text = "Dikkatli ol."
  },
  Voice_6428_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_6429_AwakerVoiceContent = {
    Text = "Asam dans etmek istiyor!"
  },
  Voice_6429_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6430_AwakerVoiceContent = {
    Text = "Ah, bu tanıdık boşluk hissi!"
  },
  Voice_6430_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6431_AwakerVoiceContent = {
    Text = "Eklem hareketlerim belirgin biçimde gelişti."
  },
  Voice_6431_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6432_AwakerVoiceContent = {
    Text = "O karanlık varlık, biçimsiz kılıç-kalkanımı hatırlatıyor bana... Ah! Lütfen içiniz rahat olsun, efendim, muhafız kılıcım asla size zarar vermez!"
  },
  Voice_6432_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_6433_AwakerVoiceContent = {Text = "Hadi ama."},
  Voice_6433_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_6434_AwakerVoiceContent = {
    Text = "Sanırım fena değil."
  },
  Voice_6434_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6435_AwakerVoiceContent = {
    Text = "Elimden gelenin en iyisini yapacağım."
  },
  Voice_6435_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6436_AwakerVoiceContent = {
    Text = "Bugün burada mı oynayalım?"
  },
  Voice_6436_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6437_AwakerVoiceContent = {
    Text = "O bodrum su ile doluydu, yumuşak ve soğuk. Bu yüzden bedenim her zaman nemle sarılıydı... Sanki yer ile gök arasında kalan tek fiziksel varlık benmişim gibi. Bazen gerçekten suyun içinde eriyip gitmek isterdim. Ama o zaman var olmazdım ve seninle asla tanışamazdım."
  },
  Voice_6437_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6437_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6438_AwakerVoiceContent = {
    Text = "Sana bir sır vereyim... Aslında kandan nefret ederim. Renginden, tadından tiksiniyorum. Ama onsuz yaşayamıyorum... Kanı yutuyorum, sonra hepsini kusuyorum... Ah, kendimden ne kadar nefret ediyorum."
  },
  Voice_6438_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6438_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_6439_AwakerVoiceContent = {
    Text = "Ah! Kanın... bal şarabı gibi tadı var. Sanırım bu sırrı bilen tek kişi benim, değil mi?"
  },
  Voice_6439_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_6439_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_6440_AwakerVoiceContent = {
    Text = "Hayallerimde cesur bir şövalye beni karanlıktan çekip çıkarır, sonra zincirlerle bağlar. {Male=He,Female=She} bana vurabilir, bana küfredebilir, {Male=he,Female=she} ne isterse yapabilir—acı, yaşadığımın kanıtıdır. Sen... benim şövalyem olur musun?"
  },
  Voice_6440_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6440_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6441_AwakerVoiceContent = {
    Text = "Kan nehir gibi akıyor. Ben seninim. Hiç bu kadar Güçlü hissetmemiştim."
  },
  Voice_6441_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6441_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6442_AwakerVoiceContent = {
    Text = "Bu, Üç İntikam Tanrıçası’nın iradesidir!"
  },
  Voice_6442_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6443_AwakerVoiceContent = {
    Text = "Bıçağım hazır."
  },
  Voice_6443_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_6444_AwakerVoiceContent = {
    Text = "Olmaz öyle şey!"
  },
  Voice_6444_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_6445_AwakerVoiceContent = {
    Text = "Ah, seni pis küçük şey seni!"
  },
  Voice_6445_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_6446_AwakerVoiceContent = {
    Text = "...B-Ben... şimdi görüyorum!"
  },
  Voice_6446_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_6447_AwakerVoiceContent = {
    Text = "...B-Ben... şimdi görüyorum!"
  },
  Voice_6447_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6448_AwakerVoiceContent = {
    Text = "Bahşiş tabii, bahşiş! Şu okul yemekhanesindeki tamamen bihaber garsonlara bak! Şezlongları önceden hazırlamaya bile tenezzül etmiyorlar ama hâlâ fazladan para mı bekliyorlar? Rüya görmeye devam etsinler!"
  },
  Voice_6448_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_6449_AwakerVoiceContent = {Text = "Siyah."},
  Voice_6449_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_6450_AwakerVoiceContent = {
    Text = "Bırakın beni!"
  },
  Voice_6450_AwakerVoiceTitle = {
    Text = "Beceri: Birinci: Mani"
  },
  Voice_6451_AwakerVoiceContent = {
    Text = "Bunu yapma..."
  },
  Voice_6451_AwakerVoiceTitle = {
    Text = "Beceri: Birinci: Depresyon"
  },
  Voice_6452_AwakerVoiceContent = {
    Text = "Nezakete gerek yok, Soluk Haberci. Aramızda hiçbir Bariyer olmamalı; zira ikimiz de Yaratıcı Tanrı’nın yaratımlarıyız ve bu çamurlu, sınayıcı Yol’da birlikte yürüyoruz."
  },
  Voice_6452_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_6452_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_6453_AwakerVoiceContent = {
    Text = "Hayır, onlardan korkmuyorum. Çözünme tarafından işkenceye uğrayan o zavallı Ruh’lar için yalnızca Ağıt duyuyorum. Acılarını onlar adına taşıyamayacağımı biliyorum, ama onlara bir anlık teselli getirecekse, sahip olduğum her şeyi vermeye hazırım."
  },
  Voice_6453_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6453_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6454_AwakerVoiceContent = {
    Text = "Benimle birlikte dua eder misin, Soluk Alev’im? Bugünkü Savaş’ımızda ölenler için dua edelim. Çözünme ve Delilik’le lanetlenmiş olsalar da, hâlâ Yaratıcı Tanrı’nın Çocuklar’ı, bizim kardeşlerimiz. Şimdi hak ettikleri huzuru bulsunlar."
  },
  Voice_6454_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6454_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_6455_AwakerVoiceContent = {
    Text = "Kızıl alevler beni huzursuz etse de, senin için bir kez daha o yanan sehpanın üzerine çıkardım. Buna takılıp kalma, Solgun Alevim. Benim kurbanım, senin getirdiğin lütufların yanında önemsiz."
  },
  Voice_6455_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6455_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6456_AwakerVoiceContent = {
    Text = "Pişmanlık mı? Hayır, elbette hayır. Ölümüm onların acısını hafifletti, onlara biraz daha zaman kazandırdı; bu bana yeter. Ama... madem sen bana karşı dürüst oldun, bunu saklamayacağım: o günkü odun yığınının bıraktığı izler hâlâ kalbimin üstünde."
  },
  Voice_6456_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6456_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6457_AwakerVoiceContent = {
    Text = "Benimle bir sözleşme yapar mısın? Ne olursa olsun, \"\"Ramona\"\"yı hatırlayacağına söz ver."
  },
  Voice_6457_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6457_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6458_AwakerVoiceContent = {
    Text = "Böyle bir şeye dönüşmekten pişman değilim, Koruyucu; yine seçerdim. Ama korkuyorum... eskiden olduğum \"\"Ramona\"\"nın geride hiçbir iz bırakmayacağından korkuyorum."
  },
  Voice_6458_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6458_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6459_AwakerVoiceContent = {
    Text = "Göz bandı görüşümü etkilemiyor. Hatta, fazla şey görmemi engelliyor diyebilirim."
  },
  Voice_6459_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_6459_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_6460_AwakerVoiceContent = {
    Text = "Ben... yabancı mı görünüyorum? Kontrolü elimde tutmaya çalışıyorum. Onun varlığı giderek güçleniyor."
  },
  Voice_6460_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6460_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6461_AwakerVoiceContent = {
    Text = "Çok fazla gizem, kurtarılması gereken çok fazla insan var. Bunu ne kadar sürdürebilirim bilmiyorum... Herkesi koruyamam. Bu zor."
  },
  Voice_6461_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6461_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_6462_AwakerVoiceContent = {
    Text = "Hâlâ bana mı oynayacaksın? Demek ki kaygısız yaşamak göründüğü kadar kolay değil. Merak etme, dertlerini çözeceğim... bol bol molayla."
  },
  Voice_6462_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_6462_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_6463_AwakerVoiceContent = {
    Text = "Demek ağır topları sahaya sürmemiz gerekecek, öyle mi? Olay yeri neresi? Şüpheliyi son teslim tarihinden önce yakalamak için şansımın son zerresini bile yakacağım!"
  },
  Voice_6463_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_6463_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_6464_AwakerVoiceContent = {
    Text = "Off, sana borçlu olduğum lütuf çok, bu sırrı saklayamam: Aslında, belki de dünyadaki en şanssız herif benimdir."
  },
  Voice_6464_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_6464_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_6465_AwakerVoiceContent = {
    Text = "Uyarımı pek ciddiye almamış gibisin... Ah, boşver. Yine de düşmanı lime lime etmene yardım edeceğim. Sonuçta, bu pençeler ve dişler de şans eseri kazanıldı, değil mi?"
  },
  Voice_6465_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_6465_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_6466_AwakerVoiceContent = {
    Text = "Şansım yoldaşlarıma bulaşmayabilir. O sözü bilirsin, değil mi? \"Tavşan ayağı tavşan için pek de uğurlu değildir.\""
  },
  Voice_6466_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_6466_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_6467_AwakerVoiceContent = {
    Text = "Ruhuna kazınmış bu Varlığın mührünü mü arıyorsun?"
  },
  Voice_6467_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6468_AwakerVoiceContent = {
    Text = "Gücümü böylesine umutsuzca mı arzuluyorsun?"
  },
  Voice_6468_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6469_AwakerVoiceContent = {
    Text = "Görünüşüme aldanma; ben de bir zamanlar Soylu Hanımefendi idim... Nakış işlerdim, Tennyson okurdum... Ah, bir de şarkılar söylerdim: “Damarlarımda sonsuz bir nehir gibi akıyor...”"
  },
  Voice_6469_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6470_AwakerVoiceContent = {
    Text = "Pickman’la birlikte büyüleyici bazı yerleştirme işleri üzerinde çalışıyoruz; görsel ilkelciliği yapıbozuma uğratarak soyut temsilciliğin yeniden inşasını araştırıyoruz... Ha? Aurita neden bayıldı ki?"
  },
  Voice_6470_AwakerVoiceTitle = {
    Text = "Sohbet: Aurita Hakkında"
  },
  Voice_6470_UnlockDesc = {
    Text = "\"Aurita\" Uyandıranı edinince açılır"
  },
  Voice_6471_AwakerVoiceContent = {
    Text = "Gülümsememi mi istiyorsun?\nŞu an... gülümsüyor muyum?"
  },
  Voice_6471_AwakerVoiceTitle = {
    Text = "Sohbet: Onun Gülümsemesi Hakkında"
  },
  Voice_6472_AwakerVoiceContent = {
    Text = "Ne sürpriz, denk bir yoldaşlık kazandım.\nAncak... sana emir verme hakkımı saklı tutmak istiyorum, sadece karşılıklı eğlencemiz için. Bu gece odama gel; insan duyarlılıkları hakkında öğrenecek çok şeyim var..."
  },
  Voice_6472_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6472_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6473_AwakerVoiceContent = {
    Text = "Seni en çekici kılan şeyi biliyor musun? Bana \"hayır\" dediğin an. Burnun hafifçe kırışıyor, kaşların belli belirsiz kalkıyor... Evet, tam da böyle."
  },
  Voice_6473_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6473_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6474_AwakerVoiceContent = {
    Text = "Uşaklarımı severim. Çözünme’den titreyip arkamda saklanan şu yakışıklı küçük yaratıklar öylesine sevimli ki. Bir güzelin gözyaşları her zaman büyüleyicidir. Peki ya sen? Çözünme’den korkar mısın?"
  },
  Voice_6474_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6474_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6475_AwakerVoiceContent = {
    Text = "Koruyucu, hoşlanmadığın biri var mı? Bir Lütuf olarak, ona bir ders verebilirim. Bir hafta içinde bambaşka biri olacak, usulca önünde secdeye kapanacak."
  },
  Voice_6475_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6475_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_6476_AwakerVoiceContent = {
    Text = "Hmm... Sıkıcı olsan da tamamen nahoş değilsin. Yarından itibaren bana hizmet edeceksin.\nİstemiyorsun mu...? Ha. Bu bir rica değil; bu bir emirdir."
  },
  Voice_6476_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_6476_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_6477_AwakerVoiceContent = {
    Text = "Uzun zamandır kendimi böyle hissetmemiştim. Sahneye kusursuz bir biçimde çıkacağım ve tüm kozmosu kucaklayan bir şarkıyı yalnız senin için söyleyeceğim."
  },
  Voice_6477_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_6477_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_6478_AwakerVoiceContent = {
    Text = "Bunun bütünüyle anlamsız olduğunu bilmelisin."
  },
  Voice_6478_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_6478_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_6479_AwakerVoiceContent = {
    Text = "Zafer çiçeğini kopardıktan sonra, küçük de olsa bir ödül talep etmek isterim..."
  },
  Voice_6479_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6480_AwakerVoiceContent = {Text = "Ah!"},
  Voice_6480_AwakerVoiceTitle = {
    Text = "Darbe: Depresyon·Üçüncü"
  },
  Voice_6481_AwakerVoiceContent = {
    Text = "Uzay gemisi dardı ve klostrofobikti, sanki uzayda yüzen metal bir tabut gibiydi. Sonsuzluktan beri Sabah Yıldızımı bekliyordum, ta ki sen benim için ortaya çıkana dek."
  },
  Voice_6481_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_6481_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_6482_AwakerVoiceContent = {
    Text = "Bu... nasıl olabilir?!"
  },
  Voice_6482_AwakerVoiceTitle = {
    Text = "Vuruş: Histeri: I"
  },
  Voice_6483_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_6483_AwakerVoiceTitle = {
    Text = "Vuruş: Depresyon: I"
  },
  Voice_6484_AwakerVoiceContent = {Text = "Ah..."},
  Voice_6484_AwakerVoiceTitle = {
    Text = "Darbe: Depresyon·II"
  },
  Voice_6485_AwakerVoiceContent = {
    Text = "İlahi Cezalandırma!"
  },
  Voice_6485_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_6486_AwakerVoiceContent = {
    Text = "İlahi Cezalandırma!"
  },
  Voice_6486_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6487_AwakerVoiceContent = {Text = "Sıkıcı."},
  Voice_6487_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_6488_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_6488_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_6489_AwakerVoiceContent = {
    Text = "Hâlâ dayanabiliyorum."
  },
  Voice_6489_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6490_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_6490_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6491_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_6491_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6492_AwakerVoiceContent = {
    Text = "Saygısız olanlar bu yakıcı dinginlikte Çözünme’ye uğrasın."
  },
  Voice_6492_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_6493_AwakerVoiceContent = {
    Text = "Dikkat et! Elini başka bir Boyut’un uzamına sokarsan, geri alamayabilirsin!"
  },
  Voice_6493_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_6494_AwakerVoiceContent = {
    Text = "Bir avuç beceriksizsiniz. Kıyma hâline gelmek istemiyorsanız, bir dahaki sefere çok daha dikkatli olsanız iyi edersiniz."
  },
  Voice_6494_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6495_AwakerVoiceContent = {
    Text = "Aman, bana karşı sevecen mi davranıyorsun? Bu sorun yaratır. Böyle devam ederse, senin tamamen olgunlaşmanı bekleyemeyeceğim, sevgili {Male=Mr.,Female=Miss} Koruyucum..."
  },
  Voice_6495_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_6496_AwakerVoiceContent = {
    Text = "Özgür iradenin derinliklerine dal!"
  },
  Voice_6496_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6497_AwakerVoiceContent = {
    Text = "Nefret mi? Yarı yolda vazgeçenlerden tiksinirim. Onları düşünmek bile, dünkü yemeği midemden geri sökmek istetiyor."
  },
  Voice_6497_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_6498_AwakerVoiceContent = {
    Text = "Ey sonsuz kafatasları, kendi suretinize bakın!"
  },
  Voice_6498_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6499_AwakerVoiceContent = {
    Text = "Ey sonsuz kafatasları, kendi suretinize bakın!"
  },
  Voice_6499_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_6500_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6500_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6501_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6501_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6502_AwakerVoiceContent = {
    Text = "Bana bu kadar mı güveniyorsun?"
  },
  Voice_6502_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_6502_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_6503_AwakerVoiceContent = {Text = "Geri dön."},
  Voice_6503_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_6504_AwakerVoiceContent = {Text = "Güzel!"},
  Voice_6504_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_6505_AwakerVoiceContent = {
    Text = "Evet, elbette onu tanıyorum. O benim diğer benliğim, başka bir ihtimalim. Ama neden direniyor? Seçilmiş Olan olarak kaderini kabul etse, parmaklarının ucunda dilediği her şeye kavuşmaz mıydı?"
  },
  Voice_6505_AwakerVoiceTitle = {
    Text = "Sohbet: \"Murphy\" Hakkında"
  },
  Voice_6505_UnlockDesc = {
    Text = "Uyanışçı \"Murphy\" edinildiğinde açılır"
  },
  Voice_6506_AwakerVoiceContent = {
    Text = "Merhaba, benim adım Nergis. Bir misafirle takas yaptım, sana yardım etmemi istedi. Öyleyse, neye ihtiyacın olduğunu söyle bakalım.\nAman tanrım... dilediğin şeyin bedeli oldukça yüksek, değil mi?"
  },
  Voice_6506_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6507_AwakerVoiceContent = {
    Text = "Bok herif! Ne yapıyorsun sen?! İster inan ister inanma, elini keserim!"
  },
  Voice_6507_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_6508_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_6508_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6509_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_6509_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_6510_AwakerVoiceContent = {
    Text = "Gül dikenleri parmaklarımı deliyor, kızılı şiire akıyor."
  },
  Voice_6510_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6511_AwakerVoiceContent = {
    Text = "Bu derin ağıt mürekkebinin altında eğil, bir yas şarkısına dönüş..."
  },
  Voice_6511_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_6512_AwakerVoiceContent = {Text = "Şuna bak!"},
  Voice_6512_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6513_AwakerVoiceContent = {Text = "Hmm...!"},
  Voice_6513_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6514_AwakerVoiceContent = {
    Text = "Felaket iniyor!"
  },
  Voice_6514_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6515_AwakerVoiceContent = {
    Text = "Ver onu bana."
  },
  Voice_6515_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6516_AwakerVoiceContent = {
    Text = "Adım, şey, hatırlayamıyorum. Ha, doğru, \"24\", bana böyle diyorlar... Hayır! Dur! Dışarı çıkma! Şimdi olmaz, şimdi çıkamazsın..."
  },
  Voice_6516_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6517_AwakerVoiceContent = {
    Text = "Mürekkep izi, nereye gidiyorsun?..."
  },
  Voice_6517_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_6518_AwakerVoiceContent = {
    Text = "Benim için belirme..."
  },
  Voice_6518_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6519_AwakerVoiceContent = {
    Text = "\"Semavi Ses\" unvanını hak etmiyorum. Sen şarkımı beğendiğin sürece, gerisi önemli değil."
  },
  Voice_6519_AwakerVoiceTitle = {
    Text = "Sohbet: Şarkı Söylemek Hakkında"
  },
  Voice_6520_AwakerVoiceContent = {
    Text = "Ah, elbisem kirlendi. Bir sonraki salondan önce üzerimdekini değiştirmeliyim."
  },
  Voice_6520_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_6521_AwakerVoiceContent = {
    Text = "Bana yetişiyor, o ebedi karanlık... Hiç kimse kaçış bulamaz..."
  },
  Voice_6521_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6522_AwakerVoiceContent = {
    Text = "Seni her gördüğümde, bana vurduğun görünmez zincirleri düşünüyorum. Seni hayatta bırakmak, gösterebileceğim en büyük hoşgörü."
  },
  Voice_6522_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_6523_AwakerVoiceContent = {
    Text = "Kaç kez yeniden Başla’mamız gerekirse gereksin, seninle yan yana yürüyeceğim."
  },
  Voice_6523_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6524_AwakerVoiceContent = {
    Text = "İlahi sevgisi ruhunu ısıtsın."
  },
  Voice_6524_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_6525_AwakerVoiceContent = {
    Text = "Amaçsızca dolaşmaktan hoşlanırım. Bataklıklar, mezarlıklar, revirler, terk edilmiş kaleler... Bu yerlerde daima beklenmedik hazlar bulurum."
  },
  Voice_6525_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6526_AwakerVoiceContent = {
    Text = "Onur duy, çünkü Ebedî Krallık’ın kapıları burada!"
  },
  Voice_6526_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6527_AwakerVoiceContent = {
    Text = "Hehe—çok gıdıklanıyor! Kaçma! Ben de seni kaşımak zorundayım!"
  },
  Voice_6527_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_6528_AwakerVoiceContent = {
    Text = "\"Ölmekte Olan Kuğu\", Dansçı’nın beden diliyle yaşamın özlemini ve mücadelesini aktardığı bir performans. Alevlerin içindeki o çarpılmış siluet de aynı değil mi?"
  },
  Voice_6528_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6529_AwakerVoiceContent = {
    Text = "Kes, kes, paramparça et. Tıpkı onların bana yaptığı gibi... Hehe... HAHAHA!"
  },
  Voice_6529_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_6530_AwakerVoiceContent = {
    Text = "Leydi Thais’e fazla yaklaşmasan iyi edersin... Hayır, kıskanmıyorum. Sadece birinin onun oyunlarına kanmasından korkuyorum."
  },
  Voice_6530_AwakerVoiceTitle = {
    Text = "Sohbet: Thais Hakkında"
  },
  Voice_6530_UnlockDesc = {
    Text = "\"Thais\" Uyandıranı edinince açılır"
  },
  Voice_6531_AwakerVoiceContent = {
    Text = "...Sağ ol."
  },
  Voice_6531_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_6531_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_6532_AwakerVoiceContent = {
    Text = "Pekâlâ… Ehliyetli insanları ayırt etme konusunda keskin bir göze sahipsin."
  },
  Voice_6532_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_6532_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_6533_AwakerVoiceContent = {
    Text = "Memleketim çok güzel! Bir gölün içindeki taş bir şehir. Her dolunayda, alevlerin içinde sessizce dans ederiz, ibadet ederiz... Açıkçası, bu okula ilk geldiğimde her gece evimi özler, yatakta ağlardım. Ama şimdi yeni bir evim ve ailem var. Her şey daha iyiye gidiyor!"
  },
  Voice_6533_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6533_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6534_AwakerVoiceContent = {
    Text = "Oh~ Hâlâ doymadın mı? Yaklaş biraz, sana gerçek hazza nasıl varılacağını öğreteyim~"
  },
  Voice_6534_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_6535_AwakerVoiceContent = {
    Text = "Zayıf kaslar, solgun bir yüz—yalnızca o ölü gibi gözlerde biraz değer var. Örümcekleri beslemek için mükemmeller!"
  },
  Voice_6535_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_6536_AwakerVoiceContent = {
    Text = "T-Teşekkür ederim... yaptığın her şey için. Elimden gelenin en iyisini yapacağım... seni hayal kırıklığına uğratmamak için!"
  },
  Voice_6536_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6537_AwakerVoiceContent = {
    Text = "(Dehşet çığlığı)"
  },
  Voice_6537_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_6538_AwakerVoiceContent = {Text = "Hayır!"},
  Voice_6538_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6539_AwakerVoiceContent = {
    Text = "Beni bundan kurtar..."
  },
  Voice_6539_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6540_AwakerVoiceContent = {
    Text = "(Dehşet çığlığı)"
  },
  Voice_6540_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6541_AwakerVoiceContent = {
    Text = "Bayan Ramona’nın kılıç ustalığı, öğrendiklerimden epey farklı. Eğer efendim izin verirse, kendisiyle talim yapmayı çok isterim... Elbette yalnızca kendi gelişimim için!"
  },
  Voice_6541_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6541_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_6542_AwakerVoiceContent = {
    Text = "Neden diğer Çocuklar ile oynamadığımı soruyorsunuz? Söylemesi zor... Önceki hayatımda oyun oynama fırsatım pek olmazdı. Tek yoldaşım hizmet ettiğim Prenses’ti... Ah! Sizin önünüzde başka bir hükümdardan söz ettim, efendim, bu patavatsızlığımı bağışlayın."
  },
  Voice_6542_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6542_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6543_AwakerVoiceContent = {
    Text = "Mythag Üniversitesi tarafından bir Koruyucu olarak tanınıyorsunuz, bu yüzden size karşılık gelen erişim izinlerini vereceğim."
  },
  Voice_6543_AwakerVoiceTitle = {
    Text = "Sohbet: \"Protagonist\" Hakkında"
  },
  Voice_6544_AwakerVoiceContent = {
    Text = "Öğrendiğim Yedi Şövalye Sanatı ile ilgileniyor musunuz? Bu harika! Aa... ıı... Lütfen az önceki kabalığımı bağışlayın, efendim. Demek istediğim şuydu: Eğer atlı okçuluk çalışmak isterseniz, sizinle talim yapmaktan onur duyarım!"
  },
  Voice_6544_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6544_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6545_AwakerVoiceContent = {
    Text = "Ben layık bir Şövalye değilim. İster o alçak Veba, ister istilacı düşmanlar olsun, eski efendimi koruyamadım. Şimdi, benim gibi birine duyduğunuz güven büyük bir onur... Şövalye onurum ve bu küçük hayatım üzerine yemin ederim ki, ilerleyiş yolunuzu sonsuza dek koruyacağım."
  },
  Voice_6545_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6545_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6546_AwakerVoiceContent = {
    Text = "Zarar verme."
  },
  Voice_6546_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_6547_AwakerVoiceContent = {Text = "Hadi ama~"},
  Voice_6547_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6548_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6548_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_6549_AwakerVoiceContent = {Text = "Öldürme."},
  Voice_6549_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_6550_AwakerVoiceContent = {Text = "Ah, evet~!"},
  Voice_6550_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_6551_AwakerVoiceContent = {
    Text = "Artık sadece su ve yağ gibiyiz. Asla karışmayacağız."
  },
  Voice_6551_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_6552_AwakerVoiceContent = {
    Text = "Özel olarak favori bir şeyim yok. Ama söylemem gerekirse, göreve çıkma hissi oldukça hoş."
  },
  Voice_6552_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6553_AwakerVoiceContent = {
    Text = "Neden, neden beni buraya kilitliyorsunuz? Haha... İstediğinizi alamayacaksınız. Bu kelepçeleri, bu zindanı, parçalara ayıracağım!"
  },
  Voice_6553_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_6554_AwakerVoiceContent = {
    Text = "Lily koruyacak."
  },
  Voice_6554_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6555_AwakerVoiceContent = {
    Text = "Siz yok musunuz, şu sihir gösterisini izlemekten hiç yorulmaz mısınız? Kıpırdamadan oturun, tamam mı? Bir daha sahneye fırlarsanız, sizi başka bir Boyut’a fırlatırım!"
  },
  Voice_6555_AwakerVoiceTitle = {
    Text = "Sohbet: Çocuklar Hakkında"
  },
  Voice_6555_UnlockDesc = {
    Text = "\"Aigis\", \"Jenkin\", \"Lily\", \"Murphy\", \"Karen\" ya da \"Aurita\" Uyananlarından herhangi birini elde ettikten sonra açılır."
  },
  Voice_6556_AwakerVoiceContent = {
    Text = "Cömert hediyeni minnetle kabul edeceğim."
  },
  Voice_6556_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6557_AwakerVoiceContent = {
    Text = "Senin adanmışlığınla boy ölçüşebilecek ne tür bir dönüş armağanı olabilir?"
  },
  Voice_6557_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6558_AwakerVoiceContent = {
    Text = "Ne kadar güzel..."
  },
  Voice_6558_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6559_AwakerVoiceContent = {
    Text = "Yüksek akım tespit edildi, bakım başlatılıyor... Düzeltme: Neden aşırı ısınma yok?"
  },
  Voice_6559_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_6559_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_6560_AwakerVoiceContent = {
    Text = "Son Aydınlanma ritüelinden beri, kış uykusu hâlindeyken parçalanmış görüşler görüyorum. Onlarda, sizinki gibi bir insan bedenine sahibim ve gözlerimden yaşlar akıyor. Bu bir rüya mı?"
  },
  Voice_6560_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_6560_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_6561_AwakerVoiceContent = {
    Text = "Her ritüelden sonra göğüs bölgesinde yüksek düzeyde ısı tespit ediliyor, ancak enerjiyle ilgili hiçbir bileşen yok. Nedenini biliyor musunuz?"
  },
  Voice_6561_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_6561_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_6562_AwakerVoiceContent = {
    Text = "Gördüm. Her şey <Del:ebedi akımda yok olmalı>. Ü-ü-üzgünüm, modül sanki—Uyarı, uyarı. Erica-dışı bilinç etkinliği artıyor. İmha et, imhaetimhaetYOKET... Merhaba, size nasıl yardımcı olabilirim?"
  },
  Voice_6562_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_6562_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_6563_AwakerVoiceContent = {
    Text = "Dikkatli analizden sonra, kış uykusu hâlinde gördüklerimin geleneksel anlamda bir rüya değil, aslında benim <Del:sefil et yığını bedeniniz yok edilmeli> anım olduğunu çıkardım. Aşırı yüklenmeye benzer o yakıcı sıcaklığa gelince, bu \"İsteksizlik\" denen duygu olabilir."
  },
  Voice_6563_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_6563_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_6564_AwakerVoiceContent = {
    Text = "Gösterimi izlemek istiyorsan, seyirciler arasında adam gibi otur!"
  },
  Voice_6564_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_6564_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_6565_AwakerVoiceContent = {
    Text = "Nefretin alevleri şiddetle yanar, asla sönmez."
  },
  Voice_6565_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6567_AwakerVoiceContent = {
    Text = "Kaynaştığım irade epey gürültücü; ne kadar yükselirsem, O’nun sesi o kadar berraklaşıyor... Hyde Park’taki kazlar gibi, durmaksızın cıvıldayan."
  },
  Voice_6567_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_6567_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_6568_AwakerVoiceContent = {
    Text = "Bu Güç'ü, hainleri yutmak için kullanacağım."
  },
  Voice_6568_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6569_AwakerVoiceContent = {
    Text = "...Sağ ol."
  },
  Voice_6569_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6570_AwakerVoiceContent = {
    Text = "Sen, dünyayı kurtaran o çok yüce Koruyucu musun? Gülünç. Uyan artık. Bu düş çoktan bayatladı."
  },
  Voice_6570_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6571_AwakerVoiceContent = {
    Text = "İntikamın kanı kaynıyor..."
  },
  Voice_6571_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6572_AwakerVoiceContent = {
    Text = "Çekil yolumdan, it."
  },
  Voice_6572_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6573_AwakerVoiceContent = {Text = "Boğulma!"},
  Voice_6573_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_6574_AwakerVoiceContent = {Text = "Vuuşş!"},
  Voice_6574_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_6575_AwakerVoiceContent = {
    Text = "Yemekhanenin arka kapısının yanındaki fare tuzaklarını attım. Ya o sakar Brown onlardan birine basarsa?! Fazla tehlikeli!"
  },
  Voice_6575_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_6576_AwakerVoiceContent = {
    Text = "Bu çok tuhaf hissettiriyor... Ölüyor muyum? Hayır, kurtarın beni! Yardım edin! Hayır!!"
  },
  Voice_6576_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_6576_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_6579_AwakerVoiceContent = {
    Text = "Hiç sönmeyen bir lamba istiyorum. Bana, onu \"kanatsız uçan bir hidra\"örneğiyle satın alabileceğimi söyledi... Böyle tuhaf bir türü nerede bulabilirim ki?!"
  },
  Voice_6579_AwakerVoiceTitle = {
    Text = "Sohbet: Nergis Hakkında"
  },
  Voice_6579_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Nergis\" elde edildikten sonra açılır"
  },
  Voice_6582_AwakerVoiceContent = {Text = "Tehlike."},
  Voice_6582_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6583_AwakerVoiceContent = {Text = "Uyarı."},
  Voice_6583_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6584_AwakerVoiceContent = {Text = "Darbe."},
  Voice_6584_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6585_AwakerVoiceContent = {
    Text = "Şeker ambalajları gibi parıldayan bir hazine... Onu büyük bir özenle saklayacağım."
  },
  Voice_6585_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6586_AwakerVoiceContent = {
    Text = "Hasar alındı."
  },
  Voice_6586_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_6587_AwakerVoiceContent = {
    Text = "Dükkânım, evrenin her Boyut’unda, her konumunda var olur ve elbette burada da olabilir. Ayrıca, Mythag’deki o dikkatsiz Çocuklar’ı seviyorum."
  },
  Voice_6587_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_6588_AwakerVoiceContent = {
    Text = "Yeşil biber... iğrenç."
  },
  Voice_6588_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_6589_AwakerVoiceContent = {
    Text = "Seninle ilişkim, yelkenle gemi arasındaki ilişki gibi. Gemi olmadan yelken var olmamalı; yelken olmadan da gemi pek uzağa uzun yolculuk yapamaz. Öyle değil mi?"
  },
  Voice_6589_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_6590_AwakerVoiceContent = {
    Text = "O inançlı Dansçı öldü, sanatın küfürbazı da öldü; ikisi de katran kokulu alevlerde can verdi. Ölüm son değil, başlangıçtır; çünkü yalnızca insanlar ölür, Dans ve sanat ise ebedidir."
  },
  Voice_6590_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6590_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6591_AwakerVoiceContent = {
    Text = "Anlayışın için teşekkür ederim. Belki de şimdi geçmişteki benliğimle barışma vaktidir... Doğru olanı yaptığıma ve ailemin Dans mirasını lekelemediğime inanıyorum. Senin Hazırlan dığın Aşama’ya çıkacak ve dilediğin gibi parlayacağım."
  },
  Voice_6591_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6591_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6592_AwakerVoiceContent = {
    Text = "Dikkatli ol."
  },
  Voice_6592_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_6593_AwakerVoiceContent = {
    Text = "Sahneye çıkıp parlamamamı mı istiyorsun? Bu artık imkânsız. Bu gözler nefret tarafından tüketildi. Yapabildiğim tek şey her şeyi küle çevirmek."
  },
  Voice_6593_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_6593_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_6594_AwakerVoiceContent = {
    Text = "O duyguyu anlıyor musun? Dönmek, dönmek, dönmek, hiç durmadan. Dizler sınırına kadar gerilmiş, parmak uçları siyah Kan akıtma içinde, bale ayakkabılarını sırılsıklam ediyor, yine de tek bir an durmuyor. Sırf, sıradan bir oyuncak olma Kader’ini kabullenmeyi reddettiğim için..."
  },
  Voice_6594_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6594_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_6595_AwakerVoiceContent = {
    Text = "Ne usta saray Dansçılarını, ne zarif bale ustalarını, ne de güzelliği takdir eden Asil’leri yaktım. Ben, bedenini satan işe yaramaz ahmakları, başkalarını hiçe sayan dalkavukları ve şehvette kaybolmuş pis varlıkları yaktım... Beni anlıyorsun, değil mi?"
  },
  Voice_6595_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6595_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6596_AwakerVoiceContent = {
    Text = "Bu sümüksü Dokunaçları sevmiyorum, Derin Denizden de hoşlanmıyorum... Bana öyle bilmiş bilmiş bakma! Ben anne babasından korkan bir çocuk değilim!"
  },
  Voice_6596_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6596_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6597_AwakerVoiceContent = {
    Text = "Cömertliğiniz büyük bir minnetle anılıyor..."
  },
  Voice_6597_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6598_AwakerVoiceContent = {Text = "Kaybol!"},
  Voice_6598_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6599_AwakerVoiceContent = {Text = "Kaybol!"},
  Voice_6599_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_6600_AwakerVoiceContent = {
    Text = "Çabuk, Brown'ı kap ve toz ol!"
  },
  Voice_6600_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6601_AwakerVoiceContent = {Text = "Yapma..."},
  Voice_6601_AwakerVoiceTitle = {
    Text = "Savunma: Depresyon"
  },
  Voice_6602_AwakerVoiceContent = {Text = "Defol!"},
  Voice_6602_AwakerVoiceTitle = {
    Text = "Savunma: Mani"
  },
  Voice_6603_AwakerVoiceContent = {
    Text = "Who is Leigh? Oh, the woman who begged me to beat her up. Haha, interesting... This place isn't boring after all.\nLeigh kim? Ha, bana yalvarıp beni dövmemi isteyen Kadın. Haha, ilginç... Demek ki burası o kadar da sıkıcı değilmiş."
  },
  Voice_6603_AwakerVoiceTitle = {
    Text = "Sohbet: Leigh Hakkında"
  },
  Voice_6603_UnlockDesc = {
    Text = "\"Leigh\" Uyandıranı edinince açılır"
  },
  Voice_6604_AwakerVoiceContent = {
    Text = "Şu küçük tepeden izlediğim gün batımı, sık sık Cleveland’daki günlerimi hatırlatır… Cleveland. Bana bu yaraları veren o yerin adını hâlâ hatırlayabiliyor olmam inanılır gibi değil."
  },
  Voice_6604_AwakerVoiceTitle = {
    Text = "Sohbet: Alacakaranlık Üzerine"
  },
  Voice_6605_AwakerVoiceContent = {
    Text = "Ah... yıldızlar... düştü..."
  },
  Voice_6605_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6606_AwakerVoiceContent = {
    Text = "Hiç şüphesiz, insanlar. İnsanlardan daha kirli bir yaratık var mı?"
  },
  Voice_6606_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_6607_AwakerVoiceContent = {Text = "Şimdi!"},
  Voice_6607_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6608_AwakerVoiceContent = {Text = "Hey!"},
  Voice_6608_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6609_AwakerVoiceContent = {
    Text = "Çözünme mi? Hımm... Evet! Dondurma erir! Ama paylaşırsak, tamamen kremaya dönmeden önce yiyebiliriz!"
  },
  Voice_6609_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_6610_AwakerVoiceContent = {
    Text = "Bu gücü sizi güvende tutmak için kullanacağım."
  },
  Voice_6610_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_6610_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_6611_AwakerVoiceContent = {
    Text = "Ah canım, burada satılan eşyaların iadesi yoktur! Derin Deniz’e dalmak için bir denizaltıya ihtiyacın var, değil mi?"
  },
  Voice_6611_AwakerVoiceTitle = {
    Text = "Sohbet: Caecus Hakkında"
  },
  Voice_6611_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Caecus\" elde edildikten sonra açılır"
  },
  Voice_6612_AwakerVoiceContent = {
    Text = "Ah, işte en iyi Aşama bu! Mythag Üniversitesi’ndeki herkes gösterimin gerçek sihir olduğunu anlıyor! Buna sihirbazın en iyi seyircisi diyor olmalılar, değil mi?"
  },
  Voice_6612_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_6613_AwakerVoiceContent = {
    Text = "Evrenin düzeni burada yer değiştirir; Yıkım’la sonlanan gelecek, sihirbazın öz inancıdır!"
  },
  Voice_6613_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_6613_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_6614_AwakerVoiceContent = {
    Text = "Biraz daha burada kalabilir miyim? Sessiz kalacağım, tek ses çıkarmayacağım ve seni rahatsız etmemek için elimden geleni yapacağım..."
  },
  Voice_6614_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6614_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_6615_AwakerVoiceContent = {
    Text = "Dünyanın sırlarını insan zekâsıyla açığa çıkar!"
  },
  Voice_6615_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6616_AwakerVoiceContent = {
    Text = "Rüyalarımda sık sık gelgitin sesini duyarım; giderek daha da Faint olur. Burada sonsuza dek kalabileceğimi biliyorum, İnsan."
  },
  Voice_6616_AwakerVoiceTitle = {
    Text = "Sohbet: Aequor Hakkında"
  },
  Voice_6617_AwakerVoiceContent = {
    Text = "Daha çok Anı, daha çok duygu, daha çok Rüya—"
  },
  Voice_6617_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_6617_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_6618_AwakerVoiceContent = {
    Text = "Sihir zamanı!"
  },
  Voice_6618_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6619_AwakerVoiceContent = {
    Text = "Gözünü kırpma!"
  },
  Voice_6619_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_6620_AwakerVoiceContent = {
    Text = "O bir kez doğdu mu... Artık böyle bir aşağılanmaya tahammül etmek zorunda kalmayacağım..."
  },
  Voice_6620_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6621_AwakerVoiceContent = {
    Text = "Beni seç, beni seç! Nerede parti varsa, orada Karen vardır!"
  },
  Voice_6621_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6622_AwakerVoiceContent = {
    Text = "Hımm? Benimle mi ilgileniyorsun? Öyleyse sanırım... bedelini ödemeye de hazırsın?"
  },
  Voice_6622_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_6623_AwakerVoiceContent = {
    Text = "Merhamet yok, merhamet yok...!"
  },
  Voice_6623_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6624_AwakerVoiceContent = {
    Text = "Hâlâ Uzaydan Gelen Ana Renk’i söylüyorum..."
  },
  Voice_6624_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6625_AwakerVoiceContent = {
    Text = "Söyle, benim için ilahi söyle!"
  },
  Voice_6625_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_6626_AwakerVoiceContent = {
    Text = "Anne’yi seviyorum!"
  },
  Voice_6626_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6627_AwakerVoiceContent = {Text = "Hadi ama."},
  Voice_6627_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_6628_AwakerVoiceContent = {
    Text = "Dikkatli ol."
  },
  Voice_6628_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_6629_AwakerVoiceContent = {
    Text = "Uyandıranlar meraktan yiyip içebilir, fakat besin varoluşumuz için şart değildir. Bu yüzden her ikindi çayı için beni çağırmana gerek yok. Şeker alımı, bu bedenin bilyeli eklemlerinin yıpranmasını yalnızca hızlandırıyor."
  },
  Voice_6629_AwakerVoiceTitle = {
    Text = "Sohbet: İkindi Çayı Üzerine"
  },
  Voice_6632_AwakerVoiceContent = {
    Text = "Lütfen, Efendimi bağışlayın. K-Karen’le ne isterseniz yapın!"
  },
  Voice_6632_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6633_AwakerVoiceContent = {
    Text = "Bunlar... benim için mi? Yiyebilir miyim? Gerçekten mi?"
  },
  Voice_6633_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_6633_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_6634_AwakerVoiceContent = {
    Text = "Neden... nefret ederim? Söyleyebilir miyim? Kendimden nefret ediyorum, bu kadar işe yaramaz olduğum için... Ama bunu söylersem Jenkin gerçekten çok kızacak..."
  },
  Voice_6634_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_6635_AwakerVoiceContent = {
    Text = "Küllere dön."
  },
  Voice_6635_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_6636_AwakerVoiceContent = {
    Text = "Küllere dön."
  },
  Voice_6636_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6637_AwakerVoiceContent = {
    Text = "Well done, Keeper. So, who am I killing this time?\nİyi iş çıkardın, Koruyucu. Peki, bu sefer kimi öldürüyorum?"
  },
  Voice_6637_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_6637_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_6638_AwakerVoiceContent = {
    Text = "Çözünme, bu akademinin kuruluş sebebi ve bizim karşılaşma nedenimiz. İnsanlığın Işığı’nı Çözünme’den kurtarmak için elimizden geleni yapalım, ortak."
  },
  Voice_6638_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_6639_AwakerVoiceContent = {
    Text = "O kız çocuğunun düşmanlığını hissedebiliyorum; sana olan sevgim onun kıskançlığının ateşini yaktı... Bak, şu kambur balina bile kıskançlıktan ağzı açık kalmış."
  },
  Voice_6639_AwakerVoiceTitle = {
    Text = "Sohbet: Lotan Hakkında"
  },
  Voice_6639_UnlockDesc = {
    Text = "\"Lotan\" Uyandıranı edinince açılır"
  },
  Voice_6640_AwakerVoiceContent = {
    Text = "Efendim, Efendim! Karen bugün Harold’da inanılmaz güzel bir kabartma broş gördü! Onu Karen’e alır mısınız? Bu, hayat boyu tek dileğim!"
  },
  Voice_6640_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6641_AwakerVoiceContent = {
    Text = "Karanlıkta senin Kılavuz Işığın olacağım, ama sonsuza dek değil."
  },
  Voice_6641_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_6642_AwakerVoiceContent = {
    Text = "Anne... Acıyor... Anne..."
  },
  Voice_6642_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6643_AwakerVoiceContent = {
    Text = "Teslim ol! Zafer zaten benim!"
  },
  Voice_6643_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_6644_AwakerVoiceContent = {
    Text = "Teslim ol! Zafer zaten benim!"
  },
  Voice_6644_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6645_AwakerVoiceContent = {
    Text = "Çözünme... Ee, beyin kapasitem sınırlı, böyle karmaşık hastalıkları kavrayamıyorum... Eğer tamir edilmesi gereken bir makine varsa, beni bul!"
  },
  Voice_6645_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_6646_AwakerVoiceContent = {
    Text = "Ah hayır! Bulundum! Kaybetme cezası olarak benden bir dilekte bulunabilirsin—yeter ki beni derse yollama, ne olur!"
  },
  Voice_6646_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_6647_AwakerVoiceContent = {
    Text = "Onun görkemli Dönüşü için yolu açmak..."
  },
  Voice_6647_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6648_AwakerVoiceContent = {
    Text = "Bir gün Ornn Amca beni su altındaki yurduma geri götürecek. O zamana dek, istemeye istemeye de olsa arkadaşın olabilirim."
  },
  Voice_6648_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6648_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6649_AwakerVoiceContent = {
    Text = "\"Ailemiz büyük bir soy taşır; seçilmiş olan, derin denizde sonsuz huzurun tadını çıkaracaktır.\" Bu huzuru denizi terk edip akademiye geldikten sonra hissedeceğimi hiç beklemezdim. Sen bana zorbalık edenlerden farklısın, bu yüzden başkalarının sana zorbalık etmesine de izin vermeyeceğim."
  },
  Voice_6649_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6649_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6650_AwakerVoiceContent = {
    Text = "Süper dayanıklı, özel yapım malzeme!"
  },
  Voice_6650_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6651_AwakerVoiceContent = {
    Text = "Bu yarı-insan kabuk gerçekten... tiksindiriyor beni. Nihayet geçmişimden kurtulmuştum, şimdi onu yeniden hatırlamak zorundayım..."
  },
  Voice_6651_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_6651_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_6652_AwakerVoiceContent = {
    Text = "Büyük kan soyunun varisinin bir insana hizmet edecek kadar alçalacağını kim düşünürdü... Hıh. Beni istediğin gibi yönlendirebileceğini sanma."
  },
  Voice_6652_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6652_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_6653_AwakerVoiceContent = {
    Text = "Hıh, sen zayıf insanın komuta konusunda biraz yeteneğin var... bu aşağılık kabuk olmasaydı sana gerçek gücümü gösterirdim."
  },
  Voice_6653_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6653_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6654_AwakerVoiceContent = {
    Text = "Vücudum ısınıyor."
  },
  Voice_6654_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6655_AwakerVoiceContent = {
    Text = "Koş... Koşmalıyım! Buradan uzaklaş!"
  },
  Voice_6655_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6656_AwakerVoiceContent = {
    Text = "Koş... Koşmalıyım! Buradan uzaklaş!"
  },
  Voice_6656_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_6657_AwakerVoiceContent = {
    Text = "Çabaların için teşekkür ederim. İzin ver, seni aynı ölçüde ödüllendireyim."
  },
  Voice_6657_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6658_AwakerVoiceContent = {
    Text = "Katlanılabilir."
  },
  Voice_6658_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6659_AwakerVoiceContent = {
    Text = "(Yumuşak, bastırılmış bir nefes alış)"
  },
  Voice_6659_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6660_AwakerVoiceContent = {
    Text = "Frail human, your conviction is sufficient. I will be your weapon. Let's carve out some chaos together!\nZayıf insan, kararlılığın yeterli. Ben senin silahın olacağım. Hadi birlikte biraz Kaos oyup çıkaralım!"
  },
  Voice_6660_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6660_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6662_AwakerVoiceContent = {
    Text = "Burası BENİM salonum."
  },
  Voice_6662_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6664_AwakerVoiceContent = {
    Text = "Herkesin eşit muamele gördüğü bir okul... Ne tür aptalca Rüyalar besliyorsun acaba. Hiçbir yanlış yapmamış olsan bile, yine de seni ayakları altında çiğneyecekler. O duyguyu bilirim."
  },
  Voice_6664_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_6665_AwakerVoiceContent = {
    Text = "Bu, Kirliliğin Kaynağı..."
  },
  Voice_6665_AwakerVoiceTitle = {
    Text = "Taşkınlık: Depresyon"
  },
  Voice_6666_AwakerVoiceContent = {
    Text = "Denizcileri koruyamadığım için cezalandırıldım; ailelerine sonsuza dek kayboldular. Beni bu trajedinin baş suçlusu ilan ettiler... Çözünme dedikleri şey bu mu?"
  },
  Voice_6666_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_6667_AwakerVoiceContent = {
    Text = "Daha yakın... Efendime her an daha yakın..."
  },
  Voice_6667_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6668_AwakerVoiceContent = {
    Text = "Neden? Efendim, neden hâlâ... uyanışa direniyorsunuz?"
  },
  Voice_6668_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6669_AwakerVoiceContent = {
    Text = "Ben Cité’den Horla’yım, müstear adım ise... Ah, affedin, kimseye açıklamama dair bir söz verdim. En içten özrümle, lütfen, bana yalnızca Horla diye hitap edin."
  },
  Voice_6669_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6670_AwakerVoiceContent = {
    Text = "Ben her türlü adaletsizliğe karşıyım; ihanet en kötüsüdür. Orduda, eğer yoldaşlarının sırtını koruyacağına güvenemezsen ya da buna cesaret edemezsen, tüm birlik dağılır."
  },
  Voice_6670_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_6671_AwakerVoiceContent = {
    Text = "Neden bu kadar karanlık görünüyorsun da aynı zamanda bu kadar parlaksın...? Hayır, boş ver, saçmalamalarımı görmezden gel."
  },
  Voice_6671_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_6672_AwakerVoiceContent = {Text = "(İniltı)"},
  Voice_6672_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_6673_AwakerVoiceContent = {
    Text = "(İniltiden boğuk bir homurtu)"
  },
  Voice_6673_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6674_AwakerVoiceContent = {Text = "Ne?!"},
  Voice_6674_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6675_AwakerVoiceContent = {
    Text = "Tüm yaşamları seviyorum. Işığı seviyorum. Faint'in kendi kabuğundan Belirmesini ve dünyayı kendi Gözleri ve kulaklarıyla deneyimlemesini istiyorum."
  },
  Voice_6675_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6676_AwakerVoiceContent = {
    Text = "Beni göremezsin!"
  },
  Voice_6676_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_6677_AwakerVoiceContent = {
    Text = "Bakım çalışmasının sürmesi gerekiyor mu?"
  },
  Voice_6677_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6678_AwakerVoiceContent = {
    Text = "Parça bakımı tamamlandı."
  },
  Voice_6678_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6679_AwakerVoiceContent = {
    Text = "İnsanlar ihanet edebilir, ama araçlar asla etmez. Doğru kullanıldığında, Çözünme de bir intikam aracı hâline gelebilir."
  },
  Voice_6679_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_6680_AwakerVoiceContent = {
    Text = "Bu an nihayet geldi, binlerce yıllık Bekleyiş’in ardından… Ben, Filistin’in biricik hükümdarıyım!"
  },
  Voice_6680_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_6680_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_6681_AwakerVoiceContent = {
    Text = "Az önce yanından geçtiğimiz o, melez bir Derin Varlık mıydı? Hmm... Şu kasılmış duruşuna bak. Bu gece, o güzel küçük sırtını nasıl kavis verip önümde sürüneceğini göreceğim."
  },
  Voice_6681_AwakerVoiceTitle = {
    Text = "Sohbet: Caecus Hakkında"
  },
  Voice_6681_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Caecus\" elde edildikten sonra açılır"
  },
  Voice_6682_AwakerVoiceContent = {
    Text = "Gücümü geri kazanıyorum… Sırada, hakkım olan Hükümranlık’ı geri almak var!"
  },
  Voice_6682_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_6682_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_6683_AwakerVoiceContent = {
    Text = "Fena değil. O ikiyüzlü kadının peçesini yırtıp atmaya bir adım daha yaklaştık."
  },
  Voice_6683_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_6683_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_6684_AwakerVoiceContent = {
    Text = "Sakin ol, sakin ol..."
  },
  Voice_6684_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_6685_AwakerVoiceContent = {
    Text = "Endişelenmenize gerek yok. Pain eşiğim hayal gücünüzün çok ötesinde olabilir."
  },
  Voice_6685_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_6685_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_6686_AwakerVoiceContent = {
    Text = "Bana sorarsan, en iyisi güzel ahmaklardır. Ne yazık ki buralarda fazlasıyla çok, işe yaramaz ama kurnaz zihin var."
  },
  Voice_6686_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_6687_AwakerVoiceContent = {
    Text = "Kırmızı bir devin nükleer füzyonuyla beslenip çöken bir yıldızın enerjisiyle desteklenirse, bir devridaim makinesi çalıştırabilir ve ebedî bir lamba yakabilirsin... Ha? Burada devridaim makinesi kurmanın imkânsız olduğunu, kırmızı dev de olmadığını mı söylüyorsun? Hımm..."
  },
  Voice_6687_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6688_AwakerVoiceContent = {
    Text = "Düşmanın kanı henüz tamamen tükenmedi."
  },
  Voice_6688_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_6689_AwakerVoiceContent = {
    Text = "Kurban! Her şeyi... bana kurban edin!"
  },
  Voice_6689_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6690_AwakerVoiceContent = {
    Text = "Kurban! Her şeyi... bana kurban edin!"
  },
  Voice_6690_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6691_AwakerVoiceContent = {
    Text = "Savaş alanına gitme vakti!"
  },
  Voice_6691_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6692_AwakerVoiceContent = {
    Text = "Zamanı geldi!"
  },
  Voice_6692_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_6693_AwakerVoiceContent = {
    Text = "Uykum rüyaları zehir gibi sızdırır. Ben uyurken yaklaşma—ve beni asla sebepsiz yere uyandırma."
  },
  Voice_6693_AwakerVoiceTitle = {
    Text = "Sohbet: Hafif Uyku Hakkında"
  },
  Voice_6694_AwakerVoiceContent = {
    Text = "Zamanı geldi!"
  },
  Voice_6694_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6695_AwakerVoiceContent = {
    Text = "Herbert korkunç bir insan olsa da kedileri çok uysal... Daha doğrusu, iki kedi var, değil mi?"
  },
  Voice_6695_AwakerVoiceTitle = {
    Text = "Sohbet: Herbert Hakkında"
  },
  Voice_6695_UnlockDesc = {
    Text = "Ana Hikâye 2. Bölüm tamamlandıktan sonra açılır"
  },
  Voice_6696_AwakerVoiceContent = {
    Text = "Şu Murphy denen kadın çok cafcaflı giyiniyor... Olmaz, Karen ona yenilmez! Ya da belki, onu öldürürüm..."
  },
  Voice_6696_AwakerVoiceTitle = {
    Text = "Sohbet: Murphy Hakkında"
  },
  Voice_6696_UnlockDesc = {
    Text = "Uyanışçı \"Murphy\" edinildiğinde açılır"
  },
  Voice_6697_AwakerVoiceContent = {Text = "Ah..."},
  Voice_6697_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6698_AwakerVoiceContent = {
    Text = "Bu hoşuna gidiyor mu?"
  },
  Voice_6698_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6699_AwakerVoiceContent = {
    Text = "Mythag Üniversitesi ile ortaklık kurduğumda, açıkça savaşa gönderilmeyeceğim belirtilmişti..."
  },
  Voice_6699_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_6699_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_6700_AwakerVoiceContent = {
    Text = "Kendini fazla kaptırma. Bazen asille aşağılık arasındaki sınır, yalnızca tek bir adımdır."
  },
  Voice_6700_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_6700_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_6701_AwakerVoiceContent = {
    Text = "Faros seni selamlıyor. Beni buraya çağırmış olman, yelken açmaya hazır olduğun anlamına geliyor olmalı."
  },
  Voice_6701_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6702_AwakerVoiceContent = {
    Text = "Yuhuu—çok yoruldum, artık gidip oynayabilir miyim!"
  },
  Voice_6702_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_6703_AwakerVoiceContent = {
    Text = "Ah... Parıltısı öyle yoğun, öyle göz kamaştırıcı ki, görmezden gelmek imkânsız! Duyularımı bulandıran aptalca bir coşkuydu bu... Hayır, kendi ahmaklığıma dair hiçbir mazeret öne sürmeyeceğim..."
  },
  Voice_6703_AwakerVoiceTitle = {
    Text = "Sohbet: Tulu Hakkında"
  },
  Voice_6703_UnlockDesc = {
    Text = "\"Tulu\" Uyandıranı edinince açılır"
  },
  Voice_6705_AwakerVoiceContent = {
    Text = "Benim uyuyan yıldızlarımın düşleri şimdi kıpırdanıyor—bırak, yazgılı kaderlerine doğru birleşsinler. Yolunu İlahi Âlem’e çevir!"
  },
  Voice_6705_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6706_AwakerVoiceContent = {
    Text = "Her şeyi sonuna itmenin, evrenin dönen dişlilerini durdurmanın büyüleyici olduğunu düşünmüyor musun?"
  },
  Voice_6706_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6707_AwakerVoiceContent = {
    Text = "Hepsini iç!"
  },
  Voice_6707_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6708_AwakerVoiceContent = {Text = "Harika!"},
  Voice_6708_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6709_AwakerVoiceContent = {
    Text = "Savaş komutunu gir."
  },
  Voice_6709_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6710_AwakerVoiceContent = {
    Text = "Yıldızların Arasında sürüklendiğim günlerde, bu anı sayısız kez rüyamda gördüm... Beni Tinktur’la yeniden birleştirdiğin için teşekkür ederim."
  },
  Voice_6710_AwakerVoiceTitle = {
    Text = "Sohbet: Tinktur Hakkında"
  },
  Voice_6710_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Tinct\" elde edildikten sonra açılır"
  },
  Voice_6711_AwakerVoiceContent = {
    Text = "Mythag Üniversitesi harika bir yer, özellikle her hafta ortaya çıkan yeraltı kumarhanesiyle...\nDur, bilmiyor muydun? Hay aksi, ağzımdan kaçırdı."
  },
  Voice_6711_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_6712_AwakerVoiceContent = {
    Text = "\"Çözünme krizine diren\"... Ha. İnsan kibri beni asla eğlendirmekten vazgeçmiyor."
  },
  Voice_6712_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_6713_AwakerVoiceContent = {
    Text = "Sonuçta insanlar yalnızca sığ yaratıklardır. Birkaç söz, küçük bir ima ve hemen birbirleriyle kavga etmeye başlarlar... Ah, bu düzeydeki çatışma ilham vermeye bile yetmiyor."
  },
  Voice_6713_AwakerVoiceTitle = {
    Text = "Sohbet: İnsanlar Hakkında"
  },
  Voice_6714_AwakerVoiceContent = {
    Text = "Belki de seni yalnızca bir ölümlü diye küçümsemekte acele ettim. Lütufla dokunulmamış biri nasıl hâlâ amacına tutunur? Bu, Denizlerin Kutsal Anası’nın değil, Miryam’ın merakı. Bana... eşlik eder misin?"
  },
  Voice_6714_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6714_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6715_AwakerVoiceContent = {
    Text = "\"Senin kadar olağanüstü biri, bu gelip geçici, çalkantılı dünyadan nasıl bıkmasın? Hak ettiğin yurdu ebedi âlemde bulacaksın. Orada ayakların kutsal toprağı öpecek, nefeslerin mukaddes sularda tazelenecek ve ruhun lütuflanmış toprakta serpilecek... Benimle birlikte bu kutsal Hac Yolculuğu'na katılacaksın. Benimle birlikte bu kutsal Hac Yolculuğu'na katıl. Birlikte ölümlü sınırların çok ötesine yükseleceğiz, ta ki Taht'ın huzurunda birleşip, ışığında olgunlaşmış sevinci tadana dek...\""
  },
  Voice_6715_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_6715_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_6716_AwakerVoiceContent = {
    Text = "Hepimiz toz içinde kıvranan sefil ölümlüleriz, fakat Bilge ayrı yürür. O, Elçi’dir, ilahi bir Tecessüd. Öğüdü, tanrıların sesleriyle yankılanır, çelimsiz uygarlığımızı ölümsüzlüğe doğru sürükler… Şimdi senin kof zihninin adanmışlığı kavramasını beklemiyorum, ama bir gün sen de O’nun tahtı önünde diz çökeceksin."
  },
  Voice_6716_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6716_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_6717_AwakerVoiceContent = {
    Text = "Seçilmişler gerçekten de Lütuflanmış, sence de öyle değil mi? Etleri, Onun kutsal iradesiyle yeniden biçimlendirildi, yaşamları fanilerin ölçüsünü aştı. O kıyıya adım attığında, onlar da Onun korosu olarak yükselecek. Kum taneleri kadar zayıf faniler için bundan daha tatlı, bundan daha yüce bir mutluluk olabilir mi?"
  },
  Voice_6717_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6717_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6718_AwakerVoiceContent = {
    Text = "Onun ihtişamıyla aydınlanmanın vecdi, imansız kavrayışının çok ötesinde... Merhametiyle, körlüğünü ve küstahlığını bağışlasın."
  },
  Voice_6718_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_6718_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_6719_AwakerVoiceContent = {
    Text = "Hızlıca bitirelim, Koruyucu."
  },
  Voice_6719_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6720_AwakerVoiceContent = {Text = "Ehe!"},
  Voice_6720_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_6720_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_6721_AwakerVoiceContent = {
    Text = "Ölmeye hazırlan, Spartalı haşere."
  },
  Voice_6721_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6722_AwakerVoiceContent = {
    Text = "Bayan Bebek, bedenimi onun gibi terk edersem Çözünme’den bir süreliğine kaçınabileceğimi söylüyor... Hayır, yapamam! Yapamam! İşlem sırasında bilincimi kaybedeceğim ve karanlık her şeyi ele geçirecek!"
  },
  Voice_6722_AwakerVoiceTitle = {
    Text = "Sohbet: Doll Hakkında"
  },
  Voice_6722_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Doll\" elde edildikten sonra açılır"
  },
  Voice_6723_AwakerVoiceContent = {
    Text = "Hıh. Bu sefer ne var? Yok oluş kaderini kucaklamaya şimdi hazır mısın?"
  },
  Voice_6723_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_6724_AwakerVoiceContent = {
    Text = "Hâlâ uykusuzluk mu çekiyorsunuz, Efendim? Sizin için Dobie’nin sakinleştiricisini hazırladım~! Dozu biraz yüksek olabilir ama, iyi bir uyku her şeyden önce gelir!"
  },
  Voice_6724_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_6724_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_6725_AwakerVoiceContent = {
    Text = "İçip şarkı söylüyorduk ki birden canavara dönüştük! Ama sorun değil, şu yeşilimsi ten rengi epey eğlenceli!"
  },
  Voice_6725_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_6725_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_6726_AwakerVoiceContent = {
    Text = "Rüyam mı? Hmm... Güzel bir inci kolye alıp onu bir baloda takmak. Sonra herkesin dikkatinin merkezinde ben olacağım!"
  },
  Voice_6726_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_6726_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_67276_AwakerVoiceContent = {
    Text = "Arzu Eonu, Tifere Yesod, hayatta kalmanın yolunu buldu. Bilinmeyen Yaratık’la yüz yüze gelindiğinde, hiç kimse yöntemlerinin soyluluğunu ya da bayağılığını yargılayamaz."
  },
  Voice_67276_AwakerVoiceTitle = {
    Text = "Sohbet: Arzu Eonu Hakkında"
  },
  Voice_67276_UnlockDesc = {
    Text = "\"Thais\" Uyandıranı edinince açılır"
  },
  Voice_67277_AwakerVoiceContent = {
    Text = "Gümüş Anahtar Kapısı’ndan geç ve Onların Tahtı’na eriş."
  },
  Voice_67277_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_67278_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_67279_AwakerVoiceContent = {
    Text = "Onların Bilgi ve Anılarının israf olmasına izin verme."
  },
  Voice_67279_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6727_AwakerVoiceContent = {
    Text = "Sola süpür, sağa sil, hadi tozu ve kaygıları silelim~!"
  },
  Voice_6727_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_6727_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_67280_AwakerVoiceContent = {
    Text = "Burada değilim."
  },
  Voice_67280_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_67281_AwakerVoiceContent = {
    Text = "Sonsuz uzay-zaman sürekliliğinden bir Parça, bilincimin sınırlarına varıyor."
  },
  Voice_67281_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_67282_AwakerVoiceContent = {
    Text = "Bütünü gördüm."
  },
  Voice_67282_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_67283_AwakerVoiceContent = {
    Text = "Her şey hiçliğin içinde var olur."
  },
  Voice_67283_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_67284_AwakerVoiceContent = {
    Text = "Çok derine, çok ama çok derine indin. Yakında olağanüstü bir mucizeye tanık olacaksın. Umarım şu anki kadar aklı başında ve sakinsin."
  },
  Voice_67284_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_67284_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_67285_AwakerVoiceContent = {
    Text = "Ben... \"Cehalet\" ten nefret ediyorum. Hayır, azimle nihai hakikati aramak cehalet değildir. Gerçek cehalet, neyi bilmediğinin farkında olmadan, bir sisin içinde yaşamaktır."
  },
  Voice_67285_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_67286_AwakerVoiceContent = {
    Text = "Sana rüyalarımı göstereceğim. Gördüğün her tuhaf ve kaotik şey, bildiğin gerçeklikten çok daha fazla bu dünyanın hakiki doğasına yakındır."
  },
  Voice_67286_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_67286_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_67287_AwakerVoiceContent = {
    Text = "Sana tavsiyem şu: Sakin kal. Yorulduğunu hissettiğinde hemen dur ve gücünü muhafaza et. Aksi halde rüya diyarında sonsuza dek kaybolursun."
  },
  Voice_67287_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_67287_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_67288_AwakerVoiceContent = {
    Text = "Evren sonsuz döngülerle devinir."
  },
  Voice_67288_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_67289_AwakerVoiceContent = {
    Text = "Aramızdaki senkronizasyon bu kadar uzun bir ayarlama gerektirmemeli. Yine de, seni düşlerden koruyup zihninin berraklığını muhafaza etmek için yavaş ilerleyeceğim."
  },
  Voice_67289_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_67289_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_6728_AwakerVoiceContent = {
    Text = "Çözünme... Ona değen bir dava üzerinde çalışmıştım. Ama ortadan kaybolmak epey doğal görünmüyor mu? Sonunda herkes yok olur."
  },
  Voice_6728_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_67290_AwakerVoiceContent = {
    Text = "Birinci Kapı. Sonsuz evren, tek bir noktadan doğdu."
  },
  Voice_67290_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_67290_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_67291_AwakerVoiceContent = {
    Text = "İkinci Kapı. Bir noktadan bir çizgi uzanır, sonsuz kutuplara doğru gerilir."
  },
  Voice_67291_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_67291_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_67292_AwakerVoiceContent = {
    Text = "Dördüncü Kapı. Ebedi arketip, Boyut dolu bir uzamda katılaşır."
  },
  Voice_67292_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_67292_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_67293_AwakerVoiceContent = {
    Text = "Üçüncü Kapı. Düzlemler, eksik ve tek yanlı kurgulardır."
  },
  Voice_67293_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_67293_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_67294_AwakerVoiceContent = {
    Text = "Son Sınırın Kapısı. Sayısız evreni birbirine bağlayan nihai hiçlik. İçinden geç, dünyanın sırları sana açılacak."
  },
  Voice_67294_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_67294_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_67295_AwakerVoiceContent = {
    Text = "Beşinci Kapı. Zamanın akışı yalnızca bir düş; ne bir başlangıç olmuştur, ne de bu yüzden bir son vardır."
  },
  Voice_67295_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_67295_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_67296_AwakerVoiceContent = {
    Text = "Ben yalnızca senin rehberin olmalı, seni bu yolculukta önderlik edip sonra düşsel sulara dönüp dinlenmeliydim. Şimdi ise sen benim Bağlayıcımsın ve aramızdaki bağ öylesine girift ki koparmak güç."
  },
  Voice_67296_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_67297_AwakerVoiceContent = {
    Text = "Bir şeyleri teyit etmek mi istiyorsun? Bu bedenin duyuları fazlasıyla kısıtlı. Uçurum’da karşılaşırsak sana çok daha fazlasını gösterebilirim."
  },
  Voice_67297_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_67298_AwakerVoiceContent = {
    Text = "O, ebediyen yok edilmiş başka bir boyuttan benim bir Parçam. Ne yazık ki, zaman akışı tersine dönüşü ustalıkla kavrasa da, uzay-zamanı aşmanın özünü idrak edemedi ve tekrar tekrar ızdıraba yenik düştü. Bu benim suçum."
  },
  Voice_67298_AwakerVoiceTitle = {
    Text = "Sohbet: Ramona Hakkında: Zaman Aşınmış"
  },
  Voice_67298_UnlockDesc = {
    Text = "Uyandırmaçı \"Ramona: Zaman Aşınmış\" elde edildikten sonra açılır"
  },
  Voice_67299_AwakerVoiceContent = {Text = "Biliyorum."},
  Voice_67299_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6729_AwakerVoiceContent = {
    Text = "Şimdiki gemimin görünüşünü merak ediyor gibisin? Fazla kurcalama. Ben doğuştan insan yüzüyle geldim."
  },
  Voice_6729_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_67300_AwakerVoiceContent = {
    Text = "Anlıyorum."
  },
  Voice_67300_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_67301_AwakerVoiceContent = {Text = "Önemsiz."},
  Voice_67301_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_67302_AwakerVoiceContent = {
    Text = "Soğukkanlılığını koru."
  },
  Voice_67302_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_67303_AwakerVoiceContent = {
    Text = "Bir Aeon’la doğrudan bağ kurmak zihnine zarar verir. Yine de ısrar ettiğine göre, çağrına karşılık vereceğim."
  },
  Voice_67303_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_67304_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_67305_AwakerVoiceContent = {
    Text = "O çocuk, içinde taşıdığı benim Parçam yüzünden fazlasıyla tahammül etmek zorunda kaldı. Neyse ki ruhu hâlâ akan gümüş kadar berrak."
  },
  Voice_67305_AwakerVoiceTitle = {
    Text = "Sohbet: Ramona Hakkında"
  },
  Voice_67305_UnlockDesc = {
    Text = "\"Ramona\" Uyandıranı edinince açılır"
  },
  Voice_67306_AwakerVoiceContent = {
    Text = "Onların Rüyası’nı ziyaret et ve evrenin yasaklı sırlarına göz at."
  },
  Voice_67306_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_67307_AwakerVoiceContent = {Text = "Hımm."},
  Voice_67307_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_67308_AwakerVoiceContent = {
    Text = "Son Sınırın Kapısı senin için açılıyor. Ötesindeki ölümcül sessizlik dünyasını kucakla."
  },
  Voice_67308_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_67308_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_67309_AwakerVoiceContent = {
    Text = "Ben onlara yalnızca bu \"Depo\" kurumunu kurmalarında yardım ettim. Okul, beklediğimden çok daha fazlasını başardı."
  },
  Voice_67309_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_6730_AwakerVoiceContent = {
    Text = "Çözünme ilahi bir armağandır. Getirdiği Pain, sinirlerimizi felce uğratmaya yetecek kadardır; böylece yok oluşa süzülürken kendimizi bütünüyle yemeğe, şaraba ve şölene bırakabiliriz."
  },
  Voice_6730_AwakerVoiceTitle = {
    Text = "Sohbet: Çözünme Hakkında"
  },
  Voice_67310_AwakerVoiceContent = {
    Text = "Geçmiş, şimdi, gelecek. Milyar parıltı tek bir noktada toplanıyor!"
  },
  Voice_67310_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_67311_AwakerVoiceContent = {
    Text = "Geçmiş, şimdi, gelecek. Milyar parıltı tek bir noktada toplanıyor!"
  },
  Voice_67311_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_67312_AwakerVoiceContent = {
    Text = "Son Sınırın Kapısı açıldı. Her Şeyde Bir’i ve Bir’de Her Şey’i seyret!"
  },
  Voice_67312_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_67313_AwakerVoiceContent = {
    Text = "Son Sınırın Kapısı açıldı. Her Şeyde Bir’i ve Bir’de Her Şey’i seyret!"
  },
  Voice_67313_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_67314_AwakerVoiceContent = {
    Text = "Bilgeliğin sesini dinle."
  },
  Voice_67314_AwakerVoiceTitle = {
    Text = "Özel Beceri: II"
  },
  Voice_67315_AwakerVoiceContent = {
    Text = "Sonsuz, hudutsuz, bitimsiz, sınırsız."
  },
  Voice_67315_AwakerVoiceTitle = {
    Text = "Özel Beceri: III"
  },
  Voice_67316_AwakerVoiceContent = {
    Text = "Bu, Onların iradesi... Hayır, bu, nefeslerinin içinde her şeyi kuşatan bilinçsiz bir bakıştır."
  },
  Voice_67316_AwakerVoiceTitle = {
    Text = "Sohbet: Kriz Hakkında"
  },
  Voice_67317_AwakerVoiceContent = {
    Text = "Hepsini... göremedim..."
  },
  Voice_67317_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_67318_AwakerVoiceContent = {
    Text = "Gerçeği açığa çıkaracağım."
  },
  Voice_67318_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_67319_AwakerVoiceContent = {
    Text = "Ben... \"Cevap\"ı seviyorum. Bu sevgiden ötürü bu Kapı’yı korudum ve yine bu sevgiden ötürü Anahtar’ını eline bıraktım."
  },
  Voice_67319_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6731_AwakerVoiceContent = {
    Text = "Dönmeliyim... Dönmek zorundayım..."
  },
  Voice_6731_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_6732_AwakerVoiceContent = {
    Text = "Gök ve Toprak, nedenselliğin döngüsüne uyun!"
  },
  Voice_6732_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6733_AwakerVoiceContent = {
    Text = "Gök ve Toprak, nedenselliğin döngüsüne uyun!"
  },
  Voice_6733_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6734_AwakerVoiceContent = {
    Text = "Bıçak henüz keskinliğini yitirmedi."
  },
  Voice_6734_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6735_AwakerVoiceContent = {
    Text = "Eğitim asla ihmal edilmemeli!"
  },
  Voice_6735_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6736_AwakerVoiceContent = {
    Text = "Artık daha çevikim."
  },
  Voice_6736_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6737_AwakerVoiceContent = {
    Text = "Şekilsiz Yaratıklar emrinizde olacak."
  },
  Voice_6737_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_6737_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_6738_AwakerVoiceContent = {
    Text = "Kavurucu nefesimi hisset!"
  },
  Voice_6738_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6739_AwakerVoiceContent = {
    Text = "Hepimiz... Yeşil Alev’in bir parçası olacağız..."
  },
  Voice_6739_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_6740_AwakerVoiceContent = {
    Text = "Karakter Kalkanım daima sizin için parlayacak, efendim."
  },
  Voice_6740_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_6740_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_6741_AwakerVoiceContent = {
    Text = "Ben... sadece biraz daha Güçlü oldum. Gerçekten minnettarım!"
  },
  Voice_6741_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_6741_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_6743_AwakerVoiceContent = {Text = "Tsk..."},
  Voice_6743_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_6744_AwakerVoiceContent = {
    Text = "(Aşağılayıcı Tahammül)"
  },
  Voice_6744_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6745_AwakerVoiceContent = {
    Text = "(Aşağılayıcı Tahammül)"
  },
  Voice_6745_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6746_AwakerVoiceContent = {
    Text = "(Aşağılayıcı Tahammül)"
  },
  Voice_6746_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6747_AwakerVoiceContent = {
    Text = "Dostlarla geçirilen zaman her zaman öyle... dinlendirici."
  },
  Voice_6747_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_6748_AwakerVoiceContent = {
    Text = "Kanlı Kıyım Zinciri, Tisiphone’un Habercisi, Nefret Bıçağı... Umurumda değil. Bunlar sadece bana taktıkları adlar. Gerçi, onlara layık yaşamaktan da şikâyetçi değilim."
  },
  Voice_6748_AwakerVoiceTitle = {
    Text = "Sohbet: Helot’un Kendisi Hakkında"
  },
  Voice_6749_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_6749_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_6750_AwakerVoiceContent = {Text = "ALL-IN!"},
  Voice_6750_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_6751_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_6751_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_6752_AwakerVoiceContent = {Text = "(İnleme)"},
  Voice_6752_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_6753_AwakerVoiceContent = {
    Text = "Bu sefer daha ileri gidebilir miyiz? Hadi sahile gidelim!"
  },
  Voice_6753_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_6754_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_6755_AwakerVoiceContent = {
    Text = "Vay—teşekkürler, sevgili dostum~"
  },
  Voice_6755_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_6756_AwakerVoiceContent = {
    Text = "Dostlar~ Daha Çok Dost~"
  },
  Voice_6756_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_6757_AwakerVoiceContent = {
    Text = "Uvhash… o özeldir. Ailemin refahının kolayca geldiğini mi sandın? Hepsi, arenada kudurmuş bir köpek gibi öldürmesine sayesindedir. O bizim en büyük para kaynağımızdı."
  },
  Voice_6757_AwakerVoiceTitle = {
    Text = "Sohbet: Uvhash Hakkında"
  },
  Voice_6757_UnlockDesc = {
    Text = "\"Uvhash\" Uyandıranı edinince açılır"
  },
  Voice_6758_AwakerVoiceContent = {Text = "Aptal!"},
  Voice_6758_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_6759_AwakerVoiceContent = {Text = "Heh."},
  Voice_6759_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_6760_AwakerVoiceContent = {
    Text = "Yürüyün! Savaş emrini verin!"
  },
  Voice_6760_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_6761_AwakerVoiceContent = {
    Text = "Uçurumda... bir adalet ışığı olacak."
  },
  Voice_6761_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_6762_AwakerVoiceContent = {
    Text = "Adaletin ışığı burada yakıldı!"
  },
  Voice_6762_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6763_AwakerVoiceContent = {
    Text = "İnsan duyguları çiçekler kadar kırılgan ve çiçekler kadar kıymetlidir..."
  },
  Voice_6763_AwakerVoiceTitle = {
    Text = "Sohbet: Colette Hakkında"
  },
  Voice_6764_AwakerVoiceContent = {
    Text = "Hit, Stand, Blackjack!"
  },
  Voice_6764_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_6765_AwakerVoiceContent = {
    Text = "Hit, Stand, Blackjack!"
  },
  Voice_6765_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_67754_AwakerVoiceContent = {
    Text = "Direnme. Ağlama. Hiçliğe dönüş!"
  },
  Voice_67754_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_67756_AwakerVoiceContent = {
    Text = "Direnme. Ağlama. Hiçliğe dönüş!"
  },
  Voice_67756_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_67772_AwakerVoiceContent = {
    Text = "Kapı, bana açıl."
  },
  Voice_67772_AwakerVoiceTitle = {
    Text = "Özel Beceri: I"
  },
  Voice_79297_AwakerVoiceContent = {Text = "Ah."},
  Voice_79297_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_79298_AwakerVoiceContent = {Text = "Hımm...?"},
  Voice_79298_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_80092_AwakerVoiceContent = {
    Text = "Hidroterapi, elektrokonvülsif tedavi, kısıtlama tedavisi... bunlar tedavi değil, işkence. Bu yüzden o hastanelerdeki Hastaları kendi yöntemlerimle, ücretsiz tedavi ediyorum. Eninde sonunda hepsi iyileşiyor ve gerçek özgürlüğü buluyor."
  },
  Voice_80092_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_80092_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_80093_AwakerVoiceContent = {
    Text = "Zavallı Bay White. Ailesi onu, mahalledeki Akıl Hastaneleri dolu olduğu için domuz ahırında tuttu. Onu ücretsiz tedavi ettim ve sonunda bir hayvan değil, insan olduğunu fark etti. Sonra kendi elleriyle onurunu geri aldı."
  },
  Voice_80093_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_80093_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_80094_AwakerVoiceContent = {
    Text = "Dokumacılar, avukatlar, baronlar... Bir ücreti olduğu sürece hiçbir Hastayı geri çevirmem. Benim için hepsi sadece İyileştirmeye muhtaç Hasta."
  },
  Voice_80094_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_80094_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_80095_AwakerVoiceContent = {
    Text = "Seni hafife aldığımı kabul ediyorum. Varlığın bizzat Pain’in kendisi. Bu kez takip randevusuna gerek yok. Yanında kalmak ve sonucu bizzat görmek istiyorum."
  },
  Voice_80095_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_80095_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_80096_AwakerVoiceContent = {
    Text = "Bu Hastalar bana güzel Anılar bıraktı. Sırada sen varsın, Koruyucu. Senin için çoktan mükemmel bir son seçtim. Bu, kariyerimin en rafine muayenesi olacak."
  },
  Voice_80096_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_80096_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_81138_AwakerVoiceContent = {
    Text = "Bir doktorun yardımını reddetmek sana fayda sağlamaz. Belki bir dahaki sefere derin hipnozu deneriz."
  },
  Voice_81138_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_81139_AwakerVoiceContent = {
    Text = "Karanlık bir oda, yapayalnızım; zihnimde durmaksızın yankılanan sayısız acılı fısıltıyla baş başa... zamanı geçirmenin en güzel yolu bu."
  },
  Voice_81139_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_81140_AwakerVoiceContent = {
    Text = "Kaba olacak belki ama, o çocukla konuşmak beni yalnızca sıkıyor. Görebildiğin tek bir ifade var... bir gülümseme."
  },
  Voice_81140_AwakerVoiceTitle = {
    Text = "Sohbet: Aurita Hakkında"
  },
  Voice_81140_UnlockDesc = {
    Text = "\"Aurita\" Uyandıranı edinince açılır"
  },
  Voice_81141_AwakerVoiceContent = {
    Text = "Bu izinsiz girişimi bağışla, yalnızca düşük bir psikolojik enerji sezdim ve seni kontrol etmeye geldim. Şimdi, Koruyucu, zihninin içinde bir yolculuğa çıkalım mı?"
  },
  Voice_81141_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_81143_AwakerVoiceContent = {
    Text = "Psikiyatristler bir zamanlar hastaları, kafataslarını trepanasyon tekniğiyle delerek tedavi ederdi... Lütfen, rahat ol. O çok geride kaldı. O zamandan beri zihne inmeye yarayan çok daha fazla yöntem geliştirdik."
  },
  Voice_81143_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_81143_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_81144_AwakerVoiceContent = {
    Text = "Birbirini anlamak için insanın kalbini açması gerekir. Şuraya dokun, Gümüş kalbim senin için açılacak."
  },
  Voice_81144_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_81145_AwakerVoiceContent = {
    Text = "Düşüncelerimi arıyorsan hayal kırıklığına uğrayabilirsin. Yorum sunmaktan çok, dinlemekte iyiyimdir."
  },
  Voice_81145_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_81146_AwakerVoiceContent = {
    Text = "Ah, O’nun sesini duydum... o mırıltıları, her hecesi en yoğun ızdırapla doluydu."
  },
  Voice_81146_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_81147_AwakerVoiceContent = {
    Text = "Bu anın acısını hatırlayacağım... tekrar tekrar anımsayıp tadına varacağım."
  },
  Voice_81147_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_81148_AwakerVoiceContent = {
    Text = "O varlığın bir parçası olarak, Onların kokusunu taşıyorsun... Acıyla dolu, güzel bir koku. Senin her bir hafızanı tarifsiz derecede leziz kılıyor."
  },
  Voice_81148_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_81149_AwakerVoiceContent = {
    Text = "O Dehşetleri hatırla, Pain duygularını ayrıntılarıyla anlat. Duygusal Darbe tedavisinin özü, Pain’le yüzleşmek ve onu fethetmektir. Gel, gözyaşlarını sileyim. Acele etme. O Anıları bana ayrıntılı biçimde anlat..."
  },
  Voice_81149_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_81149_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_81150_AwakerVoiceContent = {
    Text = "Tebrikler, iyileştin. Evet, o sanrılar ve Düşler normal; iyileşmenin kanıtı onlar."
  },
  Voice_81150_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_81150_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_81151_AwakerVoiceContent = {
    Text = "Görüş Alanın muhtemelen şimdi tuhaf sanrılarla dolu, bu oldukça normal. Onları dışarı dök, böylece bilinçaltın ve içgüdülerin her şeyi açığa vuracak."
  },
  Voice_81151_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_81151_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_81152_AwakerVoiceContent = {
    Text = "Sırada Philippe Pinel’in ahlaki tedavisi var. En derin arzularını ve Dehşetlerini ifade etmelisin. Zihnin zincirlerini kırmak ve uykuda olan İnsanlığın Işığı’nı geri getirmek için bu gerekli bir prosedür."
  },
  Voice_81152_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_81152_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_81153_AwakerVoiceContent = {
    Text = "Koruyucu, küçük bir testte bana yardım eder misin? Rorschach mürekkep lekesi testi. İç benliğinin derinliklerini görmeme yardım edecek... Kalbinin sırlarını açığa çıkaran tek Uyanışçı ben olacağım."
  },
  Voice_81153_AwakerVoiceTitle = {
    Text = "Sohbet: Psikolojik Analiz Hakkında"
  },
  Voice_81154_AwakerVoiceContent = {
    Text = "Önce biraz müzik dinleyelim. Bu melodiyi nasıl buluyorsun? Yatıştırıcı ve yumuşak. Şimdi bedenin ve zihnin müzikle birlikte titreşsin, ruhsal bir gevşeme Durumu’na gir."
  },
  Voice_81154_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_81154_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_81155_AwakerVoiceContent = {
    Text = "Sarkaca bak... Gözlerinle hareketini takip et."
  },
  Voice_81155_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_81156_AwakerVoiceContent = {
    Text = "Şşş... sessiz ol. Şimdi, seni götüreceğim sona doğru yürü."
  },
  Voice_81156_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_81157_AwakerVoiceContent = {
    Text = "Uyuşmuş bir ruh beni hiç ilgilendirmez. Onların ruhları zaten ölü. Ne kadar kurcalarsan kurcala, en ufak bir dalga bile oluşmaz."
  },
  Voice_81157_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_81158_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_81159_AwakerVoiceContent = {
    Text = "Dinliyorum. Lütfen, devam et."
  },
  Voice_81159_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_81160_AwakerVoiceContent = {
    Text = "Lütfen sessiz kal."
  },
  Voice_81160_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_81161_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_81162_AwakerVoiceContent = {
    Text = "Bana biraz daha güven."
  },
  Voice_81162_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_81163_AwakerVoiceContent = {
    Text = "Acını açığa vur."
  },
  Voice_81163_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_81164_AwakerVoiceContent = {
    Text = "Çekinme, saklanmana gerek yok. Ben senin tek sırdaşınım. Gel, en derin Pain’ini bana dök."
  },
  Voice_81164_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_81165_AwakerVoiceContent = {
    Text = "Aigis şimdi çok daha parlak görünüyor. Elbette, küçük konuğumun yardıma ihtiyacı olursa, bunu memnuniyetle sunarım. Yani, gerçek bir yardım."
  },
  Voice_81165_AwakerVoiceTitle = {
    Text = "Sohbet: Aigis Hakkında"
  },
  Voice_81165_UnlockDesc = {
    Text = "\"Aigis\" Uyandıranı edinince açılır"
  },
  Voice_81166_AwakerVoiceContent = {
    Text = "Bana en gerçek hâlini göster."
  },
  Voice_81166_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_81168_AwakerVoiceContent = {
    Text = "Bu tatlı acının tadını çıkaracağım."
  },
  Voice_81168_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_81169_AwakerVoiceContent = {
    Text = "Çekinme, saklanmana gerek yok. Ben senin tek sırdaşınım. Gel, en derin Pain’ini bana dök."
  },
  Voice_81169_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_81170_AwakerVoiceContent = {
    Text = "Ruhsal hastalık bu çağa özgü değil; zamanı ve mekânı Aşmakta. Çözünme de öyle. İkisi de insan bilişinin sınırlarını Aşmıyor mu?"
  },
  Voice_81170_AwakerVoiceTitle = {
    Text = "Sohbet: Kriz Hakkında"
  },
  Voice_81171_AwakerVoiceContent = {
    Text = "Şşş... sessiz ol. Şimdi, seni götüreceğim sona doğru yürü."
  },
  Voice_81171_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_81172_AwakerVoiceContent = {
    Text = "Bu yer tarih izleriyle dolu ve bir bakıma tarih, Anıları temsil eder... Ölü Ruh’un acı Anılarını."
  },
  Voice_81172_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_81173_AwakerVoiceContent = {
    Text = "Derin bir nefes al."
  },
  Voice_81173_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_81174_AwakerVoiceContent = {
    Text = "Pain, umutsuzluk, ölüm... Bu anılar, nefis bir yemeğin ardından gelen tatlı gibi tadıyor."
  },
  Voice_81174_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_81175_AwakerVoiceContent = {
    Text = "Böylesine gerginliğe gerek yok. Bu sadece sıradan bir muayene."
  },
  Voice_81175_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_81176_AwakerVoiceContent = {
    Text = "Rehberliğimi dinle."
  },
  Voice_81176_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_84185_AwakerVoiceContent = {
    Text = "Ayin sırasında beklenmedik bir olay yaşandı. Sancağı koluna savurduğum için beni bağışla; seni uyanık tutmak zorundaydım."
  },
  Voice_84185_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_84185_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_84186_AwakerVoiceContent = {
    Text = "Burada birçok türde gemiyle karşılaşıyor ve gelişmiş seyir ekipmanlarıyla çalışıyorum. Bunu son derece tatmin edici buluyorum. Her şeyden önemlisi, bu \"geminin\" insanlık tarihine doğru rotayı çizdiğine inanıyorum."
  },
  Voice_84186_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_84187_AwakerVoiceContent = {
    Text = "Ayin Tamamlandı. İş birliğin için teşekkür ederim. Bir dahaki sefere, içinden daha güvenle geçmemiz için özel sancaklar hazırlayacağım."
  },
  Voice_84187_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_84187_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_84188_AwakerVoiceContent = {
    Text = "Neden var olduğunu bilmiyorum. Bildiğim tek şey şu: Başarıyla rota çizmek ve Herkes’i eve getirmek zorundayım."
  },
  Voice_84188_AwakerVoiceTitle = {
    Text = "Sohbet: Kriz Hakkında"
  },
  Voice_84189_AwakerVoiceContent = {
    Text = "İçin rahat olsun, bu gücü gemiyi güvenle yönlendirmek için kullanacağım ve asla kötüye kullanmayacağım."
  },
  Voice_84189_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_84190_AwakerVoiceContent = {
    Text = "Lütfen direnmekten vazgeç."
  },
  Voice_84190_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_84191_AwakerVoiceContent = {
    Text = "Size tüm saygımla bağlıyım. Verdiğiniz her emri yerine getirmeye ant içiyorum."
  },
  Voice_84191_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_84192_AwakerVoiceContent = {
    Text = "Beni bağışla. İnsanlardan çok gemilerden anlarım. Ama müsaadenle: senin omurgan ne ağaç ne de demir, çelikten. Güçlü. Metanetli. Gerçekten hayranlık uyandırıcı."
  },
  Voice_84192_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_84192_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_84193_AwakerVoiceContent = {Text = "Teslim ol."},
  Voice_84193_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_84194_AwakerVoiceContent = {
    Text = "\"Hoşlanmak\" yerine \"adanmışlık\" kelimesini tercih ederim. O tarif edilemez tanrıya doğrudan baktığımda, zihnim aklını yitirir ve vecd ile dolar. Ondan korkmalıydım, ama kendimi alamıyorum."
  },
  Voice_84194_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_84195_AwakerVoiceContent = {
    Text = "Bu fırtına beni yenemeyecek."
  },
  Voice_84195_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_84196_AwakerVoiceContent = {
    Text = "Düzen olmadan, bu dünyada ne kalır? Yalnızca kaos."
  },
  Voice_84196_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_84197_AwakerVoiceContent = {
    Text = "Bir sonraki Uzun Yolculuk’ta, gemiye artık seyir subayı olarak binmek istemiyorum. Şey... Yani, senin izinden giden biri olarak. Sana tam bir güven duyuyorum, Koruyucu."
  },
  Voice_84197_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_84197_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_84198_AwakerVoiceContent = {
    Text = "Ben yalnızca seyrüsefer görevimi yerine getiriyorum; ne rapora ne de övgüye ihtiyacım var."
  },
  Voice_84198_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_84199_AwakerVoiceContent = {
    Text = "Fener sistemi, seyrüseferin yükünü hafifletir. Işını güçlü ve berrak. Faros’la seyretmekten memnunum."
  },
  Voice_84199_AwakerVoiceTitle = {
    Text = "Sohbet: Faros Hakkında"
  },
  Voice_84199_UnlockDesc = {
    Text = "\"Faros\" Uyandıranı edinince açılır"
  },
  Voice_84200_AwakerVoiceContent = {
    Text = "Denizciler, Rehberliğimi izleyin. Limana sağ salim varacağımızdan emin olacağım."
  },
  Voice_84200_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_84201_AwakerVoiceContent = {
    Text = "Ruhsal bağ kuruldu. Varlığını hissedebiliyorum. Boşlukta ilk kez yol alıyorum. Bir şey rotadan saparsa, lütfen hemen düzelt."
  },
  Voice_84201_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_84201_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_84202_AwakerVoiceContent = {
    Text = "Sirüs bulutları gözlemlendi, barometrik basınç düşmeye devam ediyor. Tüm mürettebata alarm. Gemi az sonra fırtınaya girecek."
  },
  Voice_84202_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_84203_AwakerVoiceContent = {
    Text = "Bu kaos, rotayı yanlış hesaplamamın bir sonucu. Kurallara uygun şekilde cezalandırılmayı kabul ediyorum."
  },
  Voice_84203_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_84204_AwakerVoiceContent = {
    Text = "Göksel cisimlerin yükseklik açısı ölçülüyor."
  },
  Voice_84204_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_84205_AwakerVoiceContent = {
    Text = "Bu baş döndürücü his, deniz tutmasına çok benziyor. Lütfen gözlerini kapat, elimi tut ve bana yaslan. Biraz olsun hafifletecektir."
  },
  Voice_84205_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_84205_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_84206_AwakerVoiceContent = {
    Text = "Pruvadaki yelkenleri indir. Dalgalar iskele tarafından bastırıyor. Dümenci, rotayı Hesaplamalarıma göre ayarla."
  },
  Voice_84206_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_84207_AwakerVoiceContent = {
    Text = "Bu deneyimler paha biçilemez. Onları, geleceğin denizcileri için seyir defterine ayrıntılı biçimde kaydedeceğim."
  },
  Voice_84207_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_84208_AwakerVoiceContent = {
    Text = "Ruhsal bağlantıyı Derinleştirme ayini riskler ve bilinmeyen sonuçlar taşır. Ama için rahat olsun, ayinin sorunsuz tamamlanması için senin adına seyrüseferi ben yöneteceğim."
  },
  Voice_84208_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_84208_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_84209_AwakerVoiceContent = {
    Text = "Ağırlık dağılımı yeniden ayarlanıyor."
  },
  Voice_84209_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_84210_AwakerVoiceContent = {
    Text = "Her şeyden önce geminin güvenliğini sağlayın."
  },
  Voice_84210_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_84211_AwakerVoiceContent = {
    Text = "Bazı insanlar buharlı gemiler gibidir—tepki vermeleri yavaştır ama yüksek hıza ulaşabilirler. Bazılarıysa dizel gemiler—çabuk Başlarlar ama güçleri sınırlıdır. Peki ya sen, Koruyucu?"
  },
  Voice_84211_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_84211_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_84212_AwakerVoiceContent = {
    Text = "Çabanın karşılığını getiren temel yasaya yürekten inanıyorum ve gelecekte daha da çok çalışacağım."
  },
  Voice_84212_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_84213_AwakerVoiceContent = {
    Text = "Kendini defalarca kanıtladın. Bence mükemmel bir seyrüsefersin, belki de benden daha yetkinsin."
  },
  Voice_84213_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_84213_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_84214_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_84215_AwakerVoiceContent = {
    Text = "Sen ihtiyaç duyduğun sürece, Corposant her zaman tetikte bekler."
  },
  Voice_84215_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_84215_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_84216_AwakerVoiceContent = {
    Text = "Denizciler, Rehberliğimi izleyin. Limana sağ salim varacağımızdan emin olacağım."
  },
  Voice_84216_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_84217_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_84218_AwakerVoiceContent = {
    Text = "Seyrüseferci Corposant göreve hazır! Sancak çekildi, kişisel durum iyi, fırlatma emrini verin, Koruyucu."
  },
  Voice_84218_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_84219_AwakerVoiceContent = {
    Text = "Gemimi doğru rotaya ben götüreceğim."
  },
  Voice_84219_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_84220_AwakerVoiceContent = {
    Text = "Şapkam yamuk mu? Özür dilerim, ama ne demek istediğinizden emin değilim. Lütfen bana net talimatlar verin."
  },
  Voice_84220_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_84221_AwakerVoiceContent = {
    Text = "Sancak, seyrüseferin dili ve aynı zamanda mezar yazıtıdır. Gemi battığında, enkazdan çıkarılan sancaktan geride bıraktığım son mesajı okuyacaklar."
  },
  Voice_84221_AwakerVoiceTitle = {
    Text = "Sohbet: Onun Sancağı Hakkında"
  },
  Voice_84222_AwakerVoiceContent = {
    Text = "Geminin trimi ve dengesini değerlendiriyor."
  },
  Voice_84222_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_84223_AwakerVoiceContent = {
    Text = "Pruvadaki yelkenleri indir. Dalgalar iskele tarafından bastırıyor. Dümenci, rotayı Hesaplamalarıma göre ayarla."
  },
  Voice_84223_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_84224_AwakerVoiceContent = {
    Text = "E sancağı talimatları iletir."
  },
  Voice_84224_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_84225_AwakerVoiceContent = {
    Text = "Gerektiğinde, makine dairesiyle iş birliği konusunda eğitimli bir seyrüsefer, dümenci olarak görev yapabilir. Ama geminin güvenliği için, o görevi hâlâ daha yetenekli birine emanet etmeyi tercih ederim."
  },
  Voice_84225_AwakerVoiceTitle = {
    Text = "Sohbet: Celeste Hakkında"
  },
  Voice_84225_UnlockDesc = {
    Text = "\"Celeste\" Uyandıranı edinince açılır"
  },
  Voice_84226_AwakerVoiceContent = {
    Text = "Hissediyorum... önce bir ağırlıksızlık, ardından şiddetli sarsıntılar—sanki gemi oradan oraya savruluyor. Koruyucu, dengenin için merkezini bulmak üzere hareketlerimi takip et ve Dengeyi koru."
  },
  Voice_84226_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_84226_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_84406_AwakerVoiceContent = {
    Text = "Düzeltilerle seyir haritasını güncellemeye başla."
  },
  Voice_84406_AwakerVoiceTitle = {
    Text = "Özel Beceri: I"
  },
  Voice_84407_AwakerVoiceTitle = {
    Text = "Özel Beceri: III"
  },
  Voice_84408_AwakerVoiceContent = {
    Text = "C sancağı talimatları aldığını bildirir."
  },
  Voice_84408_AwakerVoiceTitle = {
    Text = "Özel Beceri: II"
  },
  Voice_84409_AwakerVoiceTitle = {
    Text = "Özel Beceri: III"
  },
  Voice_90333_AwakerVoiceContent = {
    Text = "Benden öteye geçemeyeceksin."
  },
  Voice_90333_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_90334_AwakerVoiceContent = {
    Text = "Arkadaşlar nasıl geçinmeli? Pollux, kendisi de yapabileceği şeyler için bana emir vermeyi seviyor. Ben de bu işleri onun için yapmaya razıyım; birlikte vakit geçirme biçimimiz bu. İstersen, senin için de bir şeyler yaparım."
  },
  Voice_90334_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_90334_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_90335_AwakerVoiceContent = {
    Text = "Bırak Felaket gelsin. Bu Ölümsüz Beden asla kırılmayacak!"
  },
  Voice_90335_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_90336_AwakerVoiceContent = {
    Text = "O kitaptan önce bile, gölün adasının, o kızıl duvarların ötesindeki dünyayı merak ederdik. Yine de Pollux acı çekerken karşı koymadım. Onun cesaretinden yoksunum. Pollux’un aksine, çok daha korkak ve beceriksizim."
  },
  Voice_90336_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_90336_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_90337_AwakerVoiceContent = {
    Text = "Ben... aptal gibi mi konuşuyorum? Özür dilerim, lütfen cehaletimi bağışla. Bilgim Fener’in öğretileriyle başlar ve biter. Bana sevdiklerini ve sevmediklerini öğret—onları Hafızama kazıyacağım."
  },
  Voice_90337_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_90337_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_90338_AwakerVoiceContent = {
    Text = "Şu irademe tanık ol—özgürlük için duyduğum bu açlığa."
  },
  Voice_90338_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_90339_AwakerVoiceContent = {
    Text = "Her dileği yerine getirebilen, sayısız gizli hazineyle taşan bir dükkân... İnsanın yaklaşmaya tereddüt etmesine yol açıyor. Hanımefendinin gücünden şüphem yok elbette, ama \"bir şey elde etmek için, ona denk bir bedel ödemek gerekir\"— Pollux’la ikimizin, acı tecrübelerle, defalarca öğrenmiş olduğu ders budur."
  },
  Voice_90339_AwakerVoiceTitle = {
    Text = "Sohbet: Nergis Hakkında"
  },
  Voice_90339_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Nergis\" elde edildikten sonra açılır"
  },
  Voice_90340_AwakerVoiceContent = {
    Text = "Bu lanetli kanatlar bir gün yeniden uçacak gücü bulabilecek mi..."
  },
  Voice_90340_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_90341_AwakerVoiceContent = {
    Text = "Beni asla İmha Etmeyeceksin!"
  },
  Voice_90341_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_90342_AwakerVoiceContent = {
    Text = "Kanatlarıma dokunmak ister misin? Elbette, buyur. Daha da açmamı ister misin?"
  },
  Voice_90342_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_90343_AwakerVoiceContent = {
    Text = "Cömertliğin beni huzursuz ediyor. Bana verdiğin pahalı kitaplar, göktaşı kristalleri... bunun bir bedeli var mı? Özür dilerim, lütfen Şüphemi bağışla. Sana böyle kuşkuyla yaklaşmamalıyım."
  },
  Voice_90343_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_90343_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_90344_AwakerVoiceContent = {
    Text = "Her kuş eninde sonunda kendi göğünü bulur."
  },
  Voice_90344_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_90345_AwakerVoiceContent = {
    Text = "Ah, usta bir aşçı olduğunu duydum... Yemek yapma bilgisi gerçekten çok gerekli. Gerçi ben yemek konusunda pek seçici değilim, ama Pollux son derece titizdir. Ondan bir şeyler öğrenmek için zaman ayırmalıyım... Gitmemeli miyim? Neden? Beyefendinin yaptığı yemekler çok lezzetli görünüyor oysa."
  },
  Voice_90345_AwakerVoiceTitle = {
    Text = "Sohbet: Doresain Hakkında"
  },
  Voice_90345_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Doresain\" elde edildikten sonra açılır"
  },
  Voice_90346_AwakerVoiceContent = {
    Text = "Şimdi geriye dönüp baktığımda, fener taşıyan hizmetçiler Pollux ve benden o kadar da farklı değillerdi. Hepimiz görünmez zincirlerle prangalanmış, kaderimize sessizce boyun eğerek yaşıyorduk. Ama o yeşil hizmetçi... o başkaydı. Üzerinde bir hafiflik vardı; sanki görevlerinden gerçekten haz alıyordu. Belki de... belki o, çoktan gerçek özgürlüğü keşfetmişti."
  },
  Voice_90346_AwakerVoiceTitle = {
    Text = "Sohbet: Karen Hakkında"
  },
  Voice_90346_UnlockDesc = {
    Text = "Uyanışçı \"Karen\" edinildiğinde açılır"
  },
  Voice_90347_AwakerVoiceContent = {
    Text = "Beni asla İmha Etmeyeceksin!"
  },
  Voice_90347_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_90348_AwakerVoiceContent = {
    Text = "Demek ki... hiç... çıkamamışım, ha..."
  },
  Voice_90348_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_90349_AwakerVoiceContent = {
    Text = "Rüzgârla birlikte yok olun!"
  },
  Voice_90349_AwakerVoiceTitle = {
    Text = "Özel Beceri: II"
  },
  Voice_90350_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_90351_AwakerVoiceContent = {
    Text = "Selamlar. Ben Castor... Daha başka bir şey söylemem gerekiyor muydu? Bağışla—kelimeler bana kolay gelmiyor. Bir şeye ihtiyacın olursa, sor yeter."
  },
  Voice_90351_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_90352_AwakerVoiceContent = {
    Text = "Sadece bir çizik..."
  },
  Voice_90352_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_90353_AwakerVoiceContent = {Text = "Düş!"},
  Voice_90353_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_90354_AwakerVoiceContent = {
    Text = "Ne çok şey görülmemiş... ne çok şey yarım kalmış. O ıssız koyu yeşil göller ve dinmek bilmeyen yoğun sis artık bizi tutamayacak. Kitabın sayfalarındaki okyanusları, şehirleri, tarlaları... göreceğim. Pollux’la. Seninle."
  },
  Voice_90354_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_90354_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_90355_AwakerVoiceContent = {
    Text = "Ağaçlardaki yaprakların hışırtısını duyduğunda, yanındayım demektir."
  },
  Voice_90355_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_90355_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_90356_AwakerVoiceContent = {
    Text = "Bu karanlık kanatlar her geçen gün daha da ağırlaşıyor."
  },
  Voice_90356_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_90357_AwakerVoiceContent = {
    Text = "En çok imrendiğim, yoldaşlarına böylesine zahmetsizce güvenebilmen. Unutulmak... ihanete uğramak... yaralar asla silinmiyor."
  },
  Voice_90357_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_90358_AwakerVoiceContent = {
    Text = "O usta hırsız, yalnızca beş yüz Leonian Florin karşılığında bana en iyi hayatta kalma becerilerini öğretmeyi teklif etti... Kandırıldım mı? Hayır, bunun öğrenmeye değer bir bilgi olduğuna inanıyorum ve bu tam da Pollux’la benim eksikliğini çektiğimiz şey... Mesele para mı? Anlıyorum. Öyleyse, gidip onunla pazarlık etsem ve bunun yerine dört yüz elli Leonian Florin ödesem nasıl olur?"
  },
  Voice_90358_AwakerVoiceTitle = {
    Text = "Sohbet: Jenkin Hakkında"
  },
  Voice_90358_UnlockDesc = {
    Text = "\"Jenkin\" Uyandıranı edinince açılır"
  },
  Voice_90359_AwakerVoiceContent = {
    Text = "Daha fazlasına dayanabilirim..."
  },
  Voice_90359_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_90360_AwakerVoiceContent = {
    Text = "Biz çocukken kurallar bu kadar katı değildi. Bazen Pollux gider bir şeyler söyler, sonra da sihirliymiş gibi bir avuç şekerle dönerdi. O tatlılık... sanki şu anki an gibi."
  },
  Voice_90360_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_90360_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_90361_AwakerVoiceContent = {
    Text = "Bırak Felaket gelsin. Bu Ölümsüz Beden asla kırılmayacak!"
  },
  Voice_90361_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_90362_AwakerVoiceContent = {
    Text = "Bana ticaret yapmayı öğretir misin? Ürün Takası’nı, elde edilen parayı nasıl yönetmem gerektiğini... bunlar gerçekten derin konular. Özgürlüğü kazanmak sadece başlangıç; Pollux ve benim, başımızın çaresine bakmayı öğrenmek için hâlâ çok yolumuz var. Sana güvenebilir miyim?"
  },
  Voice_90362_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_90363_AwakerVoiceContent = {
    Text = "Rüzgârla birlikte yok olun!"
  },
  Voice_90363_AwakerVoiceTitle = {
    Text = "Özel Beceri: I"
  },
  Voice_90364_AwakerVoiceContent = {
    Text = "Rüzgâr, onları ölümün ağzına taşı!"
  },
  Voice_90364_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_90365_AwakerVoiceContent = {
    Text = "Pollux... Fener zihnini zehirli fikirlerle doldurdu, ama aslında o iyi biri. Mesele bencillik değil... Sadece dehşete kapılmış durumda. Fener’in onayını yitirmekten, o kırılgan kimlik duygusu olmadan yok olup gitmekten ödü kopuyor. Onları memnun etmek için gösterdiği o umutsuz çaba... Bildiği tek \"benliğe\" tutunan birinin panik hâli."
  },
  Voice_90365_AwakerVoiceTitle = {
    Text = "Sohbet: Pollux Hakkında"
  },
  Voice_90365_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Pollux\" elde edildikten sonra açılır"
  },
  Voice_90366_AwakerVoiceContent = {
    Text = "Üzgünüm, dalıp gitmek istememiştim... Bana bu tüyün ne olduğunu sormuştun, değil mi? Bu... Onun en kıymetli şeyi... ve artık benim. Beğendin mi? Güzel, değil mi?"
  },
  Voice_90366_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_90367_AwakerVoiceContent = {
    Text = "Albino ve Işık Bekçisi eşliğinde Teoloji dersleriyle doluydu günlerimiz. Daha kısa Kutsal Sözler düşlerdim—tökezleyeceğim daha az ayet, yiyeceğim daha az azar."
  },
  Voice_90367_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_90367_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_90368_AwakerVoiceContent = {
    Text = "Teşekkür ederim... özgürlüğümün anahtarı için. Kendi kaderimi kavramama izin verdiğin için."
  },
  Voice_90368_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_90369_AwakerVoiceContent = {
    Text = "Bu kanatlar artık bütünüyle gelişti. Ne kadar sağlam, ne kadar güçlüler. Artık hem Pollux’u hem seni taşıyabilirim. Uçmak istediğinde beni çağır."
  },
  Voice_90369_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_90369_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_90370_AwakerVoiceContent = {
    Text = "Kanatlarımın ardına geç!"
  },
  Voice_90370_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_90371_AwakerVoiceContent = {
    Text = "Nihayet... O sayfalardaki yıldızları gördüm."
  },
  Voice_90371_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_90372_AwakerVoiceContent = {
    Text = "Baş Rahibe... Juliette. O zamanlar bize karşı çok yumuşaktı. Sıcak gülümsemeleri, itaatsizliği akla bile getirmiyordu. Başımıza kondurduğu bir şefkat dokunuşu, bütün itirazları sustururdu. Onu hayal kırıklığına uğratmak istemezdik. Evet, merak etme, artık öyle hissetmiyorum... İstersen başımı sen okşayabilirsin."
  },
  Voice_90372_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_90372_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_90373_AwakerVoiceContent = {
    Text = "Uzun, çok uzun bir süre o siyah, yapışkan sıvının içinde kaldım—öyle uzun ki zamanı unuttum, öyle uzun ki Pollux bile beni unuttu. Fiziksel bir acı getirmedi... sadece ruhumun çözünüşünü izlerken duyduğum dehşeti."
  },
  Voice_90373_AwakerVoiceTitle = {
    Text = "Sohbet: Kriz Hakkında"
  },
  Voice_90374_AwakerVoiceContent = {
    Text = "Çocukluktan beri başkalarıyla konuşmamıza izin verilmezdi. “Arkadaş” benim için yabancı bir kavramdı... yakın zamana dek. Pollux ve ben birbirimiz için her şeydik: kardeş, dost, yoldaş Tutsak, tek teselli. Şimdi... belki de yeni arkadaşlar edinmeliyim."
  },
  Voice_90374_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_90374_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_90375_AwakerVoiceContent = {Text = "Geri dur!"},
  Voice_90375_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_90376_AwakerVoiceContent = {
    Text = "Teoloji olmayan bir okul mu? Dersleri kendin seçtiğin... kaytardığın? Kulağa bir rüya gibi geliyor."
  },
  Voice_90376_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_90377_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_90378_AwakerVoiceContent = {
    Text = "Çekil önümden!"
  },
  Voice_90378_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_95050_AwakerVoiceContent = {
    Text = "Siz küfürbazlar... cezalandırılacaksınız..."
  },
  Voice_95050_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_95051_AwakerVoiceContent = {
    Text = "Kalbim İç Ateş’le yanıyor!"
  },
  Voice_95051_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_95052_AwakerVoiceContent = {Text = "Pislik."},
  Voice_95052_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_95053_AwakerVoiceContent = {
    Text = "Ah, şu aşırı fanatik mümin. Dünya onu kudurmuş bir deli kadın olarak görebilir. Bir zamanlar kötülük işlemiş olsa da, böylesine ateşli bir adanmışlık—tanrısına her şeyini sunma iradesi—sıradan ruhların çoğunun asla kuşanamayacağı bir azimdir. Onun hakkında ne düşündüğümü soruyorsun? …Yalnızca… belli bir acıma hissediyorum. Aynı çalkantılı denizde savrulmuş birine duyulan bir yakınlık."
  },
  Voice_95053_AwakerVoiceTitle = {
    Text = "Sohbet: Miryam Hakkında"
  },
  Voice_95053_UnlockDesc = {
    Text = "Uyanışçı \"Miryam\" elde edildikten sonra açılır"
  },
  Voice_95054_AwakerVoiceContent = {
    Text = "Kılavuzluk ve Yargı getireceğim; Ak Gece günahlarını arındırsın!"
  },
  Voice_95054_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_95055_AwakerVoiceContent = {
    Text = "Ha... Bunca zaman sonra, en ufak bir değişiklik bile yok onda. Çocukken asla hayal etmezdim, kardeşimi incitenin ben olacağımı—seçmediğimiz bir kader yüzünden, utançla sızlayacak kadar çok şey borçlu kalacağımı. Yeterince Ayrılık çektik. Şimdi geri döndüğüme göre, yemin ederim: artık hiçbir şey bizi ayıramayacak. Ölüm bile."
  },
  Voice_95055_AwakerVoiceTitle = {
    Text = "Sohbet: Castor Hakkında"
  },
  Voice_95055_UnlockDesc = {
    Text = "Uyanışçı \"Castor\" elde edildikten sonra açılır"
  },
  Voice_95056_AwakerVoiceContent = {
    Text = "Bir zamanlar pek çok şeyden nefret ederdim—kaba hizmetkârlardan, saygısız uşaklardan, Işık’ı kirleten sapkınlardan… Peki ya şimdi? Fener’den nefret ediyorum. Yalnızca Fener’den! Juliette ve Kilisesi, kardeşime ve bana onarılamaz acılar yaşattı. Eski bir Divus olarak taşıdığım unvan üzerine yemin ederim, böyle bir acının bir daha kimsenin başına gelmesine asla izin vermeyeceğim!"
  },
  Voice_95056_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_95057_AwakerVoiceContent = {
    Text = "Son nefesime dek ışığın fitil yolunda yürüyeceğim."
  },
  Voice_95057_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_95058_AwakerVoiceContent = {
    Text = "Işık Taşıyıcı’nın parıltısı, bu sonsuz geceyi delsin!"
  },
  Voice_95058_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_95059_AwakerVoiceContent = {
    Text = "Cömertliğin ve merhametin sonsuzdur; ışığının sıcaklığı üzerine tefekküre dalacağım."
  },
  Voice_95059_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_95060_AwakerVoiceContent = {
    Text = "Işık Taşıyıcı’nın Havarisi, Ak Gecenin evladı, Karanlığı Dağıtan, İlahi Yüreğin Divus’u—ben, Pollux, çağrına icabet ettim. Sana Karanlık üzerindeki gücümü ve Işıkla dövülmüş ruhumu sunuyorum."
  },
  Voice_95060_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_95061_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_95062_AwakerVoiceContent = {
    Text = "Günahlarını arındır!"
  },
  Voice_95062_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_95063_AwakerVoiceContent = {
    Text = "Bana, bu uçurumvari karanlığın imana layık olduğu söylendi. Sadıklara ulaştıracağım bir lütuf olduğu… Şimdi ise bu karanlık çoktan beni içten içe çürüttü, varlığımın ta kendisiyle kaynaştı… Yine de bu günahkâr bedende atan yürek, asla kirletilemeyecek bir mabed olarak kalıyor. Emin ol, bana bahşettiği gücü bu dünyaya gerçek takdisi getirmek için kullanacağım!"
  },
  Voice_95063_AwakerVoiceTitle = {
    Text = "Sohbet: Kriz Hakkında"
  },
  Voice_95064_AwakerVoiceContent = {
    Text = "Görkemli adını müjdeleyeceğim, ve her ne kirli ve necis ise, onun parıltısıyla arındırılacak."
  },
  Voice_95064_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_95065_AwakerVoiceContent = {
    Text = "Geçmişin günahları işlendi; artık onlardan kaçmayacağım. Fener’in hatalarını da düzeltmeli ve yoldan sapanları gerçek yola geri rehberlik etmeliyim. Bırak, günahlarımı ben taşıyayım. Sonra, çağrının ışığına cevap verecek ve bir Divus olarak doğru fitil yolunda yürüyeceğim."
  },
  Voice_95065_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_95065_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_95066_AwakerVoiceContent = {
    Text = "Günahla bu denli yüklü birini affedecek kadar merhametli bir ruhun var. Ruhunun içindeki o saf, göz kamaştırıcı ışığı hissediyorum—en parlak alevden daha güçlü yanıyor. Belki de yolunu yitirmiş bu kalbe sen rehberlik edebilirsin..."
  },
  Voice_95066_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_95066_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_95067_AwakerVoiceContent = {
    Text = "Karanlık... Juliette’in ilahisiyle yayılmış Karanlık, zihnimde oyalanıp durdu... Ve şimdi, tek bir ışık huzmesi onu deldi! O sönük parıltı bana bir şey anlatmaya mı çalışıyor?"
  },
  Voice_95067_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_95067_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_95068_AwakerVoiceContent = {
    Text = "Bir zamanlar Azize olduğunu duymuştum. Ama şu görgüsüz tavırları ve kaba saba davranışlarıyla... Ne? Tek bir dua bile edemiyor mu? Ne derin bir dinsizlik... Onun ilahı adına utanç duyuyorum."
  },
  Voice_95068_AwakerVoiceTitle = {
    Text = "Sohbet: Murphy Hakkında"
  },
  Voice_95068_UnlockDesc = {
    Text = "Uyanışçı \"Murphy\" edinildiğinde açılır"
  },
  Voice_95069_AwakerVoiceContent = {
    Text = "Sislerin içinden herkesi çıkarıp önderlik edebilen, en saf Gümüş’ten dövülmüş gerçek Işık Taşıyıcı’dır. Juliette’in vaaz ettiği günahsız Paradise, hakikatte sadıkların kemikleri üzerine inşa edilmiştir. Bir Divus olarak, kurtuluğa layık olanların tümü arasında yeni müjdeyi ekeceğim."
  },
  Voice_95069_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_95070_AwakerVoiceContent = {
    Text = "Beni sen yönlendirdin ve bana Işık bahşettin. Ne kadar uzun süre sahte bir amaç tarafından kör edilmişim. Şimdi, gerçek çağrımı buldum: cahil ve çarpık sapkınları düzeltmek ve bu dünyaya ebedî Işık getirmek. Senin özverini biliyorum; benim adanmışlığıma ya da sunularıma ihtiyacın yok. O hâlde yalvarırım: bana senin yanında yürümeme izin ver, her kutsal sözünü ve eylemini kaydedeyim ki, onlar da yolumu karanlığın içinden geçerken aydınlatsın."
  },
  Voice_95070_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_95070_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_95071_AwakerVoiceContent = {
    Text = "Zincirlere vurulmuş, kara pislikle yıkanmış hâlde, o ışık huzmesini ne olursa olsun kovalayacağım... Bana öğretmek istediğin şey bu muydu?"
  },
  Voice_95071_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_95071_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_95072_AwakerVoiceContent = {
    Text = "Işığımı yitirdim, ve bu kör ıstırap beni kemiriyor. Yalvarırım, kaybolmuş ruhumu kurtar. Lütfen, elimi tut; ben seninkini göğsümdeki bu Kutsal Yürek üzerinde gezdirirken. Lütfen, beni ışığa doğru rehberlik et..."
  },
  Voice_95072_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_95072_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_95073_AwakerVoiceContent = {
    Text = "Ne talihsiz bir çocuk. Kendini senin davana adadığına göre, er geç nihai kurtuluşa erişecektir. Ama neden maymuna benzeyen yoldaşı da senin merhametine nail oldu? O kötü çocuk benim ayin eşyalarımı bile çaldı! Ruhunun içinde günah kasırgaları kopuyor olmalı. Ahh, saygısızlık! BÜSBÜTÜN SAYGISIZLIK!"
  },
  Voice_95073_AwakerVoiceTitle = {
    Text = "Sohbet: Aigis ve Jenkin Hakkında"
  },
  Voice_95073_UnlockDesc = {
    Text = "Uyanışçı \"Aigis\" ve \"Jenkin\" elde edildikten sonra açılır"
  },
  Voice_95074_AwakerVoiceContent = {Text = "Defol."},
  Voice_95074_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_95075_AwakerVoiceContent = {
    Text = "Işık Taşıyıcı’nın parıltısı, bu sonsuz geceyi delsin!"
  },
  Voice_95075_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_95076_AwakerVoiceContent = {
    Text = "Ah... şimdi görüyorum! Böylesine muazzam bir güç görüyorum, dünyanın hakikatini görüyorum... Geçmişte yanıldım. Gerçek Işık Taşıyıcı sensin! Lütfen, sadık Havar’in olmama izin ver. Işık Taşıyıcı için doğmuş bu kalp, bundan böyle yalnızca senin hizmetinde atacak ve titreyecek..."
  },
  Voice_95076_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_95076_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_95077_AwakerVoiceContent = {
    Text = "Şu rahibin körü körüne kurtuluş peşinde koşması, ahmaklığın zirvesidir. İlahi Lütuf yalnızca hakiki müminlere ve erdemlilere bahşedilmelidir. Eğer o bile, bir Havari olarak, buğdayla samanı ayırt edecek basiretten yoksunsa; tövbesiz günahkârları ödüllendirip onların ilahının krallığını kirletmelerine göz yumuyorsa… bu, inancına ve hizmet ettiğini iddia ettiği erdemli ruhlara karşı işlenebilecek en derin İhanet değil midir?"
  },
  Voice_95077_AwakerVoiceTitle = {
    Text = "Sohbet: Salvador Hakkında"
  },
  Voice_95077_UnlockDesc = {
    Text = "Uyanışçı \"Salvador\" elde edildikten sonra açılır"
  },
  Voice_95078_AwakerVoiceContent = {
    Text = "Kalbim İç Ateş’le yanıyor!"
  },
  Voice_95078_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_95079_AwakerVoiceContent = {Text = "Hah!"},
  Voice_95079_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_95080_AwakerVoiceContent = {
    Text = "Gençliğimde, o yerden kurtulmaya kararlıydım. Bana yalnızca acı veriyordu ve onu özlemeğe değmez buluyordum. Ama şimdi, ikinci bir hayat bahşedilmişken görüyorum ki özgürlük tek arzum değilmiş. Divus olmanın gerçek anlamı, kurtuluşun yakın olduğunu öğrendiklerinde müminlerin yüzlerinde beliren o adanmış, umutlu ve minnettar ifadeye tanıklık etmektir."
  },
  Voice_95080_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_95081_AwakerVoiceContent = {
    Text = "Juliette’in peşinden gittiğim vakit, ağır hatalar işledim ve güvenini hak etmedim. Yine de beni seçtin... Bil ki, inancımı yeniden arayacağım. Bir Divus olarak, tebaamı bir daha hayal kırıklığına uğratmayacağım, seni de."
  },
  Voice_95081_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_95081_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_95082_AwakerVoiceContent = {
    Text = "Bahşettiğin armağanı, en derin şükranımla kuşanacağım."
  },
  Voice_95082_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_95083_AwakerVoiceContent = {
    Text = "Küstahlık!"
  },
  Voice_95083_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_95084_AwakerVoiceContent = {
    Text = "Lanet olsun."
  },
  Voice_95084_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_95085_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_95086_AwakerVoiceContent = {
    Text = "Benim adımla!"
  },
  Voice_95086_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_95087_AwakerVoiceContent = {
    Text = "Görüyorum! Bilincimin derinliklerinde parlayan o ışık—gittikçe aydınlanıyor! Bana sesleniyor..."
  },
  Voice_95087_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_95087_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_95088_AwakerVoiceContent = {
    Text = "Çocukluk yıllarımızda, Castor ve ben birlikte İkiz Divus’lar olarak hizmet ettik. Onu hep fazla sönük, fazla sakar bulur, yalnızca benim geleceğimize yön vermem gerektiğini sanırdım. Şimdi, senin yürüdüğün fitil yoluna tanık olduktan sonra görüyorum ki, dünyanın temeli senin ve onun gibi olanlarca atılıp döşeniyor: metanetli ve dürüst olanlarca."
  },
  Voice_95088_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_95088_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_95089_AwakerVoiceContent = {
    Text = "Benim Işığım, rehberliğini aldığım günden beri, tek gerçek yola girdiğime inanıyorum. Yine de, pek de zeki sayılmayacak müminin hâlâ tek bir soruyla şaşkın: Efsanevi, günahsız Paradise da senin hükümranlığının bir parçası mı? “Öyle bir yer yok,” diyorsun…? Yoksa… demek istediğin, Paradise’ın burada, fani dünyada, erdemlilerin arınmış yüreklerinde var olduğu mu?"
  },
  Voice_95089_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_95090_AwakerVoiceContent = {
    Text = "Bir zamanlar ilahi buyruğa kulak veren bu kalp, şimdi seninkine daha yakın atıyor."
  },
  Voice_95090_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_95091_AwakerVoiceContent = {
    Text = "Ş-Şey... Benim için bir buyruğun var mı, Işığım? Havar’in, öğretilerini duymaya her daim hazır bekliyor."
  },
  Voice_95091_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_95092_AwakerVoiceContent = {
    Text = "Lütfen beni aydınlat, Kılavuz Işığım! Senin ışığınla, görülmesi gereken her şeyi artık gördüm... Bu lanetli bedeni geçmiş olan her şeyi arındırmak için kullanacağım, ve gelecek olan her şey senin parıltında yıkanacak!"
  },
  Voice_95092_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_95092_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_95093_AwakerVoiceContent = {
    Text = "Işığın İlahisi!"
  },
  Voice_95093_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_95391_AwakerVoiceContent = {
    Text = "Bu çirkin dünyada kurtuluş mu arıyorsun? Devam et, küçük umutlu."
  },
  Voice_95391_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_95391_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_95392_AwakerVoiceContent = {
    Text = "Al, bunlar senin olsun. Bazı harabelerden çıkan yasak kalıntılar. Yakacaktım ama belki işine yarar diye düşündüm. Bunları nasıl mı elde ettim? Diyelim ki bazıları <Italic:gönüllü olarak> teslim etti. Ve merak etme, kaynak temiz."
  },
  Voice_95392_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_95392_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_95393_AwakerVoiceContent = {
    Text = "Av bitti. Ödeme mi? Bana bir gülümse. Yeter de artar."
  },
  Voice_95393_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_95394_AwakerVoiceContent = {
    Text = "Biliyor musun, bu silahlar mermi atmıyor. Arzu ve kötülük atıyorlar. Yedi atış ve her şey yanar. Ete benzeyen bu kaotik alevler, her şeyi cehenneme sürükleyecek."
  },
  Voice_95394_AwakerVoiceTitle = {
    Text = "Sohbet: Silahlar Hakkında"
  },
  Voice_95395_AwakerVoiceContent = {
    Text = "Kendini fazla zorlama, Koruyucu. Dışarısı çetin, biliyorum; tek bir yanlış adım felaket demek. Ama böyle devam edersen Kırılma yaşarsın. Konuşacak birine ihtiyaç duyduğunda beni bul. Biz aileyiz."
  },
  Voice_95395_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_95395_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_95396_AwakerVoiceContent = {
    Text = "Yak. Parçala. Ulula!"
  },
  Voice_95396_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_95397_AwakerVoiceContent = {Text = "Yok ol."},
  Voice_95397_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_95398_AwakerVoiceContent = {
    Text = "Artık daha net görüyorum. Uçurumun altında kıvrananı görüyorum... Ben, Biz, daha fazla Güç istiyoruz. Senin için. Ailem için. Yapmalıyım..."
  },
  Voice_95398_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_95398_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_95399_AwakerVoiceContent = {
    Text = "Buraya gel. Daha yakına otur. Bu kadar gergin olmana gerek yok. \nKomik, değil mi? İlk tanıştığımızda, böyle rahat olabileceğimi hiç düşünmezdim. Ha, yüce Yaşayan Alev, tamamen güvenebileceği bir aile özlüyor.\nŞimdi bana bir söz ver. O gün geldiğinde... daha fazla dayanamadığında— Adımı söyle. Ve Ben, Biz, geleceğiz. Seni Krallığımıza alacağız. Belki sadece kaçınılmazı erteleyecektir... ama son anlarında, Bizim kucağımızda huzur bulacaksın."
  },
  Voice_95399_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_95399_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_95400_AwakerVoiceContent = {
    Text = "Sonun yaklaştı."
  },
  Voice_95400_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_95401_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_95401_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_95402_AwakerVoiceContent = {
    Text = "Sonsuz öfke ve arzuların körüğünde... Yan!"
  },
  Voice_95402_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_95403_AwakerVoiceContent = {
    Text = "İyi bir avın ardından iyi bir ziyafet gelir. Al, kızarmış develerimden ve taze tekilamdan tat. Ne? İçkiyle aran iyi değil mi? Pekâlâ, o zaman biraz meyve suyu iç."
  },
  Voice_95403_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_95403_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_95404_AwakerVoiceContent = {
    Text = "Ne oldu, ufaklık? Sarılmaya mı ihtiyacın var? Gel buraya. Abla yanında... Haha, utangaç olma."
  },
  Voice_95404_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_95406_AwakerVoiceContent = {
    Text = "Lanet olsun."
  },
  Voice_95406_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_95407_AwakerVoiceContent = {
    Text = "Kehribar Renkli Ölüm geldi."
  },
  Voice_95407_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_95408_AwakerVoiceContent = {
    Text = "Geri çekil, sana Siper olurum... Tasalanma, ben her zaman sağ çıkarım."
  },
  Voice_95408_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_95409_AwakerVoiceContent = {
    Text = "Hadi. Bu dünyanın tamamını küle çevirelim!"
  },
  Voice_95409_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_95410_AwakerVoiceContent = {
    Text = "Alev alev yanan ateş, küllerden ve Unutuş’tan doğ!"
  },
  Voice_95410_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_95411_AwakerVoiceContent = {
    Text = "Ateş daha parlak yanıyor. Gerçek bir havai fişek gösterisi görmek ister misin, ufaklık?"
  },
  Voice_95411_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_95412_AwakerVoiceContent = {
    Text = "Karanlıkta insan hayatlarıyla oynayan o hasta herifler mi? Evet. Hepsini öldüreceğim. Sonuncusuna kadar."
  },
  Voice_95412_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_95413_AwakerVoiceContent = {Text = "Bang!"},
  Voice_95413_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_95414_AwakerVoiceContent = {
    Text = "Onu bulacağım. Bu çürümüş evrenin neresinde saklanırsa saklansın fark etmez. O pis sıçan bedelini ödeyecek. \"Vecdi ve zevkinin\" her zerresi cehennem ateşinde yanacak. Merak etme, cenaze töreninde sana birinci sınıf bir koltuk ayıracağım... böylece son çığlıklarının tadını birlikte çıkarabiliriz."
  },
  Voice_95414_AwakerVoiceTitle = {
    Text = "Sohbet: N Hakkında"
  },
  Voice_95415_AwakerVoiceContent = {
    Text = "Dinle. Bu, eriyen Yıldızlar’ın ölüm çığlığı."
  },
  Voice_95415_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_95415_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_95416_AwakerVoiceContent = {
    Text = "Sonun yaklaştı."
  },
  Voice_95416_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_95417_AwakerVoiceContent = {
    Text = "Sen benim ailemsin. Ve seninle gurur duyuyorum, hem de deli gibi. O yüzden dimdik dur, benim %player%’m! Ne olursa olsun, arkandayım."
  },
  Voice_95417_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_95418_AwakerVoiceContent = {
    Text = "Adı konulamayan o şeyler karanlıkta sürünür, dünyanın kenarlarını kemirir. Er ya da geç onlarla yüzleşmek zorunda kalacaksın. Ama merak etme, arkandayım. Her zaman."
  },
  Voice_95418_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_95418_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_95420_AwakerVoiceContent = {
    Text = "Yak. Parçala. Ulula!"
  },
  Voice_95420_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_95421_AwakerVoiceContent = {Text = "Sakin kal."},
  Voice_95421_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_95422_AwakerVoiceContent = {
    Text = "Geri adım at."
  },
  Voice_95422_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_95423_AwakerVoiceContent = {
    Text = "Çözünme hakkında ne mi düşünüyorum? Git de bir lağım faresine kral hakkında ne düşündüğünü sor. Benim cevabım basit: derin, içgüdüsel bir tiksinti. Fırsat ver, deve sütü şarabından bir kadeh doldurayım ve silahlarım onları küle çevirirken çığlıklarını dinleyeyim."
  },
  Voice_95423_AwakerVoiceTitle = {
    Text = "Sohbet: Kriz Hakkında"
  },
  Voice_95424_AwakerVoiceContent = {
    Text = "Alevlerin daha da parlak yanmasını ister misin?"
  },
  Voice_95424_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_95424_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_95425_AwakerVoiceContent = {
    Text = "Ben yalnızca iş olduğunda gelirim. Bana mı ihtiyacın var? Sözcükleri söyle. Hadi, tekrar et benimle: ...@4...@2Ia! Kathigu-Ra!"
  },
  Voice_95425_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_95426_AwakerVoiceContent = {
    Text = "O bok çukuru kasabada, hayatta kalmak için herkesten daha acımasız olmak zorundaydık. Tırnaklarımızla yukarı tırmandıktan sonra bile arkamızı kollamamız gerekti—lordlar, muhafızlar, geçmişe yapışıp kalmış şu lanet “asil şövalyeler”. Şimdi farklı. Onlar benim ailem. Benim Kynde’im. Artık eğilmek yok. Dışarıda kalmış tek bir başıboş var... ama o mu? O gayet iyi olacak. Ben uzaktayken her zaman geride kalanların icabına bakmıştır."
  },
  Voice_95426_AwakerVoiceTitle = {
    Text = "Sohbet: Aile Hakkında"
  },
  Voice_95427_AwakerVoiceContent = {
    Text = "Düşmanın o mu? Öyleyse av başlasın."
  },
  Voice_95427_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_95428_AwakerVoiceContent = {
    Text = "Ben, Yaşayan Alev’im—unutulmaz, durdurulamaz! Şimdi tanık ol, HER ŞEYİN YOK OLUŞUNA!"
  },
  Voice_95428_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_95429_AwakerVoiceContent = {
    Text = "Yanmak ve Yıkım benim her şeyim, avdan gelen ölüme takıntılıyım... Gerçekten böyle bir şey söyleyeceğimi mi düşündün? Haha. Ben sadece ailemi önemsedim... Kendimden bile çok."
  },
  Voice_95429_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_95430_AwakerVoiceContent = {
    Text = "Başın dertte mi, ufaklık? Kathigu-Ra geliyor ve yanında Yıkım’ı getiriyor. Sorunlarına el salla. Hepsi Yok Olsun! Gitti."
  },
  Voice_95430_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_95431_AwakerVoiceContent = {
    Text = "Ah, Güç’ün tadı... Gidip birkaç zavallı günahkâr bulup üzerinde deneyelim mi?"
  },
  Voice_95431_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_95431_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_95432_AwakerVoiceContent = {
    Text = "Ben, Yaşayan Alev’im—unutulmaz, durdurulamaz! Şimdi tanık ol, HER ŞEYİN YOK OLUŞUNA!"
  },
  Voice_95432_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_95433_AwakerVoiceContent = {
    Text = "Efsanevi Aram Kraliçesi, Büyük Arzu Eonu, Tifere Yesod... Onu bir kez gördüm, N’yi avlarken. Yöntemlerine katılmıyorum ama... ailemi \"Onun\" bakışından korumanın tek yolu buysa... aynısını yapardım. O kadar da farklı değiliz, o ve ben."
  },
  Voice_95433_AwakerVoiceTitle = {
    Text = "Sohbet: Thais Hakkında"
  },
  Voice_95433_UnlockDesc = {
    Text = "\"Thais\" Uyandıranı edinince açılır"
  },
  Voice_95434_AwakerVoiceContent = {
    Text = "Demirini temiz tutmuşsun, iyi iş. Parlak silah, mutlu silahtır."
  },
  Voice_95434_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_95435_AwakerVoiceContent = {
    Text = "Biz Ateşiz. Ebedî Aleviz. Ölmeyen Kaosuz. Ve hepiniz... eve dönün diye geleceğiz..."
  },
  Voice_95435_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_95435_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_96361_AwakerVoiceContent = {
    Text = "Bu kurumun Gotik saat kulesinin klasik güzelliğine bayılıyorum. Ve buradaki Uyananlar, ah... Daha önce tatmadığım aromatik bir tat yayıyorlar: ölü ruh kokusunun kusursuz bir karışımı ve içinde hafif bir canlılık izi. Gerçekten de küçük bir ısırık almayı istetiyor insana."
  },
  Voice_96361_AwakerVoiceTitle = {
    Text = "Sohbet: Mythag Hakkında"
  },
  Voice_96362_AwakerVoiceContent = {
    Text = "Aradığınız şey ölümse, o hâlde dileğinizi yerine getireceğim."
  },
  Voice_96362_AwakerVoiceTitle = {
    Text = "Taşkınlık·II"
  },
  Voice_96363_AwakerVoiceContent = {
    Text = "Başlamak için epey sabırsızlanıyorum."
  },
  Voice_96363_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_96364_AwakerVoiceContent = {
    Text = "Nihayet ilginizi cezbetmeyi başardım mı? Gelin, sevgili Konuğum, masama oturun ve bu görkemli Şölen'e katılın. Gelin, her bir Ruh'un ince artçı lezzetini birlikte tadarken size Rehberlik etmeme izin verin."
  },
  Voice_96364_AwakerVoiceTitle = {
    Text = "Aydınlanma: Serpilme"
  },
  Voice_96364_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 15’te açılır"
  },
  Voice_96365_AwakerVoiceContent = {
    Text = "Şşşt, lütfen, sessiz ol. Ölü ruhların seslerini dinleyelim."
  },
  Voice_96365_AwakerVoiceTitle = {
    Text = "Afinite·Birinci"
  },
  Voice_96365_UnlockDesc = {
    Text = "Afinite Seviye 2’de açılır"
  },
  Voice_96366_AwakerVoiceContent = {
    Text = "Halkım ve ben kalıcılığın güzelliğine hürmet ederiz. Çözünme, yaşayan bir insanı yavaş yavaş aşındırır, varlığının tüm izlerini siler... Böylesine zalim bir işkenceye izin verilmemeli."
  },
  Voice_96366_AwakerVoiceTitle = {
    Text = "Sohbet: Kriz Hakkında"
  },
  Voice_96367_AwakerVoiceContent = {
    Text = "Benim gibi Bay Pickman da ölümsüzleştirilmiş güzelliğin peşinde. Daha yakın dostlar olabilirdik. Ama o, yemeyi muhafaza edilmiş ebediyete bir ihlal olarak görüyor. Ne dar bir sanatsal felsefe."
  },
  Voice_96367_AwakerVoiceTitle = {
    Text = "Sohbet: Pickman Hakkında"
  },
  Voice_96367_UnlockDesc = {
    Text = "Uyanıklaştırıcı \"Pickman\" elde edildikten sonra açılır"
  },
  Voice_96368_AwakerVoiceContent = {Text = "Ha!"},
  Voice_96368_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_96369_AwakerVoiceContent = {
    Text = "Hiçbir sıfat bedeninin sarhoş edici kokusunu tarif edemez. Zengin bir Bordeaux şarabının buruk art tadı ve olgun, tereyağlı bir pandispanyanın yoğun aroması gibidir. Ölüm günün, muhtemelen kalan zamanımın en önemli olayı olacak."
  },
  Voice_96369_AwakerVoiceTitle = {
    Text = "Sohbet: Koruyucu Hakkında"
  },
  Voice_96370_AwakerVoiceContent = {
    Text = "Genç bir kızın etini, tırnaklarını, ellerini ve ayaklarını yavaş yavaş oyan, bunu yaparken de onu durmaksızın iyileştiren bir adam vardı. Ne ölmesini istiyordu, ne de yaşamasını. Elbette ona huzurlu bir ölüm bahşedemezdim. Bu yüzden, ona kendi ilacından tattırdım. Acaba kaç yıldır orada sıkışıp kaldı… Ölümü saygısızlığa uğratan biri için, bu oldukça adil değil mi?"
  },
  Voice_96370_AwakerVoiceTitle = {
    Text = "Sohbet: Nefret Ettiklerim"
  },
  Voice_96371_AwakerVoiceContent = {
    Text = "Ölümün üzerinde hüküm sürerim, ama lütfen yanlış anlamayın. Onu asla ben yaratmam; yalnızca izini sürer, ardında kalan en seçkin lokmaları toplarım."
  },
  Voice_96371_AwakerVoiceTitle = {
    Text = "Aydınlanma: Gözlem"
  },
  Voice_96371_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 1’de açılır"
  },
  Voice_96372_AwakerVoiceContent = {
    Text = "Sen de mi etimin tadını arzuluyorsun, sevgili Koruyucu?"
  },
  Voice_96372_AwakerVoiceTitle = {
    Text = "Sohbet: Dokun"
  },
  Voice_96373_AwakerVoiceContent = {
    Text = "Bugün akşam soframı hangi talihsiz misafir şereflendirecek, merak ediyorum."
  },
  Voice_96373_AwakerVoiceTitle = {
    Text = "Soruşturma Başlıyor"
  },
  Voice_96374_AwakerVoiceContent = {
    Text = "Size bu geceki Ziyafet olma onurunu bahşedeceğim."
  },
  Voice_96374_AwakerVoiceTitle = {
    Text = "Soruşturma Başarılı"
  },
  Voice_96375_AwakerVoiceContent = {
    Text = "Ne kadar da korkunç derecede zarafetten yoksun."
  },
  Voice_96375_AwakerVoiceTitle = {
    Text = "Darbe·Üçüncü"
  },
  Voice_96376_AwakerVoiceContent = {
    Text = "Sana lekesiz bir dinlenme ve toparlanma getireceğim."
  },
  Voice_96376_AwakerVoiceTitle = {
    Text = "Beceri·Birinci"
  },
  Voice_96377_AwakerVoiceContent = {
    Text = "Her öğünden önce, ölü ruhlarla sohbet ederim. Onlar için, içten bir samimiyetle yenmek ve tadılmak, hayatın bir devamı ve son, en görkemli anlarıdır.\nNasıl ki ben onlara özlem duyuyorsam, onlar da bana özlem duyar."
  },
  Voice_96377_AwakerVoiceTitle = {
    Text = "Afinite·Üçüncü"
  },
  Voice_96377_UnlockDesc = {
    Text = "Afinite Seviye 6’da açılır"
  },
  Voice_96378_AwakerVoiceContent = {
    Text = "Sessiz ol, olur mu?"
  },
  Voice_96378_AwakerVoiceTitle = {Text = "Darbe·IV"},
  Voice_96379_AwakerVoiceContent = {
    Text = "Saçılın ve gölgelerin içine karışıp yok olun!"
  },
  Voice_96379_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_96380_AwakerVoiceContent = {
    Text = "Mesafemizi koruyalım."
  },
  Voice_96380_AwakerVoiceTitle = {
    Text = "Savunma·Birinci"
  },
  Voice_96381_AwakerVoiceContent = {
    Text = "Saçılın ve gölgelerin içine karışıp yok olun!"
  },
  Voice_96381_AwakerVoiceTitle = {
    Text = "Yetenek: IV"
  },
  Voice_96382_AwakerVoiceContent = {
    Text = "Benden neden bu kadar sakınıyorsun? Ne korkmana gerek var ne de korkman gerekir; yaşayan bir insanı yemek, benim estetik anlayışıma aykırıdır."
  },
  Voice_96382_AwakerVoiceTitle = {
    Text = "Sohbet: Yemek Hakkında"
  },
  Voice_96383_AwakerVoiceContent = {
    Text = "Aradığınız şey ölümse, o hâlde dileğinizi yerine getireceğim."
  },
  Voice_96383_AwakerVoiceTitle = {
    Text = "Taşkınlık"
  },
  Voice_96384_AwakerVoiceContent = {
    Text = "Ne kadar da korkunç derecede zarafetten yoksun."
  },
  Voice_96384_AwakerVoiceTitle = {
    Text = "Darbe·Birinci"
  },
  Voice_96385_AwakerVoiceContent = {
    Text = "Dikkatli ol."
  },
  Voice_96385_AwakerVoiceTitle = {
    Text = "Savunma·II"
  },
  Voice_96386_AwakerVoiceContent = {
    Text = "O hanımefendinin coşkusu pek dokunaklı, ama bedeninde fazla mayalanmış, nemli bir koku var. Tadına bakmam için yalvarıp dursa da, damak zevkime hiç hitap etmiyor. Ne can sıkıcı."
  },
  Voice_96386_AwakerVoiceTitle = {
    Text = "Sohbet: Leigh Hakkında"
  },
  Voice_96386_UnlockDesc = {
    Text = "\"Leigh\" Uyandıranı edinince açılır"
  },
  Voice_96387_AwakerVoiceContent = {
    Text = "Biliyor musun?\nHer hayat, solup giderken uzun süre yankılanan bir iz bırakır.\nPerdeleri ve tınıları farklıdır; ölüm anından itibaren yavaş yavaş uzar, ta ki göğe ve yere karışıp yok olana dek, iç çekerek yükselen bir çığlık gibi."
  },
  Voice_96387_AwakerVoiceTitle = {
    Text = "Afinite·II"
  },
  Voice_96387_UnlockDesc = {
    Text = "Afinite Seviye 4’te açılır"
  },
  Voice_96388_AwakerVoiceContent = {
    Text = "İçiniz rahat olsun, {Male=Bay,Female=Bayan} Koruyucu, yaşamınız kaderde yazılı sonuna kavuşacağı güne dek yanınızda kalacağım. O gün geldiğinde, tüm ciddiyetimle bedeninizi parça parça tüketeceğim. Ve ruhunuz sonsuza dek benim içimde ikamet edecek."
  },
  Voice_96388_AwakerVoiceTitle = {Text = "Afinite: V"},
  Voice_96388_UnlockDesc = {
    Text = "Afinite Seviye 10’da açılır"
  },
  Voice_96389_AwakerVoiceContent = {
    Text = "Kendini koklayamıyor musun? Ah, ne yazık. En tatlı, en yüce... şeyden mahrum kalıyorsun... A, ne oldu? Neden geri çekiliyorsun?"
  },
  Voice_96389_AwakerVoiceTitle = {
    Text = "Afinite·IV"
  },
  Voice_96389_UnlockDesc = {
    Text = "Afinite Seviye 8’de açılır"
  },
  Voice_96390_AwakerVoiceContent = {
    Text = "Daha çok yaklaşan ölüm görüyorum. Öte taraf gitgide daha da berraklaşıyor..."
  },
  Voice_96390_AwakerVoiceTitle = {
    Text = "Yükseltme·Üçüncü"
  },
  Voice_96391_AwakerVoiceContent = {
    Text = "Lütfen bedeninizi bana emanet edin. Sizi itinayla tadacağım: her damla kanınızı, her parça etinizi, her bir kemiğinizi."
  },
  Voice_96391_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık"
  },
  Voice_96392_AwakerVoiceContent = {
    Text = "Farklı malzemeler, farklı hazırlıklar talep eder. Organların marine edilmesi gerekir. Bacaklardaki tendonlar en çok haşlamaya yakışır. Yağlı kısımlar fermantasyon ve yıllandırma için kusursuzdur; daha narin parçalar ise kızartılabilir, fırınlanabilir ya da zarifçe şekillendirilmiş jölelere dönüştürülebilir. Bu seçimlerin hepsi, takdiri ve sezgiyi gerektirir. Zira malzemenin doğal lezzetini koruyup öne çıkarmadan, saygı olmaz."
  },
  Voice_96392_AwakerVoiceTitle = {
    Text = "Aydınlanma: Kavrayış"
  },
  Voice_96392_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 7’de açılır"
  },
  Voice_96393_AwakerVoiceContent = {
    Text = "Biraz serin olabilir."
  },
  Voice_96393_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_96394_AwakerVoiceContent = {
    Text = "Yemeklerin eşleştirilmesi de büyük önem taşır.\nEkşinin tatlıyla, gevreğin yumuşakla, hafifin zenginle, narinin kaba ile yan yana gelişi; katmanlı bir lezzet ve dokusal bir karşıtlık yaratır; bu da, ilk temas anından çiğnemeye ve sonrasında damağında kalan yankıya dek bambaşka duyumlara yol açar.\nİşte bu, usulünce hazırlanmış bir yemeğin sunduğu sonsuz ve hayret verici hazdır."
  },
  Voice_96394_AwakerVoiceTitle = {
    Text = "Aydınlanma: Yükseliş"
  },
  Voice_96394_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 11’de açılır"
  },
  Voice_96395_AwakerVoiceContent = {
    Text = "Coşkunuz için size minnettarım. Bu onur bütünüyle benim."
  },
  Voice_96395_AwakerVoiceTitle = {
    Text = "Yükseltme·II"
  },
  Voice_96396_AwakerVoiceContent = {
    Text = "Gerçekten leziz bir yemek, beklemeye her zaman değer."
  },
  Voice_96396_AwakerVoiceTitle = {
    Text = "Soruşturma Durduruldu"
  },
  Voice_96397_AwakerVoiceContent = {
    Text = "Çiğ etle tıka basa dolan barbar bir canavar değilim. Ölümün tüketimi ağırbaşlı ve zarif bir törendir. Her bir malzemenin kendine özgü tadıyla hemhâl olmalı, onu gerçekten anlamalısınız."
  },
  Voice_96397_AwakerVoiceTitle = {
    Text = "Aydınlanma: Düşün"
  },
  Voice_96397_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 2’de açılır"
  },
  Voice_96398_AwakerVoiceContent = {
    Text = "Huzur bulmuş ölüler güzeldir ve hoş kokuludurlar. Güzellikleri, ölümden önce ya da sonra, etlerinde değil, ruhlarındadır. O ruhların ölüme dair Aydınlanma’sı, hayata duydukları özlem ve hatırlanma arzuları, hep düşlediğim o nefis lezzetlerdir."
  },
  Voice_96398_AwakerVoiceTitle = {
    Text = "Sohbet: Sevdiğim Şeyler"
  },
  Voice_96399_AwakerVoiceContent = {
    Text = "Hiçbir parfüm, insan bedeninin kendi doğal kokusuyla boy ölçüşemez. Birini kokusundan tanımak, başlı başına ilahi bir hazdır."
  },
  Voice_96399_AwakerVoiceTitle = {
    Text = "Aydınlanma: Tefekkür"
  },
  Voice_96399_UnlockDesc = {
    Text = "Aydınlanma Seviyesi 3’te açılır"
  },
  Voice_96400_AwakerVoiceContent = {
    Text = "Ah, ne unutulmaz bir koku... Seni kutsal mekânıma kabul etmek için sabırsızlanıyorum."
  },
  Voice_96400_AwakerVoiceTitle = {Text = "Uyanış"},
  Voice_96401_AwakerVoiceContent = {
    Text = "Lütfen bedeninizi bana emanet edin. Sizi itinayla tadacağım: her damla kanınızı, her parça etinizi, her bir kemiğinizi."
  },
  Voice_96401_AwakerVoiceTitle = {
    Text = "Aşırı Taşkınlık·II"
  },
  Voice_96402_AwakerVoiceContent = {
    Text = "Sana lekesiz bir dinlenme ve toparlanma getireceğim."
  },
  Voice_96402_AwakerVoiceTitle = {Text = "Beceri·II"},
  Voice_96403_AwakerVoiceContent = {
    Text = "Sessiz ol, olur mu?"
  },
  Voice_96403_AwakerVoiceTitle = {Text = "Darbe·II"},
  Voice_96404_AwakerVoiceContent = {
    Text = "Kokunun öylesine baştan çıkarıcı ki insanı sarhoş ediyor."
  },
  Voice_96404_AwakerVoiceTitle = {
    Text = "Yükseltme·Birinci"
  },
  Voice_98324_AwakerVoiceContent = {
    Text = "Sonsuz öfke ve arzuların körüğünde... Yan!"
  },
  Voice_98324_AwakerVoiceTitle = {
    Text = "Özel Beceri: I"
  }
})
return Text_Voice
